def repo_root() -> Path:
    try:
        result = subprocess.run(
            ["git", "rev-parse", "--show-toplevel"],
            capture_output=True,
            text=True,
            cwd=Path(__file__).parent,
        )
    except FileNotFoundError:
        sys.exit("error: git not found in PATH")
    if result.returncode != 0:
        sys.exit("error: could not determine repo root via git")
    return Path(result.stdout.strip())


def canonical_failure_log_path(root: Path) -> Path:
    """Return the preferred failure-log path, with legacy fallback for old artifacts/tests."""
    current = root / CANONICAL_FAILURE_LOG_REL
    if current.exists():
        return current
    legacy = root / LEGACY_FAILURE_LOG_REL
    if legacy.exists():
        return legacy
    return current


def legacy_failure_log_path(root: Path) -> Path:
    return root / LEGACY_FAILURE_LOG_REL


def runs_dir(root: Path) -> Path:
    return root / "artifacts" / "maintainer" / "watchdog_runs"


def multiplayer_ledger_path(root: Path) -> Path:
    return root / "docs" / "multiplayer-vps-regression-ledger.md"


def load_git_tags(root: Path) -> set:
    result = subprocess.run(
        ["git", "tag", "-l", "watchdog-run-*"], capture_output=True, text=True, cwd=root
    )
    if result.returncode != 0:
        return set()
    return set(result.stdout.strip().splitlines())


def gap_registry_path(root: Path) -> Path:
    return root / "scripts" / "watchdog" / "gap_registry.json"


def load_gap_registry_with_status(root: Path) -> tuple[dict[str, dict], dict[str, object]]:
    """Load the watchdog gap registry keyed by gate name with fail-closed status."""
    path = gap_registry_path(root)
    if not path.exists():
        return {}, {"ok": False, "path": str(path), "error": "gap_registry_missing"}
    try:
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
    except Exception as exc:
        return {}, {
            "ok": False,
            "path": str(path),
            "error": "gap_registry_invalid",
            "detail": str(exc),
        }
    if not isinstance(data, dict) or not isinstance(data.get("gaps"), list):
        return {}, {
            "ok": False,
            "path": str(path),
            "error": "gap_registry_invalid",
            "detail": "expected object with gaps list",
        }
    mapping: dict[str, dict] = {}
    for gap in data.get("gaps", []):
        if not isinstance(gap, dict):
            continue
        for gate in gap.get("gate_names") or []:
            mapping[gate] = gap
    return mapping, {"ok": True, "path": str(path), "error": None}


def load_gap_registry(root: Path) -> dict:
    """Load the watchdog gap registry keyed by gate name."""
    mapping, _ = load_gap_registry_with_status(root)
    return mapping


def missing_plan_required_gap_registry_gates(gaps: dict[str, dict]) -> list[str]:
    """Return sorted gate names in PLAN_REQUIRED_APPEARANCE_GATES not covered by the gap registry mapping."""
    return sorted(gate for gate in PLAN_REQUIRED_APPEARANCE_GATES if gate not in gaps)


