_VERDICT_NORMALIZE = {
    "launch_blocked": "infra_fail",
    "blocked": "infra_fail",
}

_FAILURE_CLASS_TO_VERDICT = {
    "prelaunch_block": "infra_fail",
    "dirty_worktree": "infra_fail",
    "binary_arch_wrong": "infra_fail",
    "online_unavailable": "bootstrap_fail",
    "post_ready_offline": "fail",
    "ws_1006": "bootstrap_fail",
    "join_opcode_wrong": "bootstrap_fail",
    "wrong_ws_endpoint": "bootstrap_fail",
    "npc_out_of_range": "setup_invalid",
    "player_unarmed": "setup_invalid",
    "extra_players": "setup_invalid",
    "scenario_staging_failed": "setup_invalid",
}


def normalize_verdict(d: dict) -> str:
    """Map legacy verdict strings to the newer corpus vocabulary."""
    verdict = d.get("verdict") or "blocked"
    failure_class = d.get("failure_class", "")
    journal = d.get("journal_transcript") or {}
    classifier = journal.get("classifier") or {}
    first_valid_snapshot_seen = bool(classifier.get("first_valid_snapshot_seen"))
    mounted_witness = d.get("mounted_witness") or {}
    witness_found = bool(mounted_witness.get("witness_found"))
    if (
        verdict == "artifact_invalid"
        and failure_class == "online_unavailable"
        and (first_valid_snapshot_seen or witness_found)
    ):
        return "fail"
    if verdict in _VERDICT_NORMALIZE:
        return _VERDICT_NORMALIZE[verdict]
    if verdict == "artifact_invalid":
        return _FAILURE_CLASS_TO_VERDICT.get(failure_class, "bootstrap_fail")
    # Reclassify fail/partial when failure_class maps to a more specific verdict.
    if failure_class and failure_class in _FAILURE_CLASS_TO_VERDICT:
        return _FAILURE_CLASS_TO_VERDICT[failure_class]
    return verdict


def is_prelaunch_artifact_run(run: dict) -> bool:
    """True when the run never became a real gameplay/online artifact.

    Fresh-agent defaults should not treat dry-runs, launch-blocked receipts, or
    other infra/prelaunch artifacts as first-class VPS evidence.
    """
    if normalize_verdict(run) == "infra_fail":
        return True
    online_ok = run.get("online_integrity_ok")
    has_gate_data = bool(run.get("false_gates") or run.get("null_gates"))
    return online_ok is False and not has_gate_data


def run_label_for(run: dict) -> str:
    # Primary field is run_label; fall back to deprecated "scenario" for old artifacts
    return str(run.get("run_label") or run.get("scenario") or "")


def passive_provenance_note(run: dict) -> str | None:
    label = run_label_for(run).strip()
    if label != "passive":
        return None
    return (
        "historical provenance label only: 'passive' does not mean nobody drove "
        "the tabs, and it does not invalidate recorder metrics by itself. "
        "'no_active_input_owner' is a gate-local qualifier, not a blanket "
        "artifact-invalid verdict."
    )


# ═══════════════════════════════════════════════════════════════════════════
# AGENT WARNING — READ BEFORE INTERPRETING ANY PASSIVE RUN (FL-2783 / FL-3023)
# ═══════════════════════════════════════════════════════════════════════════
# AGENT_TRAP OVERREAD COUNTER: 4 TIMES, 0 PREVENTED.
#
# controller_mode=off DOES NOT mean movement did not happen.
# controller_mode=off DOES NOT mean the artifact is invalid.
# controller_mode=off DOES NOT mean you can skip movement gate analysis.
#
# Human operators frequently drive input manually in passive runs.
# Playwright tab-switching fires OnFocus(false) which memsets input state.
# Held keys die. Metrics may show zero movement intent even though the user
# was actively pressing W/A/S/D. This is a BROWSER FOCUS-WIPE BUG, not a
# controller configuration bug. See FL-2783 and FL-3023 in FAILURE_LOG.md.
#
# The string below is intentionally loud because FOUR consecutive agent
# sessions have ignored the documented warning and treated controller_mode=off
# as a blanket "no movement happened" verdict. DO NOT BE THE FIFTH.
# ═══════════════════════════════════════════════════════════════════════════
def controller_mode_off_warning(run: dict) -> str | None:
    controller_mode = str(run.get("controller_mode") or "").strip()
    if controller_mode != "off":
        return None
    return "JUST BECAUSE CONTROLLER MODE IS OFF DOES NOT EMAN MOVEMENT DID NOT FUCKING HAPPEN!!!!!!!!!!!"


def requested_run_label(args) -> str:
    # --scenario is a deprecated alias for --run-label; check both
    return str(getattr(args, "run_label", None) or getattr(args, "scenario", None) or "")


def canonical_gate_name(gate: str) -> str:
    """Map renamed historical gate names to their canonical current names."""
    return GATE_ALIASES.get(gate, gate)


def canonical_gate_list(gates: list[str] | None) -> list[str] | None:
    """Canonicalize a gate list while preserving first-seen order."""
    if gates is None:
        return None
    out: list[str] = []
    seen: set[str] = set()
    for gate in gates:
        canonical = canonical_gate_name(gate)
        if canonical in seen:
            continue
        out.append(canonical)
        seen.add(canonical)
    return out


