def _correct_lag_band_and_gates(run: dict) -> int:
    """Fix stored lag_band and lag_yellow_spike_budget_ok when raw metrics
    contradict them.  The watchdog sometimes stores lag_band=green even when
    lag_ms_max, raw RTT, or yellowLatest crosses yellow/red.  This function
    recomputes the proof gates from raw tab metrics and patches the run dict
    in-place.

    Returns the number of corrections made.
    """
    rs = run.get('recorder_surface') or (run.get('diagnostics') or {}).get('recorder_surface')
    if not isinstance(rs, dict):
        return 0

    false_gates: list[str] = list(run.get('false_gates') or [])
    null_gates: list[str] = list(run.get('null_gates') or [])
    corrections = 0

    for tab_name in ('tab1', 'tab2'):
        tab = rs.get(tab_name)
        if not isinstance(tab, dict):
            continue

        # --- correct lag_band ---
        honest = _honest_lag_band(tab)
        stored = tab.get('lag_band')
        if honest and stored and honest != stored:
            tab['lag_band'] = honest
            corrections += 1

        # --- correct lag_yellow_spike_budget_ok ---
        red_count = tab.get('lag_spike_count')
        yellow_count = tab.get('lag_yellow_count')
        raw_rtt_yellow_count = tab.get('lag_rtt_raw_yellow_count')
        raw_rtt_red_count = tab.get('lag_rtt_raw_spike_count')
        tab_max = tab.get('lag_ms_max')
        raw_rtt_max = tab.get('lag_rtt_raw_ms_max')
        post_join_max = tab.get('post_join_lag_max_ms')
        post_join_p95 = tab.get('post_join_lag_p95_ms')

        if all(isinstance(v, (int, float)) for v in (
            red_count,
            yellow_count,
            raw_rtt_yellow_count,
            raw_rtt_red_count,
            tab_max,
            raw_rtt_max,
            post_join_max,
            post_join_p95,
        )):
            honest_yellow_budget = (
                red_count == 0
                and yellow_count == 0
                and raw_rtt_yellow_count == 0
                and raw_rtt_red_count == 0
                and tab_max < 100
                and raw_rtt_max < 100
                and post_join_max < 100
                and post_join_p95 <= 90
            )
            stored_yellow_failed = 'lag_yellow_spike_budget_ok' in false_gates
            if honest_yellow_budget and stored_yellow_failed:
                false_gates[:] = [g for g in false_gates if g != 'lag_yellow_spike_budget_ok']
                corrections += 1
            elif not honest_yellow_budget and not stored_yellow_failed:
                if 'lag_yellow_spike_budget_ok' not in false_gates:
                    false_gates.append('lag_yellow_spike_budget_ok')
                corrections += 1

        # --- correct lag_spike_count_ok ---
        if isinstance(red_count, (int, float)):
            raw_rtt_spikes_ok = (
                raw_rtt_red_count == 0
                if isinstance(raw_rtt_red_count, (int, float))
                else True
            )
            honest_spike_ok = red_count == 0 and raw_rtt_spikes_ok
            stored_spike_failed = 'lag_spike_count_ok' in false_gates
            if honest_spike_ok and stored_spike_failed:
                false_gates[:] = [g for g in false_gates if g != 'lag_spike_count_ok']
                corrections += 1
            elif not honest_spike_ok and not stored_spike_failed:
                if 'lag_spike_count_ok' not in false_gates:
                    false_gates.append('lag_spike_count_ok')
                corrections += 1

    if false_gates != run.get('false_gates'):
        run['false_gates'] = canonical_gate_list(false_gates)
    null_gates = [g for g in null_gates if g not in false_gates]
    if null_gates != run.get('null_gates'):
        run['null_gates'] = canonical_gate_list(null_gates)

    return corrections


def load_run_dict(d: dict, *, default_run_id: str | None = None) -> dict:
    """Normalize a run record loaded from summary.json or synthesized metadata."""
    # Normalize failed-*.json (minimal format) to look like a full record
    if "run_id" not in d:
        # Extract timestamp from filename: failed-20260404-161710.json
        stem = default_run_id or "unknown-run"
        d["run_id"] = stem
        d.setdefault("branch", None)
        d.setdefault("git_head", None)
        d.setdefault("git_tag", None)
        d.setdefault("run_label", None)
        d.setdefault("scenario", None)  # deprecated: kept for old-artifact compat
        d.setdefault("false_gates", None)
        d.setdefault("null_gates", None)
        d.setdefault("runtime_required_passed", None)
        d.setdefault("runtime_required_total", None)
        d.setdefault("runtime_core_passed", None)
        d.setdefault("runtime_core_total", None)
        d.setdefault("verdict", d.get("verdict", "blocked"))
    if not d.get("run_label") and d.get("scenario"):
        d["run_label"] = d.get("scenario")
    pending_phase10 = (
        (d.get("diagnostics") or {})
        .get("phase10", {})
        .get("proof_surface", {})
        .get("pending_gates", [])
    )
    if pending_phase10:
        null_gates = list(d.get("null_gates") or [])
        null_gates.extend(pending_phase10)
        d["null_gates"] = null_gates
    d["false_gates"] = canonical_gate_list(d.get("false_gates"))
    d["null_gates"] = canonical_gate_list(d.get("null_gates"))
    d["_canonical_gate_lists"] = True
    d["verdict"] = normalize_verdict(d)
    _correct_lag_band_and_gates(d)
    return d


def load_run(path: Path) -> dict:
    """Load and normalize a single run record."""
    with open(path) as f:
        d = json.load(f)
    return load_run_dict(d, default_run_id=path.stem)


_RUN_SUMMARY_INDEX_VERSION = 1
_RUN_SUMMARY_INDEX_NAME = "index.json"
_RUN_SUMMARY_CACHE: dict[str, tuple[list[dict], list[str]]] = {}


def _run_id_from_watchdog_artifact_dir(path: Path) -> str | None:
    prefix = "watchdog-vps-"
    name = path.name
    if not name.startswith(prefix):
        return None
    return name[len(prefix):]


def _live_tmp_artifact_dirs() -> list[Path]:
    tmp = Path("/tmp")
    if not tmp.exists():
        return []
    try:
        return sorted(
            path
            for path in tmp.glob("watchdog-vps-*")
            if path.is_dir() and (path / "metrics.json").exists()
        )
    except OSError:
        return []


def _live_tmp_artifact_dir_for_run(run_id: str) -> Path | None:
    candidate = Path("/tmp") / f"watchdog-vps-{run_id}"
    if (candidate / "metrics.json").exists():
        return candidate
    for path in _live_tmp_artifact_dirs():
        if _run_id_from_watchdog_artifact_dir(path) == run_id:
            return path
    return None


def _run_record_from_live_artifact(path: Path) -> dict | None:
    run_id = _run_id_from_watchdog_artifact_dir(path)
    if not run_id:
        return None
    metrics_path = path / "metrics.json"
    try:
        metrics = json.loads(metrics_path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return None

    slot_manifest: dict[str, Any] = {}
    slot_manifest_path = path / "slot_manifest.json"
    if slot_manifest_path.exists():
        try:
            slot_manifest = json.loads(slot_manifest_path.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError):
            slot_manifest = {}

    gates = metrics.get("gates") or {}
    false_gates = sorted(canonical_gate_list([k for k, v in gates.items() if v is False]) or [])
    null_gates = sorted(canonical_gate_list([k for k, v in gates.items() if v is None]) or [])
    raw_verdict = str(metrics.get("verdict") or "").strip().lower()
    if raw_verdict in ("pass", "partial", "fail"):
        verdict = raw_verdict
    elif false_gates:
        verdict = "fail"
    elif null_gates:
        verdict = "partial"
    elif gates:
        verdict = "pass"
    else:
        verdict = "blocked"

    provenance = metrics.get("provenance") or {}
    source_ref = (
        slot_manifest.get("gameplay_ref")
        or slot_manifest.get("source_ref")
        or provenance.get("source_ref")
        or ""
    )
    run = {
        "run_id": run_id,
        "run_label": run_id.split("-", 1)[0] if "-" in run_id else None,
        "started_at_utc": metrics.get("started_at"),
        "completed_at_utc": metrics.get("finished_at"),
        "git_head": str(source_ref)[:8] if source_ref else None,
        "source_ref": source_ref,
        "branch": None,
        "verdict": verdict,
        "artifact_path": str(path),
        "live_tmp_artifact": True,
        "false_gates": false_gates,
        "null_gates": null_gates,
        "runtime_required_passed": None,
        "runtime_required_total": None,
        "runtime_core_passed": None,
        "runtime_core_total": None,
        "online_integrity_ok": True,
    }
    return load_run_dict(run)


def _merge_live_tmp_artifacts(records: list[dict]) -> list[dict]:
    seen = {str(r.get("run_id") or "") for r in records}
    additions: list[dict] = []
    for path in _live_tmp_artifact_dirs():
        run_id = _run_id_from_watchdog_artifact_dir(path)
        if not run_id or run_id in seen:
            continue
        run = _run_record_from_live_artifact(path)
        if run is not None:
            additions.append(run)
            seen.add(run_id)
    if not additions:
        return records
    merged = list(records) + additions

    def sort_key(d):
        for field in ("started_at_utc", "completed_at_utc"):
            ts = d.get(field)
            if ts:
                try:
                    dt = datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=timezone.utc)
                    return dt
                except Exception:
                    pass
        return datetime.min.replace(tzinfo=timezone.utc)

    merged.sort(key=sort_key, reverse=True)
    return merged


def _should_merge_live_tmp_artifacts(root: Path) -> bool:
    try:
        if root.resolve() == repo_root().resolve():
            return True
    except Exception:
        pass
    rd = runs_dir(root)
    try:
        return rd.exists() and not any(
            path.is_dir() and (path / "summary.json").exists()
            for path in rd.iterdir()
        )
    except OSError:
        return False


def _run_summary_manifest(rd: Path) -> list[dict]:
    manifest = []
    for path in sorted(rd.iterdir()):
        if path.name == _RUN_SUMMARY_INDEX_NAME:
            continue
        if path.is_dir():
            summary = path / "summary.json"
            if summary.exists():
                try:
                    st = summary.stat()
                except OSError:
                    continue
                manifest.append(
                    {
                        "rel": f"{path.name}/summary.json",
                        "mtime_ns": st.st_mtime_ns,
                        "size": st.st_size,
                    }
                )
            else:
                manifest.append({"rel": f"{path.name}/", "missing_summary": True})
        elif path.suffix == ".json" and path.name.startswith("failed-"):
            try:
                st = path.stat()
            except OSError:
                continue
            manifest.append(
                {
                    "rel": path.name,
                    "mtime_ns": st.st_mtime_ns,
                    "size": st.st_size,
                }
            )
    return manifest


def _load_run_summary_index(rd: Path, manifest: list[dict]) -> tuple[list[dict], list[str]] | None:
    index_path = rd / _RUN_SUMMARY_INDEX_NAME
    if not index_path.exists():
        return None
    try:
        data = json.loads(index_path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError) as exc:
        print(f"warning: run summary index: {exc}", file=sys.stderr)
        return None
    if data.get("version") != _RUN_SUMMARY_INDEX_VERSION:
        return None
    if data.get("manifest") != manifest:
        return None
    records = data.get("records")
    incomplete = data.get("incomplete")
    if not isinstance(records, list) or not isinstance(incomplete, list):
        return None
    return records, incomplete


def _write_run_summary_index(rd: Path, manifest: list[dict], records: list[dict], incomplete: list[str]) -> None:
    index_path = rd / _RUN_SUMMARY_INDEX_NAME
    payload = {
        "version": _RUN_SUMMARY_INDEX_VERSION,
        "manifest": manifest,
        "records": records,
        "incomplete": incomplete,
    }
    try:
        index_path.write_text(json.dumps(payload, separators=(",", ":")), encoding="utf-8")
    except OSError:
        pass


def load_all_runs(root: Path) -> tuple:
    """Load all run records. Returns (records, incomplete_dir_names), sorted newest first."""
    rd = runs_dir(root)
    if not rd.exists():
        sys.exit(f"error: runs dir not found: {rd}")

    manifest = _run_summary_manifest(rd)
    cache_key = str(rd)
    cached = _RUN_SUMMARY_CACHE.get(cache_key)
    if cached and getattr(load_all_runs, "_manifest", {}).get(cache_key) == manifest:
        return cached

    merge_live_tmp = _should_merge_live_tmp_artifacts(root)
    indexed = _load_run_summary_index(rd, manifest)
    if indexed is not None:
        indexed = (_merge_live_tmp_artifacts(indexed[0]) if merge_live_tmp else indexed[0], indexed[1])
        _RUN_SUMMARY_CACHE[cache_key] = indexed
        manifests = getattr(load_all_runs, "_manifest", {})
        manifests[cache_key] = manifest
        setattr(load_all_runs, "_manifest", manifests)
        return indexed

    records = []
    incomplete = []
    dirs = sorted(rd.iterdir())
    total_dirs = len(dirs)
    for idx, path in enumerate(dirs):
        if not _JSON_MODE and total_dirs > 20 and idx % 20 == 0:
            sys.stderr.write(f"\r{cli_style.progress(idx, total_dirs, 'Loading runs...')}")
            sys.stderr.flush()
        if path.is_dir():
            summary = path / "summary.json"
            if summary.exists():
                try:
                    records.append(load_run(summary))
                except (json.JSONDecodeError, KeyError) as e:
                    print(
                        f"warning: skipping {path.name}/summary.json: {e}",
                        file=sys.stderr,
                    )
            else:
                incomplete.append(path.name)
        elif path.suffix == ".json" and path.name.startswith("failed-"):
            try:
                records.append(load_run(path))
            except (json.JSONDecodeError, KeyError) as e:
                print(f"warning: skipping {path.name}: {e}", file=sys.stderr)

    if not _JSON_MODE and total_dirs > 20:
        sys.stderr.write("\r\033[K")  # clear progress line
        sys.stderr.flush()

    # Sort newest first by started_at_utc; parse to datetime for correct ordering
    def sort_key(d):
        for field in ("started_at_utc", "completed_at_utc"):
            ts = d.get(field)
            if ts:
                try:
                    dt = datetime.fromisoformat(str(ts).replace("Z", "+00:00"))
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=timezone.utc)
                    return dt
                except Exception:
                    pass
        return datetime.min.replace(tzinfo=timezone.utc)

    records.sort(key=sort_key, reverse=True)
    indexed_records = list(records)
    if merge_live_tmp:
        records = _merge_live_tmp_artifacts(records)
    result = (records, incomplete)
    _write_run_summary_index(rd, manifest, indexed_records, incomplete)
    _RUN_SUMMARY_CACHE[cache_key] = result
    manifests = getattr(load_all_runs, "_manifest", {})
    manifests[cache_key] = manifest
    setattr(load_all_runs, "_manifest", manifests)
    return result


_FL_LEDGER_RECEIPT_SOURCE = "multiplayer_ledger"

_LEDGER_FL_RE = re.compile(r"\bFL-\d+\b", re.IGNORECASE)
_LEDGER_RUN_ID_RE = re.compile(r"\b[a-z][a-z0-9_-]*-\d{8}-\d{6}\b")
_LEDGER_COMMIT_RE = re.compile(r"\bcommit\s+([0-9a-f]{8,40})\b", re.IGNORECASE)
_LEDGER_COMMIT_RANGE_RE = re.compile(r"\bcommits?\s+([0-9a-f]{8,40})\.\.([0-9a-f]{8,40})\b", re.IGNORECASE)
_LEDGER_SHA_RANGE_RE = re.compile(r"\b([0-9a-f]{8,40})\.\.([0-9a-f]{8,40})\b", re.IGNORECASE)
_LEDGER_SHA_RE = re.compile(r"\b[0-9a-f]{8,40}\b", re.IGNORECASE)
_LEDGER_FIELD_RE = re.compile(r"^(?P<label>[A-Z][A-Za-z0-9 /()._-]+):\s*(?P<value>.*)$")
_LEDGER_HEADER_SKIP_PREFIXES = (
    "FLs:",
    "Code surface:",
    "Metrics:",
    "Hypothesis:",
    "Outcome:",
    "Lag:",
    "Validation:",
    "Findings:",
    "Qualitative:",
    "Caveats:",
    "Architecture verdict:",
    "Diagnostic scope note:",
    "Recorder surface",
    "Gate regressions",
    "Required instrumentation fields:",
    "Spent families confirmed",
    "Decision gate:",
)


def _is_multiplayer_ledger_header_line(stripped: str) -> bool:
    if not stripped:
        return False
    if "|" not in stripped:
        return False
    if stripped.startswith(("-", "*")):
        return False
    if stripped.startswith(_LEDGER_HEADER_SKIP_PREFIXES):
        return False
    if stripped.startswith(("###", "##")):
        return False
    if ":" in stripped and not re.search(r"\bcommit\b|\brun\b|\bFL-\d+\b|\bno run\b|\bno commit\b", stripped, re.IGNORECASE):
        return False
    return True


def _append_multiplayer_ledger_block(
    blocks: list[dict[str, Any]],
    *,
    header_line: int | None,
    lines: list[str],
) -> None:
    if header_line is None or not lines:
        return
    parsed = parse_multiplayer_ledger_receipt_block(lines, line_no=header_line)
    if parsed is not None:
        blocks.append(parsed)


def parse_multiplayer_ledger_receipt_block(lines: list[str], *, line_no: int) -> dict[str, Any] | None:
    if not lines:
        return None
    header_lines = [lines[0].strip()]
    field_start = 1
    while field_start < len(lines):
        stripped = lines[field_start].strip()
        if not stripped:
            field_start += 1
            continue
        if _LEDGER_FIELD_RE.match(stripped):
            break
        header_lines.append(stripped)
        field_start += 1
    header = " | ".join(part for part in header_lines if part)
    fields: dict[str, list[str]] = {}
    narrative: list[str] = []
    current_label: str | None = None
    for raw in lines[field_start:]:
        stripped = raw.strip()
        if not stripped:
            if current_label and fields.get(current_label):
                fields[current_label].append("")
            continue
        match = _LEDGER_FIELD_RE.match(stripped)
        if match:
            current_label = match.group("label").strip()
            fields.setdefault(current_label, []).append(match.group("value").strip())
            continue
        if current_label:
            fields.setdefault(current_label, []).append(stripped)
        else:
            narrative.append(stripped)
    if "FLs" not in fields and "Outcome" not in fields and "Code surface" not in fields:
        return None

    def join_field(label: str) -> str | None:
        values = fields.get(label) or []
        text = "\n".join(values).strip()
        return text or None

    commit_refs: list[str] = []
    header_text = " ".join(part for part in header_lines if part)
    for match in _LEDGER_COMMIT_RANGE_RE.finditer(header_text):
        for ref in (match.group(1), match.group(2)):
            if ref not in commit_refs:
                commit_refs.append(ref)
    for match in _LEDGER_COMMIT_RE.finditer(header_text):
        ref = match.group(1)
        if ref not in commit_refs:
            commit_refs.append(ref)
    for match in _LEDGER_SHA_RANGE_RE.finditer(header_text):
        refs = (match.group(1), match.group(2))
        if not all(re.search(r"[a-f]", ref, re.IGNORECASE) for ref in refs):
            continue
        for ref in refs:
            if ref not in commit_refs:
                commit_refs.append(ref)
    for match in _LEDGER_SHA_RE.finditer(header_text):
        ref = match.group(0)
        if not re.search(r"[a-f]", ref, re.IGNORECASE):
            continue
        if ref not in commit_refs:
            commit_refs.append(ref)
    run_ids: list[str] = []
    for run_id in _LEDGER_RUN_ID_RE.findall(header_text):
        if run_id not in run_ids:
            run_ids.append(run_id)
    fl_ids: list[str] = []
    for fl_id in _LEDGER_FL_RE.findall(join_field("FLs") or " ".join(lines)):
        fl_norm = fl_id.upper()
        if fl_norm not in fl_ids:
            fl_ids.append(fl_norm)
    date_context = header.split("|", 1)[0].strip()
    title = None
    if "|" in header:
        parts = [part.strip() for part in header.split("|")]
        if parts:
            title = parts[-1] or None
    return {
        "ledger_line": line_no,
        "header": header,
        "date_context": date_context,
        "title": title,
        "fl_ids": fl_ids,
        "run_ids": run_ids,
        "commit_refs": commit_refs,
        "code_surface": join_field("Code surface"),
        "metrics": join_field("Metrics"),
        "hypothesis": join_field("Hypothesis"),
        "outcome": join_field("Outcome"),
        "validation": join_field("Validation"),
        "qualitative": join_field("Qualitative"),
        "narrative": "\n".join(narrative).strip() or None,
        "raw_text": "\n".join(lines).rstrip(),
    }


def _ledger_block_has_receipt_field(lines: list[str]) -> bool:
    return any(_LEDGER_FIELD_RE.match(raw.strip()) for raw in lines[1:] if raw.strip())


def parse_multiplayer_ledger_receipt_blocks(path: Path) -> list[dict[str, Any]]:
    try:
        raw_lines = path.read_text(encoding="utf-8").splitlines()
    except OSError:
        return []
    start_idx = 0
    for idx, line in enumerate(raw_lines):
        if line.strip() == "## CHRONOLOGICAL HISTORY":
            start_idx = idx + 1
            break
    blocks: list[dict[str, Any]] = []
    current_header_line: int | None = None
    current_lines: list[str] = []
    for idx in range(start_idx, len(raw_lines)):
        line = raw_lines[idx]
        stripped = line.strip()
        if idx > start_idx and line.startswith("## "):
            break
        if stripped.startswith("###"):
            _append_multiplayer_ledger_block(
                blocks,
                header_line=current_header_line,
                lines=current_lines,
            )
            current_header_line = None
            current_lines = []
            continue
        if line.startswith("    ") and _is_multiplayer_ledger_header_line(stripped):
            if current_header_line is not None and current_lines and not _ledger_block_has_receipt_field(current_lines):
                current_lines.append(line)
                continue
            _append_multiplayer_ledger_block(
                blocks,
                header_line=current_header_line,
                lines=current_lines,
            )
            current_header_line = idx + 1
            current_lines = [line]
            continue
        if current_header_line is not None:
            current_lines.append(line)
    _append_multiplayer_ledger_block(
        blocks,
        header_line=current_header_line,
        lines=current_lines,
    )
    return blocks


def _resolve_git_commit_ref(root: Path, ref: str) -> str | None:
    proc = run_git(["rev-parse", f"{ref}^{{commit}}"], root)
    if proc.returncode != 0:
        return None
    resolved = (proc.stdout or "").strip()
    return resolved or None


def _multiplayer_ledger_requested_corpora(run_hits: list[dict[str, Any]]) -> list[str]:
    for hit in run_hits:
        intent_diff = hit.get("run_intent_diff")
        if not isinstance(intent_diff, dict):
            continue
        corpora = normalize_diff_corpora(intent_diff.get("corpora") or [])
        if corpora:
            return corpora
    return ["gameplay", "watchdog"]


def _multiplayer_receipt_warning_tags(fl_statuses: list[dict[str, Any]]) -> list[str]:
    tags: set[str] = set()
    epochs = {
        str(item.get("epoch_status") or "").strip()
        for item in fl_statuses
        if str(item.get("epoch_status") or "").strip()
    }
    kinds = {
        str(kind).strip()
        for item in fl_statuses
        for kind in (item.get("kinds") or [])
        if str(kind).strip()
    }
    subsystems = {
        str(subsystem).strip()
        for item in fl_statuses
        for subsystem in (item.get("subsystems") or [])
        if str(subsystem).strip()
    }
    detail_tags = {
        str(tag).strip()
        for item in fl_statuses
        for tag in (item.get("tags") or [])
        if str(tag).strip()
    }
    areas = {
        str(item.get("area") or "").strip()
        for item in fl_statuses
        if str(item.get("area") or "").strip()
    }
    proof_states = {
        str(item.get("proof_state") or "").strip()
        for item in fl_statuses
        if str(item.get("proof_state") or "").strip()
    }

    if "multiplayer" in areas or "multiplayer" in detail_tags:
        tags.add("multiplayer_context")
    if epochs:
        tags.add("epoch_context")
    if len(epochs) > 1:
        tags.add("cross_epoch_mix")
    if "epoch_boundary" in subsystems:
        tags.add("epoch_boundary")
    if "historical_gate_row" in kinds:
        tags.add("historical_gate_row")
    if "proof_gap" in kinds:
        tags.add("proof_gap")
    if "proof_open" in detail_tags or "OPEN" in proof_states:
        tags.add("open_proof_lane")
    if any(tag.startswith("epoch_") for tag in detail_tags):
        tags.add("historical_epoch_status")
    if "epoch_likely_superseded" in detail_tags:
        tags.add("likely_superseded")
    if "epoch_relay_era_retired" in detail_tags:
        tags.add("relay_era_retired")
    return sorted(tags)


def _classify_multiplayer_ledger_anchor_gap(
    block: dict[str, Any],
    receipt_class: str,
    fl_statuses: list[dict[str, Any]],
) -> dict[str, Any] | None:
    if receipt_class != "insufficient_evidence":
        return None

    header = str(block.get("header") or "").strip()
    header_lower = header.lower()
    reason = "unanchored_history_row"
    if "working tree" in header_lower or "working-tree" in header_lower:
        if "no run" in header_lower:
            reason = "working_tree_no_run"
        else:
            reason = "working_tree_only"
    elif "no run" in header_lower and "no commit" in header_lower:
        reason = "no_run_no_commit"
    elif "audit band" in header_lower:
        reason = "audit_band_without_runtime_anchor"
    elif "no single runtime commit" in header_lower or "no single commit" in header_lower:
        reason = "multi_change_family_without_single_anchor"
    elif "instrumentation" in header_lower:
        reason = "instrumentation_only_without_anchor"

    return {
        "reason": reason,
        "header_facts": {
            "explicit_no_run": "no run" in header_lower,
            "explicit_no_commit": "no commit" in header_lower,
            "working_tree": "working tree" in header_lower or "working-tree" in header_lower,
            "audit_band": "audit band" in header_lower,
            "single_anchor_absent": (
                "no single runtime commit" in header_lower or "no single commit" in header_lower
            ),
        },
        "warning_tags": _multiplayer_receipt_warning_tags(fl_statuses),
    }


def _multiplayer_ledger_anchor(
    *,
    block: dict[str, Any],
    run_hits: list[dict[str, Any]],
    run_map: dict[str, dict[str, Any]],
    commit_hits: list[dict[str, Any]],
    requested_corpora: list[str],
) -> dict[str, Any] | None:
    if run_hits:
        primary = run_hits[0]
        run_id = str(primary.get("run_id") or "").strip()
        run = run_map.get(run_id)
        if run is not None:
            head = str(run.get("git_head_full") or run.get("git_head") or "").strip()
            if head:
                return {
                    "kind": "run",
                    "run_id": run_id,
                    "header": block.get("header"),
                    "head": head,
                    "requested_corpora": requested_corpora,
                    "run": run,
                }
    if commit_hits:
        primary = commit_hits[0]
        head = str(primary.get("commit") or "").strip()
        if head:
            return {
                "kind": "commit",
                "commit_ref": primary.get("ref"),
                "header": block.get("header"),
                "head": head,
                "requested_corpora": requested_corpora,
            }
    return None


def _multiplayer_ledger_aggregate_delta(
    *,
    root: Path,
    previous_anchor: dict[str, Any] | None,
    current_anchor: dict[str, Any] | None,
    requested_corpora: list[str],
) -> dict[str, Any]:
    if isinstance((current_anchor or {}).get("run"), dict):
        stored_payload = _stored_receipt_aggregate_payload(
            current_anchor["run"],
            requested_corpora=requested_corpora,
            pathspecs=diff_pathspecs_for_corpora(requested_corpora),
        )
        if stored_payload is not None:
            return stored_payload
    if previous_anchor is None:
        return {
            "state": "no_prior_anchor",
            "basis": "no earlier resolved multiplayer ledger anchor was available",
            "requested_corpora": requested_corpora,
            "code_surface_unchanged": None,
        }
    if current_anchor is None:
        return {
            "state": "unavailable",
            "basis": "current ledger row has no resolved run or immutable commit anchor",
            "requested_corpora": requested_corpora,
            "previous_anchor": {
                "kind": previous_anchor.get("kind"),
                "run_id": previous_anchor.get("run_id"),
                "commit_ref": previous_anchor.get("commit_ref"),
                "head": previous_anchor.get("head"),
            },
            "code_surface_unchanged": None,
        }
    if isinstance(previous_anchor.get("run"), dict):
        run_a = dict(previous_anchor["run"])
        run_a["git_head"] = previous_anchor.get("head")
    else:
        run_a = {"git_head": previous_anchor.get("head")}
    if isinstance(current_anchor.get("run"), dict):
        run_b = dict(current_anchor["run"])
        run_b["git_head"] = current_anchor.get("head")
    else:
        run_b = {
            "git_head": current_anchor.get("head"),
            "run_intent": {"diff": {"corpora": requested_corpora}},
        }
    payload = resolve_code_diff_payload(
        root=root,
        run_a=run_a,
        run_b=run_b,
        diff_corpora=requested_corpora,
        diff_mode="between_runs",
    )
    if payload.get("state") in {"diff_failed", "unavailable"}:
        recorded_payload = _recorded_codestate_diff_payload(
            run_a=run_a,
            run_b=run_b,
            requested_corpora=requested_corpora,
            note="git diff unavailable; using recorded runtime/watchdog codestate backfill",
        )
        if recorded_payload is not None:
            recorded_payload["git_diff_fallback"] = {
                "state": payload.get("state"),
                "stderr": payload.get("stderr"),
            }
            payload = recorded_payload
    payload["basis"] = "previous resolved multiplayer ledger anchor"
    payload["previous_anchor"] = {
        "kind": previous_anchor.get("kind"),
        "run_id": previous_anchor.get("run_id"),
        "commit_ref": previous_anchor.get("commit_ref"),
        "head": previous_anchor.get("head"),
    }
    payload["current_anchor"] = {
        "kind": current_anchor.get("kind"),
        "run_id": current_anchor.get("run_id"),
        "commit_ref": current_anchor.get("commit_ref"),
        "head": current_anchor.get("head"),
    }
    payload["code_surface_unchanged"] = payload.get("state") in {
        "same_head",
        "no_source_delta",
        "recorded_codestate_same",
    }
    return payload


def build_multiplayer_ledger_receipt_payload(
    root: Path,
    *,
    fl_id_filter: str | None = None,
    receipt_class_filter: str | None = None,
) -> dict[str, Any]:
    ledger_path = multiplayer_ledger_path(root)
    blocks = parse_multiplayer_ledger_receipt_blocks(ledger_path)
    runs, _incomplete = load_all_runs(root)
    run_map = {
        str(run.get("run_id") or "").strip(): run
        for run in runs
        if str(run.get("run_id") or "").strip()
    }
    fl_entries = load_fl_entries(root)
    fl_map = {
        str(entry.get("fl") or "").upper(): entry
        for entry in fl_entries
        if str(entry.get("fl") or "").strip()
    }
    fl_filter = str(fl_id_filter or "").strip().upper() or None
    class_filter = str(receipt_class_filter or "").strip().lower() or None
    receipts: list[dict[str, Any]] = []
    previous_anchor: dict[str, Any] | None = None
    for block in blocks:
        block_fl_ids = [fl_id.upper() for fl_id in (block.get("fl_ids") or [])]
        if fl_filter and fl_filter not in block_fl_ids:
            continue
        run_hits = []
        run_misses = []
        for run_id in block.get("run_ids") or []:
            run = run_map.get(run_id)
            if run is None:
                run_misses.append(run_id)
                continue
            summary_path = runs_dir(root) / run_id / "summary.json"
            run_hits.append(
                {
                    "run_id": run_id,
                    "summary_path": str(summary_path) if summary_path.exists() else None,
                    "git_head": run.get("git_head"),
                    "git_head_full": run.get("git_head_full"),
                    "verdict": run.get("verdict"),
                    "source_snapshot_available": bool((run.get("source_snapshot") or {}).get("available")),
                    "front_door_restoreability_contract": bool(run.get("front_door_restoreability_contract")),
                    "run_intent_diff": _resolve_intent_diff_spec(run),
                    "recorded_codestate": _recorded_codestate_for_run(run),
                }
            )
        commit_hits = []
        commit_misses = []
        for ref in block.get("commit_refs") or []:
            resolved = _resolve_git_commit_ref(root, ref)
            if resolved:
                commit_hits.append({"ref": ref, "commit": resolved})
            else:
                commit_misses.append(ref)
        requested_corpora = _multiplayer_ledger_requested_corpora(run_hits)
        current_anchor = _multiplayer_ledger_anchor(
            block=block,
            run_hits=run_hits,
            run_map=run_map,
            commit_hits=commit_hits,
            requested_corpora=requested_corpora,
        )
        fl_hits = [fl_id for fl_id in block_fl_ids if fl_id in fl_map]
        fl_misses = [fl_id for fl_id in block_fl_ids if fl_id not in fl_map]
        fl_statuses = [_fl_status_details(fl_map, fl_id) for fl_id in fl_hits]

        explicit_no_run = "no run" in str(block.get("header") or "").lower()
        explicit_no_commit = "no commit" in str(block.get("header") or "").lower()
        if run_hits and not run_misses:
            receipt_class = "runtime_receipt"
            basis = "explicit ledger run ids resolved to local watchdog summaries"
        elif commit_hits and not explicit_no_commit:
            receipt_class = "derived_receipt"
            basis = "explicit immutable commit refs resolved from the multiplayer ledger"
        else:
            receipt_class = "insufficient_evidence"
            if explicit_no_run and explicit_no_commit:
                basis = "ledger block explicitly records no run and no immutable commit anchor"
            elif explicit_no_run:
                basis = "ledger block names no runtime artifact and no resolved immutable commit anchor"
            else:
                basis = "no fully-resolved local runtime receipt or immutable commit anchor was available"
        if class_filter and receipt_class != class_filter:
            continue
        evidence_gap = _classify_multiplayer_ledger_anchor_gap(
            block,
            receipt_class,
            fl_statuses,
        )
        receipts.append(
            {
                "ledger_line": block.get("ledger_line"),
                "header": block.get("header"),
                "date_context": block.get("date_context"),
                "title": block.get("title"),
                "receipt_class": receipt_class,
                "basis": basis,
                "fl_ids": block_fl_ids,
                "run_ids": list(block.get("run_ids") or []),
                "commit_refs": list(block.get("commit_refs") or []),
                "anchors": {
                    "runs_found": run_hits,
                    "runs_missing": run_misses,
                    "commits_resolved": commit_hits,
                    "commits_missing": commit_misses,
                    "fls_found": fl_hits,
                    "fls_missing": fl_misses,
                },
                "fl_statuses": fl_statuses,
                "evidence_gap": evidence_gap,
                "aggregate_code_surface": _multiplayer_ledger_aggregate_delta(
                    root=root,
                    previous_anchor=previous_anchor,
                    current_anchor=current_anchor,
                    requested_corpora=requested_corpora,
                ),
                "receipt": {
                    "code_surface": block.get("code_surface"),
                    "metrics": block.get("metrics"),
                    "hypothesis": block.get("hypothesis"),
                    "outcome": block.get("outcome"),
                    "validation": block.get("validation"),
                    "qualitative": block.get("qualitative"),
                },
            }
        )
        if current_anchor is not None:
            previous_anchor = current_anchor
    counts = Counter(item["receipt_class"] for item in receipts)
    return {
        "command": "fl ledger-receipts",
        "source": str(ledger_path.relative_to(root) if ledger_path.is_relative_to(root) else ledger_path),
        "entry_count": len(receipts),
        "receipt_counts": {
            "runtime_receipt": counts.get("runtime_receipt", 0),
            "derived_receipt": counts.get("derived_receipt", 0),
            "insufficient_evidence": counts.get("insufficient_evidence", 0),
        },
        "receipts": receipts,
    }


def load_run_by_id(root: Path, run_id: str) -> dict:
    rd = runs_dir(root)
    # Try directory form first
    candidate = rd / run_id / "summary.json"
    if candidate.exists():
        return load_run(candidate)
    # Try flat failed-*.json form
    candidate = rd / f"{run_id}.json"
    if candidate.exists():
        return load_run(candidate)
    live = _live_tmp_artifact_dir_for_run(run_id)
    if live is not None:
        run = _run_record_from_live_artifact(live)
        if run is not None:
            return run
    sys.exit(f"error: run not found: {run_id}")


# ---------------------------------------------------------------------------
# Gate state helpers
# ---------------------------------------------------------------------------


def gate_state(run: dict, gate: str) -> str:
    """Return 'true', 'false', 'null', or 'unknown' for a gate in a run."""
    gate = canonical_gate_name(gate)
    false_gates = run.get("false_gates")
    null_gates = run.get("null_gates")
    if false_gates is None and null_gates is None:
        return "unknown"  # failed/blocked run with no gate data
    if not run.get("_canonical_gate_lists"):
        false_gates = canonical_gate_list(false_gates)
        null_gates = canonical_gate_list(null_gates)
    false_gates = false_gates or []
    null_gates = null_gates or []
    if gate in false_gates:
        return "false"
    if gate in null_gates:
        return "null"
    return "true"


def split_gate_groups(gates: list[str] | None) -> tuple[list[str] | None, list[str], list[str]]:
    """Return (active, diagnostic_only, deprecated) gate lists preserving order."""
    if gates is None:
        return None, [], []
    gates = canonical_gate_list(gates) or []
    active = [g for g in gates if g not in DEPRECATED_GATES and g not in DIAGNOSTIC_ONLY_GATES]
    diagnostic = [g for g in gates if g in DIAGNOSTIC_ONLY_GATES]
    deprecated = [g for g in gates if g in DEPRECATED_GATES]
    return active, diagnostic, deprecated


def all_known_gates(runs: list) -> set:
    """All gate names seen across any run (that were ever not-true)."""
    result = set()
    for r in runs:
        if r.get("_canonical_gate_lists"):
            result.update(r.get("false_gates") or [])
            result.update(r.get("null_gates") or [])
        else:
            result.update(canonical_gate_list(r.get("false_gates")) or [])
            result.update(canonical_gate_list(r.get("null_gates")) or [])
    return result


def load_watchdog_gate_registry(root: Path) -> set[str]:
    path = root / "scripts" / "multiplayer_visual_watchdog.js"
    if not path.exists():
        return set()
    gates: set[str] = set()
    gate_re = re.compile(r"""['"]([a-zA-Z_][a-zA-Z0-9_\-]*)['"]""")
    in_array = False
    try:
        with open(path, encoding="utf-8", errors="replace") as handle:
            for line in handle:
                if not in_array:
                    if re.search(r"const\s+allGateKeys\s*=\s*\[", line):
                        in_array = True
                    continue
                for match in gate_re.finditer(line):
                    gates.add(canonical_gate_name(match.group(1)))
                if "];" in line or line.strip() == "];":
                    break
    except OSError:
        return set()
    return gates


# ---------------------------------------------------------------------------
# Formatting helpers
# ---------------------------------------------------------------------------


def fmt_ts(ts_str, short: bool = False) -> str:
    if not ts_str:
        return "-"
    try:
        dt = datetime.fromisoformat(ts_str)
        if short:
            return dt.strftime("%Y-%m-%d")
        return dt.strftime("%Y-%m-%d %H:%M")
    except Exception:
        return ts_str[:16] if ts_str else "-"


def fmt_gates(passed, total) -> str:
    if passed is None or total is None:
        return "-"
    return f"{passed}/{total}"


def fmt_count(val) -> str:
    if val is None:
        return "-"
    return str(len(val)) if isinstance(val, list) else str(val)


def fmt_bool(val) -> str:
    """'yes' / 'NO' / '-' — uppercase NO so failures stand out."""
    if val is None:
        return "-"
    return "yes" if val else "NO"


def fmt_delta(run: dict) -> str:
    """Format gate_deltas as -R/+C (regressions/recoveries). '-' if no delta data."""
    gd = run.get("gate_deltas")
    if gd is None:
        return "-"
    regs = len(gd.get("regressions_true_to_false") or [])
    recs = len(gd.get("recoveries_to_true") or [])
    return f"-{regs}/+{recs}"


def tag_exists(run: dict, tags: set) -> str:
    tag = run.get("git_tag")
    if not tag:
        return "-"
    return "yes" if tag in tags else "no"


def transcript_exists(run: dict) -> bool:
    jt = run.get("journal_transcript") or {}
    paths = [
        jt.get("jsonl_path"),
        jt.get("txt_path"),
        run.get("journal_transcript_path"),
        run.get("journal_transcript_text_path"),
    ]
    return any(bool(p) for p in paths)


def transcript_status(run: dict) -> str:
    jt = run.get("journal_transcript") or {}
    if jt.get("ok") is True:
        return "yes"
    if transcript_exists(run):
        return "partial"
    return "-"


def next_action_text(run: dict) -> str:
    # Prefer a recomputed recommendation: archived summaries can carry stale
    # `next_action` strings after gate taxonomy / heuristics change.
    stored = run.get("next_action")
    recommended = recommend_next_action(run)
    # If we can't derive anything more specific than the generic fallback,
    # preserve an explicit stored next_action when present.
    if stored and recommended and recommended.startswith("Review the summary and update the plan entry point"):
        return stored
    return recommended or stored or "-"


def compact_text(text: str, max_len: int = 72) -> str:
    text = " ".join(str(text).split())
    if len(text) <= max_len:
        return text
    return text[: max_len - 1] + "…"


def _load_text_file(path: Path, max_lines: int | None = None) -> str | None:
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return None
    lines = text.splitlines()
    if max_lines is not None and len(lines) > max_lines:
        lines = lines[:max_lines]
        lines.append(f"... truncated after {max_lines} lines ...")
    return "\n".join(lines).rstrip()


def _load_transcript_from_jsonl(path: Path, max_lines: int) -> str | None:
    try:
        lines = path.read_text(encoding="utf-8").splitlines()
    except OSError:
        return None
    rendered = []
    for raw in lines[:max_lines]:
        try:
            entry = json.loads(raw)
        except json.JSONDecodeError:
            rendered.append(raw)
            continue
        event = entry.get("event") or entry.get("type") or "journal"
        payload = {k: v for k, v in entry.items() if k not in {"event", "type"}}
        rendered.append(f"{event}: {json.dumps(payload, sort_keys=True, default=str)}")
    if len(lines) > max_lines:
        rendered.append(f"... truncated after {max_lines} lines ...")
    return "\n".join(rendered).rstrip()


def render_transcript(run: dict, root: Path, max_lines: int = 120) -> str | None:
    jt = run.get("journal_transcript") or {}
    text_path = jt.get("txt_path") or run.get("journal_transcript_text_path")
    if text_path:
        path = Path(text_path)
        if not path.is_absolute():
            path = root / path
        if path.exists():
            text = _load_text_file(path, max_lines=max_lines)
            if text:
                return text
    jsonl_path = jt.get("jsonl_path") or run.get("journal_transcript_path")
    if jsonl_path:
        path = Path(jsonl_path)
        if not path.is_absolute():
            path = root / path
        if path.exists():
            return _load_transcript_from_jsonl(path, max_lines=max_lines)
    return None


def print_table(headers, rows):
    """Tabular output — delegates to cli_style.table()."""
    print(cli_style.table(headers, rows))


def run_git(args: list[str], root: Path) -> subprocess.CompletedProcess:
    return subprocess.run(
        ["git", *args],
        capture_output=True,
        text=True,
        cwd=root,
    )


