_NON_DIAGNOSTIC_DIFF_CORPORA = frozenset({"all", "auto"})
_DIAGNOSTIC_SCOPE_LABELS = {
    "runtime": "runtime candidate",
    "proof-harness": "proof-harness candidate",
    "launcher": "launcher candidate",
    "docs-only": "docs-only candidate",
    "mixed": "mixed-scope candidate",
    "unspecified": "unspecified candidate scope",
}
_DIAGNOSTIC_SCOPE_REASON_LABELS = {
    "missing_diagnostic_scope": "scope-missing",
    "mixed_diagnostic_scope": "scope-mixed",
    "dirty_paths_outside_diagnostic_scope": "scope-dirty-outside",
}


def normalize_diff_corpora(raw_values: Any) -> list[str]:
    if raw_values is None:
        return []
    if isinstance(raw_values, str):
        tokens = [part.strip() for part in raw_values.split(",")]
    elif isinstance(raw_values, (list, tuple, set)):
        tokens = []
        for raw in raw_values:
            tokens.extend(str(raw or "").split(","))
        tokens = [token.strip() for token in tokens]
    else:
        tokens = [str(raw_values).strip()]
    out: list[str] = []
    seen: set[str] = set()
    for token in tokens:
        if not token:
            continue
        normalized = DIFF_CORPUS_ALIAS.get(token.lower())
        if not normalized:
            continue
        if normalized in seen:
            continue
        seen.add(normalized)
        out.append(normalized)
    return out


def diff_corpus_label(corpora: list[str] | None) -> str:
    values = corpora or []
    if not values:
        return "all source files"
    if values == ["all"]:
        return "all source files"
    return ", ".join(values)


def diff_path_corpora(path: str) -> set[str]:
    normalized = str(path or "").replace("\\", "/").lstrip("./")
    corpora: set[str] = set()
    if (
        normalized.startswith("engine/")
        or normalized.startswith("server/")
        or normalized.startswith("web/")
        or normalized.startswith("assets/actor_visual_profiles/")
        or normalized.startswith("scripts/pipeline/")
        or (
            re.match(r"^scripts/multiplayer.*\.(js|py)$", normalized)
            and normalized != "scripts/multiplayer_visual_watchdog.js"
        )
    ):
        corpora.add("gameplay")
    if (
        re.match(r"^scripts/watchdog_.*\.py$", normalized)
        or normalized in {
            "scripts/watchdog_source.py",
            "scripts/analyze_runs.py",
            "scripts/analyze_failure_log.py",
            "scripts/multiplayer_visual_watchdog.js",
            "scripts/simplified_watchdog_vps_launcher.py",
        }
    ):
        corpora.add("watchdog")
    if (
        normalized == "scripts/launcher.py"
        or normalized.startswith("scripts/launcher_lib/")
        or normalized.startswith("scripts/launcher_ui/")
    ):
        corpora.add("launcher")
    if normalized in DIFF_CORPUS_PATHSPECS["docs"]:
        corpora.add("docs")
    return corpora


def _diagnostic_scope_path_matches(path: str, scope_path: str) -> bool:
    clean_path = str(path or "").strip().replace("\\", "/").lstrip("./")
    clean_scope = str(scope_path or "").strip().replace("\\", "/").lstrip("./")
    if not clean_path or not clean_scope:
        return False
    if clean_scope.endswith("/"):
        return clean_path.startswith(clean_scope)
    return clean_path == clean_scope or clean_path.startswith(clean_scope + "/")


def _scope_labels_for_path(path: str) -> list[str]:
    labels = set(diff_path_corpora(path))
    normalized = str(path or "").replace("\\", "/").lstrip("./")
    if normalized in DIFF_CORPUS_PATHSPECS["docs"]:
        labels.add("docs")
    return sorted(labels)


def _derive_diagnostic_scope(diff_spec: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(diff_spec, dict):
        return None
    corpora = normalize_diff_corpora(diff_spec.get("corpora") or diff_spec.get("corpus"))
    explicit_paths = [
        str(path).strip().replace("\\", "/").lstrip("./")
        for path in (diff_spec.get("paths") or [])
        if str(path).strip()
    ]
    if not corpora and not explicit_paths:
        return None

    allowed_paths: list[str] = []
    seen_allowed: set[str] = set()
    for corpus in corpora:
        if corpus in _NON_DIAGNOSTIC_DIFF_CORPORA:
            continue
        for scope_path in DIAGNOSTIC_SCOPE_PATHS.get(corpus, ()):
            if scope_path in seen_allowed:
                continue
            seen_allowed.add(scope_path)
            allowed_paths.append(scope_path)
    for scope_path in explicit_paths:
        if scope_path in seen_allowed:
            continue
        seen_allowed.add(scope_path)
        allowed_paths.append(scope_path)

    domain_labels: set[str] = set()
    if any(corpus in _NON_DIAGNOSTIC_DIFF_CORPORA for corpus in corpora):
        domain_labels.add("mixed")
    for corpus in corpora:
        if corpus in DIAGNOSTIC_SCOPE_PATHS and corpus != "docs":
            domain_labels.add(corpus)

    explicit_path_labels: dict[str, list[str]] = {}
    for scope_path in explicit_paths:
        labels = _scope_labels_for_path(scope_path)
        explicit_path_labels[scope_path] = labels
        non_doc_labels = [label for label in labels if label != "docs"]
        if non_doc_labels:
            domain_labels.update(non_doc_labels)
        elif labels and all(label == "docs" for label in labels):
            continue
        else:
            domain_labels.add("other")

    diagnostic_labels = sorted(label for label in domain_labels if label != "mixed")
    docs_only_declared = (
        bool(corpora or explicit_paths)
        and not diagnostic_labels
        and not domain_labels
        and all(corpus == "docs" for corpus in corpora)
        and all(
            labels and all(label == "docs" for label in labels)
            for labels in explicit_path_labels.values()
        )
    )
    if docs_only_declared:
        candidate_class = "docs-only"
    elif diagnostic_labels == ["gameplay"]:
        candidate_class = "runtime"
    elif diagnostic_labels == ["watchdog"]:
        candidate_class = "proof-harness"
    elif diagnostic_labels == ["launcher"]:
        candidate_class = "launcher"
    elif not diagnostic_labels and not domain_labels:
        candidate_class = "unspecified"
    else:
        candidate_class = "mixed"

    return {
        "declared_corpora": corpora,
        "explicit_paths": explicit_paths,
        "explicit_path_labels": explicit_path_labels,
        "allowed_paths": allowed_paths,
        "candidate_class": candidate_class,
        "diagnostic": candidate_class in {"runtime", "proof-harness", "launcher", "docs-only"},
    }


def diagnostic_scope_path_matches(path: str, scope_path: str) -> bool:
    """Public wrapper so other watchdog tooling can share the same scope owner."""
    return _diagnostic_scope_path_matches(path, scope_path)


def derive_diagnostic_scope(diff_spec: dict[str, Any] | None) -> dict[str, Any] | None:
    """Public wrapper for canonical diagnostic-scope derivation."""
    return _derive_diagnostic_scope(diff_spec)


def scope_outside_paths(
    paths: list[str] | tuple[str, ...] | set[str] | None,
    scope: dict[str, Any] | None,
) -> list[str]:
    """Return normalized paths that fall outside the declared diagnostic scope."""
    normalized_paths = [
        str(path or "").strip().replace("\\", "/").lstrip("./")
        for path in (paths or [])
        if str(path or "").strip()
    ]
    if not normalized_paths:
        return []
    allowed_paths = [
        str(path or "").strip().replace("\\", "/").lstrip("./")
        for path in ((scope or {}).get("allowed_paths") or [])
        if str(path or "").strip()
    ]
    if not allowed_paths:
        return normalized_paths
    outside: list[str] = []
    for path in normalized_paths:
        if not any(diagnostic_scope_path_matches(path, allowed) for allowed in allowed_paths):
            outside.append(path)
    return outside


def diagnostic_scope_for_run(run: dict[str, Any] | None) -> dict[str, Any] | None:
    contract = (run or {}).get("front_door_restoreability_contract") or {}
    if isinstance(contract, dict):
        scope = contract.get("diagnostic_scope")
        if isinstance(scope, dict) and scope:
            return scope
    return derive_diagnostic_scope(_resolve_intent_diff_spec(run))


def diagnostic_scope_label(scope: dict[str, Any] | None) -> str | None:
    if not isinstance(scope, dict):
        return None
    return _DIAGNOSTIC_SCOPE_LABELS.get(
        str(scope.get("candidate_class") or "").strip(),
        str(scope.get("candidate_class") or "").strip() or None,
    )


def filter_paths_for_corpora(paths: list[str], corpora: list[str] | None) -> list[str]:
    normalized_corpora = normalize_diff_corpora(corpora)
    if not normalized_corpora or "all" in normalized_corpora:
        return [str(path or "").strip() for path in paths if str(path or "").strip()]
    out: list[str] = []
    for path in paths:
        text = str(path or "").strip()
        if not text:
            continue
        if diff_path_corpora(text) & set(normalized_corpora):
            out.append(text)
    return out


def diff_pathspecs_for_corpora(
    corpora: list[str] | None,
    *,
    explicit_paths: list[str] | None = None,
) -> list[str]:
    explicit = [str(path or "").strip() for path in (explicit_paths or []) if str(path or "").strip()]
    if explicit:
        return explicit
    normalized_corpora = normalize_diff_corpora(corpora)
    if not normalized_corpora or "all" in normalized_corpora:
        return list(SOURCE_CODE_PATHSPECS)
    out: list[str] = []
    seen: set[str] = set()
    for corpus in normalized_corpora:
        for pathspec in DIFF_CORPUS_PATHSPECS.get(corpus, []):
            if pathspec in seen:
                continue
            seen.add(pathspec)
            out.append(pathspec)
    return out or list(SOURCE_CODE_PATHSPECS)


def _git_diff_text(root: Path, from_ref: str, to_ref: str, pathspecs: list[str]) -> tuple[subprocess.CompletedProcess, str]:
    proc = run_git(
        [
            "diff",
            "--unified=1",
            "--no-ext-diff",
            "--no-color",
            from_ref,
            to_ref,
            "--",
            *pathspecs,
        ],
        root,
    )
    return proc, (proc.stdout or "").rstrip()


_PATCH_HUNK_CONTEXT_RE = re.compile(r"^@@ [^@]* @@ ?(.*)$")


def _summarize_patch_text(patch_text: str) -> tuple[list[str], int, int, dict[str, list[str]]]:
    files_changed: list[str] = []
    seen: set[str] = set()
    insertions = 0
    deletions = 0
    changed_functions: dict[str, list[str]] = {}
    current_file: str | None = None
    for line in patch_text.splitlines():
        if line.startswith("diff --git a/"):
            parts = line.split()
            if len(parts) >= 4:
                right = parts[3]
                path = right[2:] if right.startswith("b/") else right
                if path != "/dev/null" and path not in seen:
                    seen.add(path)
                    files_changed.append(path)
                current_file = path if path != "/dev/null" else None
            continue
        if line.startswith("@@"):
            if current_file:
                match = _PATCH_HUNK_CONTEXT_RE.match(line)
                context = match.group(1).strip() if match else ""
                if context:
                    changed_functions.setdefault(current_file, [])
                    if context not in changed_functions[current_file]:
                        changed_functions[current_file].append(context)
            continue
        if line.startswith("+++ ") or line.startswith("--- "):
            continue
        if line.startswith("+"):
            insertions += 1
        elif line.startswith("-"):
            deletions += 1
    return files_changed, insertions, deletions, changed_functions


def _git_patch_payload(
    *,
    patch_text: str,
    head_a: str | None,
    head_b: str | None,
    requested_corpora: list[str],
    pathspecs: list[str],
    strategy: str,
    diff_backend: str,
    state: str,
    note: str | None = None,
    extra: dict[str, Any] | None = None,
) -> dict[str, Any]:
    files_changed, insertions, deletions, changed_functions = _summarize_patch_text(patch_text)
    payload: dict[str, Any] = {
        "state": state,
        "head_a": head_a,
        "head_b": head_b,
        "requested_corpora": requested_corpora,
        "pathspecs": pathspecs,
        "strategy": strategy,
        "diff_backend": diff_backend,
        "files_changed": files_changed,
        "insertions": insertions,
        "deletions": deletions,
        "patch_sha256": hashlib.sha256(patch_text.encode("utf-8")).hexdigest(),
        "text": fmt_code_diff(patch_text) if patch_text else None,
    }
    if note:
        payload["note"] = note
    if changed_functions:
        payload["changed_functions"] = changed_functions
    if extra:
        payload.update(extra)
    return payload


def _git_commit_parent(root: Path, commit_ref: str) -> str | None:
    proc = run_git(["rev-parse", f"{commit_ref}^"], root)
    if proc.returncode != 0:
        return None
    parent = (proc.stdout or "").strip()
    return parent or None


def _git_latest_relevant_commit(root: Path, head_ref: str, pathspecs: list[str]) -> str | None:
    proc = run_git(
        ["log", "-n", "1", "--format=%H", head_ref, "--", *pathspecs],
        root,
    )
    if proc.returncode != 0:
        return None
    commit_ref = (proc.stdout or "").strip()
    return commit_ref or None


def _resolve_intent_diff_spec(run: dict[str, Any] | None) -> dict[str, Any]:
    intent = (run or {}).get("run_intent") or {}
    raw_diff = intent.get("diff") if isinstance(intent, dict) else {}
    if not isinstance(raw_diff, dict):
        raw_diff = {}
    corpora = normalize_diff_corpora(raw_diff.get("corpora") or raw_diff.get("corpus"))
    explicit_paths = [str(path).strip() for path in (raw_diff.get("paths") or []) if str(path).strip()]
    resolved = {
        "corpora": corpora,
        "mode": str(raw_diff.get("mode") or "").strip() or None,
        "base_ref": str(raw_diff.get("base_ref") or "").strip() or None,
        "head_ref": str(raw_diff.get("head_ref") or "").strip() or None,
        "paths": explicit_paths,
    }
    if str(raw_diff.get("base_commit_resolved") or "").strip():
        resolved["base_commit_resolved"] = str(raw_diff.get("base_commit_resolved")).strip()
    if str(raw_diff.get("head_commit_resolved") or "").strip():
        resolved["head_commit_resolved"] = str(raw_diff.get("head_commit_resolved")).strip()
    if str(raw_diff.get("resolved_at") or "").strip():
        resolved["resolved_at"] = str(raw_diff.get("resolved_at")).strip()
    if str(raw_diff.get("resolution_strategy") or "").strip():
        resolved["resolution_strategy"] = str(raw_diff.get("resolution_strategy")).strip()
    if str(raw_diff.get("resolution_warning") or "").strip():
        resolved["resolution_warning"] = str(raw_diff.get("resolution_warning")).strip()
    if str(raw_diff.get("resolution_error") or "").strip():
        resolved["resolution_error"] = str(raw_diff.get("resolution_error")).strip()
    diff_snapshot = raw_diff.get("diff_snapshot")
    if isinstance(diff_snapshot, dict) and diff_snapshot:
        resolved["diff_snapshot"] = diff_snapshot
    aggregate = raw_diff.get("aggregate_since_previous_comparable_run")
    if isinstance(aggregate, dict) and aggregate:
        resolved["aggregate_since_previous_comparable_run"] = aggregate
    return resolved


def _stored_receipt_diff_payload(
    run: dict[str, Any],
    *,
    requested_corpora: list[str],
    pathspecs: list[str],
    strategy: str,
    note: str,
) -> dict[str, Any] | None:
    intent_diff = _resolve_intent_diff_spec(run)
    snapshot = intent_diff.get("diff_snapshot")
    if not isinstance(snapshot, dict) or not snapshot:
        return None
    return {
        "state": str(snapshot.get("state") or "diff").strip() or "diff",
        "head_a": None,
        "head_b": str(run.get("git_head") or "").strip() or None,
        "requested_corpora": requested_corpora,
        "pathspecs": pathspecs,
        "strategy": strategy,
        "diff_backend": "receipt_snapshot",
        "base_ref": intent_diff.get("base_commit_resolved"),
        "head_ref": intent_diff.get("head_commit_resolved"),
        "note": note,
        "text": snapshot.get("patch_text"),
        "files_changed": snapshot.get("files_changed"),
        "insertions": snapshot.get("insertions"),
        "deletions": snapshot.get("deletions"),
        "changed_functions": snapshot.get("changed_functions"),
        "patch_sha256": snapshot.get("patch_sha256"),
    }


def _stored_receipt_aggregate_payload(
    run: dict[str, Any],
    *,
    requested_corpora: list[str],
    pathspecs: list[str],
) -> dict[str, Any] | None:
    intent_diff = _resolve_intent_diff_spec(run)
    aggregate = intent_diff.get("aggregate_since_previous_comparable_run")
    if not isinstance(aggregate, dict) or not aggregate:
        return None
    payload = dict(aggregate)
    payload.setdefault("requested_corpora", requested_corpora)
    payload.setdefault("pathspecs", pathspecs)
    payload.setdefault("basis", "persisted runtime aggregate since previous comparable run")
    payload.setdefault(
        "code_surface_unchanged",
        payload.get("state") in {"same_head", "no_source_delta"},
    )
    return payload


def _recorded_runtime_manifest(run: dict[str, Any] | None) -> tuple[str | None, dict[str, Any]]:
    if not isinstance(run, dict):
        return None, {}
    runtime_probe = run.get("runtime_probe") if isinstance(run.get("runtime_probe"), dict) else {}
    runtime_probe_manifest = runtime_probe.get("manifest")
    if isinstance(runtime_probe_manifest, dict) and runtime_probe_manifest:
        return "runtime_probe.manifest", runtime_probe_manifest
    for field_name in ("pre_deploy_manifest", "pre_smoke_manifest"):
        manifest = run.get(field_name)
        if isinstance(manifest, dict) and manifest:
            return field_name, manifest
    return None, {}


def _recorded_codestate_for_run(run: dict[str, Any] | None) -> dict[str, Any]:
    manifest_source, runtime_manifest = _recorded_runtime_manifest(run)
    web = runtime_manifest.get("web") if isinstance(runtime_manifest.get("web"), dict) else {}
    server = runtime_manifest.get("server") if isinstance(runtime_manifest.get("server"), dict) else {}
    runtime = runtime_manifest.get("runtime") if isinstance(runtime_manifest.get("runtime"), dict) else {}
    measurement = (
        run.get("measurement_provenance")
        if isinstance((run or {}).get("measurement_provenance"), dict)
        else {}
    )
    contract = (
        run.get("front_door_restoreability_contract")
        if isinstance((run or {}).get("front_door_restoreability_contract"), dict)
        else {}
    )
    snapshot = run.get("source_snapshot") if isinstance((run or {}).get("source_snapshot"), dict) else {}
    return {
        "repo_git_head": str((run or {}).get("git_head") or "").strip() or None,
        "repo_git_head_full": str((run or {}).get("git_head_full") or "").strip() or None,
        "repo_source_ref": str((run or {}).get("source_ref") or "").strip() or None,
        "runtime_manifest_source": manifest_source,
        "runtime_slot_source_ref": str(runtime_manifest.get("source_ref") or "").strip() or None,
        "runtime_slot_gameplay_ref": str(runtime_manifest.get("gameplay_ref") or "").strip() or None,
        "runtime_slot_build_id": str(runtime_manifest.get("build_id") or "").strip() or None,
        "runtime_tree_manifest_sha256": str(runtime.get("tree_manifest_sha256") or "").strip() or None,
        "runtime_build_inputs_sha256": str(runtime.get("build_inputs_sha256") or "").strip() or None,
        "server_binary_sha256": str(server.get("binary_sha256") or "").strip() or None,
        "web_index_html_sha256": str(web.get("index_html_sha256") or "").strip() or None,
        "web_index_js_sha256": str(web.get("index_js_sha256") or "").strip() or None,
        "web_index_wasm_sha256": str(web.get("index_wasm_sha256") or "").strip() or None,
        "web_index_data_sha256": str(web.get("index_data_sha256") or "").strip() or None,
        "actor_visual_profile_sha256": str(web.get("actor_visual_profile_sha256") or web.get("appearance_bundle_sha256") or "").strip() or None,
        "compile_report_sha256": str(web.get("compile_report_sha256") or "").strip() or None,
        "measurement_provenance": dict(measurement) if measurement else {},
        "source_snapshot_available": bool(snapshot.get("available")),
        "restoreability_contract_available": bool(contract),
        "restoreability_source_ref": str(
            contract.get("source_ref_full") or contract.get("source_ref") or ""
        ).strip() or None,
    }


def _recorded_codestate_values(
    codestate: dict[str, Any] | None,
    *,
    requested_corpora: list[str],
) -> dict[str, Any]:
    if not isinstance(codestate, dict):
        return {}
    normalized_corpora = normalize_diff_corpora(requested_corpora) or ["all"]
    include_runtime = "all" in normalized_corpora or any(
        corpus in {"gameplay", "launcher"} for corpus in normalized_corpora
    )
    include_watchdog = "all" in normalized_corpora or "watchdog" in normalized_corpora
    values: dict[str, Any] = {}
    if include_runtime:
        runtime_pairs = {
            "repo.git_head_full": codestate.get("repo_git_head_full"),
            "repo.source_ref": codestate.get("repo_source_ref"),
            "runtime.manifest_source": codestate.get("runtime_manifest_source"),
            "runtime.slot.source_ref": codestate.get("runtime_slot_source_ref"),
            "runtime.slot.gameplay_ref": codestate.get("runtime_slot_gameplay_ref"),
            "runtime.slot.build_id": codestate.get("runtime_slot_build_id"),
            "runtime.tree_manifest_sha256": codestate.get("runtime_tree_manifest_sha256"),
            "runtime.build_inputs_sha256": codestate.get("runtime_build_inputs_sha256"),
            "runtime.server.binary_sha256": codestate.get("server_binary_sha256"),
            "runtime.web.index_html_sha256": codestate.get("web_index_html_sha256"),
            "runtime.web.index_js_sha256": codestate.get("web_index_js_sha256"),
            "runtime.web.index_wasm_sha256": codestate.get("web_index_wasm_sha256"),
            "runtime.web.index_data_sha256": codestate.get("web_index_data_sha256"),
            "runtime.web.actor_visual_profile_sha256": codestate.get("actor_visual_profile_sha256"),
            "runtime.web.compile_report_sha256": codestate.get("compile_report_sha256"),
        }
        values.update({key: value for key, value in runtime_pairs.items() if value is not None})
    if include_watchdog:
        measurement = (
            codestate.get("measurement_provenance")
            if isinstance(codestate.get("measurement_provenance"), dict)
            else {}
        )
        watchdog_pairs = {
            "watchdog.measurement.watchdog_sha256": measurement.get("watchdog_sha256"),
            "watchdog.measurement.analyzer_sha256": measurement.get("analyzer_sha256"),
            "watchdog.measurement.gate_config_sha256": measurement.get("gate_config_sha256"),
        }
        values.update({key: value for key, value in watchdog_pairs.items() if value is not None})
    return values


def _recorded_codestate_diff_payload(
    *,
    run_a: dict[str, Any] | None,
    run_b: dict[str, Any] | None,
    requested_corpora: list[str],
    note: str,
) -> dict[str, Any] | None:
    codestate_a = _recorded_codestate_for_run(run_a)
    codestate_b = _recorded_codestate_for_run(run_b)
    values_a = _recorded_codestate_values(codestate_a, requested_corpora=requested_corpora)
    values_b = _recorded_codestate_values(codestate_b, requested_corpora=requested_corpora)
    if not values_a and not values_b:
        return None
    changed_fields = [
        field_name
        for field_name in sorted(set(values_a) | set(values_b))
        if values_a.get(field_name) != values_b.get(field_name)
    ]
    return {
        "state": "recorded_codestate_same" if not changed_fields else "recorded_codestate_delta",
        "head_a": str((run_a or {}).get("git_head") or "").strip() or None,
        "head_b": str((run_b or {}).get("git_head") or "").strip() or None,
        "requested_corpora": requested_corpora,
        "pathspecs": diff_pathspecs_for_corpora(requested_corpora),
        "strategy": "recorded_codestate",
        "diff_backend": "recorded_codestate",
        "note": note,
        "changed_fields": changed_fields,
        "codestate_a": values_a,
        "codestate_b": values_b,
        "code_surface_unchanged": not changed_fields,
    }


def _reconstruct_receipt_diff_payload(root: Path, run: dict[str, Any] | None) -> dict[str, Any] | None:
    diff_spec = _resolve_intent_diff_spec(run)
    if not diff_spec:
        return None
    requested_corpora = normalize_diff_corpora(diff_spec.get("corpora") or []) or ["all"]
    requested_mode = (
        str(diff_spec.get("mode") or "").strip().lower()
        or ("latest_relevant" if requested_corpora != ["all"] else "between_runs")
    )
    if requested_mode == "between_runs" and not diff_spec.get("base_ref") and not diff_spec.get("head_ref"):
        return None
    head_ref = str((run or {}).get("git_head_full") or (run or {}).get("git_head") or "").strip()
    if not head_ref:
        return None
    run_ref = dict(run or {})
    run_ref["git_head"] = head_ref
    run_ref["git_head_full"] = head_ref
    return resolve_code_diff_payload(
        root=root,
        run_a=run_ref,
        run_b=run_ref,
        diff_corpora=requested_corpora,
        diff_mode=diff_spec.get("mode"),
        diff_paths=diff_spec.get("paths"),
    )


def _camera_qe_surface_for_show(run: dict[str, Any]) -> dict[str, Any] | None:
    camera_qe = run.get("camera_qe_jitter")
    if isinstance(camera_qe, dict) and camera_qe:
        payload = dict(camera_qe)
    else:
        try:
            metrics, _source = _load_metrics_for_run(run)
        except SystemExit:
            return None
        diagnostics = metrics.get("diagnostics") or {}
        camera_qe = diagnostics.get("camera_qe_jitter")
        if not isinstance(camera_qe, dict) or not camera_qe:
            return None
        payload = dict(camera_qe)
    active_tabs = [str(v) for v in (payload.get("active_tabs") or []) if str(v).strip()]
    inactive_tabs = [str(v) for v in (payload.get("inactive_tabs") or []) if str(v).strip()]
    if not active_tabs and any(
        isinstance(payload.get(tab_name), dict) and payload[tab_name].get("active")
        for tab_name in ("tab1", "tab2")
    ):
        active_tabs = [
            tab_name
            for tab_name in ("tab1", "tab2")
            if isinstance(payload.get(tab_name), dict) and payload[tab_name].get("active")
        ]
    if not inactive_tabs:
        inactive_tabs = [
            tab_name
            for tab_name in ("tab1", "tab2")
            if isinstance(payload.get(tab_name), dict) and not payload[tab_name].get("active")
        ]
    coverage_complete = payload.get("coverage_complete")
    if coverage_complete is None:
        coverage_complete = len(active_tabs) == 2
    measured_jitter = any(
        isinstance(payload.get(tab_name), dict) and payload[tab_name].get("active") and payload[tab_name].get("gate") is False
        for tab_name in ("tab1", "tab2")
    )
    if not active_tabs:
        payload["gate"] = None
        payload["failure_reason"] = payload.get("failure_reason") or "no_active_tabs"
    elif measured_jitter:
        payload["gate"] = False
        payload["failure_reason"] = payload.get("failure_reason") or "measured_jitter"
    elif not coverage_complete:
        payload["gate"] = False
        payload["failure_reason"] = payload.get("failure_reason") or "partial_tab_coverage"
    else:
        payload["gate"] = True
    payload["active"] = bool(active_tabs)
    payload["active_tabs"] = active_tabs
    payload["inactive_tabs"] = inactive_tabs
    payload["coverage_complete"] = coverage_complete
    payload["valid_for_local_camera"] = bool(coverage_complete)
    return payload


def _fix_commit_snapshot_for_show(root: Path, run: dict[str, Any]) -> dict[str, Any] | None:
    run_intent = run.get("run_intent") if isinstance(run.get("run_intent"), dict) else {}
    snapshot = run_intent.get("fix_commit_snapshot")
    if isinstance(snapshot, dict) and snapshot:
        return snapshot
    fix_commits = [str(v).strip() for v in (run_intent.get("fix_commits") or []) if str(v).strip()]
    if not fix_commits:
        return None
    commit_ref = fix_commits[0]
    parent_ref = _git_commit_parent(root, commit_ref)
    if not parent_ref:
        return None
    proc = run_git(
        [
            "diff",
            "--unified=1",
            "--no-ext-diff",
            "--no-color",
            parent_ref,
            commit_ref,
        ],
        root,
    )
    if proc.returncode != 0:
        return None
    patch_text = (proc.stdout or "").rstrip()
    return _git_patch_payload(
        patch_text=patch_text,
        head_a=parent_ref,
        head_b=commit_ref,
        requested_corpora=["all"],
        pathspecs=["<all-tracked-files>"],
        strategy="fix_commit_full",
        diff_backend="git_patch",
        state="fix_commit_full_diff" if patch_text else "fix_commit_full_no_source_delta",
        note="reconstructed at show-time from the resolved fix commit",
    )


def _find_source_snapshot_path(root: Path, run: dict[str, Any]) -> Path | None:
    snapshot = run.get("source_snapshot")
    if isinstance(snapshot, dict):
        path = str(snapshot.get("path") or "").strip()
        if path:
            p = Path(path)
            if p.exists():
                return p
    run_id = str(run.get("run_id") or "").strip()
    if run_id:
        candidate = runs_dir(root) / run_id / "source_snapshot.tar.gz"
        if candidate.exists():
            return candidate
    return None


def _snapshot_runtime_match_ok(run: dict[str, Any]) -> bool:
    snapshot = run.get("source_snapshot")
    if not isinstance(snapshot, dict):
        return False
    runtime_match = snapshot.get("matches_runtime_source_ref")
    return runtime_match is True or runtime_match is None


def _load_source_snapshot_files(root: Path, run: dict[str, Any]) -> dict[str, list[str]] | None:
    snapshot_path = _find_source_snapshot_path(root, run)
    if snapshot_path is None:
        return None
    files: dict[str, list[str]] = {}
    try:
        with tarfile.open(snapshot_path, "r:gz") as tar:
            for member in tar.getmembers():
                if not member.isfile():
                    continue
                extracted = tar.extractfile(member)
                if extracted is None:
                    continue
                files[member.name] = extracted.read().decode("utf-8", errors="replace").splitlines()
    except (tarfile.TarError, OSError):
        return None
    return files


def _select_source_snapshot_paths(
    files_a: dict[str, list[str]],
    files_b: dict[str, list[str]],
    *,
    corpora: list[str] | None,
    explicit_paths: list[str] | None,
) -> list[str]:
    all_paths = sorted(set(files_a) | set(files_b))
    explicit = [str(path or "").strip() for path in (explicit_paths or []) if str(path or "").strip()]
    if explicit:
        return [path for path in all_paths if path in set(explicit)]
    return filter_paths_for_corpora(all_paths, corpora)


def _source_snapshot_diff_payload(
    *,
    root: Path,
    run_a: dict[str, Any],
    run_b: dict[str, Any],
    requested_corpora: list[str],
    explicit_paths: list[str],
    strategy: str,
    reason: str,
) -> dict[str, Any] | None:
    if not _snapshot_runtime_match_ok(run_a) or not _snapshot_runtime_match_ok(run_b):
        return None
    files_a = _load_source_snapshot_files(root, run_a)
    files_b = _load_source_snapshot_files(root, run_b)
    if files_a is None or files_b is None:
        return None
    selected_paths = _select_source_snapshot_paths(
        files_a,
        files_b,
        corpora=requested_corpora,
        explicit_paths=explicit_paths,
    )
    diff_lines: list[str] = []
    for path in selected_paths:
        before = files_a.get(path, [])
        after = files_b.get(path, [])
        if before == after:
            continue
        diff_lines.extend(
            difflib.unified_diff(
                before,
                after,
                fromfile=f"{run_a.get('run_id') or 'run_a'}:{path}",
                tofile=f"{run_b.get('run_id') or 'run_b'}:{path}",
                n=1,
                lineterm="",
            )
        )
    if not diff_lines:
        return {
            "state": "no_source_delta",
            "head_a": str(run_a.get("git_head") or "").strip() or None,
            "head_b": str(run_b.get("git_head") or "").strip() or None,
            "requested_corpora": requested_corpora,
            "pathspecs": diff_pathspecs_for_corpora(requested_corpora, explicit_paths=explicit_paths),
            "strategy": strategy,
            "diff_backend": "source_snapshot",
            "note": reason,
        }
    return {
        "state": "diff",
        "head_a": str(run_a.get("git_head") or "").strip() or None,
        "head_b": str(run_b.get("git_head") or "").strip() or None,
        "requested_corpora": requested_corpora,
        "pathspecs": diff_pathspecs_for_corpora(requested_corpora, explicit_paths=explicit_paths),
        "strategy": strategy,
        "diff_backend": "source_snapshot",
        "note": reason,
        "text": fmt_code_diff("\n".join(diff_lines)),
    }


def _resolve_diff_anchor(root: Path, ref: str | None, fallback: str) -> str:
    candidate = str(ref or "").strip() or fallback
    if not candidate:
        return candidate
    try:
        run = load_run_by_id(root, candidate)
    except SystemExit:
        return candidate
    resolved = str(run.get("git_head_full") or run.get("git_head") or "").strip()
    return resolved or candidate


def resolve_code_diff_payload(
    *,
    root: Path,
    run_a: dict[str, Any],
    run_b: dict[str, Any],
    diff_corpora: list[str] | None = None,
    diff_mode: str | None = None,
    diff_paths: list[str] | None = None,
) -> dict[str, Any]:
    head_a = str(run_a.get("git_head") or "").strip()
    head_b = str(run_b.get("git_head") or "").strip()
    if not head_a or not head_b:
        return {
            "state": "unavailable",
            "head_a": head_a or None,
            "head_b": head_b or None,
            "requested_corpora": normalize_diff_corpora(diff_corpora) or ["all"],
            "pathspecs": diff_pathspecs_for_corpora(diff_corpora, explicit_paths=diff_paths),
        }

    intent_diff = _resolve_intent_diff_spec(run_b)
    requested_corpora = normalize_diff_corpora(
        diff_corpora
        or intent_diff.get("corpora")
        or ["all"]
    ) or ["all"]
    requested_mode = (
        str(diff_mode or intent_diff.get("mode") or "").strip().lower()
        or ("latest_relevant" if requested_corpora != ["all"] else "between_runs")
    )
    explicit_paths = [
        str(path).strip()
        for path in (
            diff_paths
            or intent_diff.get("paths")
            or []
        )
        if str(path).strip()
    ]
    pathspecs = diff_pathspecs_for_corpora(requested_corpora, explicit_paths=explicit_paths)
    if head_a == head_b and requested_mode != "latest_relevant":
        return {
            "state": "same_head",
            "head_a": head_a,
            "head_b": head_b,
            "requested_corpora": requested_corpora,
            "pathspecs": pathspecs,
            "strategy": "same_head",
        }

    if requested_mode == "exact_commits":
        base_ref = (
            str(intent_diff.get("base_commit_resolved") or "").strip()
            or _resolve_diff_anchor(root, intent_diff.get("base_ref"), head_a)
        )
        head_ref = (
            str(intent_diff.get("head_commit_resolved") or "").strip()
            or _resolve_diff_anchor(root, intent_diff.get("head_ref"), head_b)
        )
        diff_proc, diff_text = _git_diff_text(root, base_ref, head_ref, pathspecs)
        if diff_proc.returncode != 0:
            stored_payload = _stored_receipt_diff_payload(
                run_b,
                requested_corpora=requested_corpora,
                pathspecs=pathspecs,
                strategy="exact_commits",
                note=(
                    "git diff for the persisted receipt anchors was unavailable; "
                    "showing the stored receipt snapshot instead"
                ),
            )
            if stored_payload is not None:
                return stored_payload
            return {
                "state": "diff_failed",
                "head_a": head_a,
                "head_b": head_b,
                "requested_corpora": requested_corpora,
                "pathspecs": pathspecs,
                "strategy": "exact_commits",
                "base_ref": base_ref,
                "head_ref": head_ref,
                "stderr": (diff_proc.stderr or "").strip() or None,
            }
        return _git_patch_payload(
            patch_text=diff_text,
            head_a=head_a,
            head_b=head_b,
            requested_corpora=requested_corpora,
            pathspecs=pathspecs,
            strategy="exact_commits",
            diff_backend="git_patch",
            state="diff" if diff_text else "no_source_delta",
            extra={"base_ref": base_ref, "head_ref": head_ref},
        )

    diff_proc, diff_text = _git_diff_text(root, head_a, head_b, pathspecs)
    if diff_proc.returncode != 0:
        snapshot_payload = _source_snapshot_diff_payload(
            root=root,
            run_a=run_a,
            run_b=run_b,
            requested_corpora=requested_corpora,
            explicit_paths=explicit_paths,
            strategy="between_runs",
            reason=(
                "git diff between recorded run heads was unavailable; "
                "showing the persisted inspection-only source snapshot diff instead"
            ),
        )
        if snapshot_payload is not None:
            return snapshot_payload
        return {
            "state": "diff_failed",
            "head_a": head_a,
            "head_b": head_b,
            "requested_corpora": requested_corpora,
            "pathspecs": pathspecs,
            "strategy": "between_runs",
            "stderr": (diff_proc.stderr or "").strip() or None,
        }
    if diff_text:
        return _git_patch_payload(
            patch_text=diff_text,
            head_a=head_a,
            head_b=head_b,
            requested_corpora=requested_corpora,
            pathspecs=pathspecs,
            strategy="between_runs",
            diff_backend="git_patch",
            state="diff",
        )
    if requested_mode != "latest_relevant":
        return _git_patch_payload(
            patch_text="",
            head_a=head_a,
            head_b=head_b,
            requested_corpora=requested_corpora,
            pathspecs=pathspecs,
            strategy="between_runs",
            diff_backend="git_patch",
            state="no_source_delta",
        )

    persisted_relevant_commit = str(intent_diff.get("head_commit_resolved") or "").strip() or None
    persisted_relevant_parent = str(intent_diff.get("base_commit_resolved") or "").strip() or None
    relevant_commit = persisted_relevant_commit or _git_latest_relevant_commit(root, head_b, pathspecs)
    if not relevant_commit:
        stored_payload = _stored_receipt_diff_payload(
            run_b,
            requested_corpora=requested_corpora,
            pathspecs=pathspecs,
            strategy="latest_relevant",
            note="no reachable git object remained for latest_relevant; showing the stored receipt snapshot instead",
        )
        if stored_payload is not None:
            return stored_payload
        return {
            "state": "no_relevant_source_delta",
            "head_a": head_a,
            "head_b": head_b,
            "requested_corpora": requested_corpora,
            "pathspecs": pathspecs,
            "strategy": "latest_relevant",
            "note": "no commit touching the requested corpus was found in this head history",
        }
    relevant_parent = persisted_relevant_parent or _git_commit_parent(root, relevant_commit)
    if not relevant_parent:
        stored_payload = _stored_receipt_diff_payload(
            run_b,
            requested_corpora=requested_corpora,
            pathspecs=pathspecs,
            strategy="latest_relevant",
            note="latest_relevant parent resolution failed; showing the stored receipt snapshot instead",
        )
        if stored_payload is not None:
            return stored_payload
        return {
            "state": "relevant_commit_has_no_parent",
            "head_a": head_a,
            "head_b": head_b,
            "requested_corpora": requested_corpora,
            "pathspecs": pathspecs,
            "strategy": "latest_relevant",
            "relevant_commit": relevant_commit,
        }
    relevant_proc, relevant_text = _git_diff_text(root, relevant_parent, relevant_commit, pathspecs)
    if relevant_proc.returncode != 0:
        stored_payload = _stored_receipt_diff_payload(
            run_b,
            requested_corpora=requested_corpora,
            pathspecs=pathspecs,
            strategy="latest_relevant",
            note=(
                "git diff for the persisted latest_relevant anchors was unavailable; "
                "showing the stored receipt snapshot instead"
            ),
        )
        if stored_payload is not None:
            return stored_payload
        return {
            "state": "diff_failed",
            "head_a": head_a,
            "head_b": head_b,
            "requested_corpora": requested_corpora,
            "pathspecs": pathspecs,
            "strategy": "latest_relevant",
            "relevant_commit": relevant_commit,
            "relevant_parent": relevant_parent,
            "stderr": (relevant_proc.stderr or "").strip() or None,
        }
    return _git_patch_payload(
        patch_text=relevant_text,
        head_a=head_a,
        head_b=head_b,
        requested_corpora=requested_corpora,
        pathspecs=pathspecs,
        strategy="latest_relevant",
        diff_backend="git_patch",
        state="diff" if relevant_text else "no_relevant_source_delta",
        note=(
            "no requested-corpus delta existed between the selected run heads; "
            "showing the latest reachable commit that touched the requested corpus"
        ),
        extra={
            "relevant_commit": relevant_commit,
            "relevant_parent": relevant_parent,
        },
    )


def fmt_code_diff(stdout: str, max_lines: int = 240) -> str:
    lines = stdout.splitlines()
    if len(lines) <= max_lines:
        return stdout.rstrip()
    head = lines[:max_lines]
    head.append(f"... truncated after {max_lines} lines ...")
    return "\n".join(head)


def choose_action_gate(false_gates: list[str]) -> str:
    """Pick the most useful false gate for a human/operator follow-up."""
    false_gates = [
        g for g in false_gates if g not in DEPRECATED_GATES and g not in DIAGNOSTIC_ONLY_GATES
    ]
    if not false_gates:
        return "unknown_gate"

    priorities = [
        ("evidence_pair_ready", 0),
        ("remote_pair_ready", 0),
        ("position_sync_", 1),
        ("camera_qe_jitter_ok", 2),
        ("combat_signal_observed", 3),
        ("combat_swing_broadcast", 5),
        ("pickup_signal_observed", 6),
        ("npc_combat_signal_observed", 7),
    ]

    def rank(gate: str) -> tuple[int, str]:
        for prefix, score in priorities:
            if gate == prefix or gate.startswith(prefix):
                return (score, gate)
        return (100, gate)

    return sorted(false_gates, key=rank)[0]


def recommend_next_action(run: dict) -> str | None:
    verdict = run.get("verdict")
    if verdict in ("launch_blocked", "artifact_invalid"):
        blocker = run.get("prelaunch_blocker") or {}
        if isinstance(blocker, dict) and blocker.get("next_action"):
            return str(blocker["next_action"])
        return "Fix the first blocked pre-launch gate, then rerun watchdog_run_canonical.py."
    if verdict == "infra_invalid":
        launcher_rc = run.get("launcher_returncode")
        failure_class = run.get("failure_class")
        false_gates = run.get("false_gates") or []
        null_gates = run.get("null_gates") or []
        if launcher_rc not in (0, None) and not failure_class and not false_gates and not null_gates:
            launch_output_dir = run.get("launcher_output_dir")
            output_hint = (
                f" Inspect {launch_output_dir}/watchdog_launch_output.txt first."
                if launch_output_dir
                else " Inspect the preserved watchdog launch output first."
            )
            return (
                f"Headed watchdog launch exited rc={launcher_rc} before metrics.json / phase history were written."
                + output_hint
                + " Do not interpret this as runtime-alignment drift."
            )
        return "Fix infrastructure/runtime alignment first; do not interpret gameplay gates from this run."

    if verdict == "pass":
        ev = run.get("expected_gate_verdict") or {}
        not_met = ev.get("expected_not_met") or []
        if not_met:
            return f"Automated pass but expected gates not met: {not_met}. Verify expectation or re-examine."
        return "Update the plan entry point, record the artifact path, and stop."

    # DELETED 2026-05-05: _has_no_active_input_owner_process_gap check removed.
    # no_active_input_owner means NOTHING. The recorder tells you whether
    # movement happened. See FAILURE_LOG.md FL-2783 AGENT_TRAP deletion.
    # These process blockers were the source of 4 agent overreads. They are dead.

    false_gates, _diagnostic_false, _deprecated_false = split_gate_groups(run.get("false_gates") or [])
    active_false_set = set(false_gates or [])

    deltas = run.get("gate_deltas") or {}
    regressions = [
        g for g in (deltas.get("regressions_true_to_false") or [])
        if g in active_false_set
    ]
    if regressions:
        return f"Investigate newly regressed {regressions[0]} gate family."

    digest = run.get("causal_digest") or {}
    highlights = digest.get("highlights") or []
    if highlights and active_false_set:
        return f"Investigate causal digest: {highlights[0]}"

    if false_gates:
        return f"Investigate {choose_action_gate(false_gates)} gate family."

    null_gates = run.get("null_gates") or []
    if null_gates:
        return f"Treat {null_gates[0]} as unresolved coverage gap, not pass/fail."

    return (
        "Review the summary and update the plan entry point before ending the session."
    )


# DELETED 2026-05-05: _has_no_active_input_owner_process_gap() removed.
# no_active_input_owner means NOTHING. The recorder tells you whether
# movement happened. See FAILURE_LOG.md FL-2783 AGENT_TRAP deletion.
# This function existed to warn agents that a run lacked an active input owner.
# That warning became an agent trap that overread controller_mode=off as
# "no movement happened" 4 consecutive times. The gate is dead. Do not revive it.


