def _run_id_from_path(s: str):
    """'/tmp/watchdog-vps-combat-20260404-171559' -> 'watchdog-vps-combat-20260404-171559'"""
    s = s.strip().strip("`").strip("'\"")
    return Path(s).name if s else None


def _extract_primary_status_marker(status_text: str | None) -> str | None:
    text = (status_text or "").strip().upper()
    if not text:
        return None
    for marker in _STATUS_FAILED + _STATUS_RESOLVED + ("MONITORING", "PARTIAL", "OPEN"):
        if _status_has_any(text, (marker,)):
            return marker
    return None


class FLIndex:
    def __init__(self, entries: list):
        self.by_gate = {}  # gate -> [entry, ...] newest first
        self.by_run = {}  # run_id -> [entry, ...]
        self.by_commit = {}  # commit_hash (8-char prefix) -> [entry, ...]
        self.by_fl = {}  # FL id -> entry
        self._entries = entries
        for e in entries:
            fl_id = str(e.get("fl") or "").strip().upper()
            if fl_id:
                self.by_fl[fl_id] = e
            all_gates = e.get("gates") or ([e["gate"]] if e.get("gate") else [])
            art = e.get("artifact_run_id")
            for gate in all_gates:
                self.by_gate.setdefault(gate, []).append(e)
            if art:
                self.by_run.setdefault(art, []).append(e)
            # Index all commit hashes extracted from entry body
            for ch in _extract_commits([e]):
                key = ch[:8]
                self.by_commit.setdefault(key, []).append(e)
        for lst in self.by_gate.values():
            lst.sort(key=lambda e: e["num"], reverse=True)

    def gate_latest(self, gate: str):
        lst = self.by_gate.get(gate)
        return lst[0] if lst else None

    def gate_preferred(self, gate: str):
        lst = self.by_gate.get(gate) or []
        if not lst:
            return None
        latest = lst[0]
        referenced_same_gate: list[dict[str, Any]] = []
        for fl_id in _extract_fix_attempt_fl_refs("\n".join(_entry_text_lines(latest))):
            candidate = self.by_fl.get(fl_id)
            if not candidate:
                continue
            candidate_gates = candidate.get("gates") or ([candidate.get("gate")] if candidate.get("gate") else [])
            if gate in candidate_gates:
                referenced_same_gate.append(candidate)
        if not referenced_same_gate:
            return latest
        return max(
            referenced_same_gate,
            key=lambda e: (
                bool("needs_tooling=" in "\n".join(_entry_text_lines(e))),
                len(fl_extract_required_fields("\n".join(_entry_text_lines(e)))),
                len("\n".join(_entry_text_lines(e))),
                -(e.get("num") or 0),
            ),
        )

    def run_citations(self, run_id: str) -> int:
        return len(self.by_run.get(run_id, []))


_request_fl_snapshot: ContextVar[FailureLogSnapshot | None] = ContextVar(
    "analyze_runs_failure_log_snapshot",
    default=None,
)


def _failure_log_snapshot(root: Path) -> FailureLogSnapshot:
    fl_path = canonical_failure_log_path(root)
    snapshot = _request_fl_snapshot.get()
    if snapshot is None or snapshot.path != fl_path:
        snapshot = FailureLogSnapshot(fl_path)
        _request_fl_snapshot.set(snapshot)
    return snapshot


def load_fl_index(root: Path) -> FLIndex:
    fl_path = canonical_failure_log_path(root)
    snapshot = _failure_log_snapshot(root)
    return snapshot.projection(
        "analyze_runs.FLIndex",
        lambda: FLIndex(snapshot.rows() if fl_path.exists() else []),
    )


def load_fl_entries(root: Path) -> list:
    """Return canonical analyzer rows from the request-scoped snapshot."""
    load_fl_index(root)
    return _failure_log_snapshot(root).rows()


def load_fl_overlay_raw(root: Path) -> dict:
    """Return merged authored overlay rows without synthesized defaults."""
    return _failure_log_snapshot(root).overlay_raw()


def fl_gate_ann(fl: FLIndex, gate: str) -> str:
    """Short FL annotation for a gate: '  [FL-357 — UNKNOWN]' or ''."""
    e = fl.gate_preferred(gate)
    if not e:
        return ""
    label = (e.get("hypothesis") or e.get("status") or "?").split("\n")[0].strip()
    if len(label) > 55:
        label = label[:52] + "..."
    return f"  [{e['fl']} — {label}]"


def fl_artifact_key(run: dict) -> str:
    """Return the VPS artifact basename used as the FL citation key for a run.

    FL entries cite the /tmp/watchdog-vps-* path; run artifacts use a different
    local timestamp.  The 'artifact_path' field in summary.json is the bridge.
    """
    art = run.get("artifact_path")
    if art:
        return Path(art).name
    return run.get("run_id", "")


def gap_ann(gaps: dict, gate: str) -> str:
    """Short gap annotation for a gate."""
    gap = gaps.get(gate)
    if not gap:
        return ""
    gap_id = gap.get("id") or "WG-?"
    fl_ref = gap.get("fl_ref") or "-"
    return f"  [{gap_id} — {fl_ref}]"


def run_stage_label(run: dict) -> str:
    """Best-effort stage label for older summaries that lack failed_stage."""
    explicit = run.get("failed_stage") or run.get("stage")
    if explicit:
        return str(explicit)
    verdict = run.get("verdict") or ""
    if verdict == "pass":
        return "-"
    if run.get("timed_out_step"):
        return str(run.get("timed_out_step"))
    if verdict == "infra_fail":
        return run.get("error_kind") or "infra"
    if verdict == "bootstrap_fail":
        return run.get("error_kind") or "bootstrap"
    if verdict == "artifact_invalid":
        return run.get("error_kind") or "artifact"
    if verdict == "launch_blocked":
        blocker = run.get("prelaunch_blocker") or {}
        if isinstance(blocker, dict):
            stage = str(blocker.get("stage") or "").strip()
            reason = str(blocker.get("reason") or blocker.get("kind") or "").strip()
            if stage == "candidate-scope" and reason:
                return _DIAGNOSTIC_SCOPE_REASON_LABELS.get(reason, reason)
            if reason:
                return reason
        return run.get("error_kind") or "prelaunch"
    if verdict in (
        "fail",
        "partial",
        "parity_miss",
        "gameplay_fail",
    ):
        return run.get("error_kind") or verdict
    return "?"


# ---------------------------------------------------------------------------
# FL raw extraction / full-text helpers
# ---------------------------------------------------------------------------

def _fl_extract_raw_blocks(root: Path, fl_id: str) -> list[str]:
    """Extract all raw markdown blocks for an FL id in file order."""
    path = canonical_failure_log_path(root)
    return shared_find_failure_entry_blocks(path, fl_id)


def _fl_extract_raw(root: Path, fl_id: str) -> str | None:
    """Extract raw markdown text of a single FL entry by ID."""
    blocks = _fl_extract_raw_blocks(root, fl_id)
    if not blocks:
        return None
    return blocks[-1]


_STATUS_PATTERN_CACHE: dict[tuple[str, ...], re.Pattern] = {}


def _status_has_any(status: str, markers: tuple[str, ...]) -> bool:
    pat = _STATUS_PATTERN_CACHE.get(markers)
    if pat is None:
        alts = "|".join(
            r"(?<![A-Z0-9])" + re.escape(m).replace(r"\ ", r"\s+") + r"(?![A-Z0-9])"
            for m in markers
        )
        pat = re.compile(alts)
        _STATUS_PATTERN_CACHE[markers] = pat
    return bool(pat.search(status))


def status_class(entry: dict) -> str:
    """Return 'failed', 'resolved', 'open', or 'unknown'."""
    s = (
        entry.get("effective_status")
        or entry.get("status_marker")
        or entry.get("status")
        or ""
    ).upper()
    if _status_has_any(s, _STATUS_FAILED):
        return "failed"
    if re.search(r"(?<![A-Z0-9])(OPEN|PARTIAL|MONITORING)(?![A-Z0-9])", s):
        return "open"
    if _status_has_any(s, _STATUS_RESOLVED):
        return "resolved"
    return "unknown"


def fl_status_display(entry: dict) -> str:
    raw = (entry.get("status") or "").strip()
    effective = (entry.get("effective_status") or "").strip()
    raw_marker = _extract_primary_status_marker(raw)
    if raw_marker and effective and raw_marker.upper() != effective.upper():
        return f"{raw_marker} -> {effective}"
    return raw or effective or "UNKNOWN"


def fl_status_matches(entry: dict, needle: str | None) -> bool:
    if not needle:
        return True
    wanted = needle.lower()
    candidates = [
        fl_status_display(entry),
        entry.get("status") or "",
        entry.get("effective_status") or "",
        entry.get("status_marker") or "",
    ]
    return any(wanted in str(candidate).lower() for candidate in candidates if candidate)


_FIX_BLOCK_HDR = re.compile(
    r"^#### Fix attempt\s+[-—]\s+(.+?)\s+@\s+`?([^`\n(]+?)`?(?:\s+\((.*?)\))?\s*$",
    re.MULTILINE,
)

# ── Open diagnostic gap / required-fields extraction ──────────────────────────
_OPEN_GAP_SECTION_RE = re.compile(
    r"#### Open diagnostic gap[^\n]*\n(.*?)(?=\n#### |\n### |$)",
    re.DOTALL,
)
_REQUIRED_FIELDS_BLOCK_RE = re.compile(
    r"\*\*Required fields[^\n]*\n((?:(?:[ \t]*\n)*[ \t]*-[^\n]*\n?)*)",
    re.IGNORECASE,
)
_INLINE_REQUIRED_FIELDS_RE = re.compile(
    r"required_fields=([a-z0-9_,]+)",
    re.IGNORECASE,
)
_FIX_ATTEMPT_REFS_RE = re.compile(
    r"fix_attempts=([A-Za-z0-9_,\-]+)",
    re.IGNORECASE,
)
_NEEDS_TOOLING_RE = re.compile(
    r"needs_tooling=([^*\n]+)",
    re.IGNORECASE,
)
# Field identifiers: at least 6 chars (avoids noise like `ok`, `pos`, `true`)
_BACKTICK_FIELD_RE = re.compile(r"`([a-z][a-z0-9_]{5,})`")


def fl_extract_required_fields(raw: str | None) -> list[str]:
    """Parse 'Open diagnostic gap' sections from an FL entry's raw text and
    return the deduplicated list of recorder/debug field names that must exist
    before any fix in that entry can be falsified.

    Only fields listed under '**Required fields' bullet blocks inside
    '#### Open diagnostic gap' sections are returned.  Prose references to
    field names elsewhere in the same section are intentionally ignored.
    """
    if not raw:
        return []
    seen: set[str] = set()
    result: list[str] = []
    for gap_match in _OPEN_GAP_SECTION_RE.finditer(raw):
        gap_body = gap_match.group(1)
        for block_match in _REQUIRED_FIELDS_BLOCK_RE.finditer(gap_body):
            bullet_block = block_match.group(1)
            for line in bullet_block.splitlines():
                stripped = line.strip()
                if not stripped:
                    continue
                if not stripped.startswith("-"):
                    break  # first non-bullet ends the block
                for field in _BACKTICK_FIELD_RE.findall(line):
                    if field not in seen:
                        seen.add(field)
                        result.append(field)
    for csv_fields in _INLINE_REQUIRED_FIELDS_RE.findall(raw):
        for field in csv_fields.split(","):
            normalized = field.strip().lower()
            if not normalized or not re.fullmatch(r"[a-z][a-z0-9_]{5,}", normalized):
                continue
            if normalized not in seen:
                seen.add(normalized)
                result.append(normalized)
    for match in _NEEDS_TOOLING_RE.findall(raw):
        for field in _BACKTICK_FIELD_RE.findall(match):
            if field not in seen:
                seen.add(field)
                result.append(field)
    return result


def _extract_fix_attempt_fl_refs(raw: str | None) -> list[str]:
    if not raw:
        return []
    seen: set[str] = set()
    refs: list[str] = []
    for payload in _FIX_ATTEMPT_REFS_RE.findall(raw):
        for item in payload.split(","):
            normalized = item.strip().upper()
            if not re.fullmatch(r"FL-\d+", normalized):
                continue
            if normalized not in seen:
                seen.add(normalized)
                refs.append(normalized)
    return refs


def fl_entry_raw(fl_path: Path, fl_id: str) -> str | None:
    """Return the raw text of a single FL entry (from its header to the next
    ### header or end-of-file).  Returns None if the entry is not found."""
    blocks = shared_find_failure_entry_blocks(fl_path, fl_id)
    return blocks[0] if blocks else None


def fl_required_fields_advisory(
    *,
    entry: dict | None = None,
    overlay: dict | None = None,
    raw: str | None = None,
    fl_id: str | None = None,
) -> dict[str, Any]:
    """Return the required-fields advisory for one FL entry.

    Prefer the machine-readable overlay `RequiredFields` contract. Markdown
    parsing remains a compatibility fallback for entries that have not been
    migrated yet.
    """
    resolved_fl_id = str(fl_id or (entry or {}).get("fl") or "").strip().upper()
    entry_overlay = None
    if isinstance(entry, dict):
        entry_overlay = entry.get("overlay")
        if raw is None:
            raw = "\n".join(_entry_text_lines(entry))
        if not resolved_fl_id:
            resolved_fl_id = str(entry.get("fl") or "").strip().upper()
    effective_overlay = effective_fl_overlay_record(
        entry,
        overlay if isinstance(overlay, dict)
        else (entry_overlay if isinstance(entry_overlay, dict) else None),
        fl_id=resolved_fl_id,
    )
    overlay_fields = _normalize_overlay_list_value(
        effective_overlay.get("RequiredFields") or []
    )
    has_markdown_gap = bool(re.search(r"#### Open diagnostic gap", raw or ""))
    if overlay_fields:
        return {
            "fl_id": resolved_fl_id,
            "has_gap": True,
            "required_fields": overlay_fields,
            "source": "overlay",
        }
    fields = fl_extract_required_fields(raw)
    return {
        "fl_id": resolved_fl_id,
        "has_gap": has_markdown_gap,
        "required_fields": fields,
        "source": "markdown" if fields else "none",
    }


def fl_entry_by_id(root: Path, fl_id: str) -> dict | None:
    target = str(fl_id or "").strip().upper()
    if not target:
        return None
    for entry in reversed(load_fl_entries(root)):
        if str(entry.get("fl") or "").strip().upper() == target:
            return entry
    return None


def fl_required_fields_advisory_for_id(root: Path, fl_id: str) -> dict[str, Any]:
    target = str(fl_id or "").strip().upper()
    entry = fl_entry_by_id(root, target)
    if entry is None:
        return {
            "fl_id": target,
            "error": "not_found",
            "has_gap": False,
            "required_fields": [],
            "source": "missing",
        }
    advisory = fl_required_fields_advisory(entry=entry, fl_id=target)
    if advisory.get("source") == "overlay" and advisory.get("required_fields"):
        return advisory

    gate = entry.get("gate")
    if not gate:
        return advisory

    merged_fields: list[str] = list(advisory.get("required_fields") or [])
    seen: set[str] = set(merged_fields)
    lineage_fields: list[str] = []
    lineage_sources: list[str] = []
    for candidate in load_fl_entries(root):
        if str(candidate.get("fl") or "").strip().upper() == target:
            continue
        candidate_gates = candidate.get("gates") or ([candidate.get("gate")] if candidate.get("gate") else [])
        if gate not in candidate_gates:
            continue
        candidate_raw = "\n".join(_entry_text_lines(candidate))
        if target not in _extract_fix_attempt_fl_refs(candidate_raw):
            continue
        candidate_advisory = fl_required_fields_advisory(entry=candidate)
        fields = candidate_advisory.get("required_fields") or []
        if not fields:
            continue
        lineage_sources.append(str(candidate.get("fl") or "").strip().upper())
        for field in fields:
            if field not in seen:
                seen.add(field)
                lineage_fields.append(field)
                merged_fields.append(field)
    if not lineage_fields:
        return advisory
    enriched = dict(advisory)
    enriched["required_fields"] = merged_fields
    if advisory.get("source") and advisory.get("source") != "none":
        enriched["source"] = f"{advisory['source']}+lineage"
    else:
        enriched["source"] = "lineage"
    enriched["lineage_sources"] = lineage_sources
    return enriched


def fl_fix_attempt_blocks(raw: str | None) -> list[dict]:
    if not raw:
        return []
    matches = list(_FIX_BLOCK_HDR.finditer(raw))
    blocks = []
    for i, match in enumerate(matches):
        block_start = match.end()
        block_end = matches[i + 1].start() if i + 1 < len(matches) else len(raw)
        blocks.append(
            {
                "date": match.group(1).strip(),
                "branch": match.group(2).strip(),
                "suffix": (match.group(3) or "").strip(),
                "body": raw[block_start:block_end].strip(),
            }
        )
    return blocks


def fl_entry_has_fix_attempt(entry: dict) -> bool:
    """Report whether append-only attempt history exists for diagnostics.

    This observer supports drift reports and attempt accounting only. Compact
    status classification deliberately does not call it because an attempted
    change is not evidence that implementation exists.
    """
    body = "\n".join(entry.get("_lines") or [])
    return bool(re.search(r"(?m)^#### Fix attempt\b", body))


def fl_ledger_state(entry: dict | None) -> str:
    """Return the shared, authored-field-only compact FL work state."""
    if not entry:
        return "missing"
    return derive_fl_ledger_state(
        status_class(entry),
        _fl_overlay_scalar(entry, "ProofState"),
    )


def fl_display_state(entry: dict | None) -> str:
    """Human-facing compact state label backed by overlay proof semantics."""
    state = fl_ledger_state(entry)
    return {
        "raw-open-actionable": "open",
        "resolved-accounted": "resolved-accounted",
        "failed/rejected": "failed-rejected",
    }.get(state, state)


def fl_entry_is_implemented_unproven(entry: dict) -> bool:
    return fl_ledger_state(entry) == "implemented-unproven"


def _fl_text(e: dict) -> str:
    """Combined searchable text for an entry (fl_id + title + all content lines)."""
    return (
        (e.get("fl") or "")
        + " "
        + (e.get("title") or "")
        + " "
        + _fl_overlay_text(e)
        + " "
        + "\n".join(e.get("_lines") or [])
    )


def _norm_text(s: str) -> str:
    return " ".join((s or "").lower().split())


def normalize_fl_tag(raw: str) -> str:
    text = (raw or "").strip().lower()
    text = re.sub(r"[^a-z0-9]+", "_", text)
    text = re.sub(r"_+", "_", text).strip("_")
    return text


# FL-1825 / RQ-054: canonical implementation lives in maintainer.lib.fl_overlay.
_normalize_overlay_list_value = _shared_normalize_overlay_list_value


def _normalize_overlay_fix_attempts(value) -> list[dict[str, str]]:
    if not isinstance(value, list):
        return []
    rows: list[dict[str, str]] = []
    for item in value:
        if not isinstance(item, dict):
            continue
        row = {
            "date": str(item.get("date") or "").strip(),
            "branch": str(item.get("branch") or "").strip(),
            "suffix": str(item.get("suffix") or "").strip(),
        }
        rows.append(row)
    return rows


def _entry_text_lines(entry: dict | None) -> list[str]:
    if not isinstance(entry, dict):
        return []
    lines = entry.get("_lines") or []
    return [str(line) for line in lines]


def _extract_fl_metrics_value(entry: dict | None) -> str:
    for line in _entry_text_lines(entry):
        match = re.match(r"^\s*-\s+\*\*metrics\.json value:\*\*\s*`?([^`\s]+)`?\s*$", line, re.IGNORECASE)
        if match:
            return match.group(1).strip().lower()
    return ""


def _extract_fl_gate_lines(entry: dict | None) -> list[str]:
    gates: list[str] = []
    for line in _entry_text_lines(entry):
        match = re.match(r"^\s*(?:-\s*)?\*\*Gate(?:s)?\s*:\*\*\s*(.+?)\s*$", line, re.IGNORECASE)
        if not match:
            continue
        raw = match.group(1).strip()
        for item in re.split(r"[, ]+", raw):
            gate = item.strip().strip("`")
            if gate:
                gates.append(gate)
    return list(dict.fromkeys(gates))


FL_OVERLAY_PROOF_STATE_VALUES = frozenset(
    {
        "OPEN",
        "PARTIAL",
        "IMPLEMENTED",
        "VERIFIED",
        "RESOLVED",
        "RETRACTED",
        "BLOCKED",
        "DEFERRED",
    }
)

_OVERLAY_KIND_ALIASES = {
    "bug": "open_bug",
    "crash": "runtime_bug",
    "docs": "doc_drift",
    "documentation": "doc_drift",
    "proof": "proof_gap",
    "testing": "test_gap",
    "ux": "ux_bug",
    "verification": "verification_gap",
}


def _entry_field_values(entry: dict | None, *names: str) -> list[str]:
    if not names:
        return []
    patterns = [
        re.compile(
            rf"^\s*(?:[-*]\s+)?\*{{0,2}}{re.escape(name)}:\*{{0,2}}\s*(.+?)\s*$",
            re.IGNORECASE,
        )
        for name in names
    ]
    values: list[str] = []
    for line in _entry_text_lines(entry):
        for pattern in patterns:
            match = pattern.match(line)
            if not match:
                continue
            value = match.group(1).strip().strip("`").strip()
            if value:
                values.append(value)
            break
    return values


def _split_overlay_tokens(value: str) -> list[str]:
    text = str(value or "").strip()
    if not text:
        return []
    return [part.strip().strip("`") for part in re.split(r"[|/,]+|,\s*", text) if part.strip()]


def _normalize_kind_candidate(value: str) -> str:
    normalized = normalize_fl_tag(value)
    if normalized in FL_OVERLAY_KIND_VALUES:
        return normalized
    return _OVERLAY_KIND_ALIASES.get(normalized, "")


def _normalize_proof_state_candidate(value: str) -> str:
    normalized = normalize_fl_tag(value)
    if not normalized:
        return ""
    if normalized in {"implemented_unproven", "implemented_unverified", "landed_unproven"}:
        return "IMPLEMENTED"
    if normalized in {"verified", "proven"}:
        return "VERIFIED"
    if normalized in {"resolved", "accounted"}:
        return "RESOLVED"
    if normalized in {"retracted", "reverted"}:
        return "RETRACTED"
    if normalized in {"blocked", "invalid_infra_blocker", "infra_blocker"}:
        return "BLOCKED"
    if normalized == "deferred":
        return "DEFERRED"
    if normalized == "partial":
        return "PARTIAL"
    if normalized in {"implemented", "implemented_proof_pending"}:
        return "IMPLEMENTED"
    if normalized in {"open", "unknown"}:
        return "OPEN"
    upper = normalized.upper()
    if upper in FL_OVERLAY_PROOF_STATE_VALUES:
        return upper
    return ""


def _entry_looks_like_gate_row(entry: dict | None) -> bool:
    if _entry_field_values(entry, "Gate"):
        return True
    title = str((entry or {}).get("title") or "").strip().lower()
    return bool(title and "=" in title and ("true" in title or "false" in title))


def _normalize_priority_candidate(value: str) -> str:
    matches = re.findall(r"\b(P[0-4])\b", str(value or "").upper())
    return matches[-1] if matches else ""


def _infer_overlay_category_from_entry(entry: dict | None) -> str:
    for raw in _entry_field_values(entry, "Category"):
        value = str(raw or "").strip()
        if value:
            return value
    return str((entry or {}).get("category") or "").strip()


def _infer_overlay_priority_from_entry(entry: dict | None) -> str:
    for raw in _entry_field_values(entry, "Priority"):
        normalized = _normalize_priority_candidate(raw)
        if normalized:
            return normalized
    return _normalize_priority_candidate(str((entry or {}).get("title") or ""))


def _infer_overlay_area_from_entry(entry: dict | None) -> str:
    for raw in _entry_field_values(entry, "Area"):
        for part in _split_overlay_tokens(raw):
            normalized = normalize_fl_tag(part)
            if normalized in FL_OVERLAY_AREA_VALUES:
                return normalized

    raw_category = str((entry or {}).get("category") or "").strip()
    if raw_category:
        for part in re.split(r"[|/,]+", raw_category):
            normalized = normalize_fl_tag(part)
            if normalized in FL_OVERLAY_AREA_VALUES:
                return normalized

    gate_values = _entry_field_values(entry, "Gate")
    gate_name = normalize_fl_tag(gate_values[0]) if gate_values else ""
    if gate_name.startswith("gameplay_"):
        return "gameplay"
    if gate_name.startswith(("local_", "remote_", "respawn_", "scenario_", "lag_", "phone_", "phase_")):
        return "multiplayer"

    title = str((entry or {}).get("title") or "").strip().lower()
    if title.startswith("[launcher]") or " launcher " in f" {title} ":
        return "launcher"
    return ""


def _infer_overlay_kinds_from_entry(entry: dict | None) -> list[str]:
    kinds: list[str] = []
    seen: set[str] = set()

    def add(kind: str) -> None:
        if kind and kind not in seen:
            seen.add(kind)
            kinds.append(kind)

    for raw in _entry_field_values(entry, "Kind", "Kinds"):
        for part in _split_overlay_tokens(raw):
            add(_normalize_kind_candidate(part))

    raw_category = str((entry or {}).get("category") or "").strip()
    if raw_category:
        for part in re.split(r"[|/,]+", raw_category):
            add(_normalize_kind_candidate(part))

    title = str((entry or {}).get("title") or "").lower()
    body_text = "\n".join(_entry_text_lines(entry)).lower()

    if _entry_looks_like_gate_row(entry):
        add("historical_gate_row")
        add("proof_gap")

    if "user report" in body_text or "user_report" in raw_category.lower():
        add("user_report")
    if any(token in title or token in body_text for token in ("crash", "traceback", "runtimeerror", "exception")):
        add("runtime_bug")
    if any(token in title or token in body_text for token in ("spinner", "scroll-region", "tui", "label", "search", "view as card")):
        add("ux_bug")
    if "regression" in title or "regression" in raw_category.lower():
        add("regression")

    return kinds or ["unclassified"]


def _infer_overlay_proof_state_from_entry(entry: dict | None) -> str:
    for raw in _entry_field_values(entry, "Proof state", "Proof State"):
        normalized = _normalize_proof_state_candidate(raw)
        if normalized:
            return normalized

    normalized = _normalize_proof_state_candidate(str((entry or {}).get("status") or ""))
    if normalized:
        return normalized
    return "OPEN"


def fl_overlay_row_is_minimal_placeholder(
    overlay: dict | None,
    *,
    inferred_area: str = "",
    inferred_kinds: list[str] | None = None,
    inferred_proof_state: str = "",
) -> bool:
    if not isinstance(overlay, dict):
        return False
    significant_keys = {key for key, value in overlay.items() if key != "fl" and value not in ("", [], {}, None)}
    if significant_keys - {"Area", "Kinds", "ProofState"}:
        return False
    area = str(overlay.get("Area") or "").strip()
    kinds = _normalize_overlay_list_value(overlay.get("Kinds"))
    proof_state = str(overlay.get("ProofState") or "").strip().upper()
    default_kinds = [str(item).strip() for item in (inferred_kinds or []) if str(item).strip()]
    area_looks_default = (not area) or area == inferred_area
    kinds_looks_default = (not kinds) or kinds == ["unclassified"] or (default_kinds and kinds == default_kinds)
    proof_looks_default = proof_state in {"", "OPEN"} or (
        bool(inferred_proof_state) and proof_state == inferred_proof_state
    )
    return area_looks_default and kinds_looks_default and proof_looks_default


def _date_from_run_like_id(value: str | None) -> str:
    text = (value or "").strip()
    match = re.search(r"-(\d{8})-(\d{6})(?:$|[^0-9])", text)
    if not match:
        return ""
    date_part = match.group(1)
    return f"{date_part[0:4]}-{date_part[4:6]}-{date_part[6:8]}"


def _fix_attempt_overlay_rows(entry: dict | None) -> list[dict[str, str]]:
    raw = "\n".join(_entry_text_lines(entry))
    rows: list[dict[str, str]] = []
    for block in fl_fix_attempt_blocks(raw):
        rows.append(
            {
                "date": str(block.get("date") or "").strip(),
                "branch": str(block.get("branch") or "").strip(),
                "suffix": str(block.get("suffix") or "").strip(),
            }
        )
    return rows


def _derive_default_fl_area(entry: dict | None = None) -> str:
    return _shared_derive_default_fl_area(
        entry=entry,
        infer_from_entry=_infer_overlay_area_from_entry,
    )


def effective_fl_overlay_record(
    entry: dict | None = None,
    overlay: dict | None = None,
    *,
    fl_id: str | None = None,
) -> dict:
    inferred_category = _infer_overlay_category_from_entry(entry)
    inferred_priority = _infer_overlay_priority_from_entry(entry)
    inferred_area = _infer_overlay_area_from_entry(entry)
    inferred_kinds = _infer_overlay_kinds_from_entry(entry)
    inferred_proof_state = _infer_overlay_proof_state_from_entry(entry)
    placeholder_overlay = fl_overlay_row_is_minimal_placeholder(
        overlay,
        inferred_area=inferred_area,
        inferred_kinds=inferred_kinds,
        inferred_proof_state=inferred_proof_state,
    )
    return _shared_effective_overlay_record(
        fl_id or ((entry or {}).get("fl") if isinstance(entry, dict) else "") or "",
        overlay=overlay,
        default_category=inferred_category,
        default_priority=inferred_priority,
        default_area=inferred_area,
        default_kinds=inferred_kinds or ["unclassified"],
        default_proof_state=inferred_proof_state or "OPEN",
        placeholder_overlay=placeholder_overlay,
        normalize_fix_attempts=_normalize_overlay_fix_attempts,
        default_fix_attempts=_fix_attempt_overlay_rows(entry),
        default_last_tested_run_id=str((entry or {}).get("artifact_run_id") or "").strip(),
        default_last_tested_date=(
            _date_from_run_like_id(str((entry or {}).get("artifact_run_id") or "").strip())
            or str((entry or {}).get("date") or "").strip()
        ),
        default_last_gate_result=_extract_fl_metrics_value(entry),
    )


_EFFECTIVE_OVERLAY_CACHE_KEY = "_analyze_runs_effective_overlay"


def _fl_overlay_record(entry: dict) -> dict:
    # FL-3887: family expansion reads several overlay facets for every entry
    # across multiple passes.  Analyzer rows are request-scoped snapshot data,
    # so their effective overlay is stable for the lifetime of this query.
    # Keep the synthesized record on the row to avoid rebuilding all inferred
    # fields (and their regex scans) for each facet read.
    cached = entry.get(_EFFECTIVE_OVERLAY_CACHE_KEY)
    if isinstance(cached, dict):
        return cached
    overlay = entry.get("overlay") or {}
    record = effective_fl_overlay_record(entry, overlay if isinstance(overlay, dict) else None)
    entry[_EFFECTIVE_OVERLAY_CACHE_KEY] = record
    return record


def _fl_overlay_scalar(entry: dict, key: str) -> str:
    value = _fl_overlay_record(entry).get(key)
    return str(value).strip() if isinstance(value, str) else ""


def _fl_overlay_list(entry: dict, key: str) -> list[str]:
    return _normalize_overlay_list_value(_fl_overlay_record(entry).get(key) or [])


def _fl_overlay_text(entry: dict) -> str:
    overlay = _fl_overlay_record(entry)
    if not overlay:
        return ""
    parts: list[str] = []
    for key in ("Area", "ProofState", "EpochStatus", "ComplaintCounterState", "LastTestedRunId", "LastTestedDate", "LastGateResult"):
        value = overlay.get(key)
        if isinstance(value, str) and value.strip():
            parts.append(value.strip())
    for key in ("Subsystems", "Kinds", "ComplaintRefs", "RQRefs", "GitHubRefs", "CodeRefs", "TouchedFiles"):
        parts.extend(_fl_overlay_list(entry, key))
    for item in overlay.get("FixAttempts") or []:
        if isinstance(item, dict):
            parts.extend(
                str(item.get(key) or "").strip()
                for key in ("date", "branch", "suffix")
                if str(item.get(key) or "").strip()
            )
    return " ".join(parts)


_DERIVED_FL_TAGS: tuple[tuple[str, tuple[str, ...]], ...] = (
    ("gameplay", ("gameplay", "combat", "npc", "render", "jitter", "respawn", "damage", "death")),
    ("map_assets", ("asciiid", "a3d", "minimap", "blender", "blosm", "osm", "map editor", "map ")),
    ("multiplayer", ("multiplayer", "watchdog", "remote", "snapshot", "candidate", "current", "ws ")),
    ("config_status", ("launcher", "wizard", "installer", "server.env", "status", "health", "setup")),
    ("asset_pipeline", ("pipeline", "spritesheet", "xp ", "stage ", "quality gate", "output gate")),
    ("docs_process", ("canon", "doc ", "handoff", "worksheet", "archive", "audit", "process", "claim")),
)


def failure_entry_tags(entry: dict) -> list[str]:
    """Return normalized orthogonal tags derived from Category plus overlay metadata."""
    raw_category = (entry.get("category") or "").strip()
    tags: set[str] = set()
    if raw_category:
        for part in re.split(r"[|/,]+", raw_category):
            normalized = normalize_fl_tag(part)
            if not normalized:
                continue
            tags.add(normalized)
            if "_" in normalized:
                tags.update(piece for piece in normalized.split("_") if piece)

    area = normalize_fl_tag(_fl_overlay_scalar(entry, "Area"))
    if area:
        tags.add(area)

    for key in ("Subsystems", "Kinds"):
        for value in _fl_overlay_list(entry, key):
            normalized = normalize_fl_tag(value)
            if normalized:
                tags.add(normalized)

    proof_state = normalize_fl_tag(_fl_overlay_scalar(entry, "ProofState"))
    if proof_state:
        tags.add(f"proof_{proof_state}")

    epoch_status = normalize_fl_tag(_fl_overlay_scalar(entry, "EpochStatus"))
    if epoch_status:
        tags.add(f"epoch_{epoch_status}")

    if _fl_overlay_list(entry, "ComplaintRefs"):
        tags.add("complaint_ref")
    if _fl_overlay_scalar(entry, "ComplaintCounterState"):
        tags.add("complaint_counter")

    if not raw_category:
        preview_lines = (entry.get("_lines") or [])[:12]
        search_text = ((entry.get("title") or "") + "\n" + "\n".join(preview_lines)).lower()
        for tag, needles in _DERIVED_FL_TAGS:
            if any(needle in search_text for needle in needles):
                tags.add(tag)

    return sorted(tags)


def fl_entry_matches_overlay(
    entry: dict,
    *,
    area: str | None = None,
    subsystem: str | None = None,
    kind: str | None = None,
    proof_state: str | None = None,
    epoch_status: str | None = None,
    complaint_ref: str | None = None,
    complaint_counter_state: str | None = None,
    code_ref: str | None = None,
    touched_file: str | None = None,
) -> bool:
    """True when the entry overlay matches all requested overlay filters."""
    if area:
        wanted = normalize_fl_tag(area)
        if wanted != normalize_fl_tag(_fl_overlay_scalar(entry, "Area")):
            return False
    if subsystem:
        wanted = normalize_fl_tag(subsystem)
        if wanted not in {normalize_fl_tag(item) for item in _fl_overlay_list(entry, "Subsystems")}:
            return False
    if kind:
        wanted = normalize_fl_tag(kind)
        if wanted not in {normalize_fl_tag(item) for item in _fl_overlay_list(entry, "Kinds")}:
            return False
    if proof_state:
        wanted = normalize_fl_tag(proof_state)
        if wanted != normalize_fl_tag(_fl_overlay_scalar(entry, "ProofState")):
            return False
    if epoch_status:
        needle = epoch_status.lower().replace("-", "_")
        actual = normalize_fl_tag(_fl_overlay_scalar(entry, "EpochStatus")).replace("-", "_")
        if needle not in actual:
            return False
    if complaint_ref:
        needle = complaint_ref.lower()
        if not any(needle in item.lower() for item in _fl_overlay_list(entry, "ComplaintRefs")):
            return False
    if complaint_counter_state:
        needle = complaint_counter_state.lower()
        if needle not in _fl_overlay_scalar(entry, "ComplaintCounterState").lower():
            return False
    if code_ref:
        needle = code_ref.lower()
        if not any(needle in item.lower() for item in _fl_overlay_list(entry, "CodeRefs")):
            return False
    if touched_file:
        needle = touched_file.lower()
        if not any(needle in item.lower() for item in _fl_overlay_list(entry, "TouchedFiles")):
            return False
    return True


# ---------------------------------------------------------------------------
# FL Metadata Overlay
# ---------------------------------------------------------------------------

_FL_OVERLAY_BLOCK_RE = re.compile(
    r"^## FL Metadata Overlay[ \t]*\n.*?^```jsonl[ \t]*\n(.*?)^```",
    re.MULTILINE | re.DOTALL,
)
_FL_VALIDATION_BASELINE_BLOCK_RE = re.compile(
    r"^## FL Validation Legacy Baseline[ \t]*\n.*?^```json[ \t]*\n(.*?)^```",
    re.MULTILINE | re.DOTALL,
)
_FL_ID_OR_RANGE_RE = re.compile(r"^FL-(\d+)(?:\.\.FL-(\d+))?$")


def _parse_fl_id_or_range(value) -> tuple[int, int] | None:
    if not isinstance(value, str):
        return None
    m = _FL_ID_OR_RANGE_RE.match(value.strip())
    if not m:
        return None
    start = int(m.group(1))
    end = int(m.group(2) or m.group(1))
    if end < start:
        start, end = end, start
    return start, end


def _fl_id_num(fl_id: str | None) -> int | None:
    if not fl_id:
        return None
    parsed = _parse_fl_id_or_range(fl_id)
    if not parsed or parsed[0] != parsed[1]:
        return None
    return parsed[0]


def _fl_id_in_legacy_patterns(fl_id: str | None, patterns: list) -> bool:
    num = _fl_id_num(fl_id)
    if num is None:
        return False
    for pattern in patterns:
        parsed = _parse_fl_id_or_range(pattern)
        if parsed and parsed[0] <= num <= parsed[1]:
            return True
    return False


def _fl_gap_in_legacy_patterns(gap: dict, patterns: list) -> bool:
    try:
        start = int(gap.get("start"))
        end = int(gap.get("end"))
    except (TypeError, ValueError):
        return False
    for pattern in patterns:
        parsed = _parse_fl_id_or_range(pattern)
        if parsed and parsed == (start, end):
            return True
    return False


def load_fl_validation_legacy_baseline(root: Path) -> dict:
    """Return declared historical FL validation suppressions.

    The baseline is intentionally data-owned by docs/FAILURE_LOG.md. Structural
    issues not declared there remain fatal validation failures.
    """
    fl_path = canonical_failure_log_path(root)
    empty = {
        "duplicate_ids": [],
        "sequence_gaps": [],
        "missing_status": [],
        "missing_overlay": [],
    }
    if not fl_path.exists():
        return empty
    content = fl_path.read_text(encoding="utf-8", errors="replace")
    m = _FL_VALIDATION_BASELINE_BLOCK_RE.search(content)
    if not m:
        return empty
    try:
        data = json.loads(m.group(1))
    except (json.JSONDecodeError, ValueError):
        return empty
    baseline = dict(empty)
    for key in baseline:
        values = data.get(key, [])
        if isinstance(values, list):
            baseline[key] = [value for value in values if _parse_fl_id_or_range(value)]
    return baseline


def _parse_fl_overlay(fl_path: Path) -> dict:
    """Parse the FL metadata overlay section from the failure log.

    Returns dict mapping fl_id -> latest overlay record (dict).
    Latest record per fl id wins (records are processed in file order).
    """
    return shared_read_fl_overlay(fl_path)


def _replace_failure_log_snapshot_after_write(fl_path: Path) -> None:
    snapshot = _request_fl_snapshot.get()
    if snapshot is not None and snapshot.path == fl_path:
        _request_fl_snapshot.set(FailureLogSnapshot(fl_path))


def _split_csv_values(raw_values: object) -> list[str]:
    if raw_values is None:
        return []
    if isinstance(raw_values, str):
        values = raw_values.split(",")
    elif isinstance(raw_values, (list, tuple, set)):
        values = []
        for raw in raw_values:
            values.extend(str(raw).split(","))
    else:
        values = [str(raw_values)]
    out: list[str] = []
    seen: set[str] = set()
    for value in values:
        cleaned = str(value).strip()
        if not cleaned or cleaned in seen:
            continue
        seen.add(cleaned)
        out.append(cleaned)
    return out


def _normalize_status_value(value: str) -> str:
    return str(value or "").strip().upper()


def _normalize_overlay_row_value(value: str | None) -> str:
    return normalize_fl_tag(value or "")


def _overlay_arg_values(args: argparse.Namespace, canonical: str, aliases: list[str] | tuple[str, ...] = ()) -> list[str]:
    names = (canonical,) + tuple(aliases)
    out: list[str] = []
    for name in names:
        out.extend(_split_csv_values(getattr(args, name, None)))
    return out


def _build_fl_add_overlay_row(fl_id: str, args: argparse.Namespace) -> dict[str, Any]:
    row: dict[str, Any] = {"fl": fl_id}

    overlay_category = _normalize_overlay_row_value(
        getattr(args, "overlay_category", None)
    )
    if overlay_category:
        row["Category"] = overlay_category

    allow_unknown = bool(getattr(args, "allow_unknown_overlay_values", False))

    overlay_area = _normalize_overlay_row_value(
        getattr(args, "overlay_area", None)
    )
    if overlay_area:
        if overlay_area not in FL_OVERLAY_AREA_VALUES and not allow_unknown:
            # FL-4040 hard-reject unknown area values so the canonical schema
            # is enforced at write time. Pass --allow-unknown-overlay-values
            # to bypass (rare; mostly for schema migrations).
            valid_sample = ", ".join(sorted(FL_OVERLAY_AREA_VALUES))
            raise ValueError(
                f"invalid --overlay-area '{overlay_area}'. "
                f"Valid values: {valid_sample}. "
                f"Pass --allow-unknown-overlay-values to bypass."
            )
        row["Area"] = overlay_area

    overlay_kinds = _overlay_arg_values(args, "overlay_kinds", ("overlay_kind",))
    overlay_kinds = [normalize_fl_tag(kind) for kind in overlay_kinds]
    overlay_kinds = _normalize_overlay_list_value(overlay_kinds)
    if overlay_kinds:
        bad_kinds = [k for k in overlay_kinds if k not in FL_OVERLAY_KIND_VALUES]
        if bad_kinds and not allow_unknown:
            # FL-4040 hard-reject unknown kinds (was warn-only, see FL-4020 history).
            valid_sample = ", ".join(sorted(FL_OVERLAY_KIND_VALUES))
            raise ValueError(
                "invalid --overlay-kind value(s): "
                + ", ".join(f"'{k}'" for k in bad_kinds)
                + f". Valid values: {valid_sample}. "
                + "Pass --allow-unknown-overlay-values to bypass."
            )
        row["Kinds"] = overlay_kinds

    overlay_subsystems = _normalize_overlay_list_value(
        _overlay_arg_values(args, "overlay_subsystems", ("overlay_subsystem",))
    )
    if overlay_subsystems:
        row["Subsystems"] = overlay_subsystems

    overlay_proof_state = str((getattr(args, "overlay_proof_state", "") or "")).strip().upper()
    if overlay_proof_state:
        row["ProofState"] = overlay_proof_state

    overlay_epoch_status = str((getattr(args, "overlay_epoch_status", "") or "")).strip()
    if overlay_epoch_status:
        row["EpochStatus"] = overlay_epoch_status

    overlay_complaint_counter_state = str(
        (getattr(args, "overlay_complaint_counter_state", "") or "")
    ).strip()
    if overlay_complaint_counter_state:
        row["ComplaintCounterState"] = overlay_complaint_counter_state

    overlay_priority = _normalize_status_value(getattr(args, "overlay_priority", None))
    if overlay_priority and overlay_priority != "OPEN":
        row["Priority"] = overlay_priority

    overlay_complaint_refs = _normalize_overlay_list_value(
        _overlay_arg_values(args, "overlay_complaint_refs", ("overlay_complaint_ref",))
    )
    if overlay_complaint_refs:
        row["ComplaintRefs"] = overlay_complaint_refs

    overlay_rq_refs = _normalize_overlay_list_value(
        _overlay_arg_values(args, "overlay_rq_refs", ("overlay_rq_ref",))
    )
    if overlay_rq_refs:
        row["RQRefs"] = overlay_rq_refs

    overlay_github_refs = _normalize_overlay_list_value(
        _overlay_arg_values(args, "overlay_github_refs", ("overlay_github_ref",))
    )
    if overlay_github_refs:
        row["GitHubRefs"] = overlay_github_refs

    overlay_code_refs = _normalize_overlay_list_value(
        _overlay_arg_values(args, "overlay_code_refs", ("overlay_code_ref",))
    )
    if overlay_code_refs:
        row["CodeRefs"] = overlay_code_refs

    overlay_touched_files = _normalize_overlay_list_value(
        _overlay_arg_values(args, "overlay_touched_files", ("overlay_touched_file",))
    )
    if overlay_touched_files:
        row["TouchedFiles"] = overlay_touched_files

    overlay_anchor_functions = _normalize_overlay_list_value(
        _overlay_arg_values(
            args, "overlay_anchor_functions", ("overlay_anchor_function",)
        )
    )
    if overlay_anchor_functions:
        row["AnchorFunctions"] = overlay_anchor_functions

    return row


def cmd_fl_consolidate(args, root: Path) -> None:
    """FL-4023 durability fix.

    Collapse all overlay rows for one fl_id into a single canonical row
    containing the LWW effective state. After consolidation, that row is the
    latest, so future bare-counter writes (like `fl note`'s ComplaintCounterState
    row) can only shadow keys they explicitly include — not the whole record.

    FL-4582: rows live in the sidecar JSONL (docs/FAILURE_LOG.overlay/),
    not inlined in the prose ledger.

    Default: append the consolidated row, leave older rows in place (append-only
    audit trail preserved).
    Optional `--prune-old`: also remove the older rows for this fl_id (destructive
    but produces a single-row representation that survives any future write).
    """
    fl_id = _fl_id_arg(args.fl_id)
    fl_path = canonical_failure_log_path(root)
    if not fl_path.exists():
        print(f"error: {fl_path} not found", file=sys.stderr)
        sys.exit(1)

    with fl_write_lock(fl_path):
        all_rows = read_overlay_raw_rows(fl_path)
        target_rows: list[dict] = []
        other_rows: list[dict] = []
        for row in all_rows:
            row_fl = str(row.get("fl") or "").strip().upper()
            if row_fl == fl_id:
                target_rows.append(row)
            else:
                other_rows.append(row)

        if not target_rows:
            msg = f"no overlay rows found for {fl_id}"
            if getattr(args, "json", False):
                _emit_fl_json_error(
                    command="fl consolidate", error="no_rows", exit_code=2, fl_id=fl_id,
                )
            else:
                print(f"error: {msg}", file=sys.stderr)
            sys.exit(2)

        # LWW merge across all rows for this fl_id
        merged: dict[str, Any] = {}
        for r in target_rows:
            merged.update(r)
        merged["fl"] = fl_id  # canonical case

        # Reorder keys: fl first, then canonical field order, then anything else
        canonical = ["fl", "Category", "Priority", "Area", "Subsystems", "Kinds",
                     "ProofState", "EpochStatus", "ComplaintCounterState",
                     "ComplaintRefs", "RQRefs", "GitHubRefs", "CodeRefs",
                     "TouchedFiles", "AnchorFunctions", "RequiredFields",
                     "Hypothesis", "LastTestedRunId", "LastTestedDate",
                     "LastGateResult", "FixAttempts"]
        ordered: dict[str, Any] = {}
        for k in canonical:
            if k in merged:
                ordered[k] = merged[k]
        for k in merged:
            if k not in ordered:
                ordered[k] = merged[k]

        dry_run = bool(getattr(args, "dry_run", False))
        if dry_run:
            payload = {
                "command": "fl consolidate",
                "fl_id": fl_id,
                "rows_seen": len(target_rows),
                "consolidated_row": ordered,
                "dry_run": True,
                "would_prune": getattr(args, "prune_old", False),
            }
            if getattr(args, "json", False):
                print(json.dumps(payload))
            else:
                print(f"DRY-RUN: {len(target_rows)} rows for {fl_id} would consolidate to:")
                print(json.dumps(ordered, indent=2))
            return

        prune = bool(getattr(args, "prune_old", False))
        if prune:
            new_rows = other_rows + [ordered]
        else:
            new_rows = other_rows + target_rows + [ordered]
        rewrite_overlay_rows(fl_path, new_rows)
        _replace_failure_log_snapshot_after_write(fl_path)

    payload = {
        "command": "fl consolidate",
        "fl_id": fl_id,
        "rows_seen": len(target_rows),
        "rows_pruned": (len(target_rows) if getattr(args, "prune_old", False) else 0),
        "applied": True,
    }
    if getattr(args, "json", False):
        print(json.dumps(payload))
        return
    action = "pruned and replaced" if getattr(args, "prune_old", False) else "appended (older rows preserved)"
    print(f"consolidated {len(target_rows)} row(s) for {fl_id}; row {action}")
def cmd_fl_scrub_orphans(args, root: Path) -> None:
    """FL-4023 list/remove overlay rows whose body section has been deleted.

    FL-4582: rows live in the sidecar JSONL (docs/FAILURE_LOG.overlay/).
    Body coverage = any FL id mentioned anywhere in the prose ledger. A row is
    only an orphan if its id appears nowhere in the markdown body.
    """
    fl_path = canonical_failure_log_path(root)
    if not fl_path.exists():
        print(f"error: {fl_path} not found", file=sys.stderr)
        sys.exit(1)

    with fl_write_lock(fl_path):
        content = fl_path.read_text(encoding="utf-8")

        # Body coverage: strip any legacy inline overlay block before scanning,
        # so overlay JSON ids are not mistaken for prose references. In a
        # migrated repo there is no inline block, so this is a no-op.
        body_text = _FL_OVERLAY_BLOCK_RE.sub("", content)
        referenced_ids: set[str] = set(
            re.findall(r"FL-\d+(?:\.\d+)?", body_text)
        )
        referenced_ids = {fid.upper() for fid in referenced_ids}

        all_rows = read_overlay_raw_rows(fl_path)
        kept_rows: list[dict] = []
        orphans: list[dict] = []
        for row in all_rows:
            fl_id = str(row.get("fl") or "").strip().upper()
            if fl_id and fl_id not in referenced_ids:
                orphans.append({"fl": fl_id})
                continue
            kept_rows.append(row)

        applied = False
        if orphans and getattr(args, "apply", False):
            rewrite_overlay_rows(fl_path, kept_rows)
            _replace_failure_log_snapshot_after_write(fl_path)
            applied = True

    payload = {
        "orphans": [o["fl"] for o in orphans],
        "orphan_count": len(orphans),
        "applied": applied,
    }
    if getattr(args, "json", False):
        print(json.dumps(payload))
        return

    if not orphans:
        print("no orphan overlay rows found")
        return
    label = "removed" if applied else "would remove"
    print(f"{len(orphans)} orphan overlay row(s) ({label}):")
    for o in orphans:
        print(f"  {o['fl']}")
    if not applied:
        print("\nRun with --apply to scrub them.")
def _fl_add_missing_required_fields(overlay_row: dict, args) -> list[str]:
    """FL-4021 overlay completeness gate.

    Returns a list of required fields that are empty in `overlay_row`,
    minus any whose check has been explicitly bypassed via CLI flag.
    """
    missing: list[str] = []
    code_refs = overlay_row.get("CodeRefs") or []
    if not code_refs and not getattr(args, "allow_empty_coderefs", False):
        missing.append("CodeRefs (--overlay-code-ref)")
    complaint_refs = overlay_row.get("ComplaintRefs") or []
    bypass_parent = (
        getattr(args, "no_parent", False)
        or getattr(args, "allow_empty_complaint_refs", False)
    )
    if not complaint_refs and not bypass_parent:
        missing.append("ComplaintRefs (--overlay-complaint-ref, or --no-parent)")
    return missing


def _write_overlay_rows(root: Path, rows: list[dict]) -> bool:
    # FL-4582: overlay rows live in the sidecar JSONL, not the prose ledger.
    fl_path = canonical_failure_log_path(root)
    if not fl_path.exists():
        return False
    append_overlay_rows(fl_path, rows)
    _replace_failure_log_snapshot_after_write(fl_path)
    return True
def _repo_relative_str(root: Path, path: Path | str) -> str:
    p = Path(path)
    try:
        return str(p.resolve().relative_to(root.resolve()))
    except (OSError, ValueError):
        return str(path)


def _dedupe_preserve_order(values: list[str]) -> list[str]:
    out: list[str] = []
    seen: set[str] = set()
    for value in values:
        cleaned = str(value).strip()
        if not cleaned or cleaned in seen:
            continue
        seen.add(cleaned)
        out.append(cleaned)
    return out


def _append_fl_auto_overlay_refs(
    root: Path,
    fl_id: str,
    *,
    touched_files: list[str],
    code_refs: list[str],
) -> dict[str, Any]:
    fl_path = canonical_failure_log_path(root)
    current = shared_read_fl_overlay(fl_path).get(fl_id, {})
    existing_touched = _normalize_overlay_list_value(current.get("TouchedFiles"))
    existing_code_refs = _normalize_overlay_list_value(current.get("CodeRefs"))
    merged_touched = _dedupe_preserve_order(existing_touched + touched_files)
    merged_code_refs = _dedupe_preserve_order(existing_code_refs + code_refs)
    row: dict[str, Any] = {"fl": fl_id}
    if merged_touched != existing_touched:
        row["TouchedFiles"] = merged_touched
    if merged_code_refs != existing_code_refs:
        row["CodeRefs"] = merged_code_refs
    if len(row) == 1:
        return {
            "written": False,
            "row": None,
            "added_touched_files": [],
            "added_code_refs": [],
        }
    wrote = _write_overlay_rows(root, [row])
    return {
        "written": wrote,
        "row": row if wrote else None,
        "added_touched_files": [item for item in merged_touched if item not in existing_touched],
        "added_code_refs": [item for item in merged_code_refs if item not in existing_code_refs],
    }


def _validate_fix_attempt_overlay_refs(
    touched_files: list[str],
    code_refs: list[str],
) -> None:
    def validate_repo_path(path_text: str, option_name: str) -> None:
        path = Path(path_text)
        if path.is_absolute() or ".." in path.parts or path_text in {"", "."}:
            raise ValueError(
                f"{option_name} must be a non-empty repository-relative path: {path_text!r}"
            )
        if "\n" in path_text or "\r" in path_text:
            raise ValueError(f"{option_name} must not contain a newline")

    for path_text in touched_files:
        validate_repo_path(path_text, "--touched-file")
    for ref in code_refs:
        match = re.fullmatch(r"(.+):(\d+)(?:-(\d+))?", ref)
        if not match:
            raise ValueError(
                f"--code-ref must use repository-relative PATH:LINE or PATH:START-END syntax: {ref!r}"
            )
        validate_repo_path(match.group(1), "--code-ref")
        start = int(match.group(2))
        end = int(match.group(3) or start)
        if start < 1 or end < start:
            raise ValueError(f"--code-ref has an invalid line range: {ref!r}")


def load_fl_overlay(root: Path) -> dict:
    """Return effective metadata from the request-scoped snapshot owner."""
    load_fl_index(root)
    return _failure_log_snapshot(root).effective_overlay()


def fl_entries_missing_overlay(entries: list[dict], overlay_raw: dict) -> list[dict]:
    """Entries that have no explicit raw overlay row and rely on synthesized defaults."""
    return [e for e in entries if (e.get("fl") or "") not in overlay_raw]


def fl_entries_with_placeholder_overlay(entries: list[dict], overlay_raw: dict) -> list[dict]:
    """Entries whose raw overlay row is only the minimal placeholder metadata."""
    return [
        e
        for e in entries
        if fl_overlay_row_is_minimal_placeholder(overlay_raw.get(e.get("fl") or ""))
    ]


def _entry_texts(e: dict) -> tuple:
    raw = _fl_text(e)
    return raw.lower(), _norm_text(raw)


def _snippet_hit(e: dict, snippets: list) -> bool:
    """True if any snippet appears (exact or whitespace-normalized) in entry text."""
    if not snippets:
        return False
    raw, norm = _entry_texts(e)
    for sn in snippets:
        if sn.lower() in raw or _norm_text(sn) in norm:
            return True
    return False


_POLICY_ACCEPT_KEYS = (
    "fix direction applied",
    "what changed",
    "keep ",
    "accepted direction",
    "commit ",
    "canonical",
)
_POLICY_REJECT_KEYS = (
    "reverted",
    "rejected",
    "removed",
    "do not",
    "disabled",
    "disabled by",
    "broadening",
    "fallback",
)


def _policy_lines(e: dict, keys: tuple, max_lines: int = 2) -> list:
    """Extract most relevant lines from entry body for policy difference display."""
    results = []
    for line in e.get("_lines") or []:
        ls = line.strip()
        lsl = ls.lower()
        if any(k in lsl for k in keys) and len(ls) > 15 and not ls.startswith("#"):
            results.append(ls[:100])
            if len(results) >= max_lines:
                break
    return results


_FILE_LINE_RE = re.compile(r"(?<!//)([a-zA-Z_][a-zA-Z0-9_/.-]*\.[a-z]+):(\d+)")
# Known TLD-like extensions that are NOT source files — filter these from file refs.
_NON_FILE_EXTENSIONS = frozenset({
    "com", "org", "net", "io", "dev", "app", "co", "uk", "us", "eu",
    "edu", "gov", "mil", "int",
})
_COMMIT_RE = re.compile(r"`([0-9a-f]{7,12})`|\b([0-9a-f]{8,12})\b")


def _extract_file_refs(entries: list, limit: int | None = 12) -> list:
    """Extract unique file:line refs from a list of FL entries."""
    seen, refs = set(), []
    for e in entries:
        for line in e.get("_lines") or []:
            for m in _FILE_LINE_RE.finditer(line):
                fname = m.group(1)
                ext = fname.rsplit(".", 1)[-1] if "." in fname else ""
                if ext in _NON_FILE_EXTENSIONS:
                    continue
                ref = f"{fname}:{m.group(2)}"
                if ref not in seen:
                    seen.add(ref)
                    refs.append(ref)
    return refs if limit is None else refs[:limit]


def _extract_commits(entries: list) -> list:
    """Extract unique short commit hashes from a list of FL entries."""
    seen, commits = set(), []
    for e in entries:
        c = e.get("commit")
        if c and c not in seen:
            seen.add(c)
            commits.append(c)
        for line in e.get("_lines") or []:
            for m in _COMMIT_RE.finditer(line):
                h = m.group(1) or m.group(2)
                # Skip pure-decimal strings (dates, versions); real hashes always have a-f
                if h and h not in seen and any(c in "abcdef" for c in h):
                    seen.add(h)
                    commits.append(h)
    return commits[:6]


def _diff_paths_from_refs(refs: list, max_paths: int = 4) -> list:
    """Convert file:line refs into unique file paths for git diff."""
    paths, seen = [], set()
    for ref in refs:
        path = ref.split(":", 1)[0]
        if path not in seen:
            seen.add(path)
            paths.append(path)
            if len(paths) >= max_paths:
                break
    return paths


_LEGACY_REF_PREFIX_REWRITES: tuple[tuple[str, str], ...] = (
    ("scripts/asset_gen/", "scripts/pipeline/"),
    ("scripts/tests/", "tests/scripts_tests/"),
    ("io_asciicker/", "addons/io_asciicker/"),
    ("io_mesh_akm/", "addons/io_mesh_akm/"),
    ("io_scene_a3d/", "addons/io_scene_a3d/"),
    ("io_scene_a3d_tools/", "addons/io_scene_a3d_tools/"),
    ("imgui/", "vendor/imgui/"),
    ("SDL/", "vendor/SDL/"),
    ("v8/", "vendor/v8/"),
)
_LEGACY_CPP_BUCKET_DIRS: tuple[str, ...] = ("engine", "editor", "server", "platform", "web")


@lru_cache(maxsize=None)
def _legacy_basename_index(root_str: str) -> dict[str, tuple[str, ...]]:
    root = Path(root_str)
    index: dict[str, list[str]] = {}
    for dirname in _LEGACY_CPP_BUCKET_DIRS:
        bucket = root / dirname
        if not bucket.is_dir():
            continue
        for path in bucket.rglob("*"):
            if not path.is_file():
                continue
            rel = path.relative_to(root).as_posix()
            index.setdefault(path.name, []).append(rel)
    return {name: tuple(paths) for name, paths in index.items()}


def _resolve_repo_ref_path(root: Path, filepath: str) -> str | None:
    """Resolve legacy failure-log/source refs onto the current repo layout."""
    normalized = filepath.strip().replace("\\", "/")
    if not normalized:
        return None
    if (root / normalized).exists():
        return normalized

    for old_prefix, new_prefix in _LEGACY_REF_PREFIX_REWRITES:
        if not normalized.startswith(old_prefix):
            continue
        candidate = new_prefix + normalized[len(old_prefix):]
        if (root / candidate).exists():
            return candidate

    # P5 moved many root-level C/C++ files into bucket dirs while FL refs stayed bare.
    if "/" not in normalized:
        matches = _legacy_basename_index(str(root)).get(normalized, ())
        if len(matches) == 1:
            return matches[0]

    return None


def _run_git_diff(root: Path, commit: str, paths: list, max_lines: int = 40) -> str:
    """Run git diff <commit>^..<commit> -- <paths>. Returns first max_lines lines or ''."""
    if not commit or not paths:
        return ""
    try:
        result = subprocess.run(
            ["git", "diff", f"{commit}^..{commit}", "--"] + paths,
            cwd=str(root),
            capture_output=True,
            text=True,
            timeout=15,
        )
        if result.returncode == 0 and result.stdout.strip():
            lines = result.stdout.splitlines()
            truncated = len(lines) > max_lines
            out = "\n".join(lines[:max_lines])
            if truncated:
                out += f"\n... [diff truncated at {max_lines} lines]"
            return out
    except (subprocess.SubprocessError, OSError) as exc:
        print(f"warning: git diff: {exc}", file=sys.stderr)
    return ""


def _entry_family_scope_tokens(entry: dict) -> set[str]:
    """Overlay/code-owner tokens used to keep semantic FL families in-lane."""
    scope_stopwords = {
        "assets",
        "docs",
        "engine",
        "scripts",
        "server",
        "tests",
        "web",
        "gd",
        "glsl",
        "h",
        "json",
        "md",
        "py",
        "tscn",
    }
    overlay = _fl_overlay_record(entry)
    values: list[str] = []
    for key in ("Category", "Area"):
        value = overlay.get(key)
        if isinstance(value, str) and value.strip():
            values.append(value.strip())
    for key in ("Subsystems", "CodeRefs", "TouchedFiles"):
        values.extend(_fl_overlay_list(entry, key))

    tokens: set[str] = set()
    for value in values:
        text = str(value).strip().lower()
        if not text:
            continue
        for token in re.findall(r"[a-z0-9_]+", text):
            if token in scope_stopwords or token.isdigit() or len(token) <= 2:
                continue
            tokens.add(token)
        if text.startswith("godot_project/"):
            tokens.add("godot_project")
            tokens.add("godot")
        elif text.startswith(("engine/", "server/", "web/")):
            tokens.add("cpp_runtime")
    return tokens


def _semantic_neighbor_in_scope(candidate: dict, seed_scope: set[str], ref_score: int) -> bool:
    if not seed_scope:
        return True
    candidate_scope = _entry_family_scope_tokens(candidate)
    if {"godot", "godot_project", "godot_port"} & seed_scope:
        return bool({"godot", "godot_project", "godot_port", "godot_renderer"} & candidate_scope)
    if seed_scope & candidate_scope:
        return True
    if candidate_scope:
        return False
    # Shared concrete file refs are stronger than broad title terms.
    return ref_score > 0


def _expand_cluster(
    seed_ids: set, entries_by_id: dict, all_entries: list, terms: list
) -> set:
    """Four-pass cluster expansion for fl audit / suggest-related.
    Pass 1: one-hop Related: links
    Pass 2: entries sharing a commit with any FAILED entry in cluster (scoped to avoid noise)
    Pass 3: entries sharing >=2 file refs with FAILED entries in cluster
    Pass 4: top 5 semantic neighbors by (term_score*10 + ref_score)
    """
    expanded = set(seed_ids)

    # Pass 1: one-hop Related: links (forward)
    for fl_id in list(seed_ids):
        e = entries_by_id.get(fl_id)
        if e:
            for rel in e.get("related") or []:
                expanded.add(rel)

    # Pass 1b: reverse links — entries whose Related: field references any seed.
    # Skip hub seeds (fan-in > 4): entries like FL-036 that appear as generic
    # baseline ancestors in many Related: lists would otherwise pull in the
    # entire codebase via reverse expansion.
    reverse_fan_in: dict[str, int] = {}
    for e in all_entries:
        for rel in e.get("related") or []:
            if rel in seed_ids:
                reverse_fan_in[rel] = reverse_fan_in.get(rel, 0) + 1
    bounded_seeds = {s for s in seed_ids if reverse_fan_in.get(s, 0) <= 4}
    for e in all_entries:
        if e["fl"] not in expanded:
            for rel in e.get("related") or []:
                if rel in bounded_seeds:
                    expanded.add(e["fl"])
                    break

    # Pass 1c: overlay ComplaintRefs are first-class lineage edges. They are
    # stored outside the markdown Related: field, so family expansion must read
    # them directly or FL rows look linked in cards but disappear from
    # `fl family` output.
    for fl_id in list(seed_ids):
        e = entries_by_id.get(fl_id)
        if not e:
            continue
        for ref in _fl_overlay_list(e, "ComplaintRefs"):
            ref_id = str(ref).upper()
            if ref_id in entries_by_id:
                expanded.add(ref_id)
    for e in all_entries:
        if e["fl"] in expanded:
            continue
        for ref in _fl_overlay_list(e, "ComplaintRefs"):
            if str(ref).upper() in seed_ids:
                expanded.add(e["fl"])
                break

    # Pass 2: commit-hash expansion scoped to FAILED entries only
    cluster1 = [entries_by_id[fid] for fid in expanded if fid in entries_by_id]
    failed_commits = {
        e.get("commit")
        for e in cluster1
        if status_class(e) == "failed" and e.get("commit")
    }
    if failed_commits:
        for e in all_entries:
            if e["fl"] not in expanded and e.get("commit") in failed_commits:
                expanded.add(e["fl"])

    # Pass 3: file-ref expansion — require >=2 shared refs
    cluster2 = [entries_by_id[fid] for fid in expanded if fid in entries_by_id]
    cluster_failed_refs = set(
        _extract_file_refs([e for e in cluster2 if status_class(e) == "failed"])
    )
    if cluster_failed_refs:
        for e in all_entries:
            if e["fl"] not in expanded:
                entry_refs = set(_extract_file_refs([e]))
                if len(cluster_failed_refs & entry_refs) >= 2:
                    expanded.add(e["fl"])

    # Pass 4: semantic-neighbor expansion
    cluster3 = [entries_by_id[fid] for fid in expanded if fid in entries_by_id]
    cluster_refs = set(_extract_file_refs(cluster3))
    seed_scope: set[str] = set()
    for fl_id in seed_ids:
        seed_entry = entries_by_id.get(fl_id)
        if seed_entry:
            seed_scope.update(_entry_family_scope_tokens(seed_entry))
    neighbors = []
    for e in all_entries:
        if e["fl"] in expanded:
            continue
        text = _fl_text(e).lower()
        term_score = sum(1 for t in terms if t in text)
        ref_score = len(cluster_refs & set(_extract_file_refs([e])))
        if not _semantic_neighbor_in_scope(e, seed_scope, ref_score):
            continue
        score = (term_score * 10) + ref_score
        if score > 0:
            neighbors.append((score, e["num"], e["fl"]))
    neighbors.sort(reverse=True)
    for _, _, fl_id in neighbors[:5]:
        expanded.add(fl_id)

    return expanded


def gap_ann(gaps: dict, gate: str) -> str:
    """Short gap annotation for a gate."""
    gap = gaps.get(gate)
    if not gap:
        return ""
    gap_id = gap.get("id") or "WG-?"
    fl_ref = gap.get("fl_ref") or "-"
    return f"  [{gap_id} — {fl_ref}]"


def run_stage_label(run: dict) -> str:
    """Best-effort stage label for older summaries that lack failed_stage."""
    explicit = run.get("failed_stage") or run.get("stage")
    if explicit:
        return str(explicit)
    verdict = run.get("verdict") or ""
    if verdict == "pass":
        return "-"
    if run.get("timed_out_step"):
        return str(run.get("timed_out_step"))
    if verdict == "infra_fail":
        return run.get("error_kind") or "infra"
    if verdict == "bootstrap_fail":
        return run.get("error_kind") or "bootstrap"
    if verdict == "artifact_invalid":
        return run.get("error_kind") or "artifact"
    if verdict == "launch_blocked":
        return run.get("error_kind") or "prelaunch"
    if verdict in (
        "fail",
        "partial",
        "parity_miss",
        "gameplay_fail",
    ):
        return run.get("error_kind") or verdict
    return "?"


# ---------------------------------------------------------------------------
# Shared artifact utilities (fzf, rg, artifact path)
# ---------------------------------------------------------------------------

import shutil as _shutil

_RG_CHECKED: bool | None = None
_RG_WARNED: bool = False


def _rg_available() -> bool:
    global _RG_CHECKED
    if _RG_CHECKED is None:
        _RG_CHECKED = _shutil.which("rg") is not None
    return _RG_CHECKED


def _rg_search(pattern: str, path: Path, extra_flags: list | None = None) -> list:
    """Search path with rg (fast); fall back to Python readline if rg not found."""
    global _RG_WARNED
    if _rg_available():
        cmd = [
            "rg",
            "--no-heading",
            "--no-line-number",
            "-a",
            "--ignore-case",
            *(extra_flags or []),
            pattern,
            str(path),
        ]
        try:
            result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
            if result.returncode in (0, 1):  # 0=matches, 1=no matches
                return result.stdout.splitlines()
        except (subprocess.SubprocessError, OSError, FileNotFoundError):
            pass
    # Python fallback
    if not _RG_WARNED:
        print(
            "⚠️  rg not found; falling back to Python (install ripgrep for faster searches)",
            file=sys.stderr,
        )
        _RG_WARNED = True
    lines = []
    try:
        pat = re.compile(pattern, re.IGNORECASE)
        with open(path, errors="replace") as f:
            for line in f:
                if pat.search(line):
                    lines.append(line.rstrip("\n"))
    except OSError:
        pass
    return lines


def _maybe_fzf_pick(items: list, prompt: str = "select> ") -> str | None:
    """Present items interactively via fzf. Returns selected item or None."""
    if not sys.stdout.isatty() or not _shutil.which("fzf"):
        return None
    try:
        inp = "\n".join(str(i) for i in items)
        result = subprocess.run(
            ["fzf", "--height=40%", "--reverse", f"--prompt={prompt}"],
            input=inp,
            capture_output=True,
            text=True,
        )
        return result.stdout.strip() or None
    except (subprocess.SubprocessError, OSError, FileNotFoundError):
        return None


def _find_artifact_path(run: dict) -> Path | None:
    """Return the artifact directory for a run, or None if not present locally."""
    art = run.get("artifact_path")
    if not art:
        return None
    p = Path(art)
    return p if p.exists() else None


def _require_artifact_path(run: dict, subcommand: str) -> Path:
    """Like _find_artifact_path but exits with an informative message on failure."""
    p = _find_artifact_path(run)
    if p is None:
        art = run.get("artifact_path", "(unknown)")
        sys.exit(
            f"ERROR {subcommand}: artifact directory not found locally: {art}\n"
            f"  Artifacts are written to /tmp/watchdog-vps-<run-id>/ on the machine that ran the session.\n"
            f"  If you ran the session on a different machine, sync the artifact directory to this machine first."
        )
    return p


# ---------------------------------------------------------------------------
# Recording.jsonl loader
# ---------------------------------------------------------------------------


def _load_recording(rec_path: Path) -> tuple[dict, list, list]:
    """Load recording.jsonl. Returns (meta:dict, events:list, samples:list)."""
    meta: dict = {}
    events: list = []
    samples: list = []
    try:
        with open(rec_path, errors="replace") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = json.loads(line)
                except json.JSONDecodeError:
                    continue
                t = obj.get("type")
                if t == "meta":
                    meta = obj
                elif t == "event":
                    events.append(obj)
                else:
                    samples.append(obj)
    except OSError as exc:
        sys.exit(f"ERROR recorder: could not read {rec_path}: {exc}")
    return meta, events, samples


def _pickup_invalid_gate_result(reason: str, *, artifact_path: Path | None = None) -> dict:
    gates = {key: False for key in PICKUP_POST_RUN_GATE_KEYS}
    return {
        "available": False,
        "reason": reason,
        "window_s": PICKUP_CHAIN_WINDOW_S,
        "event_tolerance_s": PICKUP_CHAIN_EVENT_TOLERANCE_S,
        "artifact_path": str(artifact_path) if artifact_path else None,
        "gates": gates,
        "gate_reasons": {key: reason for key in PICKUP_POST_RUN_GATE_KEYS},
        "chains": [],
        "offending_item_id": None,
        "passing_item_id": None,
    }


def _pickup_item_id(value) -> int | None:
    n = _num(value)
    if n is None:
        return None
    item_id = int(n)
    if item_id <= 0 or item_id == 0xFFFF:
        return None
    return item_id


def _pickup_owner_id(value) -> int | None:
    n = _num(value)
    return int(n) if n is not None else None


def _pickup_sample_time_s(sample: dict, index: int, first_wall_ms: float | None = None) -> float:
    wall_ms = _num(sample.get("wall_ms"))
    if wall_ms is not None and first_wall_ms is not None:
        return (float(wall_ms) - first_wall_ms) / 1000.0
    rel_s = _num(sample.get("rel_s"))
    if rel_s is not None:
        return float(rel_s)
    seq = _num(sample.get("seq"))
    if seq is not None:
        return float(seq)
    return float(index)


def _pickup_tab(sample: dict) -> str:
    return str(sample.get("tab_id") or sample.get("tab") or "-")


def _pickup_visible_ids(sample: dict) -> list[int]:
    raw = sample.get("auth_visible_world_item_ids")
    if isinstance(raw, list):
        ids: list[int] = []
        for value in raw:
            item_id = _pickup_item_id(value)
            if item_id is not None and item_id not in ids:
                ids.append(item_id)
        if ids:
            return ids
    ids: list[int] = []
    for idx in range(9):
        item_id = _pickup_item_id(sample.get(f"auth_visible_world_{idx}"))
        if item_id is not None and item_id not in ids:
            ids.append(item_id)
    return ids


def _pickup_inventory_ids(sample: dict) -> set[int] | None:
    raw = sample.get("actor_inventory_item_ids")
    if not isinstance(raw, list):
        return None
    out: set[int] = set()
    for value in raw:
        item_id = _pickup_item_id(value)
        if item_id is not None:
            out.add(item_id)
    return out


def _pickup_new_chain(item_id: int) -> dict:
    return {
        "item_id": item_id,
        "map_authored_at": None,
        "server_world_at": None,
        "visible_at": None,
        "intent_at": None,
        "transition_at": None,
        "transition_kind": None,
        "intent_owners": [],
        "first_seen_at": None,
        "tabs": [],
        "visible_tabs": [],
        "intent_tabs": [],
        "transition_tabs": [],
    }


def _pickup_chain(chains: dict[int, dict], item_id: int) -> dict:
    if item_id not in chains:
        chains[item_id] = _pickup_new_chain(item_id)
    return chains[item_id]


def _pickup_set_first(chain: dict, field: str, at_s: float) -> None:
    cur = chain.get(field)
    if cur is None or at_s < cur:
        chain[field] = at_s
    if chain.get("first_seen_at") is None or at_s < chain["first_seen_at"]:
        chain["first_seen_at"] = at_s


def _pickup_note_tab(chain: dict, field: str, tab: str) -> None:
    tabs = chain.get(field)
    if isinstance(tabs, list) and tab not in tabs:
        tabs.append(tab)


def _pickup_intent_owner(reason) -> str:
    n = _num(reason)
    if n is None:
        return "explicit_pickup_request"
    return PICKUP_INTENT_OWNER_BY_REASON.get(int(n), f"pickup_reason_{int(n)}")


def _pickup_note_intent_owner(chain: dict, owner: str) -> None:
    owners = chain.get("intent_owners")
    if isinstance(owners, list) and owner not in owners:
        owners.append(owner)


def _derive_pickup_chain_gate_reason(gates: dict, violation: dict | None) -> str:
    if violation:
        return "pickup_without_prior_visible_item"
    missing = [key for key in PICKUP_POST_RUN_GATE_KEYS if gates.get(key) is False]
    if not missing:
        return "ok"
    priority = (
        ("pickup_map_item_authorship_observed", "missing_map_authored_item"),
        ("pickup_server_world_item_observed", "missing_server_world_item"),
        ("pickup_client_rendered_world_item_observed", "missing_visible_world_item"),
        ("pickup_intent_observed", "missing_explicit_pickup_intent"),
        ("pickup_ownership_transition_observed", "missing_ownership_transition"),
        ("pickup_visible_legitimate_chain_observed", "missing_same_item_visible_pickup_chain"),
        ("pickup_any_transition_observed", "no_pickup_intent_or_transition_observed"),
    )
    for gate, reason in priority:
        if gate in missing:
            return reason
    return "missing_pickup_signal"


def derive_pickup_chain_for_samples(
    samples: list,
    *,
    window_s: float = PICKUP_CHAIN_WINDOW_S,
) -> dict:
    """Derive canonical pickup gates from the full recorder window.

    The pass path is same-item only: map/server world observation, visible world
    rendering, explicit pickup request, and ownership/inventory transition must
    all refer to the same item_id inside the configured window.
    """
    chains: dict[int, dict] = {}
    prev_pickup_sent_by_tab: dict[str, int] = {}
    prev_inventory_by_tab: dict[str, set[int] | None] = {}
    violations: list[dict] = []
    invalid_intent_count = 0

    indexed = list(enumerate(samples or []))
    wall_values = [
        float(wall_ms)
        for _idx, sample in indexed
        if isinstance(sample, dict)
        for wall_ms in [_num(sample.get("wall_ms"))]
        if wall_ms is not None
    ]
    first_wall_ms = min(wall_values) if wall_values else None
    indexed.sort(key=lambda pair: (_pickup_sample_time_s(pair[1], pair[0], first_wall_ms), pair[0]))

    def record_transition(item_id: int, at_s: float, tab: str, kind: str) -> None:
        chain = _pickup_chain(chains, item_id)
        if chain.get("transition_at") is None or at_s < chain["transition_at"]:
            chain["transition_at"] = at_s
            chain["transition_kind"] = kind
        _pickup_note_tab(chain, "transition_tabs", tab)
        visible_at = chain.get("visible_at")
        if visible_at is None or visible_at > at_s + PICKUP_CHAIN_EVENT_TOLERANCE_S:
            violations.append(
                {
                    "reason": "pickup_without_prior_visible_item",
                    "item_id": item_id,
                    "transition_at": at_s,
                    "transition_kind": kind,
                    "tab": tab,
                    "visible_at": visible_at,
                }
            )

    for index, sample in indexed:
        if not isinstance(sample, dict):
            continue
        at_s = _pickup_sample_time_s(sample, index, first_wall_ms)
        tab = _pickup_tab(sample)

        item_samples = sample.get("auth_item_sample") or []
        if isinstance(item_samples, list):
            for item in item_samples:
                if not isinstance(item, dict):
                    continue
                item_id = _pickup_item_id(item.get("id"))
                if item_id is None:
                    continue
                chain = _pickup_chain(chains, item_id)
                _pickup_note_tab(chain, "tabs", tab)
                source_kind = _num(item.get("source_kind"))
                state_flags = _num(item.get("state_flags"))
                map_authored = source_kind == 1 or (
                    state_flags is not None
                    and (int(state_flags) & PICKUP_MAP_AUTHORED_STATE_FLAG) != 0
                )
                if map_authored:
                    _pickup_set_first(chain, "map_authored_at", at_s)
                owner_id = _pickup_owner_id(item.get("owner_id"))
                if owner_id == 0xFFFF:
                    _pickup_set_first(chain, "server_world_at", at_s)
                elif owner_id is not None and (
                    chain.get("map_authored_at") is not None
                    or chain.get("server_world_at") is not None
                    or chain.get("visible_at") is not None
                    or chain.get("intent_at") is not None
                    or map_authored
                ):
                    record_transition(item_id, at_s, tab, "server_owner_change")

        for item_id in _pickup_visible_ids(sample):
            chain = _pickup_chain(chains, item_id)
            _pickup_set_first(chain, "visible_at", at_s)
            _pickup_note_tab(chain, "visible_tabs", tab)

        sent = _num(sample.get("auth_pickup_req_sent"))
        if sent is not None:
            sent_i = int(sent)
            prev_sent = prev_pickup_sent_by_tab.get(tab, 0)
            if sent_i > prev_sent:
                item_id = _pickup_item_id(sample.get("auth_pickup_req_last_item_id"))
                if item_id is None:
                    invalid_intent_count += sent_i - prev_sent
                else:
                    chain = _pickup_chain(chains, item_id)
                    source_strip_item_id = _pickup_item_id(
                        sample.get("auth_pickup_req_source_strip_item_id")
                    )
                    source_strip_count = _num(sample.get("auth_pickup_req_source_strip_count"))
                    if (
                        source_strip_item_id == item_id
                        and source_strip_count is not None
                        and int(source_strip_count) > 0
                    ):
                        _pickup_set_first(chain, "visible_at", at_s)
                        _pickup_note_tab(chain, "visible_tabs", tab)
                    _pickup_set_first(chain, "intent_at", at_s)
                    _pickup_note_tab(chain, "intent_tabs", tab)
                    _pickup_note_intent_owner(
                        chain,
                        _pickup_intent_owner(sample.get("auth_pickup_req_last_reason")),
                    )
            prev_pickup_sent_by_tab[tab] = max(prev_sent, sent_i)

        event_kind = _num(sample.get("auth_item_local_event_kind"))
        event_item_id = _pickup_item_id(sample.get("auth_item_local_event_item_id"))
        if (
            event_kind is not None
            and event_kind > 0
            and int(event_kind) != ITEM_CHANGE_KIND_EQUIP_SET
            and event_item_id is not None
        ):
            record_transition(event_item_id, at_s, tab, "client_local_item_event")

        inv_ids = _pickup_inventory_ids(sample)
        if inv_ids is not None:
            prev_inv = prev_inventory_by_tab.get(tab)
            for item_id in sorted(inv_ids):
                chain = chains.get(item_id)
                added = prev_inv is not None and item_id not in prev_inv
                after_intent = bool(
                    chain
                    and chain.get("intent_at") is not None
                    and chain["intent_at"] <= at_s + PICKUP_CHAIN_EVENT_TOLERANCE_S
                )
                if added or (prev_inv is None and after_intent):
                    record_transition(item_id, at_s, tab, "actor_inventory_item_ids")
            prev_inventory_by_tab[tab] = inv_ids

    eps = PICKUP_CHAIN_EVENT_TOLERANCE_S

    def before_or_same(a, b) -> bool:
        return a is not None and b is not None and a <= b + eps

    def within(a, b) -> bool:
        return a is not None and b is not None and (b - a) <= window_s + eps

    passing: list[dict] = []
    for chain in chains.values():
        if (
            before_or_same(chain.get("map_authored_at"), chain.get("visible_at"))
            and before_or_same(chain.get("server_world_at"), chain.get("visible_at"))
            and before_or_same(chain.get("visible_at"), chain.get("intent_at"))
            and before_or_same(chain.get("intent_at"), chain.get("transition_at"))
            and within(chain.get("visible_at"), chain.get("transition_at"))
            and within(chain.get("intent_at"), chain.get("transition_at"))
        ):
            passing.append(chain)

    passing_item_ids = {chain.get("item_id") for chain in passing}
    unresolved_violations = [
        violation
        for violation in violations
        if violation.get("item_id") not in passing_item_ids
    ]
    violation = unresolved_violations[0] if unresolved_violations else None
    gates = {
        "pickup_map_item_authorship_observed": any(
            c.get("map_authored_at") is not None for c in chains.values()
        ),
        "pickup_server_world_item_observed": any(
            c.get("server_world_at") is not None for c in chains.values()
        ),
        "pickup_client_rendered_world_item_observed": any(
            c.get("visible_at") is not None for c in chains.values()
        ),
        "pickup_intent_observed": any(
            c.get("intent_at") is not None for c in chains.values()
        ),
        "pickup_ownership_transition_observed": any(
            c.get("transition_at") is not None for c in chains.values()
        ),
        "pickup_visible_legitimate_chain_observed": bool(passing) and violation is None,
    }
    # FL-3803: pickup_signal_observed is ALIAS for pickup_visible_legitimate_chain_observed.
    # Name is misleading — means "full same-item chain observed", not "any signal observed."
    # Use pickup_any_transition_observed for the weaker "any pickup happened" check.
    gates["pickup_signal_observed"] = gates["pickup_visible_legitimate_chain_observed"]
    gates["pickup_any_transition_observed"] = (
        gates["pickup_intent_observed"] is True
        or gates["pickup_ownership_transition_observed"] is True
    )

    reason = _derive_pickup_chain_gate_reason(gates, violation)
    gate_reasons = {
        key: None if value is True else reason
        for key, value in gates.items()
    }
    if gates["pickup_visible_legitimate_chain_observed"] is False and not violation:
        gate_reasons["pickup_visible_legitimate_chain_observed"] = reason
        gate_reasons["pickup_signal_observed"] = reason
    if gates["pickup_any_transition_observed"] is False:
        gate_reasons["pickup_any_transition_observed"] = reason

    def render_chain(chain: dict) -> dict:
        return {
            "item_id": chain.get("item_id"),
            "map_authored_at": chain.get("map_authored_at"),
            "server_world_at": chain.get("server_world_at"),
            "visible_at": chain.get("visible_at"),
            "intent_at": chain.get("intent_at"),
            "transition_at": chain.get("transition_at"),
            "transition_kind": chain.get("transition_kind"),
            "intent_owners": chain.get("intent_owners") or [],
            "tabs": chain.get("tabs") or [],
            "visible_tabs": chain.get("visible_tabs") or [],
            "intent_tabs": chain.get("intent_tabs") or [],
            "transition_tabs": chain.get("transition_tabs") or [],
            "passes_same_item_window": chain in passing and violation is None,
        }

    rendered_chains = [
        render_chain(chain)
        for chain in sorted(
            chains.values(),
            key=lambda c: (
                c.get("first_seen_at") if c.get("first_seen_at") is not None else math.inf,
                c.get("item_id") or 0,
            ),
        )
    ]
    return {
        "available": True,
        "reason": reason,
        "window_s": window_s,
        "event_tolerance_s": PICKUP_CHAIN_EVENT_TOLERANCE_S,
        "sample_count": len(samples or []),
        "gates": gates,
        "gate_reasons": gate_reasons,
        "chains": rendered_chains,
        "offending_item_id": violation.get("item_id") if violation else None,
        "offending_transition": violation,
        "passing_item_id": passing[0].get("item_id") if passing else None,
        "invalid_intent_count": invalid_intent_count,
        "intent_owners": sorted(
            {
                owner
                for chain in rendered_chains
                for owner in (chain.get("intent_owners") or [])
            }
        ),
    }


def derive_pickup_chain_for_artifact(
    art: Path,
    *,
    window_s: float = PICKUP_CHAIN_WINDOW_S,
) -> dict:
    rec_path = art / "recorder" / "recording.jsonl"
    if not rec_path.exists():
        result = _pickup_invalid_gate_result("recording_jsonl_missing", artifact_path=art)
        result["recording_path"] = str(rec_path)
        return result
    _meta, _events, samples = _load_recording(rec_path)
    result = derive_pickup_chain_for_samples(samples, window_s=window_s)
    result["artifact_path"] = str(art)
    result["recording_path"] = str(rec_path)
    return result


def cmd_pickup_chain(args, root: Path) -> None:
    if getattr(args, "artifact_path", None):
        art = Path(args.artifact_path).expanduser().resolve()
    else:
        if not getattr(args, "run_id", None):
            sys.exit("ERROR pickup-chain: run_id or --artifact-path is required")
        run = load_run_by_id(root, args.run_id)
        art = _require_artifact_path(run, "pickup-chain")
    result = derive_pickup_chain_for_artifact(art, window_s=args.window_s)
    if getattr(args, "json", False):
        print(json.dumps(result, indent=2, sort_keys=True))
        return

    gates = result.get("gates") or {}
    print("POST-RUN PICKUP CHAIN")
    print(f"  artifact:  {result.get('artifact_path') or art}")
    print(f"  recording: {result.get('recording_path') or '-'}")
    print(f"  reason:    {result.get('reason') or '-'}")
    print(f"  window_s:  {result.get('window_s')}")
    print(f"  tolerance: {result.get('event_tolerance_s')}")
    print(f"  pass_item: {result.get('passing_item_id') or '-'}")
    print(f"  offender:  {result.get('offending_item_id') or '-'}")
    rows = []
    for gate in PICKUP_POST_RUN_GATE_KEYS:
        rows.append([gate, fmt_bool(gates.get(gate)), (result.get("gate_reasons") or {}).get(gate) or "-"])
    _print_table(["gate", "state", "reason"], rows)
    chains = result.get("chains") or []
    if chains:
        chain_rows = []
        for chain in chains[:12]:
            chain_rows.append(
                [
                    chain.get("item_id"),
                    chain.get("map_authored_at"),
                    chain.get("server_world_at"),
                    chain.get("visible_at"),
                    chain.get("intent_at"),
                    chain.get("transition_at"),
                    chain.get("transition_kind") or "-",
                    chain.get("passes_same_item_window"),
                ]
            )
        _print_table(
            ["item", "map", "server", "visible", "intent", "transition", "kind", "pass"],
            chain_rows,
        )
        if len(chains) > 12:
            print(f"... {len(chains) - 12} more item chains")


def _fl4162_int(value: object) -> int | None:
    value_num = _num(value)
    return int(value_num) if value_num is not None else None


def _fl4162_int_list(sample: dict, key: str) -> list[int] | None:
    values = sample.get(key)
    if not isinstance(values, list):
        return None
    result: list[int] = []
    for value in values:
        value_int = _fl4162_int(value)
        if value_int is None:
            return None
        result.append(value_int)
    return result


def _fl4162_semantic_sets(sample: dict) -> list[list[str]] | None:
    values = sample.get("actor_render_layer_semantic_contributions")
    if not isinstance(values, list):
        return None
    result: list[list[str]] = []
    for contribution_set in values:
        if not isinstance(contribution_set, list) or not contribution_set:
            return None
        if any(not isinstance(value, str) or not value for value in contribution_set):
            return None
        result.append(list(contribution_set))
    return result


def _fl4162_expected_key_from_server(sample: dict) -> tuple[dict, str | None]:
    scalar_pairs = (
        ("skin_id", "actor_appearance_skin_definition_id"),
        ("presentation_kind_id", "actor_server_presentation_kind_id"),
        ("variation_id", "actor_appearance_variation_id"),
        ("mount_id", "actor_appearance_mount_definition_id"),
        ("rig_id", "actor_appearance_rig_id"),
    )
    expected: dict[str, object] = {"actor_style_id": 0}
    for target, source in scalar_pairs:
        value = _fl4162_int(sample.get(source))
        if value is None:
            return {}, f"missing_{source}"
        expected[target] = value

    slots = _fl4162_int_list(sample, "actor_appearance_slot_kind_ids")
    definitions = _fl4162_int_list(sample, "actor_appearance_definition_ids")
    styles = _fl4162_int_list(sample, "actor_appearance_visual_style_ids")
    if slots is None or definitions is None or styles is None:
        return {}, "missing_actor_appearance_entry_arrays"
    if len(slots) != len(definitions) or len(slots) != len(styles):
        return {}, "actor_appearance_entry_array_length_mismatch"

    expected.update(
        {
            "head_item_id": 0,
            "head_style_id": 0,
            "chest_item_id": 0,
            "chest_style_id": 0,
            "weapon_item_id": 0,
            "weapon_style_id": 0,
            "shield_item_id": 0,
            "shield_style_id": 0,
        }
    )
    future: list[tuple[int, int, int]] = []
    for slot, definition, style in zip(slots, definitions, styles):
        fixed_fields = FL4162_FIXED_SLOT_KEY_FIELDS.get(slot)
        if fixed_fields:
            expected[fixed_fields[0].removeprefix("actor_render_key_")] = definition
            expected[fixed_fields[1].removeprefix("actor_render_key_")] = style
        elif slot not in (300, 307):
            future.append((slot, definition, style))
    if len(future) > 4:
        return {}, "actor_appearance_future_slot_overflow"
    future.sort(key=lambda row: (row[0], row[1]))
    while len(future) < 4:
        future.append((0, 0, 0))
    expected["future_slot_kind_ids"] = [row[0] for row in future]
    expected["future_item_ids"] = [row[1] for row in future]
    expected["future_style_ids"] = [row[2] for row in future]
    return expected, None


def _fl4162_render_key_matches(sample: dict, expected: dict) -> tuple[bool, str | None]:
    for field, expected_value in expected.items():
        recorder_field = f"actor_render_key_{field}"
        if isinstance(expected_value, list):
            actual = _fl4162_int_list(sample, recorder_field)
        else:
            actual = _fl4162_int(sample.get(recorder_field))
        if actual != expected_value:
            return False, f"{recorder_field}_mismatch"
    return True, None


def derive_fl4162_actor_visual_parity_for_samples(samples: list) -> dict:
    """Derive the FL-4162 runtime contract join across the full recording.

    The analyzer reconstructs the exact key from recorded server AppearanceStateV2,
    compares it with the key actually selected by the renderer, and verifies that
    first-class semantic contribution sets reached visible source layers. Any
    contradictory active sample keeps the aggregate gate red.
    """
    active_samples = 0
    valid_samples = 0
    composite_witnesses: list[dict] = []
    contradictions: list[dict] = []
    evidence_failures = 0
    key_failures = 0
    semantic_failures = 0
    legacy_failures = 0

    required_layer_arrays = (
        "actor_render_layer_semantic_contribution_set_indices",
        "actor_render_layer_source_layer_indices",
        "actor_render_layer_contributed_cell_counts",
    )

    for index, sample in enumerate(samples or []):
        if not isinstance(sample, dict):
            continue
        compiled_profile_found = _fl4162_int(
            sample.get("actor_profile_selector_found")
        )
        if compiled_profile_found != 1:
            continue
        active_samples += 1
        tab = sample.get("tab_id") or sample.get("tab") or "-"
        rel_s = sample.get("rel_s")

        expected, expected_error = _fl4162_expected_key_from_server(sample)
        if expected_error:
            evidence_failures += 1
            key_failures += 1
            contradictions.append(
                {
                    "index": index,
                    "tab": tab,
                    "rel_s": rel_s,
                    "reason": expected_error,
                    "failed_gates": [
                        "evidence_fl4162_runtime_contract_fields_present",
                        "gameplay_fl4162_exact_server_key_selected",
                    ],
                }
            )
            continue
        key_matches, key_error = _fl4162_render_key_matches(sample, expected)
        if not key_matches:
            key_failures += 1
            contradictions.append(
                {
                    "index": index,
                    "tab": tab,
                    "rel_s": rel_s,
                    "reason": key_error,
                    "failed_gates": ["gameplay_fl4162_exact_server_key_selected"],
                }
            )

        layer_count = _fl4162_int(sample.get("actor_profile_layer_count"))
        semantic_sets = _fl4162_semantic_sets(sample)
        numeric_arrays = {
            key: _fl4162_int_list(sample, key) for key in required_layer_arrays
        }
        if layer_count is None or layer_count <= 0:
            evidence_failures += 1
            semantic_failures += 1
            contradictions.append(
                {
                    "index": index,
                    "tab": tab,
                    "rel_s": rel_s,
                    "reason": "render_layer_count_missing",
                    "failed_gates": [
                        "evidence_fl4162_runtime_contract_fields_present",
                        "gameplay_fl4162_composite_semantics_rendered",
                    ],
                }
            )
            continue
        if semantic_sets is None or len(semantic_sets) != layer_count:
            evidence_failures += 1
            semantic_failures += 1
            contradictions.append(
                {
                    "index": index,
                    "tab": tab,
                    "rel_s": rel_s,
                    "reason": "semantic_contribution_shape_mismatch",
                    "failed_gates": [
                        "evidence_fl4162_runtime_contract_fields_present",
                        "gameplay_fl4162_composite_semantics_rendered",
                    ],
                }
            )
            continue
        malformed_array = next(
            (
                key
                for key, values in numeric_arrays.items()
                if values is None or len(values) != layer_count
            ),
            None,
        )
        if malformed_array:
            evidence_failures += 1
            semantic_failures += 1
            contradictions.append(
                {
                    "index": index,
                    "tab": tab,
                    "rel_s": rel_s,
                    "reason": f"{malformed_array}_shape_mismatch",
                    "failed_gates": [
                        "evidence_fl4162_runtime_contract_fields_present",
                        "gameplay_fl4162_composite_semantics_rendered",
                    ],
                }
            )
            continue
        fallback_value = _fl4162_int(
            sample.get("actor_render_fail_visible_fallback_used")
        )
        compose_failure_value = _fl4162_int(
            sample.get("actor_render_original_compose_failure_stage")
        )
        fallback_used = fallback_value not in (None, 0)
        compose_failure_owner_used = compose_failure_value not in (None, 0)
        for field, value in (
            ("actor_render_fail_visible_fallback_used", fallback_value),
            ("actor_render_original_compose_failure_stage", compose_failure_value),
        ):
            if value is None:
                evidence_failures += 1
                legacy_failures += 1
                contradictions.append(
                    {
                        "index": index,
                        "tab": tab,
                        "rel_s": rel_s,
                        "reason": f"missing_{field}",
                        "failed_gates": [
                            "evidence_fl4162_runtime_contract_fields_present",
                            "gameplay_fl4162_legacy_fallback_absent",
                        ],
                    }
                )
        if fallback_used:
            legacy_failures += 1
            contradictions.append(
                {
                    "index": index,
                    "tab": tab,
                    "rel_s": rel_s,
                    "reason": "legacy_fail_visible_fallback_used",
                    "failed_gates": ["gameplay_fl4162_legacy_fallback_absent"],
                }
            )
        if compose_failure_owner_used:
            legacy_failures += 1
            contradictions.append(
                {
                    "index": index,
                    "tab": tab,
                    "rel_s": rel_s,
                    "reason": "legacy_compose_failure_owner_used",
                    "failed_gates": ["gameplay_fl4162_legacy_fallback_absent"],
                }
            )

        if (
            key_matches
            and fallback_value == 0
            and compose_failure_value == 0
        ):
            valid_samples += 1
        contributed = numeric_arrays["actor_render_layer_contributed_cell_counts"] or []
        for layer_index, contributions in enumerate(semantic_sets):
            if len(contributions) > 1 and contributed[layer_index] > 0:
                composite_witnesses.append(
                    {
                        "index": index,
                        "tab": tab,
                        "rel_s": rel_s,
                        "layer_index": layer_index,
                        "semantic_contributions": contributions,
                        "semantic_contribution_set_index": numeric_arrays[
                            "actor_render_layer_semantic_contribution_set_indices"
                        ][layer_index],
                        "source_layer_index": numeric_arrays[
                            "actor_render_layer_source_layer_indices"
                        ][layer_index],
                        "contributed_cell_count": contributed[layer_index],
                    }
                )

    fields_present = active_samples > 0 and evidence_failures == 0
    exact_key_selected = active_samples > 0 and key_failures == 0
    composite_rendered = (
        active_samples > 0 and semantic_failures == 0 and bool(composite_witnesses)
    )
    legacy_absent = active_samples > 0 and legacy_failures == 0
    gates = {
        "evidence_fl4162_runtime_contract_fields_present": fields_present,
        "gameplay_fl4162_exact_server_key_selected": exact_key_selected,
        "gameplay_fl4162_composite_semantics_rendered": composite_rendered,
        "gameplay_fl4162_legacy_fallback_absent": legacy_absent,
    }
    gates["gameplay_fl4162_runtime_contract_parity"] = all(gates.values())
    if active_samples == 0:
        reason = "no_active_compiled_actor_visual_sample"
    elif contradictions:
        reason = contradictions[0]["reason"]
    elif not composite_witnesses:
        reason = "no_positive_composite_semantic_witness"
    else:
        reason = "ok"
    return {
        "available": active_samples > 0,
        "reason": reason,
        "sample_count": len(samples or []),
        "active_sample_count": active_samples,
        "valid_sample_count": valid_samples,
        "evidence_failure_count": evidence_failures,
        "key_failure_count": key_failures,
        "semantic_failure_count": semantic_failures,
        "legacy_failure_count": legacy_failures,
        "gates": gates,
        "gate_reasons": {
            gate: None if state else reason for gate, state in gates.items()
        },
        "contradictions": contradictions,
        "composite_witnesses": composite_witnesses,
        "visual_operator_signoff_required": True,
    }


def derive_fl4162_actor_visual_parity_for_artifact(art: Path) -> dict:
    rec_path = art / "recorder" / "recording.jsonl"
    if not rec_path.exists():
        return {
            "available": False,
            "reason": "recording_jsonl_missing",
            "artifact_path": str(art),
            "recording_path": str(rec_path),
            "gates": {gate: False for gate in FL4162_ACTOR_VISUAL_PARITY_GATE_KEYS},
            "gate_reasons": {
                gate: "recording_jsonl_missing" for gate in FL4162_ACTOR_VISUAL_PARITY_GATE_KEYS
            },
            "contradictions": [],
            "composite_witnesses": [],
            "visual_operator_signoff_required": True,
        }
    _meta, _events, samples = _load_recording(rec_path)
    result = derive_fl4162_actor_visual_parity_for_samples(samples)
    result["artifact_path"] = str(art)
    result["recording_path"] = str(rec_path)
    return result


def cmd_actor_visual_parity(args, root: Path) -> None:
    if getattr(args, "artifact_path", None):
        art = Path(args.artifact_path).expanduser().resolve()
    else:
        if not getattr(args, "run_id", None):
            sys.exit("ERROR actor-visual-parity: run_id or --artifact-path is required")
        run = load_run_by_id(root, args.run_id)
        art = _require_artifact_path(run, "actor-visual-parity")
    result = derive_fl4162_actor_visual_parity_for_artifact(art)
    if getattr(args, "json", False):
        print(json.dumps(result, indent=2, sort_keys=True))
        return

    print("POST-RUN FL-4162 ACTOR VISUAL CONTRACT PARITY")
    print(f"  artifact:      {result.get('artifact_path') or art}")
    print(f"  recording:     {result.get('recording_path') or '-'}")
    print(f"  reason:        {result.get('reason') or '-'}")
    print(f"  active rows:   {result.get('active_sample_count', 0)}")
    print(f"  valid rows:    {result.get('valid_sample_count', 0)}")
    print(f"  composites:    {len(result.get('composite_witnesses') or [])}")
    print("  visual review: operator signoff required")
    rows = []
    gates = result.get("gates") or {}
    reasons = result.get("gate_reasons") or {}
    for gate in FL4162_ACTOR_VISUAL_PARITY_GATE_KEYS:
        rows.append([gate, fmt_bool(gates.get(gate)), reasons.get(gate) or "-"])
    _print_table(["gate", "state", "reason"], rows)


def _parse_iso_ms(text: object) -> float | None:
    if not isinstance(text, str) or not text:
        return None
    try:
        dt = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt.timestamp() * 1000.0


def _recording_run_start_ms(run: dict, art: Path | None = None) -> float | None:
    if art is not None:
        meta_path = art / "recorder" / "recording_meta.json"
        if meta_path.exists():
            try:
                meta = json.loads(meta_path.read_text(encoding="utf-8"))
            except (json.JSONDecodeError, OSError) as exc:
                print(f"warning: recording meta: {exc}", file=sys.stderr)
                meta = {}
            for key in ("started_at", "started_at_utc"):
                ms = _parse_iso_ms(meta.get(key))
                if ms is not None:
                    return ms
    for key in ("started_at_utc", "started_at"):
        ms = _parse_iso_ms(run.get(key))
        if ms is not None:
            return ms
    return None


def _sample_rel_s(sample: dict, run_start_ms: float | None, first_wall_ms_by_tab: dict[str, float]) -> float | None:
    rel_s = _num(sample.get("rel_s"))
    if rel_s is not None:
        return rel_s
    wall_ms = _num(sample.get("wall_ms"))
    if wall_ms is None:
        return None
    if run_start_ms is not None:
        return (wall_ms - run_start_ms) / 1000.0
    tab = sample.get("tab_id") or sample.get("tab") or "-"
    base = first_wall_ms_by_tab.get(str(tab))
    if base is None:
        first_wall_ms_by_tab[str(tab)] = wall_ms
        base = wall_ms
    return (wall_ms - base) / 1000.0


