def _fmt_duration_us_compact(value: object) -> str:
    if not isinstance(value, (int, float)) or value < 0:
        return "-"
    if value >= 100000:
        return f"{value / 1000.0:.0f}ms"
    if value >= 1000:
        return f"{value / 1000.0:.1f}ms"
    return f"{int(value)}us"


def _format_render_slice_summary(tab: dict) -> str | None:
    total = tab.get("client_render_duration_us_last")
    items: list[tuple[str, float]] = []
    for field, label in _RENDER_SLICE_LAST_FIELDS:
        value = tab.get(field)
        if isinstance(value, (int, float)) and value > 0:
            items.append((label, float(value)))
    for field, label in _RENDER_SLICE_MAX_FIELDS:
        value = tab.get(field)
        if isinstance(value, (int, float)) and value > 0:
            items.append((label, float(value)))
    if not items and not isinstance(total, (int, float)):
        return None
    items.sort(key=lambda item: item[1], reverse=True)
    dominant = f"{items[0][0]}={_fmt_duration_us_compact(items[0][1])}" if items else "dominant=-"
    top = " ".join(
        f"{label}={_fmt_duration_us_compact(value)}" for label, value in items[:4]
    ) if items else "slices=-"
    return (
        f"    render_diag: total={_fmt_duration_us_compact(total)} "
        f"{dominant} {top}"
    )


def _percentile_linear(values: list[float], pct: float) -> float | None:
    if not values:
        return None
    if len(values) == 1:
        return float(values[0])
    ordered = sorted(float(v) for v in values)
    rank = max(0.0, min(1.0, pct)) * (len(ordered) - 1)
    lo = int(math.floor(rank))
    hi = int(math.ceil(rank))
    if lo == hi:
        return ordered[lo]
    frac = rank - lo
    return ordered[lo] + (ordered[hi] - ordered[lo]) * frac


def _lag_band_from_ms(v: object) -> str | None:
    if not isinstance(v, (int, float)):
        return None
    if v < 100:
        return "green"
    if v < 200:
        return "yellow"
    return "red"


def _honest_lag_band(tab: dict) -> str | None:
    bands = [
        _lag_band_from_ms(tab.get("lag_ms_last")),
        _lag_band_from_ms(tab.get("lag_ms_max")),
        _lag_band_from_ms(tab.get("lag_rtt_raw_ms_last")),
        _lag_band_from_ms(tab.get("lag_rtt_raw_ms_max")),
        _lag_band_from_ms(tab.get("post_join_lag_max_ms")),
        _lag_band_from_ms(tab.get("lag_trace_yellow_latest_lag_ms")),
    ]
    if "red" in bands:
        return "red"
    if "yellow" in bands:
        return "yellow"
    if "green" in bands:
        return "green"
    return None


def derive_post_join_lag_metrics(run: dict, root: Path, start_s: float = POST_JOIN_LAG_START_S) -> dict[str, dict]:
    """Return recorder-derived post-join lag metrics per tab.

    Values are derived from recording.jsonl using rel_s when present, otherwise
    wall_ms relative to recording_meta/summary started_at. Missing artifacts
    return an empty dict so callers can degrade gracefully.
    """
    try:
        art = _require_artifact_path(run, "post-join-lag")
    except SystemExit:
        return {}
    rec_path = art / "recorder" / "recording.jsonl"
    if not rec_path.exists():
        return {}

    _meta, _events, samples = _load_recording(rec_path)
    run_start_ms = _recording_run_start_ms(run, art)
    first_wall_ms_by_tab: dict[str, float] = {}
    lag_by_tab: dict[str, list[float]] = {}
    sample_counts: dict[str, int] = {}
    lag_wait_counts: dict[str, int] = {}
    lag_stale_counts: dict[str, int] = {}
    lag_wait_age_max_by_tab: dict[str, float] = {}
    lag_response_age_max_by_tab: dict[str, float] = {}

    for sample in samples:
        tab = str(sample.get("tab_id") or sample.get("tab") or "")
        if not tab:
            continue
        rel_s = _sample_rel_s(sample, run_start_ms, first_wall_ms_by_tab)
        if rel_s is None or rel_s <= start_s:
            continue
        lag_ms = _num(sample.get("lag_ms"))
        if lag_ms is None:
            continue
        lag_by_tab.setdefault(tab, []).append(float(lag_ms))
        sample_counts[tab] = sample_counts.get(tab, 0) + 1
        if (_num(sample.get("lag_wait")) or 0) > 0:
            lag_wait_counts[tab] = lag_wait_counts.get(tab, 0) + 1
        if (_num(sample.get("lag_measurement_stale")) or 0) > 0:
            lag_stale_counts[tab] = lag_stale_counts.get(tab, 0) + 1
        lag_wait_age_ms = _num(sample.get("lag_wait_age_ms"))
        if lag_wait_age_ms is not None:
            lag_wait_age_max_by_tab[tab] = max(
                float(lag_wait_age_ms),
                lag_wait_age_max_by_tab.get(tab, float(lag_wait_age_ms)),
            )
        lag_response_age_ms = _num(sample.get("lag_response_age_ms"))
        if lag_response_age_ms is not None:
            lag_response_age_max_by_tab[tab] = max(
                float(lag_response_age_ms),
                lag_response_age_max_by_tab.get(tab, float(lag_response_age_ms)),
            )

    out: dict[str, dict] = {}
    for tab, values in lag_by_tab.items():
        out[tab] = {
            "post_join_lag_max_ms": max(values) if values else None,
            "post_join_lag_p95_ms": _percentile_linear(values, 0.95),
            "post_join_lag_sample_count": sample_counts.get(tab, 0),
            "post_join_lag_wait_sample_count": lag_wait_counts.get(tab, 0),
            "post_join_lag_stale_sample_count": lag_stale_counts.get(tab, 0),
            "post_join_lag_wait_age_max_ms": lag_wait_age_max_by_tab.get(tab),
            "post_join_lag_response_age_max_ms": lag_response_age_max_by_tab.get(tab),
        }
    return out


def derive_authoritative_tick_overrun_metrics(run: dict, root: Path) -> dict[str, Any]:
    """Return recorder-carried authoritative overrun metrics for archived runs."""
    try:
        art = _require_artifact_path(run, "tick-overrun")
    except SystemExit:
        return {}
    rec_path = art / "recorder" / "recording.jsonl"
    if not rec_path.exists():
        return {}

    _meta, _events, samples = _load_recording(rec_path)
    tick_overrun_count: int | None = None
    tick_max_elapsed_us: int | None = None
    tick_fields: dict[str, Any] = {}
    last_non_null_keys = (
        "tick_last_overrun_phase_us",
        "tick_max_phase",
        "tick_max_phase_us",
        "tick_max_phase_tick",
        "tick_last_snapshot_phase",
        "tick_last_snapshot_phase_us",
        "tick_max_snapshot_phase",
        "tick_max_snapshot_phase_us",
        "tick_max_snapshot_phase_tick",
        "tick_last_physics_phase_us",
        "tick_max_physics_phase",
        "tick_max_physics_phase_us",
        "tick_max_physics_phase_tick",
        "tick_last_physics_players_active",
        "tick_last_physics_players_steps",
        "tick_last_physics_players_idle_fast_paths",
        "tick_last_physics_players_step_once_us",
        "tick_last_physics_players_us",
        "tick_max_physics_players_tick",
        "tick_max_physics_players_active",
        "tick_max_physics_players_steps",
        "tick_max_physics_players_idle_fast_paths",
        "tick_max_physics_players_step_once_us",
        "tick_max_physics_players_step_once_client",
        "tick_max_physics_players_step_once_reject_mask",
        "tick_max_physics_players_step_once_input_flags",
        "tick_max_physics_players_step_once_grounded",
        "tick_max_physics_players_step_once_in_water",
        "tick_max_physics_players_step_once_idle_support_recovered",
        "tick_max_physics_players_step_once_full_steps",
        "tick_max_physics_players_step_once_idle_fast_paths",
        "tick_max_physics_players_step_once_max_abs_vel_milli",
        "tick_max_physics_players_step_once_yaw_delta_mdeg",
        "tick_max_physics_players_step_once_support_z_milli",
        "tick_max_physics_players_step_once_accum_contact_milli",
        "tick_max_physics_players_step_once_collect_us",
        "tick_max_physics_players_step_once_sweep_wall_us",
        "tick_max_physics_players_step_once_support_probe_us",
        "tick_max_physics_players_step_once_support_retry_probe_us",
        "tick_max_physics_players_step_once_unaccounted_us",
        "tick_max_physics_players_step_once_soup_items",
        "tick_max_physics_players_step_once_sweep_iters",
        "tick_max_physics_players_step_once_collision_checks",
        "tick_max_physics_players_us",
        "io_poll_gap_last_us",
        "io_poll_gap_max_us",
        "io_poll_gap_over_100ms_count",
        "io_poll_nfds_last",
        "io_poll_ret_last",
        "io_poll_timeout_ms_last",
        "io_poll_work_pending_last",
        "io_wake_write_count",
        "io_wake_read_count",
        "io_wake_write_errno_count",
    )
    for sample in samples:
        overrun_count = _num(sample.get("tick_overrun_count"))
        max_elapsed_us = _num(sample.get("tick_max_elapsed_us"))
        if overrun_count is not None:
            tick_overrun_count = max(int(overrun_count), tick_overrun_count or 0)
        if max_elapsed_us is not None:
            tick_max_elapsed_us = max(int(max_elapsed_us), tick_max_elapsed_us or 0)
        for key in last_non_null_keys:
            value = sample.get(key)
            if value is not None:
                tick_fields[key] = value

    if tick_overrun_count is None and tick_max_elapsed_us is None and not tick_fields:
        return {}
    out = {
        "tick_overrun_count": tick_overrun_count,
        "tick_max_elapsed_us": tick_max_elapsed_us,
    }
    out.update(tick_fields)
    preferred_players_breakdown_tick = _num(out.get("tick_max_physics_phase_tick"))
    players_breakdown = _derive_tick_players_breakdown(
        art / "server.log",
        preferred_tick=int(preferred_players_breakdown_tick)
        if preferred_players_breakdown_tick is not None
        else None,
    )
    if players_breakdown:
        out.update(players_breakdown)
    npc_breakdown = _derive_tick_npc_breakdown(
        art / "server.log",
        preferred_tick=int(preferred_players_breakdown_tick)
        if preferred_players_breakdown_tick is not None
        else None,
    )
    if npc_breakdown:
        out.update(npc_breakdown)
    return out


