def _print_table(header: list, rows: list, widths: list | None = None) -> None:
    """Tabular output — delegates to cli_style.table().

    The *widths* parameter is accepted for backward compatibility but ignored;
    cli_style.table() auto-sizes columns with a configurable max_col cap.
    """
    print(cli_style.table(header, rows))


def _val(sample: dict, field: str) -> str:
    """Get value from a sample; return '-' for missing/None."""
    v = sample.get(field)
    if v is None:
        return "-"
    if isinstance(v, float):
        return f"{v:.2f}"
    return str(v)


def _npc_attachment_mask_label(value) -> str:
    try:
        mask = int(value)
    except (TypeError, ValueError):
        return "-"
    if mask <= 0:
        return "-"
    labels = []
    for bit, label in (
        (1 << 0, "head"),
        (1 << 1, "shield"),
        (1 << 2, "weapon"),
        (1 << 3, "armor"),
    ):
        if mask & bit:
            labels.append(label)
    return ",".join(labels) if labels else str(mask)


def _num(v):
    return v if isinstance(v, (int, float)) else None


def _num_probe_alias(sample: dict, primary: str, *legacy_fields: str) -> int | float | None:
    """Read a recorder v2 numeric probe with explicit v1 fallback aliases."""
    value = _num(sample.get(primary))
    if value is not None:
        return value
    for field in legacy_fields:
        value = _num(sample.get(field))
        if value is not None:
            return value
    return None


def _nested(sample: dict, *path):
    cur = sample
    for key in path:
        if not isinstance(cur, dict):
            return None
        cur = cur.get(key)
    return cur


