def run_to_list_row(run: dict, tags: set, fl: FLIndex = None) -> list:
    verdict = run.get("verdict", "-") or "-"
    stage = run_stage_label(run)
    base = [
        run.get("run_id", "-"),
        fmt_ts(run.get("started_at_utc")),
        verdict,
        stage,
        fmt_bool(run.get("online_integrity_ok")),
        fmt_gates(
            run.get("runtime_required_passed"), run.get("runtime_required_total")
        ),
        fmt_gates(run.get("runtime_core_passed"), run.get("runtime_core_total")),
        fmt_count(run.get("false_gates")),
        fmt_count(run.get("null_gates")),
        fmt_delta(run),
        transcript_status(run),
        compact_text(next_action_text(run), max_len=64),
        run.get("git_head") or "-",
        run.get("source_ref") or "-",
        tag_exists(run, tags),
        run.get("branch") or "-",
        compact_text(run.get("user_observation") or "", max_len=40) or "-",
        "*" if run.get("run_intent") else "-",
    ]
    if fl is not None:
        n = fl.run_citations(fl_artifact_key(run))
        base.insert(10, str(n) if n else "-")
    return base


# ---------------------------------------------------------------------------
# Shared UX helpers — start cards and summary blocks
# ---------------------------------------------------------------------------


def _start_card(cmd_name: str, **kwargs: object) -> None:
    """Print a start card for a subcommand (suppressed in JSON mode)."""
    if _JSON_MODE:
        return
    cli_style.header(cmd_name)
    pairs = [(k.replace("_", " "), v) for k, v in kwargs.items() if v is not None]
    if pairs:
        print(cli_style.kv(pairs, indent=1))
    print()


def _summary_block(*, result: str = "OK", items: int | None = None,
                   artifact: str | None = None, next_action: str | None = None,
                   **extra: object) -> None:
    """Print a final summary block (suppressed in JSON mode)."""
    if _JSON_MODE:
        return
    cli_style.header("Summary")
    pairs: list[tuple[str, object]] = [("result", cli_style.status(result.upper()))]
    if items is not None:
        pairs.append(("items", cli_style.style(items, "count")))
    if artifact:
        pairs.append(("artifact", cli_style.style(artifact, "path")))
    for k, v in extra.items():
        pairs.append((k.replace("_", " "), v))
    if next_action:
        pairs.append(("next action", cli_style.style(next_action, "warn")))
    print(cli_style.kv(pairs, indent=1))


def cmd_list(args, root: Path):
    _start_card("list", mode="read-only", limit=getattr(args, "limit", None))
    runs, incomplete = load_all_runs(root)
    tags = load_git_tags(root)

    if incomplete:
        if args.list_incomplete:
            print(
                f"Incomplete dirs ({len(incomplete)} — no summary.json):",
                file=sys.stderr,
            )
            for name in incomplete:
                print(f"  {name}", file=sys.stderr)
        else:
            print(
                f"note: {len(incomplete)} dirs have no summary.json (use --list-incomplete to see them)",
                file=sys.stderr,
            )

    label_filter = requested_run_label(args)
    if label_filter:
        runs = [r for r in runs if run_label_for(r) == label_filter]
    explicit_verdicts = {
        normalize_verdict({"verdict": v}) for v in (args.verdict or [])
    }
    hidden_prelaunch = 0
    if not getattr(args, "include_prelaunch", False) and "infra_fail" not in explicit_verdicts:
        filtered = []
        for run in runs:
            if is_prelaunch_artifact_run(run):
                hidden_prelaunch += 1
                continue
            filtered.append(run)
        runs = filtered
        if hidden_prelaunch:
            print(
                f"note: hid {hidden_prelaunch} prelaunch/non-online artifact(s) by default (use --include-prelaunch to show them)",
                file=sys.stderr,
            )
    if args.verdict:
        runs = [r for r in runs if normalize_verdict(r) in explicit_verdicts]
    if args.limit:
        runs = runs[: args.limit]

    if getattr(args, "list_json", False):
        print(json.dumps(runs, indent=2, default=str))
        _summary_block(result="OK", items=len(runs))
        return

    fl = load_fl_index(root) if args.fl else None
    headers = HEADERS_LIST_FL if fl else HEADERS_LIST
    rows = [run_to_list_row(r, tags, fl=fl) for r in runs]
    print_table(headers, rows)
    _summary_block(result="OK", items=len(rows))


# ---------------------------------------------------------------------------
# Measurement provenance helpers (used by diff)
# ---------------------------------------------------------------------------


def _provenance_changed(run_a: dict, run_b: dict) -> bool:
    """True if any provenance hash differs (and both runs have provenance)."""
    pa = run_a.get("measurement_provenance")
    pb = run_b.get("measurement_provenance")
    if not pa or not pb:
        return False
    return any(pa.get(k) != pb.get(k) for k in set(pa) | set(pb))


def print_provenance_warning(run_a: dict, run_b: dict) -> None:
    """Print provenance comparison between two runs."""
    pa = run_a.get("measurement_provenance")
    pb = run_b.get("measurement_provenance")

    if not pa and not pb:
        print("  measurement provenance: (unavailable — both runs predate provenance tracking)")
        return
    if not pa:
        run_a_id = run_a.get("run_id", "A")
        print(f"  measurement provenance: run {run_a_id} predates provenance tracking")
        return
    if not pb:
        run_b_id = run_b.get("run_id", "B")
        print(f"  measurement provenance: run {run_b_id} predates provenance tracking")
        return

    changed_keys = [k for k in sorted(set(pa) | set(pb)) if pa.get(k) != pb.get(k)]
    if not changed_keys:
        print("  measurement provenance: (identical — all measurement hashes match)")
    else:
        print("  ⚠️  MEASUREMENT METHOD CHANGED between runs:")
        for k in changed_keys:
            label = k.replace("_sha256", "").replace("_", " ")
            print(f"    • {label} hash differs")
        print("    → gate regressions may be false positives; consider rebaselining")
    print("  measurement provenance scope: browser-recorder hashes only; server-side stall traces/log counts are outside this scope")


def provenance_summary(run_a: dict, run_b: dict) -> dict[str, Any]:
    pa = run_a.get("measurement_provenance")
    pb = run_b.get("measurement_provenance")
    if not pa and not pb:
        return {
            "state": "both_unavailable",
            "message": "measurement provenance unavailable — both runs predate provenance tracking",
            "changed": False,
            "changed_keys": [],
        }
    if not pa:
        return {
            "state": "run_a_unavailable",
            "message": f"run {run_a.get('run_id', 'A')} predates provenance tracking",
            "changed": False,
            "changed_keys": [],
        }
    if not pb:
        return {
            "state": "run_b_unavailable",
            "message": f"run {run_b.get('run_id', 'B')} predates provenance tracking",
            "changed": False,
            "changed_keys": [],
        }
    changed_keys = [k for k in sorted(set(pa) | set(pb)) if pa.get(k) != pb.get(k)]
    return {
        "state": "changed" if changed_keys else "identical",
        "message": "measurement method changed between runs" if changed_keys else "all measurement hashes match",
        "changed": bool(changed_keys),
        "changed_keys": changed_keys,
        "scope": "browser-recorder hashes only; server-side stall traces/log counts are outside this scope",
    }


def _safe_load_metrics_for_run(run: dict) -> tuple[dict | None, str | None]:
    try:
        return _load_metrics_for_run(run)
    except SystemExit:
        return None, None


def _diff_state_rows(items: list[tuple[str, str, str]]) -> list[dict[str, Any]]:
    return [{"gate": gate, "state_a": sa, "state_b": sb} for gate, sa, sb in items]


def build_diff_payload(args, root: Path) -> dict[str, Any]:
    run_a = load_run_by_id(root, args.run_a)
    run_b = load_run_by_id(root, args.run_b)
    provenance = provenance_summary(run_a, run_b)

    metrics_a, _ = _safe_load_metrics_for_run(run_a)
    metrics_b, _ = _safe_load_metrics_for_run(run_b)
    lag_summary_payload: dict[str, dict[str, Any]] = {}
    if metrics_a and metrics_b:
        fields_a = _lag_fields_for_run(run_a, root)
        fields_b = _lag_fields_for_run(run_b, root)
        merged = {
            key: (fields_a.get(key), fields_b.get(key))
            for key in sorted(set(fields_a) | set(fields_b))
        }
        post_a = derive_post_join_lag_metrics(run_a, root)
        post_b = derive_post_join_lag_metrics(run_b, root)
        if post_a or post_b:
            for tab_name in ("tab1", "tab2"):
                pa = (post_a or {}).get(tab_name) or {}
                pb = (post_b or {}).get(tab_name) or {}
                for suffix in ("post_join_lag_max_ms", "post_join_lag_p95_ms", "post_join_lag_sample_count"):
                    merged[f"{tab_name}.{suffix}"] = (pa.get(suffix), pb.get(suffix))
        overrun_a = derive_authoritative_tick_overrun_metrics(run_a, root)
        overrun_b = derive_authoritative_tick_overrun_metrics(run_b, root)
        if overrun_a or overrun_b:
            for key in ("tick_overrun_count", "tick_max_elapsed_us"):
                merged[key] = ((overrun_a or {}).get(key), (overrun_b or {}).get(key))
        for key, value in sorted(merged.items()):
            va, vb = value
            if va is None and vb is None:
                continue
            if isinstance(va, (int, float)) and isinstance(vb, (int, float)):
                delta_str = f"{vb - va:+.2f}" if isinstance(va, float) or isinstance(vb, float) else f"{vb - va:+d}"
            elif va != vb:
                delta_str = f"{va} -> {vb}"
            else:
                delta_str = "-"
            lag_summary_payload[key] = {"a": va, "b": vb, "delta": delta_str}

    online_a = run_a.get("online_integrity_ok")
    online_b = run_b.get("online_integrity_ok")
    online_delta_payload = {"a": online_a, "b": online_b} if online_a != online_b else None

    steps_a = {s["name"]: s for s in (run_a.get("steps") or [])}
    steps_b = {s["name"]: s for s in (run_b.get("steps") or [])}
    step_changes = []
    for name in sorted(set(steps_a) | set(steps_b)):
        a = steps_a.get(name, {}).get("verdict")
        b = steps_b.get(name, {}).get("verdict")
        if a != b:
            step_changes.append((name, a or "-", b or "-"))

    code_diff_payload = resolve_code_diff_payload(
        root=root,
        run_a=run_a,
        run_b=run_b,
        diff_corpora=getattr(args, "diff_corpus", None),
        diff_mode=getattr(args, "diff_mode", None),
        diff_paths=getattr(args, "diff_path", None),
    )

    false_a = set(run_a.get("false_gates") or [])
    null_a = set(run_a.get("null_gates") or [])
    false_b = set(run_b.get("false_gates") or [])
    null_b = set(run_b.get("null_gates") or [])
    not_ok_a = false_a | null_a
    not_ok_b = false_b | null_b
    suppressed_deprecated = sorted((not_ok_a | not_ok_b) & DEPRECATED_GATES)
    suppressed_diagnostic = sorted((not_ok_a | not_ok_b) & DIAGNOSTIC_ONLY_GATES)
    all_gates = (not_ok_a | not_ok_b) - DEPRECATED_GATES - DIAGNOSTIC_ONLY_GATES

    regressions = []
    recoveries = []
    unchanged_fail = []
    unchanged_null = []
    changed_badness = []
    for gate in sorted(all_gates):
        state_a = gate_state(run_a, gate)
        state_b = gate_state(run_b, gate)
        if state_a == "true" and state_b != "true":
            regressions.append((gate, state_a, state_b))
        elif state_a != "true" and state_b == "true":
            recoveries.append((gate, state_a, state_b))
        elif state_a == state_b == "false":
            unchanged_fail.append(gate)
        elif state_a == state_b == "null":
            unchanged_null.append(gate)
        else:
            changed_badness.append((gate, state_a, state_b))

    return {
        "run_a": {
            "run_id": run_a.get("run_id"),
            "date": run_a.get("started_at_utc"),
            "commit": run_a.get("git_head"),
            "source_ref": run_a.get("source_ref"),
            "branch": run_a.get("branch"),
            "verdict": run_a.get("verdict"),
            "online_integrity_ok": run_a.get("online_integrity_ok"),
            "git_tag": run_a.get("git_tag"),
        },
        "run_b": {
            "run_id": run_b.get("run_id"),
            "date": run_b.get("started_at_utc"),
            "commit": run_b.get("git_head"),
            "source_ref": run_b.get("source_ref"),
            "branch": run_b.get("branch"),
            "verdict": run_b.get("verdict"),
            "online_integrity_ok": run_b.get("online_integrity_ok"),
            "git_tag": run_b.get("git_tag"),
        },
        "provenance": provenance,
        "lag_summary": lag_summary_payload,
        "online_integrity_delta": online_delta_payload,
        "step_changes": [{"name": name, "a": va, "b": vb} for name, va, vb in step_changes],
        "code_diff": code_diff_payload,
        "regressions": _diff_state_rows(regressions),
        "recoveries": _diff_state_rows(recoveries),
        "changed_badness": _diff_state_rows(changed_badness),
        "unchanged_failures": unchanged_fail,
        "unchanged_nulls": unchanged_null,
        "suppressed_diagnostic": suppressed_diagnostic,
        "suppressed_deprecated": suppressed_deprecated,
        "next_action": recommend_next_action(run_b) or run_b.get("next_action"),
    }


def build_trend_payload(args, root: Path) -> dict[str, Any]:
    runs, _ = load_all_runs(root)
    tags = load_git_tags(root)
    label_filter = requested_run_label(args)
    if label_filter:
        runs = [r for r in runs if run_label_for(r) == label_filter]
    if args.skip_blocked:
        runs = [r for r in runs if r.get("false_gates") is not None or r.get("null_gates") is not None]
    pattern = args.gate_name
    all_gates = all_known_gates(runs)
    if pattern in all_gates:
        matching_gates = [pattern]
    else:
        matching_gates = sorted(g for g in all_gates if pattern in g)
    payload_gates: list[dict[str, Any]] = []
    for gate in matching_gates:
        rows = []
        for run in runs:
            rows.append(
                {
                    "run_id": run.get("run_id", "-"),
                    "date": run.get("started_at_utc"),
                    "state": gate_state(run, gate),
                    "verdict": run.get("verdict") or "-",
                    "commit": run.get("git_head") or "-",
                    "tag": tag_exists(run, tags),
                    "branch": run.get("branch") or "-",
                }
            )
        payload_gates.append({"gate": gate, "rows": rows})
    return {"pattern": pattern, "matching_gates": payload_gates, "known_gates": sorted(all_gates)}


def _bootstrap_triage_lines(run: dict) -> list[str]:
    if (run.get("verdict") or "-") not in ("bootstrap_fail",):
        return []
    try:
        art_path = _find_artifact_path(run)
        rec_file = art_path / "recorder" / "recording.jsonl" if art_path else None
        if not rec_file or not rec_file.exists():
            return []
        _, _, t_samples = _load_recording(rec_file)
        diag_fields = {
            "server_ptr_ok": None,
            "pending_drain_block_defer": None,
            "pending_drain_deferred_preserved": None,
            "pending_drain_stop_server_null": None,
            "packet_calls": None,
            "packet_proc_called": None,
            "packet_deferred": None,
            "packet_server_null": None,
            "pending_dropped": None,
            "pending_max_depth": None,
            "game_loading_state": None,
            "server_lifecycle_event": None,
            "server_first_null_after_live_seen": None,
            "server_first_null_after_live_stage": None,
            "server_first_null_after_live_op": None,
        }
        for sample in reversed(t_samples):
            for field in list(diag_fields):
                if diag_fields[field] is None and sample.get(field) is not None:
                    diag_fields[field] = sample[field]
            if all(v is not None for v in diag_fields.values()):
                break
        if not any(v is not None for v in diag_fields.values()):
            return []
        drain_blk = diag_fields.get("pending_drain_block_defer")
        deferred_preserved = diag_fields.get("pending_drain_deferred_preserved")
        drain_stop_null = diag_fields.get("pending_drain_stop_server_null")
        pkt_proc = diag_fields.get("packet_proc_called")
        pkt_calls = diag_fields.get("packet_calls")
        pkt_null = diag_fields.get("packet_server_null")
        pkt_defer = diag_fields.get("packet_deferred")
        svr_ok = diag_fields.get("server_ptr_ok")
        loading = diag_fields.get("game_loading_state")
        dropped = diag_fields.get("pending_dropped")
        max_depth = diag_fields.get("pending_max_depth")
        lifecycle = diag_fields.get("server_lifecycle_event")
        first_null_seen = diag_fields.get("server_first_null_after_live_seen")
        first_null_stage = diag_fields.get("server_first_null_after_live_stage")
        first_null_op = diag_fields.get("server_first_null_after_live_op")
        lines: list[str] = []
        if svr_ok is not None and not svr_ok:
            extra = ""
            if first_null_seen:
                op_txt = chr(first_null_op) if isinstance(first_null_op, int) and 32 <= first_null_op <= 126 else first_null_op
                extra = f" first_null={first_null_stage} op={op_txt}"
            lines.append(f"SERVER NULL (lifecycle={lifecycle}{extra})")
        if drain_blk is not None and drain_blk > 0:
            lines.append(f"LEGACY HEAD-OF-LINE BLOCK: pending_drain_block_defer={drain_blk}")
        if deferred_preserved is not None and deferred_preserved > 0:
            lines.append(f"DEFERRED PRESERVED: pending_drain_deferred_preserved={deferred_preserved}")
        if drain_stop_null is not None and drain_stop_null > 0:
            lines.append(f"DRAIN STOPPED ON SERVER NULL: pending_drain_stop_server_null={drain_stop_null}")
        if pkt_calls and (pkt_proc is None or pkt_proc == 0):
            lines.append(f"ZERO PROC: packet_calls={pkt_calls} proc={pkt_proc} null={pkt_null} defer={pkt_defer}")
        if dropped and dropped > 0:
            lines.append(f"QUEUE OVERFLOW: dropped={dropped} max_depth={max_depth}")
        if loading is not None and loading != 2:
            lines.append(f"LOADING STUCK: game_loading_state={loading}")
        if not lines:
            lines.append(f"fields present but no anomaly detected (svr_ok={svr_ok} loading={loading} pkt_proc={pkt_proc})")
        return lines
    except (json.JSONDecodeError, KeyError, OSError):
        return []


def build_triage_payload(args, root: Path) -> dict[str, Any]:
    run = load_run_by_id(root, args.run_id)
    diff_spec = _resolve_intent_diff_spec(run)
    diagnostic_scope = diagnostic_scope_for_run(run)
    false_gates, diagnostic_false, deprecated_false = split_gate_groups(run.get("false_gates") or [])
    null_gates = run.get("null_gates") or []
    gd = run.get("gate_deltas") or {}
    regs = [g for g in (gd.get("regressions_true_to_false") or []) if g not in DIAGNOSTIC_ONLY_GATES]
    diag_regs = [g for g in (gd.get("regressions_true_to_false") or []) if g in DIAGNOSTIC_ONLY_GATES]

    regression_gates = list(regs) + list(false_gates)
    last_pass_payload: dict[str, dict[str, str]] = {}
    if regression_gates:
        try:
            all_runs_triage, _ = load_all_runs(root)
            current_ts = run.get("started_at_utc") or ""
            prior_runs = [r for r in all_runs_triage if (r.get("started_at_utc") or "") < current_ts]
            last_pass: dict[str, tuple[str, str]] = {}
            for r in prior_runs:
                r_false = set(r.get("false_gates") or [])
                r_null = set(r.get("null_gates") or [])
                for gate in regression_gates:
                    if gate not in last_pass and gate not in r_false and gate not in r_null:
                        last_pass[gate] = (r.get("run_id") or "?", (r.get("git_head") or "?")[:8])
                if len(last_pass) == len(regression_gates):
                    break
            last_pass_payload = {gate: {"run_id": rid, "commit": sha} for gate, (rid, sha) in last_pass.items()}
        except (json.JSONDecodeError, KeyError, OSError):
            last_pass_payload = {}

    post_join_payload: dict[str, Any] = {}
    post_join = derive_post_join_lag_metrics(run, root)
    if post_join:
        for tab_name in ("tab1", "tab2"):
            pj = post_join.get(tab_name) or {}
            if not pj:
                continue
            post_join_payload[tab_name] = {
                "post_join_lag_max_ms": pj.get("post_join_lag_max_ms"),
                "post_join_lag_p95_ms": pj.get("post_join_lag_p95_ms"),
                "post_join_lag_sample_count": pj.get("post_join_lag_sample_count"),
                "post_join_lag_wait_sample_count": pj.get("post_join_lag_wait_sample_count"),
                "post_join_lag_stale_sample_count": pj.get("post_join_lag_stale_sample_count"),
                "post_join_lag_wait_age_max_ms": pj.get("post_join_lag_wait_age_max_ms"),
                "post_join_lag_response_age_max_ms": pj.get("post_join_lag_response_age_max_ms"),
            }

    oracle_diag_block = (run.get("diagnostics") or {}).get("render_oracle_tab1") or {}
    top_diag = oracle_diag_block.get("oracle_diagnosis_top")
    oracle_payload = None
    if top_diag:
        oracle_payload = {
            "top": top_diag,
            "count": (oracle_diag_block.get("oracle_diagnosis_counts") or {}).get(top_diag, 0),
        }

    hint = None
    try:
        all_runs, _ = load_all_runs(root)
        hint = _triage_hint(run, all_runs, root)
    except (json.JSONDecodeError, KeyError, OSError):
        hint = None

    return {
        "run": {
            "run_id": run.get("run_id"),
            "verdict": run.get("verdict") or "-",
            "online_integrity_ok": run.get("online_integrity_ok"),
            "date": run.get("started_at_utc"),
            "commit": (run.get("git_head") or "")[:8] or None,
            "runtime_required_passed": run.get("runtime_required_passed") or 0,
            "runtime_required_total": run.get("runtime_required_total") or 0,
            "runtime_core_passed": run.get("runtime_core_passed") or 0,
            "runtime_core_total": run.get("runtime_core_total") or 0,
            "intent_diff": diff_spec,
            "diagnostic_scope": diagnostic_scope,
        },
        "prelaunch_blocker": run.get("prelaunch_blocker") or None,
        "false_gates": false_gates,
        "diagnostic_false_gates": diagnostic_false,
        "deprecated_false_gates": deprecated_false,
        "null_gates": null_gates,
        "regressions": regs,
        "diagnostic_regressions": diag_regs,
        "last_pass": last_pass_payload,
        "causal_digest_highlights": (run.get("causal_digest") or {}).get("highlights") or [],
        "post_join_lag": post_join_payload,
        "tick_overrun": derive_authoritative_tick_overrun_metrics(run, root) or {},
        "oracle_diagnosis": oracle_payload,
        "bootstrap_diagnosis": _bootstrap_triage_lines(run),
        "hint": hint,
        "next_action": next_action_text(run),
        "observation": run.get("user_observation"),
    }


def build_regression_window_payload(args, root: Path) -> dict[str, Any]:
    runs, _ = load_all_runs(root)
    label_filter = requested_run_label(args)
    if label_filter:
        runs = [r for r in runs if run_label_for(r) == label_filter]
    gate = canonical_gate_name(args.gate_name)
    ordered = list(reversed(runs))
    if getattr(args, "start_commit", None):
        prefix = str(args.start_commit).strip().lower()
        start_idx = next((idx for idx, run in enumerate(ordered) if (run.get("git_head") or "").lower().startswith(prefix)), None)
        if start_idx is None:
            return {"gate": gate, "start_commit": args.start_commit, "window_found": False, "error": "start_commit_not_found"}
        ordered = ordered[start_idx:]
    prior_true = None
    first_bad = None
    first_bad_state = None
    for run in ordered:
        state = gate_state(run, gate)
        if state == "unknown":
            continue
        if state == "true":
            prior_true = run
            continue
        if state in {"false", "null"}:
            first_bad = run
            first_bad_state = state
            break
    return {
        "gate": gate,
        "start_commit": getattr(args, "start_commit", None),
        "window_found": bool(first_bad),
        "last_passing_run": _run_reference_payload(root, prior_true),
        "first_failing_run": _run_reference_payload(root, first_bad),
        "first_failing_state": first_bad_state,
        "candidate_commit_window": {
            "from_commit": (prior_true or {}).get("git_head"),
            "to_commit": (first_bad or {}).get("git_head"),
        },
    }


# ---------------------------------------------------------------------------
# Subcommand: diff
# ---------------------------------------------------------------------------


def cmd_diff(args, root: Path):
    if getattr(args, "json", False):
        print(json.dumps(build_diff_payload(args, root), indent=2))
        return
    _start_card("diff", run_a=args.run_a, run_b=args.run_b, mode="read-only")
    tags = load_git_tags(root)
    gaps = load_gap_registry(root)
    run_a = load_run_by_id(root, args.run_a)
    run_b = load_run_by_id(root, args.run_b)
    def run_header(label: str, run: dict) -> str:
        tag = tag_exists(run, tags)
        return (
            f"  {label}: {run.get('run_id', '?')}\n"
            f"    date:       {fmt_ts(run.get('started_at_utc'))}\n"
            f"    commit:     {run.get('git_head') or '-'}\n"
            f"    source_ref: {run.get('source_ref') or '-'}\n"
            f"    branch:     {run.get('branch') or '-'}\n"
            f"    verdict:    {run.get('verdict') or '-'}\n"
            f"    online:     {fmt_bool(run.get('online_integrity_ok'))}\n"
            f"    tag:        {tag}"
        )

    provenance = provenance_summary(run_a, run_b)

    cli_style.header("DIFF")
    print(run_header("A (before)", run_a))
    print()
    print(run_header("B (after) ", run_b))
    print()

    print_provenance_warning(run_a, run_b)
    print()

    metrics_a, _src_a = _safe_load_metrics_for_run(run_a)
    metrics_b, _src_b = _safe_load_metrics_for_run(run_b)
    lag_summary_payload: dict[str, dict[str, Any]] = {}
    if metrics_a and metrics_b:
        fields_a = _lag_fields_for_run(run_a, root)
        fields_b = _lag_fields_for_run(run_b, root)
        overrun_a = derive_authoritative_tick_overrun_metrics(run_a, root)
        overrun_b = derive_authoritative_tick_overrun_metrics(run_b, root)
        print(cli_style.style("--- LAG SUMMARY ---", "subheader"))
        for key in (
            "tab1.lag_ms_max",
            "tab1.lag_spike_count",
            "tab1.lag_band",
            "tab1.post_join_lag_spike_count",
            "tab1.post_join_lag_sample_count",
            "tab1.post_join_lag_wait_sample_count",
            "tab1.post_join_lag_stale_sample_count",
            "tab1.post_join_lag_max_ms",
            "tab1.post_join_lag_p95_ms",
            "tab1.post_join_lag_wait_age_max_ms",
            "tab1.post_join_lag_response_age_max_ms",
            "tab1.lag_wait_timeout_count_last",
            "tab1.lag_response_age_ms_last",
            "tab1.auth_self_lag_echo_queue_drop_count_last",
            "tab2.lag_ms_max",
            "tab2.lag_spike_count",
            "tab2.lag_band",
            "tab2.post_join_lag_spike_count",
            "tab2.post_join_lag_sample_count",
            "tab2.post_join_lag_wait_sample_count",
            "tab2.post_join_lag_stale_sample_count",
            "tab2.post_join_lag_max_ms",
            "tab2.post_join_lag_p95_ms",
            "tab2.post_join_lag_wait_age_max_ms",
            "tab2.post_join_lag_response_age_max_ms",
            "tab2.lag_wait_timeout_count_last",
            "tab2.lag_response_age_ms_last",
            "tab2.auth_self_lag_echo_queue_drop_count_last",
        ):
            va = fields_a.get(key)
            vb = fields_b.get(key)
            if isinstance(va, (int, float)) and isinstance(vb, (int, float)):
                delta = vb - va
                delta_str = f"{delta:+.2f}" if isinstance(delta, float) else f"{delta:+d}"
            elif va != vb and va is not None and vb is not None:
                delta_str = f"{va} -> {vb}"
            else:
                delta_str = "-"
            lag_summary_payload[key] = {"a": va, "b": vb, "delta": delta_str}
            print(f"  {key}: A={va if va is not None else '-'}  B={vb if vb is not None else '-'}  delta={delta_str}")
        ova = overrun_a.get("tick_overrun_count") if overrun_a else None
        ovb = overrun_b.get("tick_overrun_count") if overrun_b else None
        maxa = overrun_a.get("tick_max_elapsed_us") if overrun_a else None
        maxb = overrun_b.get("tick_max_elapsed_us") if overrun_b else None
        for key, va, vb in (
            ("tick_overrun_count", ova, ovb),
            ("tick_max_elapsed_us", maxa, maxb),
        ):
            if isinstance(va, (int, float)) and isinstance(vb, (int, float)):
                delta = vb - va
                delta_str = f"{delta:+d}" if isinstance(delta, int) else f"{delta:+.2f}"
            elif va != vb and va is not None and vb is not None:
                delta_str = f"{va} -> {vb}"
            else:
                delta_str = "-"
            lag_summary_payload[key] = {"a": va, "b": vb, "delta": delta_str}
            print(f"  {key}: A={va if va is not None else '-'}  B={vb if vb is not None else '-'}  delta={delta_str}")
        print()

    # --- Online integrity ---
    online_a = run_a.get("online_integrity_ok")
    online_b = run_b.get("online_integrity_ok")
    if online_a != online_b:
        print(cli_style.style("--- ONLINE INTEGRITY ---", "subheader"))
        print(f"  A: {fmt_bool(online_a)}  ->  B: {fmt_bool(online_b)}")
        print()

    online_delta_payload = {"a": online_a, "b": online_b} if online_a != online_b else None

    # --- Steps diff ---
    steps_a = {s["name"]: s for s in (run_a.get("steps") or [])}
    steps_b = {s["name"]: s for s in (run_b.get("steps") or [])}
    all_step_names = list(
        dict.fromkeys(list(steps_a) + list(steps_b))
    )  # preserve order
    step_changes = []
    for name in all_step_names:
        sa = steps_a.get(name)
        sb = steps_b.get(name)
        if sa is None:
            step_changes.append(
                (name, "(absent)", f"ok={sb['ok']} rc={sb.get('returncode', '-')}")
            )
        elif sb is None:
            step_changes.append(
                (name, f"ok={sa['ok']} rc={sa.get('returncode', '-')}", "(absent)")
            )
        elif sa.get("ok") != sb.get("ok") or sa.get("returncode") != sb.get(
            "returncode"
        ):
            step_changes.append(
                (
                    name,
                    f"ok={sa['ok']} rc={sa.get('returncode', '-')}",
                    f"ok={sb['ok']} rc={sb.get('returncode', '-')}",
                )
            )
    if step_changes:
        print(cli_style.style("--- STEPS CHANGED ---", "subheader"))
        for name, va, vb in step_changes:
            print(f"  {name}: [{va}] -> [{vb}]")
        print()

    # --- Code diff ---
    run_b_intent = run_b.get("run_intent") if isinstance(run_b.get("run_intent"), dict) else {}
    fix_attempts = [str(v).strip() for v in (run_b_intent.get("fix_attempts") or []) if str(v).strip()]
    baseline_runs = [str(v).strip() for v in (run_b_intent.get("baseline_runs") or []) if str(v).strip()]
    requested_paths = [
        str(v).strip()
        for v in (
            getattr(args, "diff_path", None)
            or (_resolve_intent_diff_spec(run_b).get("paths") or [])
        )
        if str(v).strip()
    ]
    # RQ-040 / FL-1794: default to MP+watchdog corpus when caller did not
    # explicitly request a corpus or path.  Use "all" only when --corpus all
    # is passed explicitly.  This filters out non-MP noise commits.
    _explicit_corpus = getattr(args, "diff_corpus", None)
    _explicit_paths = getattr(args, "diff_path", None)
    _default_corpora = _explicit_corpus or (["gameplay", "watchdog"] if not _explicit_paths else None)
    code_diff_payload = resolve_code_diff_payload(
        root=root,
        run_a=run_a,
        run_b=run_b,
        diff_corpora=_default_corpora,
        diff_mode=getattr(args, "diff_mode", None),
        diff_paths=_explicit_paths,
    )
    # RQ-040: Detect non-MP commits between the two run heads and warn loudly.
    _head_a = run_a.get("git_head") or ""
    _head_b = run_b.get("git_head") or ""
    if _head_a and _head_b and _head_a != _head_b:
        _mp_pathspecs = diff_pathspecs_for_corpora(["gameplay", "watchdog"])
        _all_pathspecs = list(SOURCE_CODE_PATHSPECS)
        try:
            _log_all = run_git(["log", "--oneline", f"{_head_a}..{_head_b}"], root)
            _all_commits = [l.strip() for l in (_log_all.stdout or "").splitlines() if l.strip()]
            _log_mp = run_git(["log", "--oneline", f"{_head_a}..{_head_b}", "--", *_mp_pathspecs], root)
            _mp_commits = set(l.split()[0] for l in (_log_mp.stdout or "").splitlines() if l.strip())
            _non_mp = [l for l in _all_commits if l.split()[0] not in _mp_commits]
            if _non_mp:
                print(cli_style.style(
                    f"\u26a0\ufe0f  WARNING: {len(_non_mp)} commit(s) between runs touch ONLY non-MP files "
                    f"(diff is filtered to gameplay+watchdog corpus; these commits are excluded):",
                    "warn"))
                for _c in _non_mp[:6]:
                    print(f"    {_c}")
                if len(_non_mp) > 6:
                    print(f"    ... and {len(_non_mp) - 6} more")
                print()
        except Exception:
            pass
    print(cli_style.style("--- CODE DIFF ---", "subheader"))
    requested_corpora = code_diff_payload.get("requested_corpora") or ["all"]
    print(f"  corpus: {diff_corpus_label(requested_corpora)}")
    strategy = str(code_diff_payload.get("strategy") or "between_runs")
    if strategy == "latest_relevant":
        print("  strategy: latest relevant source delta")
    elif strategy == "exact_commits":
        print("  strategy: explicit commit anchors")
    else:
        print("  strategy: selected run heads")
    if code_diff_payload.get("diff_backend"):
        print(f"  backend:  {code_diff_payload['diff_backend']}")
    if fix_attempts:
        print(f"  fixes:    {', '.join(fix_attempts)}")
    if baseline_runs:
        print(f"  baselines: {', '.join(baseline_runs)}")
    if requested_paths:
        print(f"  paths:    {', '.join(requested_paths)}")
    if code_diff_payload.get("note"):
        print(f"  note: {code_diff_payload['note']}")
    if code_diff_payload.get("relevant_commit"):
        print(
            "  relevant: "
            f"{str(code_diff_payload.get('relevant_parent') or '')[:12]} -> "
            f"{str(code_diff_payload.get('relevant_commit') or '')[:12]}"
        )
    state = str(code_diff_payload.get("state") or "unavailable")
    text = str(code_diff_payload.get("text") or "").rstrip()
    if state == "diff" and text:
        print(text)
        print()
    elif state == "same_head":
        print("  (same git head; no code delta)")
        print()
    elif state in {"no_source_delta", "no_relevant_source_delta"}:
        print("  (no source-file differences in the selected corpus)")
        print()
    elif state == "unavailable":
        print("  (unavailable; one or both runs lack git_head metadata)")
        print()
    elif state == "relevant_commit_has_no_parent":
        print("  (latest relevant commit has no parent; unable to diff it)")
        print()
    else:
        print(f"  (diff unavailable: {state})")
        stderr = str(code_diff_payload.get("stderr") or "").strip()
        if stderr:
            print(f"  {stderr}")
        print()

    # --- Gate diff ---
    false_a = set(run_a.get("false_gates") or [])
    null_a = set(run_a.get("null_gates") or [])
    false_b = set(run_b.get("false_gates") or [])
    null_b = set(run_b.get("null_gates") or [])

    if run_a.get("false_gates") is None and run_a.get("null_gates") is None:
        print("WARNING: run A has no gate data (blocked/failed run)")
    if run_b.get("false_gates") is None and run_b.get("null_gates") is None:
        print("WARNING: run B has no gate data (blocked/failed run)")

    not_ok_a = false_a | null_a
    not_ok_b = false_b | null_b
    suppressed_deprecated = sorted((not_ok_a | not_ok_b) & DEPRECATED_GATES)
    suppressed_diagnostic = sorted((not_ok_a | not_ok_b) & DIAGNOSTIC_ONLY_GATES)
    all_gates = (not_ok_a | not_ok_b) - DEPRECATED_GATES - DIAGNOSTIC_ONLY_GATES

    regressions = []
    recoveries = []
    unchanged_fail = []
    unchanged_null = []
    changed_badness = []

    for gate in sorted(all_gates):
        state_a = gate_state(run_a, gate)
        state_b = gate_state(run_b, gate)
        if state_a == "true" and state_b != "true":
            regressions.append((gate, state_a, state_b))
        elif state_a != "true" and state_b == "true":
            recoveries.append((gate, state_a, state_b))
        elif state_a == state_b == "false":
            unchanged_fail.append(gate)
        elif state_a == state_b == "null":
            unchanged_null.append(gate)
        else:
            changed_badness.append((gate, state_a, state_b))

    fl = load_fl_index(root)

    def print_section(title, items, with_states=False, annotate_fl=False, line_style=None):
        print(cli_style.style(f"--- {title} ({len(items)}) ---", "subheader"))
        if not items:
            print("  (none)")
        elif with_states:
            for gate, sa, sb in items:
                ann = fl_gate_ann(fl, gate) if annotate_fl else ""
                gap = gap_ann(gaps, gate)
                line = f"  {gate}  [{sa} -> {sb}]{ann}{gap}"
                print(cli_style.style(line, line_style) if line_style else line)
        else:
            for gate in items:
                ann = fl_gate_ann(fl, gate) if annotate_fl else ""
                gap = gap_ann(gaps, gate)
                line = f"  {gate}{ann}{gap}"
                print(cli_style.style(line, line_style) if line_style else line)
        print()

    # RQ-040: upgrade regression header to bold-red (was subheader/cyan)
    if regressions:
        print(cli_style.style(f"--- REGRESSIONS (true in A, not true in B) ({len(regressions)}) ---", "fail"))
        for gate, sa, sb in regressions:
            ann = fl_gate_ann(fl, gate)
            gap = gap_ann(gaps, gate)
            print(cli_style.style(f"  {gate}  [{sa} -> {sb}]{ann}{gap}", "fail"))
        print()
    else:
        print_section(
            "REGRESSIONS (true in A, not true in B)",
            regressions,
            with_states=True,
            annotate_fl=True,
            line_style="fail",
        )
    if regressions and _provenance_changed(run_a, run_b):
        print("  ↳ note: measurement method changed; verify regressions are real")
        print()
    print_section(
        "RECOVERIES (not true in A, true in B)",
        recoveries,
        with_states=True,
        annotate_fl=True,
        line_style="ok",
    )
    print_section(
        "CHANGED (bad in both, type changed)",
        changed_badness,
        with_states=True,
        annotate_fl=True,
        line_style="fail",
    )
    print_section(
        "UNCHANGED FAILURES (false in both)", unchanged_fail, annotate_fl=True, line_style="dim"
    )
    print_section("UNCHANGED NULLS (null in both)", unchanged_null, annotate_fl=True, line_style="dim")
    if suppressed_diagnostic:
        print(cli_style.style(f"--- DIAGNOSTIC GATE NOISE SUPPRESSED ({len(suppressed_diagnostic)}) ---", "subheader"))
        for gate in suppressed_diagnostic:
            print(f"  {gate}")
        print()
    if suppressed_deprecated:
        print(cli_style.style(f"--- DEPRECATED GATE NOISE SUPPRESSED ({len(suppressed_deprecated)}) ---", "subheader"))
        for gate in suppressed_deprecated:
            print(f"  {gate}")
        print()

    next_b = recommend_next_action(run_b) or run_b.get("next_action")
    if getattr(args, "json", False):
        def _state_rows(items: list[tuple[str, str, str]]) -> list[dict[str, Any]]:
            return [{"gate": gate, "state_a": sa, "state_b": sb} for gate, sa, sb in items]
        payload = {
            "run_a": {
                "run_id": run_a.get("run_id"),
                "date": run_a.get("started_at_utc"),
                "commit": run_a.get("git_head"),
                "source_ref": run_a.get("source_ref"),
                "branch": run_a.get("branch"),
                "verdict": run_a.get("verdict"),
                "online_integrity_ok": run_a.get("online_integrity_ok"),
                "git_tag": run_a.get("git_tag"),
            },
            "run_b": {
                "run_id": run_b.get("run_id"),
                "date": run_b.get("started_at_utc"),
                "commit": run_b.get("git_head"),
                "source_ref": run_b.get("source_ref"),
                "branch": run_b.get("branch"),
                "verdict": run_b.get("verdict"),
                "online_integrity_ok": run_b.get("online_integrity_ok"),
                "git_tag": run_b.get("git_tag"),
            },
            "provenance": provenance,
            "lag_summary": lag_summary_payload,
            "online_integrity_delta": online_delta_payload,
            "step_changes": [{"name": name, "a": va, "b": vb} for name, va, vb in step_changes],
            "code_diff": code_diff_payload,
            "regressions": _state_rows(regressions),
            "recoveries": _state_rows(recoveries),
            "changed_badness": _state_rows(changed_badness),
            "unchanged_failures": unchanged_fail,
            "unchanged_nulls": unchanged_null,
            "suppressed_diagnostic": suppressed_diagnostic,
            "suppressed_deprecated": suppressed_deprecated,
            "next_action": next_b,
        }
        print(json.dumps(payload, indent=2))
        return

    # --- Next action ---
    if next_b:
        print(cli_style.style("--- NEXT ACTION (B) ---", "subheader"))
        print(f"  {next_b}")
        print()


# ---------------------------------------------------------------------------
# Subcommand: trend
# ---------------------------------------------------------------------------


def cmd_trend(args, root: Path):
    if getattr(args, "json", False):
        print(json.dumps(build_trend_payload(args, root), indent=2))
        return
    runs, _ = load_all_runs(root)
    tags = load_git_tags(root)
    label_filter = requested_run_label(args)
    if label_filter:
        runs = [r for r in runs if run_label_for(r) == label_filter]
    if args.skip_blocked:
        runs = [
            r
            for r in runs
            if r.get("false_gates") is not None or r.get("null_gates") is not None
        ]
    pattern = args.gate_name

    all_gates = all_known_gates(runs)
    if pattern in all_gates:
        matching_gates = [pattern]
    else:
        matching_gates = sorted(g for g in all_gates if pattern in g)

    if not matching_gates:
        if getattr(args, "json", False):
            print(json.dumps({"pattern": pattern, "matching_gates": [], "known_gates": sorted(all_gates)}, indent=2))
            return
        print(f"No gates found matching '{pattern}'")
        print(f"Known gates ({len(all_gates)} total):")
        for g in sorted(all_gates):
            print(f"  {g}")
        return

    headers = ["RUN_ID", "DATE(UTC)", "STATE", "VERDICT", "COMMIT", "TAG?", "BRANCH"]
    payload_gates: list[dict[str, Any]] = []

    for gate in matching_gates:
        print(f"\nGATE: {gate}")
        rows = []
        payload_rows = []
        for run in runs:
            state = gate_state(run, gate)
            payload_rows.append(
                {
                    "run_id": run.get("run_id", "-"),
                    "date": run.get("started_at_utc"),
                    "state": state,
                    "verdict": run.get("verdict") or "-",
                    "commit": run.get("git_head") or "-",
                    "tag": tag_exists(run, tags),
                    "branch": run.get("branch") or "-",
                }
            )
            rows.append(
                [
                    run.get("run_id", "-"),
                    fmt_ts(run.get("started_at_utc"), short=True),
                    state,
                    run.get("verdict") or "-",
                    run.get("git_head") or "-",
                    tag_exists(run, tags),
                    run.get("branch") or "-",
                ]
            )
        payload_gates.append({"gate": gate, "rows": payload_rows})
        if getattr(args, "json", False):
            continue
        print_table(headers, rows)
    if getattr(args, "json", False):
        print(json.dumps({"pattern": pattern, "matching_gates": payload_gates}, indent=2))


def cmd_regression_window(args, root: Path):
    payload = build_regression_window_payload(args, root)
    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2))
        return
    print(f"REGRESSION-WINDOW: {payload['gate']}")
    if payload.get("error") == "start_commit_not_found":
        print(f"  start commit not found: {args.start_commit}")
        return
    last_pass = payload.get("last_passing_run") or {}
    first_fail = payload.get("first_failing_run") or {}
    if not payload.get("window_found"):
        print("  No failing transition found in scanned runs.")
        if last_pass:
            print(
                f"  Last pass: {last_pass.get('run_id') or '-'} @ {last_pass.get('commit') or '-'}"
            )
        return
    print(
        f"  Last pass:    {last_pass.get('run_id') or '-'} @ {last_pass.get('commit') or '-'}"
    )
    print(
        f"  First {payload.get('first_failing_state')}:  {first_fail.get('run_id') or '-'} @ {first_fail.get('commit') or '-'}"
    )
    window = payload.get("candidate_commit_window") or {}
    print(
        f"  Commit window: {window.get('from_commit') or '-'} -> {window.get('to_commit') or '-'}"
    )


