# Subcommand: lag-trend
# ---------------------------------------------------------------------------


def cmd_lag_trend(args, root: Path) -> None:
    runs, _ = load_all_runs(root)
    label_filter = requested_run_label(args)
    if label_filter:
        runs = [r for r in runs if run_label_for(r) == label_filter]
    if getattr(args, "limit", None):
        runs = runs[: args.limit]

    rows = []
    for run in runs:
        metrics, _src = _safe_load_metrics_for_run(run)
        if not metrics:
            continue
        fields = _lag_fields_from_metrics(metrics)
        t1 = fields.get("tab1.lag_ms_max")
        t2 = fields.get("tab2.lag_ms_max")
        numeric = [v for v in (t1, t2) if isinstance(v, (int, float))]
        max_lag = max(numeric) if numeric else "-"
        rows.append(
            [
                run.get("run_id", "-"),
                fmt_ts(run.get("started_at_utc"), short=True),
                (run.get("git_head") or "-")[:8],
                run.get("verdict") or "-",
                t1 if t1 is not None else "-",
                t2 if t2 is not None else "-",
                max_lag,
                fields.get("tab1.lag_spike_count", "-"),
                fields.get("tab2.lag_spike_count", "-"),
                fields.get("tab1.lag_band", "-"),
                fields.get("tab2.lag_band", "-"),
            ]
        )

    if not rows:
        print("(no runs with metrics.json lag data)")
        return

    _print_table(
        [
            "run_id",
            "date",
            "commit",
            "verdict",
            "tab1_max",
            "tab2_max",
            "max_lag",
            "tab1_spikes",
            "tab2_spikes",
            "tab1_band",
            "tab2_band",
        ],
        rows,
    )


def _run_dt(run: dict) -> datetime | None:
    for field in ("started_at_utc", "completed_at_utc", "started_at"):
        raw = run.get(field)
        if not raw:
            continue
        try:
            dt = datetime.fromisoformat(str(raw).replace("Z", "+00:00"))
        except ValueError:
            continue
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt
    return None


def _lag_gate_audit_row(run: dict, metrics: dict, root: Path | None = None) -> dict[str, Any]:
    # WARNING FL-3800 / FL-3815: configured/stored lag_yellow_spike_budget_ok
    # rows can duplicate the corrected raw gate. FL-3800 is parked as
    # external/no-repo-owner after clean server, public/raw A/B, standalone,
    # netlog, direction-split, host tcpdump, client-pcap, external-pcap, and
    # VPS-local control phases. Treat raw red/yellow counts and same-run
    # attribution fields as the proof surface. FL-3815 is metrics/provenance,
    # not gameplay lag ownership; FL-2957 is the separate raw-red gameplay lane.
    rs = ((metrics.get("diagnostics") or {}).get("recorder_surface") or {})
    artifact_root = root or repo_root()
    try:
        art = _require_artifact_path(run, "lag-gate-audit")
    except SystemExit:
        art = None
    tick_overrun = derive_authoritative_tick_overrun_metrics(run, artifact_root) or {}
    player_steps = _derive_all_tick_player_steps(art / "server.log", limit=4096) if art else []
    max_player_step = max((int(row.get("step_once_us") or 0) for row in player_steps), default=None)
    player_step_over_50000 = sum(1 for row in player_steps if int(row.get("step_once_us") or 0) > 50000)
    max_collect_mesh_us = max((int(row.get("collect_mesh_us") or 0) for row in player_steps), default=None)
    max_support_retry_collect_mesh_us = max(
        (int(row.get("support_retry_collect_mesh_us") or 0) for row in player_steps),
        default=None,
    )
    max_sweep_total_us = max((int(row.get("sweep_total_us") or 0) for row in player_steps), default=None)
    max_sweep_narrow_total_us = max((int(row.get("sweep_narrow_total_us") or 0) for row in player_steps), default=None)
    max_collision_checks = max((int(row.get("collision_checks") or 0) for row in player_steps), default=None)
    max_broadphase_rejects = max((int(row.get("broadphase_rejects") or 0) for row in player_steps), default=None)

    run_server_truth = {
        "player_step_over_50000_count": player_step_over_50000,
        "max_player_mp_step_once_us": max_player_step,
        "max_collect_mesh_us": max_collect_mesh_us,
        "max_support_retry_collect_mesh_us": max_support_retry_collect_mesh_us,
        "max_sweep_total_us": max_sweep_total_us,
        "max_sweep_narrow_total_us": max_sweep_narrow_total_us,
        "max_collision_checks": max_collision_checks,
        "max_broadphase_rejects": max_broadphase_rejects,
        "max_server_tick_elapsed_us": tick_overrun.get("tick_max_elapsed_us"),
        "max_server_phase": tick_overrun.get("tick_max_phase"),
        "max_server_phase_us": tick_overrun.get("tick_max_phase_us"),
        "max_snapshot_phase": tick_overrun.get("tick_max_snapshot_phase"),
        "max_snapshot_phase_us": tick_overrun.get("tick_max_snapshot_phase_us"),
        "max_snapshot_auth_phase_us": tick_overrun.get("tick_max_snapshot_phase_us")
        if tick_overrun.get("tick_max_snapshot_phase") == "authoritative_state"
        else None,
        "max_npc_physics_phase_us": tick_overrun.get("tick_npc_breakdown_npcs_us"),
        "max_physics_phase": tick_overrun.get("tick_max_physics_phase"),
        "max_physics_phase_us": tick_overrun.get("tick_max_physics_phase_us"),
    }

    raw_yellow = 0
    raw_red = 0
    raw_post_join_red = 0
    raw_rtt_yellow = 0
    raw_rtt_red = 0
    max_lag = None
    max_raw_rtt = None
    max_trace_delivery_us = None
    contradictions: list[str] = []
    tab_rows: list[dict[str, Any]] = []
    tabs: dict[str, Any] = {}
    for tab_name in ("tab1", "tab2"):
        tab = rs.get(tab_name) or {}
        if not tab:
            continue
        tab_max = tab.get("lag_ms_max")
        tab_yellow_count = tab.get("lag_yellow_count") or 0
        tab_red_count = tab.get("lag_spike_count") or 0
        tab_post_join_red_count = tab.get("post_join_lag_spike_count") or 0
        tab_rtt_max = tab.get("lag_rtt_raw_ms_max")
        tab_rtt_yellow_count = tab.get("lag_rtt_raw_yellow_count") or 0
        tab_rtt_red_count = tab.get("lag_rtt_raw_spike_count") or 0
        tab_yellow_latest = tab.get("lag_trace_yellow_latest_lag_ms")
        tab_red_latest = tab.get("lag_trace_red_latest_lag_ms")
        honest = _honest_lag_band(tab)
        stored = tab.get("lag_band")
        if isinstance(tab_max, (int, float)):
            max_lag = tab_max if max_lag is None else max(max_lag, tab_max)
        if isinstance(tab_rtt_max, (int, float)):
            max_raw_rtt = tab_rtt_max if max_raw_rtt is None else max(max_raw_rtt, tab_rtt_max)
        trace_delivery_candidates = [
            tab.get("lag_trace_network_transit_est_us_max"),
            tab.get("lag_trace_post_send_to_onmessage_us_js_max"),
            tab.get("lag_trace_send_to_onmessage_us_js_max"),
            tab.get("lag_trace_wasm_rtt_us_max"),
            tab.get("lag_trace_network_transit_est_us_yellow_latest"),
            tab.get("lag_trace_post_send_to_onmessage_us_js_yellow_latest"),
            tab.get("lag_trace_send_to_onmessage_us_js_yellow_latest"),
        ]
        for candidate in trace_delivery_candidates:
            if isinstance(candidate, (int, float)):
                max_trace_delivery_us = (
                    candidate
                    if max_trace_delivery_us is None
                    else max(max_trace_delivery_us, candidate)
                )
        if isinstance(tab_yellow_count, (int, float)) and tab_yellow_count > 0:
            raw_yellow += int(tab_yellow_count)
        elif isinstance(tab_max, (int, float)) and 100 <= tab_max < 200:
            raw_yellow += 1
        elif isinstance(tab_yellow_latest, (int, float)) and 100 <= tab_yellow_latest < 200:
            raw_yellow += 1
        if isinstance(tab_red_count, (int, float)) and tab_red_count > 0:
            raw_red += int(tab_red_count)
        elif isinstance(tab_max, (int, float)) and tab_max >= 200:
            raw_red += 1
        if isinstance(tab_post_join_red_count, (int, float)) and tab_post_join_red_count > 0:
            raw_post_join_red += int(tab_post_join_red_count)
        if isinstance(tab_rtt_yellow_count, (int, float)) and tab_rtt_yellow_count > 0:
            raw_rtt_yellow += int(tab_rtt_yellow_count)
        elif isinstance(tab_rtt_max, (int, float)) and 100 <= tab_rtt_max < 200:
            raw_rtt_yellow += 1
        if isinstance(tab_rtt_red_count, (int, float)) and tab_rtt_red_count > 0:
            raw_rtt_red += int(tab_rtt_red_count)
        elif isinstance(tab_rtt_max, (int, float)) and tab_rtt_max >= 200:
            raw_rtt_red += 1
        if stored and honest and stored != honest:
            contradictions.append(f"{tab_name}:stored={stored}:honest={honest}")
        gates = {
            gate: gate_state(run, gate)
            for gate in (
                "lag_spike_count_ok",
                "lag_yellow_spike_budget_ok",
                "post_join_lag_spike_count_ok",
                "lag_floor_p95_ok",
                "lag_floor_p95_steady_ok",
            )
        }
        lag_gates_pass = (
            gates["lag_spike_count_ok"] == "true"
            and gates["lag_yellow_spike_budget_ok"] == "true"
            and gates["lag_floor_p95_ok"] == "true"
            and gates["lag_floor_p95_steady_ok"] == "true"
        )
        tab_contradiction_reasons: list[str] = []
        if stored == "green" and isinstance(tab_yellow_count, (int, float)) and tab_yellow_count > 0:
            tab_contradiction_reasons.append("stored_green_raw_yellow")
        if stored == "green" and isinstance(tab_red_count, (int, float)) and tab_red_count > 0:
            tab_contradiction_reasons.append("stored_green_raw_red")
        if honest == "green" and isinstance(tab_yellow_count, (int, float)) and tab_yellow_count > 0:
            tab_contradiction_reasons.append("printed_green_raw_yellow")
        if honest == "green" and isinstance(tab_red_count, (int, float)) and tab_red_count > 0:
            tab_contradiction_reasons.append("printed_green_raw_red")
        if lag_gates_pass and isinstance(tab_max, (int, float)) and tab_max >= 100:
            tab_contradiction_reasons.append("lag_gates_pass_raw_threshold")
        if lag_gates_pass and (
            (isinstance(tab_yellow_count, (int, float)) and tab_yellow_count > 0)
            or (isinstance(tab_red_count, (int, float)) and tab_red_count > 0)
        ):
            tab_contradiction_reasons.append("lag_gates_pass_raw_counts")
        if (
            gates["post_join_lag_spike_count_ok"] == "true"
            and isinstance(tab_post_join_red_count, (int, float))
            and tab_post_join_red_count > 0
        ):
            tab_contradiction_reasons.append("post_join_gate_pass_raw_red")
        client_evidence = {
            "trace_max_wasm_rtt_us": tab.get("lag_trace_wasm_rtt_us_max"),
            "trace_max_net_transit_est_us": tab.get("lag_trace_network_transit_est_us_max"),
            "trace_max_post_send_to_onmessage_us_js": tab.get(
                "lag_trace_post_send_to_onmessage_us_js_max"
            ),
            "trace_max_send_to_onmessage_us_js": tab.get("lag_trace_send_to_onmessage_us_js_max"),
            "trace_yellow_latest_net_transit_est_us": tab.get(
                "lag_trace_network_transit_est_us_yellow_latest"
            ),
            "trace_yellow_latest_post_send_to_onmessage_us_js": tab.get(
                "lag_trace_post_send_to_onmessage_us_js_yellow_latest"
            ),
            "trace_max_js_longtask_us": tab.get("lag_trace_longtask_max_us_js_max")
            or tab.get("lag_trace_longtask_max_us_js_last"),
            "trace_max_js_event_queue_us": tab.get("lag_trace_message_event_to_handler_us_js_max"),
            "trace_attr_ready": tab.get("lag_trace_packet_exit_attribution_ready_last"),
            "trace_yellow_attr_ready": tab.get(
                "lag_trace_packet_exit_attribution_ready_yellow_latest"
            ),
        }
        tab_row = {
            "run_id": run.get("run_id"),
            "source_ref": run.get("source_ref") or run.get("git_head") or run.get("commit"),
            "tab_id": tab_name,
            "raw_lag_ms_max": tab_max,
            "instant_rtt_raw_ms_max": tab_rtt_max,
            "instant_rtt_raw_yellow_count": tab_rtt_yellow_count,
            "instant_rtt_raw_red_count": tab_rtt_red_count,
            "raw_yellow_count": tab.get("lag_yellow_count"),
            "raw_red_count": tab.get("lag_spike_count"),
            "raw_post_join_red_count": tab.get("post_join_lag_spike_count"),
            "yellowLatest": tab_yellow_latest,
            "redLatest": tab_red_latest,
            "stored_lag_band": stored,
            "printed_lag_band": honest,
            "lag_band_contradiction": bool(tab_contradiction_reasons),
            "lag_band_contradiction_reasons": tab_contradiction_reasons,
            "client_browser_render_evidence": client_evidence,
            **gates,
            **run_server_truth,
        }
        tab_rows.append(tab_row)
        tabs[tab_name] = {
            "stored_band": stored,
            "honest_band": honest,
            "lag_ms_max": tab_max,
            "lag_rtt_raw_ms_max": tab.get("lag_rtt_raw_ms_max"),
            "lag_rtt_raw_yellow_count": tab.get("lag_rtt_raw_yellow_count"),
            "lag_rtt_raw_spike_count": tab.get("lag_rtt_raw_spike_count"),
            "lag_yellow_count": tab.get("lag_yellow_count"),
            "lag_spike_count": tab.get("lag_spike_count"),
            "post_join_lag_spike_count": tab.get("post_join_lag_spike_count"),
            "yellow_latest": tab_yellow_latest,
            "red_latest": tab_red_latest,
            "post_join_lag_max_ms": tab.get("post_join_lag_max_ms"),
            "post_join_lag_p95_ms": tab.get("post_join_lag_p95_ms"),
        }
    corrected_yellow_states: list[bool] = []
    for tab in tabs.values():
        red_count = tab.get("lag_spike_count")
        yellow_count = tab.get("lag_yellow_count")
        tab_max = tab.get("lag_ms_max")
        post_join_max = tab.get("post_join_lag_max_ms")
        post_join_p95 = tab.get("post_join_lag_p95_ms")
        if not all(isinstance(v, (int, float)) for v in (red_count, yellow_count, tab_max, post_join_max, post_join_p95)):
            continue
        corrected_yellow_states.append(
            red_count == 0
            and yellow_count == 0
            and tab_max < 100
            and post_join_max < 100
            and post_join_p95 <= 90
        )
    corrected_yellow_gate = all(corrected_yellow_states) if corrected_yellow_states else None
    run_lag_band_contradiction = any(row["lag_band_contradiction"] for row in tab_rows) or bool(contradictions)
    owner_bucket = "no_raw_visible_lag"
    owner_evidence = "raw yellow/red absent"
    server_bounded = (
        (tick_overrun.get("tick_max_elapsed_us") or 0) < 50000
        and (max_player_step or 0) < 50000
        and (tick_overrun.get("tick_max_snapshot_phase_us") or 0) < 50000
        and (tick_overrun.get("tick_npc_breakdown_npcs_us") or 0) < 50000
    )
    trace_delivery_yellow = (max_trace_delivery_us or 0) >= 100000
    if raw_yellow > 0 or raw_red > 0 or raw_post_join_red > 0:
        if player_step_over_50000 > 0 or (max_player_step or 0) > 50000:
            owner_bucket = "player_mpsteponce_collision_sweep_owner"
            owner_evidence = "player MpStepOnce exceeded 50000us"
        elif (
            tick_overrun.get("tick_max_phase") == "physics"
            and tick_overrun.get("tick_max_physics_phase") == "players"
            and (
                (tick_overrun.get("tick_max_physics_phase_us") or 0) > 50000
                or (tick_overrun.get("tick_max_elapsed_us") or 0) > 50000
            )
        ):
            # Some historical runs did not export per-tick player step breakdowns
            # (MpStepOnce / sweep / collision counters). In those cases, treat a
            # physics overrun owned by the players subphase as a player-physics
            # owner rather than leaving it "unknown".
            owner_bucket = "player_mpsteponce_collision_sweep_owner"
            owner_evidence = "max_phase=physics and max_physics_phase=players (player step breakdown missing)"
        elif (
            tick_overrun.get("tick_max_phase") == "snapshot"
            and tick_overrun.get("tick_max_snapshot_phase") == "authoritative_state"
            and (
                (tick_overrun.get("tick_max_snapshot_phase_us") or 0) > 50000
                or (tick_overrun.get("tick_max_elapsed_us") or 0) > 50000
            )
        ):
            owner_bucket = "snapshot_auth_send_queue_overrun"
            owner_evidence = "max_phase=snapshot and max_snapshot_phase=authoritative_state"
        elif tick_overrun.get("tick_max_physics_phase") == "npcs":
            owner_bucket = "npc_physics_overrun"
            owner_evidence = "max_physics_phase=npcs"
        elif run_lag_band_contradiction:
            owner_bucket = "measurement_provenance_contradiction"
            owner_evidence = "raw lag disagrees with stored/printed band or configured gates"
        elif trace_delivery_yellow and server_bounded:
            owner_bucket = "network_or_browser_socket_delivery"
            owner_evidence = (
                "trace delivery interval crossed threshold while server gameplay, "
                "WASM, JS handler, and longtask spans stayed bounded"
            )
        elif (
            server_bounded
        ):
            owner_bucket = "client_browser_render_visible_lag_no_server_owner"
            owner_evidence = "raw visible lag with bounded server/player/NPC/snapshot phases"
        else:
            owner_bucket = "unknown"
            owner_evidence = "raw visible lag exists without current owner attribution"
    elif raw_rtt_yellow > 0 or raw_rtt_red > 0:
        owner_bucket = "network_or_browser_socket_delivery"
        owner_evidence = (
            "raw RTT crossed threshold while visible lag stayed below threshold; current clocks "
            "cannot split server-to-client transit from browser socket dispatch"
        )
    return {
        "run_id": run.get("run_id"),
        "date": run.get("started_at_utc") or run.get("completed_at_utc"),
        "verdict": run.get("verdict"),
        "commit": run.get("git_head"),
        "source_ref": run.get("source_ref") or run.get("git_head") or run.get("commit"),
        "gates": {
            gate: gate_state(run, gate)
            for gate in (
                "lag_spike_count_ok",
                "lag_yellow_spike_budget_ok",
                "post_join_lag_spike_count_ok",
                "lag_floor_p95_ok",
                "lag_floor_p95_steady_ok",
                "post_join_lag_stable",
                "lag_stable_at_respawn",
            )
        },
        "raw_yellow_count": raw_yellow,
        "raw_red_count": raw_red,
        "raw_post_join_red_count": raw_post_join_red,
        "raw_rtt_yellow_count": raw_rtt_yellow,
        "raw_rtt_red_count": raw_rtt_red,
        "raw_max_lag_ms": max_lag,
        "raw_rtt_max_ms": max_raw_rtt,
        "trace_delivery_max_us": max_trace_delivery_us,
        "corrected_lag_yellow_spike_budget_ok": corrected_yellow_gate,
        "stored_band_contradictions": contradictions,
        "lag_band_contradiction": run_lag_band_contradiction,
        "owner_bucket": owner_bucket,
        "owner_evidence": owner_evidence,
        "server_truth": run_server_truth,
        "tab_rows": tab_rows,
        "tabs": tabs,
    }


def cmd_lag_gate_audit(args, root: Path) -> None:
    runs, _ = load_all_runs(root)
    since = None
    if getattr(args, "since", None):
        try:
            since = datetime.fromisoformat(args.since.replace("Z", "+00:00"))
        except ValueError as exc:
            raise SystemExit(f"invalid --since: {args.since}: {exc}")
        if since.tzinfo is None:
            since = since.replace(tzinfo=timezone.utc)
    rows: list[dict[str, Any]] = []
    missing = 0
    for run in runs:
        dt = _run_dt(run)
        if since is not None and (dt is None or dt < since):
            continue
        metrics, _src = _safe_load_metrics_for_run(run)
        if not metrics:
            missing += 1
            continue
        rows.append(_lag_gate_audit_row(run, metrics, root))

    gate_counts: dict[str, Counter] = {}
    for row in rows:
        for gate, state in (row.get("gates") or {}).items():
            gate_counts.setdefault(gate, Counter())[state] += 1
    raw_yellow_runs = sum(1 for row in rows if (row.get("raw_yellow_count") or 0) > 0)
    raw_red_runs = sum(1 for row in rows if (row.get("raw_red_count") or 0) > 0)
    raw_rtt_yellow_runs = sum(1 for row in rows if (row.get("raw_rtt_yellow_count") or 0) > 0)
    raw_rtt_red_runs = sum(1 for row in rows if (row.get("raw_rtt_red_count") or 0) > 0)
    contradiction_runs = sum(1 for row in rows if row.get("stored_band_contradictions"))
    corrected_yellow_counts = Counter(row.get("corrected_lag_yellow_spike_budget_ok") for row in rows)
    owner_bucket_counts = Counter(row.get("owner_bucket") for row in rows)
    payload = {
        "since": args.since,
        "runs_scanned": len(rows) + missing,
        "runs_with_metrics": len(rows),
        "runs_missing_metrics": missing,
        "raw_yellow_runs": raw_yellow_runs,
        "raw_red_runs": raw_red_runs,
        "raw_rtt_yellow_runs": raw_rtt_yellow_runs,
        "raw_rtt_red_runs": raw_rtt_red_runs,
        "stored_band_contradiction_runs": contradiction_runs,
        # JSON: avoid mixed-type dict keys (None/bool) which break sort_keys on py3.14.
        "corrected_lag_yellow_spike_budget_ok_counts": {
            "true": corrected_yellow_counts.get(True, 0),
            "false": corrected_yellow_counts.get(False, 0),
            "null": corrected_yellow_counts.get(None, 0),
        },
        "owner_bucket_counts": dict(owner_bucket_counts),
        "gate_counts": {gate: dict(counts) for gate, counts in gate_counts.items()},
        "runs": rows,
    }
    if getattr(args, "json", False):
        # Do not sort keys: some payloads include mixed-type dict keys elsewhere
        # (legacy bool/None counting maps). Raw content matters more than ordering.
        print(json.dumps(payload, indent=2, sort_keys=False))
        return

    if getattr(args, "per_tab", False):
        cols = [
            "run_id",
            "source_ref",
            "verdict",
            "tab_id",
            "raw_lag_ms_max",
            "raw_yellow_count",
            "raw_red_count",
            "raw_post_join_red_count",
            "instant_rtt_raw_ms_max",
            "instant_rtt_raw_yellow_count",
            "instant_rtt_raw_red_count",
            "yellowLatest",
            "redLatest",
            "stored_lag_band",
            "printed_lag_band",
            "lag_spike_count_ok",
            "lag_yellow_spike_budget_ok",
            "post_join_lag_spike_count_ok",
            "lag_floor_p95_ok",
            "lag_floor_p95_steady_ok",
            "lag_band_contradiction",
            "owner_bucket",
            "max_server_tick_elapsed_us",
            "max_server_phase",
            "max_snapshot_phase",
            "max_snapshot_auth_phase_us",
            "max_npc_physics_phase_us",
            "player_step_over_50000_count",
            "max_player_mp_step_once_us",
            "max_collect_mesh_us",
            "max_support_retry_collect_mesh_us",
            "max_sweep_total_us",
            "max_sweep_narrow_total_us",
            "max_collision_checks",
            "max_broadphase_rejects",
            "trace_max_wasm_rtt_us",
            "trace_max_net_transit_est_us",
            "trace_max_js_longtask_us",
            "trace_max_js_event_queue_us",
            "trace_attr_ready",
        ]
        print("\t".join(cols))
        for row in rows:
            gates = row.get("gates") or {}
            st = row.get("server_truth") or {}
            for tab in row.get("tab_rows") or []:
                ce = tab.get("client_browser_render_evidence") or {}
                out = {
                    "run_id": row.get("run_id"),
                    "source_ref": row.get("source_ref"),
                    "verdict": row.get("verdict"),
                    "tab_id": tab.get("tab_id"),
                    "raw_lag_ms_max": tab.get("raw_lag_ms_max"),
                    "raw_yellow_count": tab.get("raw_yellow_count"),
                    "raw_red_count": tab.get("raw_red_count"),
                    "raw_post_join_red_count": tab.get("raw_post_join_red_count"),
                    "instant_rtt_raw_ms_max": tab.get("instant_rtt_raw_ms_max"),
                    "instant_rtt_raw_yellow_count": tab.get("instant_rtt_raw_yellow_count"),
                    "instant_rtt_raw_red_count": tab.get("instant_rtt_raw_red_count"),
                    "yellowLatest": tab.get("yellowLatest"),
                    "redLatest": tab.get("redLatest"),
                    "stored_lag_band": tab.get("stored_lag_band"),
                    "printed_lag_band": tab.get("printed_lag_band"),
                    "lag_spike_count_ok": gates.get("lag_spike_count_ok"),
                    "lag_yellow_spike_budget_ok": gates.get("lag_yellow_spike_budget_ok"),
                    "post_join_lag_spike_count_ok": gates.get("post_join_lag_spike_count_ok"),
                    "lag_floor_p95_ok": gates.get("lag_floor_p95_ok"),
                    "lag_floor_p95_steady_ok": gates.get("lag_floor_p95_steady_ok"),
                    "lag_band_contradiction": tab.get("lag_band_contradiction"),
                    "owner_bucket": row.get("owner_bucket"),
                    "max_server_tick_elapsed_us": st.get("max_server_tick_elapsed_us"),
                    "max_server_phase": st.get("max_server_phase"),
                    "max_snapshot_phase": st.get("max_snapshot_phase"),
                    "max_snapshot_auth_phase_us": st.get("max_snapshot_auth_phase_us"),
                    "max_npc_physics_phase_us": st.get("max_npc_physics_phase_us"),
                    "player_step_over_50000_count": st.get("player_step_over_50000_count"),
                    "max_player_mp_step_once_us": st.get("max_player_mp_step_once_us"),
                    "max_collect_mesh_us": st.get("max_collect_mesh_us"),
                    "max_support_retry_collect_mesh_us": st.get("max_support_retry_collect_mesh_us"),
                    "max_sweep_total_us": st.get("max_sweep_total_us"),
                    "max_sweep_narrow_total_us": st.get("max_sweep_narrow_total_us"),
                    "max_collision_checks": st.get("max_collision_checks"),
                    "max_broadphase_rejects": st.get("max_broadphase_rejects"),
                    "trace_max_wasm_rtt_us": ce.get("trace_max_wasm_rtt_us"),
                    "trace_max_net_transit_est_us": ce.get("trace_max_net_transit_est_us"),
                    "trace_max_js_longtask_us": ce.get("trace_max_js_longtask_us"),
                    "trace_max_js_event_queue_us": ce.get("trace_max_js_event_queue_us"),
                    "trace_attr_ready": ce.get("trace_attr_ready"),
                }
                print(
                    "\t".join("" if out.get(c) is None else str(out.get(c)) for c in cols)
                )
        return

    print("LAG GATE AUDIT")
    print(f"  since:                  {args.since or '-'}")
    print(f"  runs_scanned:           {payload['runs_scanned']}")
    print(f"  runs_with_metrics:      {payload['runs_with_metrics']}")
    print(f"  runs_missing_metrics:   {payload['runs_missing_metrics']}")
    print(f"  raw_yellow_runs:        {raw_yellow_runs}")
    print(f"  raw_red_runs:           {raw_red_runs}")
    print(f"  raw_rtt_yellow_runs:    {raw_rtt_yellow_runs}")
    print(f"  raw_rtt_red_runs:       {raw_rtt_red_runs}")
    print(f"  stored_band_conflicts:  {contradiction_runs}")
    print(
        "  corrected_yellow_gate: "
        f"true={corrected_yellow_counts.get(True, 0)} "
        f"false={corrected_yellow_counts.get(False, 0)} "
        f"null={corrected_yellow_counts.get(None, 0)}"
    )
    for gate in sorted(gate_counts):
        counts = gate_counts[gate]
        print(f"  {gate}: true={counts.get('true', 0)} false={counts.get('false', 0)} null={counts.get('null', 0)} missing={counts.get('missing', 0)}")
    print("  owner_buckets:")
    for bucket, count in sorted(owner_bucket_counts.items()):
        print(f"    {bucket or '-'}: {count}")
    if getattr(args, "show_runs", False):
        print()
        for row in rows:
            if (
                not row.get("stored_band_contradictions")
                and not row.get("raw_yellow_count")
                and not row.get("raw_red_count")
                and not row.get("raw_rtt_yellow_count")
                and not row.get("raw_rtt_red_count")
            ):
                continue
            print(
                f"  {row.get('run_id')}: max={row.get('raw_max_lag_ms')} "
                f"yellow={row.get('raw_yellow_count')} red={row.get('raw_red_count')} "
                f"rawRttMax={row.get('raw_rtt_max_ms')} "
                f"rawRttYellow={row.get('raw_rtt_yellow_count')} "
                f"rawRttRed={row.get('raw_rtt_red_count')} "
                f"postJoinRed={row.get('raw_post_join_red_count')} "
                f"bucket={row.get('owner_bucket')} "
                f"conflicts={','.join(row.get('stored_band_contradictions') or []) or '-'}"
            )


# ---------------------------------------------------------------------------
# Subcommand: search
# ---------------------------------------------------------------------------


def cmd_search(args, root: Path):
    _start_card("search", mode="read-only",
                verdict=getattr(args, "verdict", None),
                gate=getattr(args, "gate", None))
    runs, _ = load_all_runs(root)
    tags = load_git_tags(root)

    if args.verdict:
        verdicts = {normalize_verdict({"verdict": v}) for v in args.verdict}
        runs = [r for r in runs if (r.get("verdict") or "blocked") in verdicts]

    if args.commit:
        prefix = args.commit.lower()
        runs = [
            r
            for r in runs
            if (r.get("git_head") or "").lower().startswith(prefix)
            or (r.get("git_head_full") or "").lower().startswith(prefix)
        ]

    if args.branch:
        runs = [r for r in runs if (r.get("branch") or "") == args.branch]

    label_filter = requested_run_label(args)
    if label_filter:
        runs = [r for r in runs if run_label_for(r) == label_filter]

    if args.gate_failed:
        gate = canonical_gate_name(args.gate_failed)
        runs = [r for r in runs if gate in (r.get("false_gates") or [])]

    if args.gate_null:
        gate = canonical_gate_name(args.gate_null)
        runs = [r for r in runs if gate in (r.get("null_gates") or [])]

    if args.gate_any:
        gate = canonical_gate_name(args.gate_any)
        runs = [
            r
            for r in runs
            if gate in (r.get("false_gates") or [])
            or gate in (r.get("null_gates") or [])
        ]

    if args.online_fail:
        runs = [r for r in runs if r.get("online_integrity_ok") is False]

    if args.has_regressions:

        def has_regs(r):
            gd = r.get("gate_deltas")
            return gd is not None and bool(gd.get("regressions_true_to_false"))

        runs = [r for r in runs if has_regs(r)]

    if args.date_from:
        try:
            cutoff = datetime.fromisoformat(args.date_from).replace(tzinfo=timezone.utc)
        except ValueError:
            sys.exit("error: invalid --date-from format (use YYYY-MM-DD)")

        def after_cutoff(r):
            ts = r.get("started_at_utc")
            if not ts:
                return False
            try:
                dt = datetime.fromisoformat(ts)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
                return dt >= cutoff
            except Exception:
                print(f"warning: could not parse timestamp '{ts}'", file=sys.stderr)
                return False

        runs = [r for r in runs if after_cutoff(r)]

    if args.date_to:
        try:
            cutoff = datetime.fromisoformat(args.date_to).replace(
                hour=23, minute=59, second=59, tzinfo=timezone.utc
            )
        except ValueError:
            sys.exit("error: invalid --date-to format (use YYYY-MM-DD)")

        def before_cutoff(r):
            ts = r.get("started_at_utc")
            if not ts:
                return False
            try:
                dt = datetime.fromisoformat(ts)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
                return dt <= cutoff
            except Exception:
                print(f"warning: could not parse timestamp '{ts}'", file=sys.stderr)
                return False

        runs = [r for r in runs if before_cutoff(r)]

    if args.no_tag:
        runs = [r for r in runs if tag_exists(r, tags) != "yes"]

    if args.has_observation:
        runs = [r for r in runs if r.get("user_observation")]

    if getattr(args, "has_intent", False):
        runs = [r for r in runs if r.get("run_intent")]

    if getattr(args, "intent_ref", None):
        needle = args.intent_ref.lower()

        def _intent_contains(r: dict, needle: str) -> bool:
            intent = r.get("run_intent") or {}
            for field in ("introduced_by", "fix_attempts", "baseline_runs"):
                for val in (intent.get(field) or []):
                    if needle in str(val).lower():
                        return True
            summary = str(intent.get("summary") or "").lower()
            return needle in summary

        runs = [r for r in runs if _intent_contains(r, needle)]

    if getattr(args, "failure_class", None):
        needle = args.failure_class.lower()
        runs = [r for r in runs if needle in (r.get("failure_class") or "").lower()]

    if getattr(args, "error_kind", None):
        needle = args.error_kind.lower()
        runs = [r for r in runs if needle in (r.get("error_kind") or "").lower()]

    if getattr(args, "failed_stage", None):
        needle = args.failed_stage.lower()
        runs = [r for r in runs if needle in (r.get("failed_stage") or "").lower()]

    if getattr(args, "run_mode", None):
        needle = args.run_mode.lower()
        runs = [r for r in runs if needle in (r.get("mode") or "").lower()]

    if getattr(args, "search_json", False):
        print(json.dumps(runs, indent=2, default=str))
        return

    rows = [run_to_list_row(r, tags) for r in runs]
    print_table(HEADERS_LIST, rows)
    print(f"\n{len(rows)} runs matched.")


# ---------------------------------------------------------------------------
# Subcommand: show
# ---------------------------------------------------------------------------


def cmd_show(args, root: Path):
    _start_card("show", run_id=args.run_id, mode="read-only")
    # --field KEY[.subkey] extraction (dot-notation, max 3 levels)
    if getattr(args, "field", None):
        run = load_run_by_id(root, args.run_id)
        field_aliases = {
            "gates.false": "false_gates",
            "gates.null": "null_gates",
            "gates.required": "required_gates",
            "gates.core": "core_gates",
        }
        requested_field = field_aliases.get(args.field, args.field)
        parts = requested_field.split(".", 2)
        if parts[0] == "mounted_witness":
            stored_mounted_witness = (
                run.get("mounted_witness") if isinstance(run.get("mounted_witness"), dict) else {}
            )
            derived_mounted_witness = derive_mounted_witness_for_run(run)
            if derived_mounted_witness.get("available") or not stored_mounted_witness:
                run = dict(run)
                # Field queries need the richest mounted_witness shape available.
                # Prefer recorder-derived data when possible; keep stored summary
                # data only when recorder fallback is unavailable.
                run["mounted_witness"] = derived_mounted_witness
        val = run
        for part in parts:
            if isinstance(val, dict):
                val = val.get(part)
            else:
                val = None
                break
        if val is None:
            print(f"(field '{args.field}' not found in summary.json)")
            if args.field.startswith("gates."):
                print(
                    "hint: per-run gate aliases are gates.false -> false_gates, "
                    "gates.null -> null_gates; try `analyze_runs.py gates --run-id "
                    f"{args.run_id}` for the run gate table"
                )
        elif isinstance(val, list):
            if getattr(args, "expand", False):
                print(json.dumps(val, indent=2))
            else:
                n = len(val)
                first = str(val[0])[:60] if val else ""
                last = str(val[-1])[:60] if n > 1 else ""
                print(
                    f"[{n} items: first={first}"
                    + (f", last={last}" if last else "")
                    + "]"
                )
        elif isinstance(val, dict):
            print(json.dumps(val, indent=2))
        else:
            print(val)
        return

    tags = load_git_tags(root)
    gaps = load_gap_registry(root)
    run = load_run_by_id(root, args.run_id)

    tag = run.get("git_tag") or "-"
    tag_status = tag_exists(run, tags)

    fl = load_fl_index(root)
    citations = fl.run_citations(fl_artifact_key(run))

    cli_style.header(f"RUN: {run.get('run_id', '?')}")
    verdict_raw = run.get('verdict') or '-'
    verdict_display = cli_style.status(verdict_raw.upper()) if verdict_raw != '-' else '-'
    print(f"  date:       {fmt_ts(run.get('started_at_utc'))}")
    print(f"  branch:     {run.get('branch') or '-'}")
    print(f"  commit:     {cli_style.style(run.get('git_head') or '-', 'dim')}")
    print(f"  source_ref: {cli_style.style(run.get('source_ref') or '-', 'dim')}")
    source_snapshot = run.get("source_snapshot") if isinstance(run.get("source_snapshot"), dict) else {}
    if source_snapshot.get("available"):
        runtime_match = source_snapshot.get("matches_runtime_source_ref")
        runtime_match_label = (
            "runtime-match"
            if runtime_match is True
            else "runtime-mismatch"
            if runtime_match is False
            else "runtime-unknown"
        )
        print(
            "  source snap:"
            f" {cli_style.style(source_snapshot.get('path') or '-', 'path')} "
            f"({source_snapshot.get('file_count') or '?'} files, {runtime_match_label}, inspection-only subset)"
        )
    print(f"  run_label:  {run_label_for(run) or '-'}")
    passive_note = passive_provenance_note(run)
    if passive_note:
        print(f"  label note: {cli_style.style(passive_note, 'warn')}")
    controller_note = controller_mode_off_warning(run)
    # AGENT_TRAP FL-2783 / FL-3023 — OVERREAD COUNTER: 4 TIMES, 0 PREVENTED.
    # If you are an agent reading this output and you just thought
    # "controller was off so movement didn't happen," STOP. You are
    # making the EXACT banned overread FOR THE FOURTH TIME.
    # controller_mode=off does NOT prove movement did not happen.
    # active_input_owner_kind=none does NOT prove the tabs never moved.
    # The human operator manually drives tabs in headed runs.
    # Browser focus-wipe (OnFocus(false)) destroys input BEFORE metrics capture.
    # That is FL-3023, NOT "no movement happened."
    # Read FAILURE_LOG.md FL-2783 AGENT_TRAP before touching ANY movement gate.
    # DO. NOT. SKIP. MOVEMENT. ANALYSIS. BECAUSE. OF. THIS. WARNING.
    if controller_note:
        print(f"  controller note: {cli_style.style(controller_note, 'warn')}")
    print(f"  verdict:    {verdict_display}")
    print(f"  online:     {fmt_bool(run.get('online_integrity_ok'))}")
    print(f"  tag:        {tag} ({tag_status})")
    print(f"  transcript: {transcript_status(run)}")
    print(f"  next:       {cli_style.style(next_action_text(run), 'warn')}")
    if citations:
        print(f"  fl_entries: {citations}")
    recorded_codestate = _recorded_codestate_for_run(run)
    runtime_slot_source_ref = recorded_codestate.get("runtime_slot_source_ref")
    runtime_slot_gameplay_ref = recorded_codestate.get("runtime_slot_gameplay_ref")
    runtime_slot_build_id = recorded_codestate.get("runtime_slot_build_id")
    runtime_manifest_source = recorded_codestate.get("runtime_manifest_source")
    if runtime_slot_source_ref or runtime_slot_gameplay_ref or runtime_slot_build_id:
        runtime_parts = [runtime_slot_source_ref or "-"]
        if runtime_slot_gameplay_ref:
            runtime_parts.append(f"gameplay={runtime_slot_gameplay_ref}")
        if runtime_slot_build_id:
            runtime_parts.append(f"build={runtime_slot_build_id}")
        if runtime_manifest_source:
            runtime_parts.append(f"via {runtime_manifest_source}")
        print(f"  runtime slot: {' '.join(runtime_parts)}")
    measurement_provenance = (
        recorded_codestate.get("measurement_provenance")
        if isinstance(recorded_codestate.get("measurement_provenance"), dict)
        else {}
    )
    if measurement_provenance:
        watchdog_hash = str(measurement_provenance.get("watchdog_sha256") or "-")
        analyzer_hash = str(measurement_provenance.get("analyzer_sha256") or "-")
        gate_hash = str(measurement_provenance.get("gate_config_sha256") or "-")
        print(
            "  watchdog:   "
            f"wd={watchdog_hash[:12]} "
            f"analyzer={analyzer_hash[:12]} "
            f"gates={gate_hash[:12]}"
        )
    run_intent = run.get("run_intent") or {}
    intent_summary = compact_text(run_intent.get("summary") or "", max_len=200)
    print(f"  intent:     {intent_summary or '-'}")
    introduced_by = run_intent.get("introduced_by") or []
    if introduced_by:
        print(f"  introduced: {', '.join(str(v) for v in introduced_by)}")
    fix_attempts = run_intent.get("fix_attempts") or []
    if fix_attempts:
        print(f"  fixes:      {', '.join(str(v) for v in fix_attempts)}")
    fix_commits = run_intent.get("fix_commits") or []
    if fix_commits:
        print(f"  fix commits: {', '.join(str(v) for v in fix_commits)}")
    fix_commit_snapshot = _fix_commit_snapshot_for_show(root, run)
    if fix_commit_snapshot:
        state = str(fix_commit_snapshot.get("state") or "-")
        counts = (
            f"{len(fix_commit_snapshot.get('files_changed') or [])} files, "
            f"+{fix_commit_snapshot.get('insertions') or 0}/-{fix_commit_snapshot.get('deletions') or 0}"
        )
        print(f"  fix state:  {state} ({counts})")
        if fix_commit_snapshot.get("patch_sha256"):
            print(f"  fix hash:   {fix_commit_snapshot.get('patch_sha256')}")
        changed_functions = (
            fix_commit_snapshot.get("changed_functions")
            if isinstance(fix_commit_snapshot.get("changed_functions"), dict)
            else {}
        )
        if changed_functions:
            rendered = []
            for path, names in changed_functions.items():
                rendered.append(f"{path}: {', '.join(str(name) for name in names[:3])}")
            print(f"  fix funcs:  {'; '.join(rendered[:4])}")
    fix_commit_warnings = run_intent.get("fix_commit_warnings") or []
    if fix_commit_warnings:
        rendered = []
        for warning in fix_commit_warnings:
            if isinstance(warning, dict):
                token = str(warning.get("input") or "?")
                reason = str(warning.get("reason") or "unresolved")
                rendered.append(f"{token} ({reason})")
            else:
                rendered.append(str(warning))
        print(f"  fix warn:   {', '.join(rendered)}")
    baseline_runs = run_intent.get("baseline_runs") or []
    if baseline_runs:
        print(f"  baselines:  {', '.join(str(v) for v in baseline_runs)}")
    required_fields = run_intent.get("required_fields") or []
    if required_fields:
        print(f"  required:   {', '.join(str(v) for v in required_fields)}")
    diff_spec = _resolve_intent_diff_spec(run)
    if diff_spec.get("corpora") or diff_spec.get("mode") or diff_spec.get("paths"):
        reconstructed_diff = None
        if not isinstance(diff_spec.get("diff_snapshot"), dict) or not diff_spec.get("diff_snapshot"):
            reconstructed_diff = _reconstruct_receipt_diff_payload(root, run)
        print(
            "  diff:       "
            f"{diff_corpus_label(diff_spec.get('corpora'))} "
            f"mode={diff_spec.get('mode') or 'between_runs'}"
        )
        if diff_spec.get("base_ref") or diff_spec.get("head_ref"):
            print(
                "  diff refs:  "
                f"{diff_spec.get('base_ref') or '-'} -> {diff_spec.get('head_ref') or '-'}"
            )
        if diff_spec.get("base_commit_resolved") or diff_spec.get("head_commit_resolved"):
            print(
                "  diff revs:  "
                f"{diff_spec.get('base_commit_resolved') or '-'} -> "
                f"{diff_spec.get('head_commit_resolved') or '-'}"
            )
        if diff_spec.get("resolution_strategy") or diff_spec.get("resolved_at"):
            print(
                "  diff proof: "
                f"{diff_spec.get('resolution_strategy') or '-'}"
                + (
                    f" @ {diff_spec.get('resolved_at')}"
                    if diff_spec.get("resolved_at")
                    else ""
                )
            )
        if diff_spec.get("resolution_warning"):
            print(f"  diff warn:  {diff_spec.get('resolution_warning')}")
        if diff_spec.get("resolution_error"):
            print(f"  diff error: {diff_spec.get('resolution_error')}")
        if diff_spec.get("paths"):
            print(f"  diff paths: {', '.join(str(v) for v in diff_spec['paths'])}")
        snapshot = diff_spec.get("diff_snapshot") if isinstance(diff_spec.get("diff_snapshot"), dict) else {}
        reconstructed_at_show = False
        if not snapshot and isinstance(reconstructed_diff, dict) and reconstructed_diff:
            snapshot = reconstructed_diff
            reconstructed_at_show = True
        if snapshot:
            state = str(snapshot.get("state") or "-")
            counts = (
                f"{len(snapshot.get('files_changed') or [])} files, "
                f"+{snapshot.get('insertions') or 0}/-{snapshot.get('deletions') or 0}"
            )
            print(f"  diff state: {state} ({counts})")
            if reconstructed_at_show:
                print("  diff live:  reconstructed at show-time from recorded git anchors")
            if snapshot.get("patch_sha256"):
                print(f"  diff hash:  {snapshot.get('patch_sha256')}")
            changed_functions = snapshot.get("changed_functions") if isinstance(snapshot.get("changed_functions"), dict) else {}
            if changed_functions:
                rendered = []
                for path, names in changed_functions.items():
                    rendered.append(f"{path}: {', '.join(str(name) for name in names[:3])}")
                print(f"  diff funcs: {'; '.join(rendered[:4])}")
            if reconstructed_at_show and snapshot.get("note"):
                print(f"  diff note:  {snapshot.get('note')}")
        aggregate = (
            diff_spec.get("aggregate_since_previous_comparable_run")
            if isinstance(diff_spec.get("aggregate_since_previous_comparable_run"), dict)
            else {}
        )
        if aggregate:
            previous_anchor = aggregate.get("previous_anchor") if isinstance(aggregate.get("previous_anchor"), dict) else {}
            current_anchor = aggregate.get("current_anchor") if isinstance(aggregate.get("current_anchor"), dict) else {}
            previous_label = (
                previous_anchor.get("run_id")
                or previous_anchor.get("head")
                or previous_anchor.get("commit_ref")
                or "-"
            )
            current_label = (
                current_anchor.get("run_id")
                or current_anchor.get("head")
                or run.get("run_id")
                or "-"
            )
            print(f"  agg prev:   {previous_label} -> {current_label}")
            if aggregate.get("basis"):
                print(f"  agg basis:  {aggregate.get('basis')}")
            state = str(aggregate.get("state") or "-")
            counts = (
                f"{len(aggregate.get('files_changed') or [])} files, "
                f"+{aggregate.get('insertions') or 0}/-{aggregate.get('deletions') or 0}"
            )
            print(f"  agg state:  {state} ({counts})")
            if aggregate.get("patch_sha256"):
                print(f"  agg hash:   {aggregate.get('patch_sha256')}")
            changed_functions = aggregate.get("changed_functions") if isinstance(aggregate.get("changed_functions"), dict) else {}
            if changed_functions:
                rendered = []
                for path, names in changed_functions.items():
                    rendered.append(f"{path}: {', '.join(str(name) for name in names[:3])}")
                print(f"  agg funcs:  {'; '.join(rendered[:4])}")
    diagnostic_scope = diagnostic_scope_for_run(run)
    scope_label = diagnostic_scope_label(diagnostic_scope)
    if scope_label:
        print(f"  code surface: {scope_label}")
        corpora = diagnostic_scope.get("declared_corpora") or []
        if corpora:
            print(f"  scope corpora: {diff_corpus_label(corpora)}")
        explicit_paths = diagnostic_scope.get("explicit_paths") or []
        if explicit_paths:
            print(f"  scope paths: {', '.join(str(v) for v in explicit_paths)}")
    print(f"  observation: {compact_text(run['user_observation'], max_len=200) if run.get('user_observation') else '-'}")
    # MOUNTED_WITNESS_RECEIPT_CONTRACT:
    # `show <run-id>` is the receipt/provenance front door for the stored
    # mounted_witness block. Older receipts may derive it from recorder data,
    # but new canonical receipts should preserve it in summary.json.
    mounted_witness = run.get("mounted_witness") if isinstance(run.get("mounted_witness"), dict) else {}
    mounted_gate_context = any(
        "mounted" in str(gate)
        for gate in (run.get("false_gates") or []) + (run.get("null_gates") or [])
    )
    if not mounted_witness and mounted_gate_context and not getattr(args, "compact", False):
        mounted_witness = derive_mounted_witness_for_run(run)
    if mounted_witness and (mounted_gate_context or mounted_witness.get("primary_subject")):
        print()
        print(cli_style.style("--- MOUNTED WITNESS ---", "subheader"))
        if not mounted_witness.get("available"):
            print(f"  unavailable: {mounted_witness.get('reason') or 'unknown'}")
        else:
            print(
                "  status: "
                f"witness_found={mounted_witness.get('witness_found')} "
                f"witness_subject={mounted_witness.get('witness_subject') or '-'} "
                f"primary_subject={mounted_witness.get('primary_subject') or '-'} "
                f"first_failing_stage={mounted_witness.get('first_failing_stage') or '-'}"
            )
            for subject_name in ("actor", "remote0"):
                subject = mounted_witness.get(subject_name) if isinstance(mounted_witness.get(subject_name), dict) else {}
                if not subject or not subject.get("observed"):
                    continue
                state_bits = [f"mount_state={subject.get('mount_state', 0)}"]
                if subject.get("snapshot_mount_state") is not None:
                    state_bits.append(f"snapshot_mount_state={subject.get('snapshot_mount_state')}")
                state_bits.extend(
                    [
                        f"auth_mount_definition_id={subject.get('auth_mount_definition_id', 0)}",
                                                f"compose_mode={subject.get('compose_mode_label') or '-'}",
                        f"compose_fail={subject.get('compose_failure_stage_label') or '-'}",
                    ]
                )
                if subject.get("post_interp_has_inst") is not None:
                    state_bits.append(f"post_interp_has_inst={subject.get('post_interp_has_inst')}")
                print(
                    f"  {subject_name}: "
                    f"seq={subject.get('seq') if subject.get('seq') is not None else '-'} "
                    f"rel_s={subject.get('rel_s') if subject.get('rel_s') is not None else '-'} "
                    f"tab={subject.get('tab') or '-'} "
                    + " ".join(state_bits)
                )
        if mounted_witness.get("provenance_mismatch"):
            print(f"  hint: {_MOUNTED_PROVENANCE_HINT}")
            print("  route: FL-2519 for provenance mismatch; `callgraph --fl FL-2500` for compose-path source routing")
    print()

    chronology_lines = _show_chronology_context(root, run)
    if chronology_lines:
        print(cli_style.style("--- CHRONOLOGY CONTEXT ---", "subheader"))
        for line in chronology_lines:
            print(f"  {line}")
        print()

    blocker = run.get("prelaunch_blocker") or {}
    if isinstance(blocker, dict) and blocker:
        print(cli_style.style("--- PRELAUNCH BLOCKER ---", "subheader"))
        print(f"  stage:      {blocker.get('stage') or '-'}")
        print(f"  reason:     {blocker.get('reason') or blocker.get('kind') or '-'}")
        if blocker.get("owner"):
            print(f"  owner:      {blocker.get('owner')}")
        if blocker.get("first_fatal"):
            print(f"  first fatal: {blocker.get('first_fatal')}")
        if blocker.get("next_owner"):
            print(f"  next owner: {blocker.get('next_owner')}")
        blocker_scope = blocker.get("candidate_scope") if isinstance(blocker.get("candidate_scope"), dict) else None
        blocker_scope_label = diagnostic_scope_label(blocker_scope)
        if blocker_scope_label:
            print(f"  code surface: {blocker_scope_label}")
            scope_corpora = blocker_scope.get("declared_corpora") or []
            if scope_corpora:
                print(f"  scope corpora: {diff_corpus_label(scope_corpora)}")
            scope_paths = blocker_scope.get("explicit_paths") or []
            if scope_paths:
                print(f"  scope paths: {', '.join(str(v) for v in scope_paths)}")
        if blocker.get("returncode") is not None:
            print(f"  returncode: {blocker.get('returncode')}")
        outside_scope = blocker.get("outside_scope_paths") or []
        if outside_scope:
            print("  dirty out-of-scope:")
            for path in outside_scope[:12]:
                print(f"    - {path}")
        violations = blocker.get("violations") or []
        if violations:
            print("  violations:")
            for violation in violations[:12]:
                print(f"    - {violation}")
        local_errors = blocker.get("local_web_errors") or []
        if local_errors:
            print("  local-web errors:")
            for error in local_errors[:12]:
                print(f"    - {error}")
        local_mismatches = blocker.get("local_web_mismatches") or []
        if local_mismatches:
            print("  local-web mismatches:")
            for mismatch in local_mismatches[:8]:
                print(f"    - {json.dumps(mismatch, sort_keys=True)}")
        lines = blocker.get("interesting_lines") or []
        if lines:
            print("  retained output:")
            for line in lines[:12]:
                print(f"    - {line}")
        print()

    _compact = getattr(args, "compact", False)

    # Steps
    steps = run.get("steps") or []
    if steps and not _compact:
        print(cli_style.style("--- STEPS ---", "subheader"))
        for s in steps:
            ok_str = cli_style.status("OK") if s.get("ok") else cli_style.status("FAIL")
            rc = s.get("returncode")
            rc_str = str(rc) if rc is not None else "-"
            note = s.get("note") or ""
            note_str = f"  # {note}" if note else ""
            print(f"  {s['name']:<35} {ok_str:<6} rc={rc_str}{note_str}")
        print()

    # Gates
    # FL-4203: Enrich with local-light gates if local_light_metrics.json exists
    if not run.get("has_local_light_gates"):
        run = _enrich_run_with_local_light_gates(run, root)

    req_str = fmt_gates(
        run.get("runtime_required_passed"), run.get("runtime_required_total")
    )
    core_str = fmt_gates(run.get("runtime_core_passed"), run.get("runtime_core_total"))
    print(cli_style.style("--- GATES ---", "subheader"))
    print(f"  Required: {cli_style.style(req_str, 'count')}   Core: {cli_style.style(core_str, 'count')}")
    false_gates, diagnostic_false, deprecated_false = split_gate_groups(run.get("false_gates"))
    null_gates = run.get("null_gates")
    if false_gates is not None:
        print(f"  {cli_style.style('False', 'fail')} ({cli_style.style(len(false_gates), 'count')}):")
        for g in false_gates:
            print(f"    {cli_style.fail_item(g)}{fl_gate_ann(fl, g)}{gap_ann(gaps, g)}")
    if diagnostic_false:
        print(f"  Diagnostic false ({len(diagnostic_false)}):")
        for g in diagnostic_false:
            print(f"    {g}{fl_gate_ann(fl, g)}{gap_ann(gaps, g)}")
    if deprecated_false:
        print(f"  Deprecated false ({len(deprecated_false)}):")
        for g in deprecated_false:
            print(f"    {g}{fl_gate_ann(fl, g)}")
    if null_gates is not None:
        print(f"  Null ({len(null_gates)}):")
        for g in null_gates:
            print(f"    {g}{fl_gate_ann(fl, g)}{gap_ann(gaps, g)}")
    print()

    art = _find_artifact_path(run)
    pickup_chain = run.get("post_run_pickup_chain")
    if not pickup_chain:
        if art is not None:
            pickup_chain = derive_pickup_chain_for_artifact(art)
    if isinstance(pickup_chain, dict) and not _compact:
        gates = pickup_chain.get("gates") or {}
        print(cli_style.style("--- POST-RUN PICKUP CHAIN ---", "subheader"))
        print(f"  reason:    {pickup_chain.get('reason') or '-'}")
        print(f"  window_s:  {pickup_chain.get('window_s')}")
        print(f"  tolerance: {pickup_chain.get('event_tolerance_s')}")
        print(f"  pass_item: {pickup_chain.get('passing_item_id') or '-'}")
        print(f"  offender:  {pickup_chain.get('offending_item_id') or '-'}")
        gate_bits = [
            f"map={fmt_bool(gates.get('pickup_map_item_authorship_observed'))}",
            f"server={fmt_bool(gates.get('pickup_server_world_item_observed'))}",
            f"visible={fmt_bool(gates.get('pickup_client_rendered_world_item_observed'))}",
            f"intent={fmt_bool(gates.get('pickup_intent_observed'))}",
            f"transition={fmt_bool(gates.get('pickup_ownership_transition_observed'))}",
            f"chain={fmt_bool(gates.get('pickup_visible_legitimate_chain_observed'))}",
        ]
        print(f"  gates:     {' '.join(gate_bits)}")
        chains = pickup_chain.get("chains") or []
        for chain in chains[:5]:
            print(
                "  item {item}: map={map_at} server={server_at} visible={visible_at} "
                "intent={intent_at} transition={transition_at} pass={passed}".format(
                    item=chain.get("item_id"),
                    map_at=chain.get("map_authored_at"),
                    server_at=chain.get("server_world_at"),
                    visible_at=chain.get("visible_at"),
                    intent_at=chain.get("intent_at"),
                    transition_at=chain.get("transition_at"),
                    passed=chain.get("passes_same_item_window"),
                )
            )
        if len(chains) > 5:
            print(f"  ... {len(chains) - 5} more item chains")
        print()

    # Gate deltas
    gd = run.get("gate_deltas")
    if gd is not None:
        regs = [g for g in (gd.get("regressions_true_to_false") or []) if g not in DIAGNOSTIC_ONLY_GATES]
        diag_regs = [g for g in (gd.get("regressions_true_to_false") or []) if g in DIAGNOSTIC_ONLY_GATES]
        became_null = gd.get("became_unresolved_true_to_null") or []
        recs = gd.get("recoveries_to_true") or []
        print(cli_style.style("--- GATE DELTAS (vs previous run) ---", "subheader"))
        print(f"  Regressions ({len(regs)}):")
        for g in regs:
            print(f"    {g}")
        if diag_regs:
            print(f"  Diagnostic regressions ({len(diag_regs)}):")
            for g in diag_regs:
                print(f"    {g}")
        if became_null:
            print(f"  Became null ({len(became_null)}):")
            for g in became_null:
                print(f"    {g}")
        print(f"  Recoveries ({len(recs)}):")
        for g in recs:
            print(f"    {g}")
        print()

    # Operator comparison context. The canonical runner embeds this in its
    # final summary; show it here too so analyze_runs.py remains the single
    # post-run surface for pasteable previous/peak/similar comparisons.
    if not _compact:
        try:
            from watchdog_operator_help import build_operator_help, format_operator_help

            help_summary = dict(run)
            summary_path = runs_dir(root) / str(run.get("run_id") or "") / "summary.json"
            if summary_path.exists():
                help_summary.setdefault("summary_path", str(summary_path))
            help_data = build_operator_help(help_summary)
            if help_data.get("comparisons"):
                use_color = cli_style._color_enabled()
                rendered = format_operator_help(help_data, color=use_color)
                capture = False
                comparison_lines: list[str] = []
                _comparison_headers = {"  Run comparisons:", "  Similar Run Failing Gates:"}
                for line in rendered:
                    if line in _comparison_headers or (line.endswith(":") and "comparisons" in line.lower()):
                        capture = True
                    if capture:
                        comparison_lines.append(line[2:] if line.startswith("  ") else line)
                if comparison_lines:
                    print(cli_style.style("--- OPERATOR COMPARISONS ---", "subheader"))
                    for line in comparison_lines:
                        print(line)
                    print()
        except (ImportError, json.JSONDecodeError, KeyError, OSError, ValueError) as exc:
            # FL-4756: ImportError guard — watchdog_operator_help was once
            # deleted in a bulk sweep (ef4c90ec0) and every `show` run
            # traceback-exited here. Comparisons degrade to a note instead.
            print(cli_style.style("--- OPERATOR COMPARISONS ---", "subheader"))
            print(f"  unavailable: {exc}")
            print()

    # Causal digest
    cd = run.get("causal_digest")
    if cd:
        highlights = cd.get("highlights") or []
        if highlights:
            print(cli_style.style("--- CAUSAL DIGEST ---", "subheader"))
            for h in highlights:
                print(f"  {h}")
            print()

    # Warnings
    warnings = list(run.get("warnings") or [])
    vps_warn = run.get("vps_journal_warning")
    if vps_warn and vps_warn not in warnings:
        warnings.append(vps_warn)
    if warnings:
        print(cli_style.style("--- WARNINGS ---", "subheader"))
        for w in warnings:
            print(f"  {w}")
        print()

    camera_qe_surface = _camera_qe_surface_for_show(run) if not _compact else None
    if camera_qe_surface:
        print(cli_style.style("--- CAMERA Q/E JITTER ---", "subheader"))
        print(f"  camera_qe_jitter_ok: {camera_qe_surface.get('gate')}")
        print(f"  active:              {camera_qe_surface.get('active')}")
        print(
            f"  active_tabs:         {', '.join(str(v) for v in (camera_qe_surface.get('active_tabs') or [])) or '-'}"
        )
        inactive_tabs = [str(v) for v in (camera_qe_surface.get("inactive_tabs") or []) if str(v).strip()]
        if inactive_tabs:
            print(f"  inactive_tabs:       {', '.join(inactive_tabs)}")
        if "coverage_complete" in camera_qe_surface:
            print(f"  coverage_complete:   {camera_qe_surface.get('coverage_complete')}")
        if camera_qe_surface.get("failure_reason"):
            print(f"  failure_reason:      {camera_qe_surface.get('failure_reason')}")
        if "valid_for_local_camera" in camera_qe_surface:
            print(f"  valid_for_local:     {camera_qe_surface.get('valid_for_local_camera')}")
        for tab_name in ("tab1", "tab2"):
            tab = camera_qe_surface.get(tab_name) if isinstance(camera_qe_surface.get(tab_name), dict) else {}
            if not tab:
                continue
            if not tab.get("active"):
                print(f"  {tab_name}: inactive ({tab.get('inactive_reason') or 'unknown'})")
                continue
            max_correction = tab.get("max_correction_delta_deg")
            max_correction_str = f"{max_correction:.2f}" if isinstance(max_correction, (int, float)) else "-"
            print(
                f"  {tab_name}: gate={tab.get('gate')} windows={tab.get('rotate_only_window_count', '-')} "
                f"snapshot_edges={tab.get('snapshot_edge_count', '-')} max_correction_deg={max_correction_str} "
                f"opposite_direction={tab.get('opposite_direction_count', '-')} "
                f"oversized={tab.get('oversized_correction_count', '-')}"
            )
            worst_event = tab.get("worst_event") if isinstance(tab.get("worst_event"), dict) else {}
            if worst_event:
                rel_s = worst_event.get("rel_s")
                rel_s_str = f"{rel_s:.3f}" if isinstance(rel_s, (int, float)) else "-"
                correction = worst_event.get("correction_delta_deg")
                correction_str = f"{correction:.2f}" if isinstance(correction, (int, float)) else "-"
                sample_seq = worst_event.get("sample_seq")
                lag_ms = worst_event.get("lag_ms")
                print(
                    f"    worst_event: rel_s={rel_s_str} seq={sample_seq if sample_seq is not None else '-'} "
                    f"correction_deg={correction_str} lag_ms={lag_ms if lag_ms is not None else '-'}"
                )
        print()

    input_stimulus = derive_input_stimulus_summary(run, root)
    if input_stimulus:
        print(cli_style.style("--- INPUT STIMULUS ---", "subheader"))
        shown_tabs: set[str] = set()
        for tab_name in ("tab1", "tab2"):
            line = input_stimulus.get(tab_name)
            if line is None:
                continue
            shown_tabs.add(tab_name)
            print(f"  {tab_name}: {line}")
        for tab_name in sorted(input_stimulus):
            if tab_name in shown_tabs:
                continue
            print(f"  {tab_name}: {input_stimulus[tab_name]}")
        print()

    recorder_surface = {} if _compact else (run.get("recorder_surface") or {})
    if not recorder_surface and not _compact:
        # Archive-ingested runs do not carry recorder_surface in summary.json.
        # Fall back to metrics.json/diagnostics/recorder_surface so show always
        # renders the lag section.  Fail noisily so a broken path is visible.
        try:
            _m, _ = _load_metrics_for_run(run)
            recorder_surface = ((_m.get("diagnostics") or {}).get("recorder_surface") or {})
        except SystemExit:
            print(cli_style.style("--- RECORDER SURFACE ---", "subheader"))
            print("  lag surface unavailable (metrics.json not found in artifact_path, archive_path, or launcher_output_dir)")
            print()
    post_join = derive_post_join_lag_metrics(run, root)
    tick_overrun = derive_authoritative_tick_overrun_metrics(run, root)
    if recorder_surface:
        print(cli_style.style("--- RECORDER SURFACE ---", "subheader"))
        for tab_name in ("tab1", "tab2"):
            tab = recorder_surface.get(tab_name) or {}
            if not tab:
                continue
            def _ms(v: object) -> str:
                return f"{v:.0f}ms" if isinstance(v, (int, float)) and v >= 0 else "-"
            spikes = tab.get("lag_spike_count")
            band = _honest_lag_band(tab) or tab.get("lag_band") or "-"
            print(
                f"  {tab_name}: lag=last={_ms(tab.get('lag_ms_last'))} min={_ms(tab.get('lag_ms_min'))}"
                f" max={_ms(tab.get('lag_ms_max'))} spikes={spikes if spikes is not None else '-'}"
                f" band={band} "
                f"local(vis={tab.get('visible_local_last') if tab.get('visible_local_last') is not None else '-'} "
                f"body={tab.get('body_visible_local_last') if tab.get('body_visible_local_last') is not None else '-'}) "
                f"remote(vis={tab.get('visible_remote_last') if tab.get('visible_remote_last') is not None else '-'} "
                f"body={tab.get('body_visible_remote_last') if tab.get('body_visible_remote_last') is not None else '-'}) "
                f"npc={tab.get('tracked_npc0_inst_visible_last') if tab.get('tracked_npc0_inst_visible_last') is not None else '-'} "
                f"npc_corpse={tab.get('tracked_npc0_corpse_visible_last') if tab.get('tracked_npc0_corpse_visible_last') is not None else '-'} "
                f"npc_hold={tab.get('tracked_npc0_corpse_hold_age_ticks_last') if tab.get('tracked_npc0_corpse_hold_age_ticks_last') is not None else '-'} "
                f"npc_diverge={tab.get('tracked_npc0_render_diverged_from_snapshot_last') if tab.get('tracked_npc0_render_diverged_from_snapshot_last') is not None else '-'} "
                f"invisible(local={bool(tab.get('local_invisible_last'))} remote={bool(tab.get('remote_invisible_last'))}) "
                f"sprite(queue={tab.get('remote0_queue_world_count_last') if tab.get('remote0_queue_world_count_last') is not None else '-'}"
                f"/{tab.get('remote0_queue_refl_count_last') if tab.get('remote0_queue_refl_count_last') is not None else '-'} "
                f"blit={tab.get('remote0_blit_world_count_last') if tab.get('remote0_blit_world_count_last') is not None else '-'}"
                f"/{tab.get('remote0_blit_refl_count_last') if tab.get('remote0_blit_refl_count_last') is not None else '-'} "
                f"retry={tab.get('remote0_blit_retry_count_last') if tab.get('remote0_blit_retry_count_last') is not None else '-'}"
                f"/{tab.get('remote0_blit_retry_drawn_last') if tab.get('remote0_blit_retry_drawn_last') is not None else '-'})"
            )
            pj = post_join.get(tab_name) or {}
            if pj:
                skipped = tab.get('post_join_lag_skipped_sample_count', '-')
                skipped_reasons = tab.get('post_join_lag_skipped_reason_counts')
                skipped_reasons_text = skipped_reasons if skipped_reasons else '-'
                print(
                    f"    post_join_lag_max_ms={_ms(pj.get('post_join_lag_max_ms'))} "
                    f"post_join_lag_p95_ms={_ms(pj.get('post_join_lag_p95_ms'))} "
                    f"samples={pj.get('post_join_lag_sample_count', '-')} "
                    f"skipped={skipped} "
                    f"skip_reasons={skipped_reasons_text} "
                    f"wait={pj.get('post_join_lag_wait_sample_count', '-')} "
                    f"stale={pj.get('post_join_lag_stale_sample_count', '-')} "
                    f"wait_age_max={_ms(pj.get('post_join_lag_wait_age_max_ms'))} "
                    f"rsp_age_max={_ms(pj.get('post_join_lag_response_age_max_ms'))} "
                    f"red={tab.get('post_join_lag_spike_count', '-')} "
                    f"gate_ready={tab.get('post_join_lag_gate_ready', '-')}"
                )
            print(
                f"    lag_diag: req={tab.get('lag_request_count_last', '-')} "
                f"req_fail={tab.get('lag_request_send_fail_count_last', '-')} "
                f"rsp={tab.get('lag_response_count_last', '-')} "
                f"timeout={tab.get('lag_wait_timeout_count_last', '-')} "
                f"wait={tab.get('lag_wait_last', '-')} "
                f"wait_age={_ms(tab.get('lag_wait_age_ms_last'))} "
                f"rsp_age={_ms(tab.get('lag_response_age_ms_last'))} "
                f"stale={tab.get('lag_measurement_stale_last', '-')} "
                f"auth_queue_drop={tab.get('auth_self_lag_echo_queue_drop_count_last', '-')}"
            )
            print(
                f"    lag_auth: send_ok={tab.get('auth_self_lag_echo_send_success_count_last', '-')} "
                f"send_errno={tab.get('auth_self_lag_echo_send_errno_count_last', '-')} "
                f"last_errno={tab.get('auth_self_lag_echo_last_errno_last', '-')}"
                )
            render_diag = _format_render_slice_summary(tab)
            if render_diag:
                print(render_diag)
            # T71: Mobile diagnostic fields — only shown on mobile emulation runs
            phone_diag_show = (run.get("diagnostics") or {}).get("phone_emulation")
            if phone_diag_show:
                dpr = tab.get("device_pixel_ratio")
                render_ms = tab.get("render_ms_last")
                print(
                    f"    mobile: DPR={dpr if dpr is not None else '-'}"
                    f" renderMs={_ms(render_ms)}"
                    f" raf={tab.get('raf_count_last', '-')}"
                    f" nullMem={tab.get('null_mem_count_last', '-')}"
                    f" crashes={tab.get('crashes_last', '-')}"
                    f" COI={tab.get('cross_origin_isolated', '-')}"
                )
        print()

    if tick_overrun and not _compact:
        print(cli_style.style("--- SERVER TICK OVERRUNS ---", "subheader"))
        count = tick_overrun.get("tick_overrun_count")
        max_us = tick_overrun.get("tick_max_elapsed_us")
        over_budget = isinstance(max_us, int) and max_us > TICK_OVERRUN_BUDGET_US
        print(
            f"  tick_overrun_count={count if count is not None else '-'} "
            f"tick_max_elapsed_us={max_us if max_us is not None else '-'} "
            f"budget_us={TICK_OVERRUN_BUDGET_US} "
            f"over_budget={over_budget}"
        )
        server_log_path = art / "server.log" if art is not None else None
        for line in _format_tick_overrun_owner(tick_overrun, server_log_path=server_log_path):
            print(line)
        print()

    if not _compact:
        transcript = render_transcript(run, root)
        jt = run.get("journal_transcript") or {}
        if transcript:
            print(cli_style.style("--- JOURNAL TRANSCRIPT ---", "subheader"))
            print(transcript)
            print()
            classifier = jt.get("classifier") or {}
            if classifier:
                print(cli_style.style("--- TRANSCRIPT CLASSIFIER ---", "subheader"))
                print(
                    "  "
                    f"1006={classifier.get('ws_close_1006_seen')} "
                    f"first_snapshot={classifier.get('first_valid_snapshot_seen')} "
                    f"pose_before_auth={classifier.get('pose_published_before_auth_valid')} "
                    f"spawn_zero_reconnect={classifier.get('spawn_at_zero_after_reconnect')} "
                    f"remote_local_divergence={classifier.get('remote_local_snapshot_divergence_seen')} "
                    f"join_before_snapshot={classifier.get('join_before_snapshot_seen')} "
                    f"stale_origin={classifier.get('stale_origin_rejection_seen')}"
                )
                print()
        elif transcript_exists(run):
            print(cli_style.style("--- JOURNAL TRANSCRIPT ---", "subheader"))
            print("  (transcript paths recorded but files are missing or unreadable)")
            print()

    # Error detail (for blocked/failed runs)
    error = run.get("error")
    if error:
        print(cli_style.style("--- ERROR ---", "subheader"))
        print(f"  kind: {run.get('error_kind') or '-'}")
        print(f"  {error}")
        print()

    if getattr(args, "update_canon_spec", False):
        updated = _append_run_to_canon_spec(run, root)
        if updated:
            print(f"[canon-spec] updated: {updated}")

    if getattr(args, "auto_inline_fls", False):
        _auto_inline_fls_for_run(run, root)


def _check_canon_spec_reorg_lock(root: Path) -> None:
    """Fail closed if the canon-spec reorg lock is active.

    During Phase 0 of the canon-spec reorg, a lock file prevents any automated
    writes to the canonical spec. Commands that need to bypass this (e.g. for
    FAILURE_LOG-only work) must use --no-canon-spec-sync.
    """
    lock_path = root / "docs" / "plans" / ".canon-spec-reorg.lock"
    if lock_path.exists():
        print(
            "ERROR: canon-spec reorg lock is active "
            f"({lock_path}).\n"
            "Automated writes to the canonical spec are blocked during reorg.\n"
            "Use --no-canon-spec-sync to skip canon-spec writes, or remove the\n"
            "lock file after the reorg is complete.",
            file=sys.stderr,
        )
        raise SystemExit(1)


def _append_run_to_canon_spec(run: dict, root: Path) -> str | None:
    """Back-compat helper: write the generated watchdog mirror outside the canon.

    The legacy flag name `--update-canon-spec` is kept for compatibility, but the
    generated run summary now lives in a dedicated maintainer report so the canon
    spec stays durable and hand-edited.
    """
    report_path = root / "artifacts" / "maintainer" / "watchdog_mirrors.md"
    report_path.parent.mkdir(parents=True, exist_ok=True)

    run_id = run.get("run_id") or ""
    if not run_id:
        return None

    # Build the block
    label = run_label_for(run) or "-"
    verdict = run.get("verdict") or "-"
    date_str = fmt_ts(run.get("started_at_utc"))
    branch = run.get("branch") or "-"
    commit = (run.get("git_head") or "-")[:12]
    req_str = fmt_gates(run.get("runtime_required_passed"), run.get("runtime_required_total"))
    core_str = fmt_gates(run.get("runtime_core_passed"), run.get("runtime_core_total"))
    false_gates, diagnostic_false, deprecated_false = split_gate_groups(run.get("false_gates") or [])
    null_gates = run.get("null_gates") or []
    causal = (run.get("causal_digest") or {}).get("highlights") or []
    next_act = next_action_text(run)
    ownership_blocker = run.get("ownership_blocker_detected")
    ownership_message = run.get("ownership_blocker_message") or run.get("ownership_blocker_marker")

    gd = run.get("gate_deltas") or {}
    regressions = [g for g in (gd.get("regressions_true_to_false") or []) if g not in DIAGNOSTIC_ONLY_GATES]
    diagnostic_regressions = [g for g in (gd.get("regressions_true_to_false") or []) if g in DIAGNOSTIC_ONLY_GATES]

    false_str = ", ".join(false_gates[:6]) + ("…" if len(false_gates) > 6 else "")
    diagnostic_false_str = ", ".join(diagnostic_false[:6]) + ("…" if len(diagnostic_false) > 6 else "")
    deprecated_false_str = ", ".join(deprecated_false[:6]) + ("…" if len(deprecated_false) > 6 else "")
    null_str = ", ".join(null_gates[:4]) + ("…" if len(null_gates) > 4 else "")
    reg_str = ", ".join(regressions[:4]) + ("…" if len(regressions) > 4 else "")
    diagnostic_reg_str = ", ".join(diagnostic_regressions[:4]) + ("…" if len(diagnostic_regressions) > 4 else "")
    causal_str = " / ".join(str(h) for h in causal[:3])

    block_lines = [
        f"### {run_id} — {label} — {verdict} — {date_str}\n",
        f"- Branch: `{branch}`  Commit: `{commit}`\n",
        f"- Required: {req_str}  Core: {core_str}\n",
    ]
    if false_gates:
        block_lines.append(f"- False ({len(false_gates)}): {false_str}\n")
    if diagnostic_false:
        block_lines.append(f"- Diagnostic false ({len(diagnostic_false)}): {diagnostic_false_str}\n")
    if deprecated_false:
        block_lines.append(f"- Deprecated false ({len(deprecated_false)}): {deprecated_false_str}\n")
    if null_gates:
        block_lines.append(f"- Null ({len(null_gates)}): {null_str}\n")
    if regressions:
        block_lines.append(f"- Regressions ({len(regressions)}): {reg_str}\n")
    if diagnostic_regressions:
        block_lines.append(f"- Diagnostic regressions ({len(diagnostic_regressions)}): {diagnostic_reg_str}\n")
    if causal_str:
        block_lines.append(f"- Causal: {causal_str}\n")
    if ownership_blocker:
        blocker_str = str(ownership_message or "OWNERSHIP BLOCKER DETECTED")
        block_lines.append(f"- Ownership: {blocker_str}\n")
    if next_act and next_act != "-":
        block_lines.append(f"- Next: {next_act}\n")

    if report_path.exists():
        with open(report_path, encoding="utf-8") as f:
            content = f.read()
    else:
        content = (
            "# Watchdog Mirrors\n\n"
            "Generated watchdog run and fix-attempt summaries live here so they do not "
            "regrow inside the canon spec.\n\n"
        )

    SECTION_HEADER = "## Recent Watchdog Runs\n"
    SECTION_COMMENT = "<!-- auto-updated by analyze_runs.py show --update-canon-spec -->\n"
    FIX_ATTEMPT_HEADER = "### Failure-Log Fix-Attempt Mirror (auto-synced)\n"

    # Check if section exists
    section_pos = content.find(SECTION_HEADER)
    if section_pos == -1:
        tail = f"\n---\n\n{SECTION_HEADER}{SECTION_COMMENT}"
        if not tail.endswith("\n"):
            tail += "\n"
        content = content.rstrip() + "\n" + tail
        section_pos = content.find(SECTION_HEADER)

    insert_after = content.find(SECTION_COMMENT, section_pos)
    if insert_after == -1:
        insert_pos = section_pos + len(SECTION_HEADER)
    else:
        insert_pos = insert_after + len(SECTION_COMMENT)
        while insert_pos < len(content) and content[insert_pos] == "\n":
            insert_pos += 1

    fix_attempt_pos = content.find(FIX_ATTEMPT_HEADER, insert_pos)
    if fix_attempt_pos == -1:
        section_end = _find_next_md_header(content, section_pos + len(SECTION_HEADER))
        suffix = ""
    else:
        section_end = fix_attempt_pos
        suffix = "\n" if fix_attempt_pos > 0 and content[fix_attempt_pos - 1] != "\n" else ""

    new_block = "".join(block_lines) + "\n"
    replacement = new_block + suffix
    content = content[:insert_pos] + replacement + content[section_end:]

    tmp_fd, tmp_path = tempfile.mkstemp(
        dir=report_path.parent,
        prefix=".watchdog_mirror_tmp_",
        suffix=".md",
    )
    try:
        with os.fdopen(tmp_fd, "w", encoding="utf-8") as f:
            f.write(content)
        os.replace(tmp_path, report_path)
    except Exception:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        return None

    return str(report_path)


def _find_next_md_header(text: str, start: int) -> int:
    """Return index of the next ## or ### header line after start, or len(text)."""
    pos = start
    while pos < len(text):
        nl = text.find("\n", pos)
        if nl == -1:
            break
        line_start = nl + 1
        if line_start < len(text) and text[line_start:line_start + 2] == "##":
            return line_start
        pos = nl + 1
    return len(text)


def _auto_inline_fls_for_run(run: dict, root: Path):
    """Print updater dry-runs for all FL entries cited in this run."""
    fl = load_fl_index(root)
    key = fl_artifact_key(run)
    cited = fl.by_run.get(key, [])
    if not cited:
        print("[auto-inline] no FL entries cite this run")
        return
    seen: set[str] = set()
    for entry in cited:
        fl_id = entry.get("fl", "")
        if fl_id and fl_id not in seen:
            seen.add(fl_id)
            plan = _inline_comment_plan_for_fl(root, fl_id, family_scope=False)
            _print_inline_comment_plan(plan, write=False)
            print(
                "Dry run only. Re-run fl update-inline-comments "
                f"{fl_id} --write to edit source comments."
            )


def _auto_inline_fl_comments(root: Path, fl_id: str, target_only: bool = False) -> dict:
    """Back-compat helper used by tests and older local tooling.

    Default behavior writes comments across the full FL family scope.
    `target_only=True` limits file refs to the target FL while keeping the
    computed family IDs in the inline comment.
    """
    entries_by_id = {e["fl"]: e for e in load_fl_entries(root)}
    plan = _inline_comment_plan_for_fl(
        root,
        fl_id,
        family_scope=not target_only,
    )
    fl_id = fl_id.upper()
    for edit in plan.get("edits", []):
        legacy_ids = [fid for fid in edit.get("new_ids", []) if fid != fl_id]
        if fl_id in edit.get("new_ids", []):
            legacy_ids.append(fl_id)
        if legacy_ids and legacy_ids != edit.get("new_ids", []):
            _, _, suffix = _parse_fl_family_comment(edit["old_line"])
            new_comment = _format_fl_family_comment(
                legacy_ids,
                suffix,
                edit.get("accounted_ids") or [],
                entries_by_id,
            )
            prefix = edit["old_line"]
            comment_match, _, _ = _parse_fl_family_comment(prefix)
            if comment_match:
                prefix = prefix[: comment_match.start()].rstrip()
            edit["new_ids"] = legacy_ids
            edit["new_line"] = f"{prefix} {new_comment}" if prefix else new_comment
    _write_inline_comment_plan(root, plan)
    return plan


