def _what_failed_payload(run: dict, run_id: str) -> dict:
    false_gates, diagnostic_false, deprecated_false = split_gate_groups(run.get("false_gates") or [])
    false_gates = sorted(false_gates or [])
    diagnostic_false = sorted(diagnostic_false)
    deprecated_false = sorted(deprecated_false)
    null_gates = sorted(run.get("null_gates") or [])
    blocker = run.get("prelaunch_blocker") if isinstance(run.get("prelaunch_blocker"), dict) else {}
    verdict = run.get("verdict") or "-"
    error_kind = run.get("error_kind") or "-"
    failure_class = (
        run.get("failure_class")
        or blocker.get("stage")
        or blocker.get("kind")
        or error_kind
        or "-"
    )
    first_fatal = (
        blocker.get("first_fatal")
        or blocker.get("fatal")
        or blocker.get("reason")
        or run.get("first_fatal")
        or run.get("fatal_error")
        or "-"
    )
    owner = (
        blocker.get("owner")
        or run.get("owner")
        or run.get("next_owner")
        or run.get("source_owner")
        or "-"
    )
    prelaunch_verdicts = {"launch_blocked", "artifact_invalid", "infra_invalid"}
    prelaunch_error_kinds = {
        "prelaunch_block",
        "prelaunch_blocker",
        "launch_blocked",
        "infra_fail",
        "infra_invalid",
        "artifact_invalid",
    }
    is_infra = bool(
        blocker
        or verdict in prelaunch_verdicts
        or str(error_kind).lower() in prelaunch_error_kinds
        or (run.get("launcher_returncode") not in (None, 0) and not false_gates and not null_gates)
    )
    if is_infra:
        if failure_class == "-":
            failure_class = "infra"
        should_rerun = "no"
        rerun_reason = "fix the blocker or wrapper auto-heal first"
    elif false_gates or null_gates:
        if failure_class == "-":
            failure_class = "runtime_gate_failure"
        should_rerun = "no"
        rerun_reason = "inspect the listed gate families first"
    elif verdict == "pass":
        should_rerun = "no"
        rerun_reason = "run already passed"
    else:
        should_rerun = "unknown"
        rerun_reason = "insufficient summary fields"
    return {
        "run_id": run.get("run_id") or run_id,
        "verdict": verdict,
        "class": failure_class,
        "is_infra": is_infra,
        "error_kind": error_kind,
        "owner": owner,
        "first_fatal": first_fatal,
        "false_gates": false_gates,
        "diagnostic_false_gates": diagnostic_false,
        "deprecated_false_gates": deprecated_false,
        "null_gates": null_gates,
        "false_count": len(false_gates),
        "diagnostic_false_count": len(diagnostic_false),
        "deprecated_false_count": len(deprecated_false),
        "null_count": len(null_gates),
        "should_rerun": should_rerun,
        "rerun_reason": rerun_reason,
        "next": next_action_text(run),
        "commands": [
            f"python3 scripts/analyze_runs.py show {run.get('run_id') or run_id} --compact",
            f"python3 scripts/analyze_runs.py gates --run-id {run.get('run_id') or run_id}",
        ],
    }


def cmd_what_failed(args, root: Path):
    if not getattr(args, "json", False):
        _start_card("what-failed", run_id=args.run_id, mode="read-only")
    run = load_run_by_id(root, args.run_id)
    payload = _what_failed_payload(run, args.run_id)
    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2, sort_keys=True))
        return
    false_gates = payload["false_gates"]
    diagnostic_false = payload["diagnostic_false_gates"]
    deprecated_false = payload["deprecated_false_gates"]
    null_gates = payload["null_gates"]
    print(f"run: {payload['run_id']}")
    print(f"verdict: {payload['verdict']}")
    print(f"class: {payload['class']}")
    print(f"is_infra: {str(payload['is_infra']).lower()}")
    print(f"owner: {payload['owner']}")
    print(f"first_fatal: {compact_text(payload['first_fatal'], 140)}")
    gate_names = ", ".join(false_gates[:10]) if false_gates else "none"
    if len(false_gates) > 10:
        gate_names += f", ... +{len(false_gates) - 10}"
    print(f"false_gates: {len(false_gates)} [{gate_names}]")
    if diagnostic_false:
        diag_names = ", ".join(diagnostic_false[:10])
        if len(diagnostic_false) > 10:
            diag_names += f", ... +{len(diagnostic_false) - 10}"
        print(f"diagnostic_false_gates: {len(diagnostic_false)} [{diag_names}]")
    if deprecated_false:
        dep_names = ", ".join(deprecated_false[:10])
        if len(deprecated_false) > 10:
            dep_names += f", ... +{len(deprecated_false) - 10}"
        print(f"deprecated_false_gates: {len(deprecated_false)} [{dep_names}]")
    null_names = ", ".join(null_gates[:6]) if null_gates else "none"
    if len(null_gates) > 6:
        null_names += f", ... +{len(null_gates) - 6}"
    print(f"null_gates: {len(null_gates)} [{null_names}]")
    print(f"should_rerun: {payload['should_rerun']} ({payload['rerun_reason']})")
    print(f"next: {compact_text(payload['next'], 160)}")
    print("commands:")
    for command in payload["commands"]:
        print(f"  - {command}")


def _is_infra_payload(run: dict, run_id: str) -> dict:
    failed = _what_failed_payload(run, run_id)
    classification = "infra" if failed["is_infra"] else "gameplay"
    return {
        "run_id": failed["run_id"],
        "classification": classification,
        "is_infra": failed["is_infra"],
        "verdict": failed["verdict"],
        "class": failed["class"],
        "owner": failed["owner"],
        "first_fatal": failed["first_fatal"],
        "first_gameplay_gate": (failed["false_gates"] or [None])[0],
        "prelaunch_blocker": run.get("prelaunch_blocker") or None,
        "next": failed["next"],
    }


def cmd_is_infra(args, root: Path):
    run = load_run_by_id(root, args.run_id)
