def cmd_gates(args, root: Path):
    if not getattr(args, "json", False):
        _start_card("gates", mode="read-only")
    if getattr(args, "run_id", None):
        run = load_run_by_id(root, args.run_id)
        # FL-4203: Enrich with local-light gates if local_light_metrics.json exists
        if not run.get("has_local_light_gates"):
            run = _enrich_run_with_local_light_gates(run, root)
        false_gates = sorted(run.get("false_gates") or [])
        null_gates = sorted(run.get("null_gates") or [])
        payload = {
            "run_id": run.get("run_id") or args.run_id,
            "false_gates": false_gates,
            "null_gates": null_gates,
            "false_count": len(false_gates),
            "null_count": len(null_gates),
        }
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, sort_keys=True))
            return
        print(f"RUN: {payload['run_id']}")
        print(f"false gates ({len(false_gates)}):")
        if false_gates:
            for gate in false_gates:
                print(f"  - {gate}")
        else:
            print("  - none")
        print(f"null gates ({len(null_gates)}):")
        if null_gates:
            for gate in null_gates:
                print(f"  - {gate}")
        else:
            print("  - none")
        return
    gaps, gap_registry_status = load_gap_registry_with_status(root)
    missing_plan_gaps = missing_plan_required_gap_registry_gates(gaps)
    gap_registry_error = gap_registry_status.get("error")
    if gap_registry_error or missing_plan_gaps:
        if gap_registry_error:
            message = (
                "ERROR: gap registry unavailable: "
                f"{gap_registry_error} at {gap_registry_status.get('path')}"
            )
        else:
            message = (
                "ERROR: gap registry is missing plan-required appearance gate coverage: "
                + ", ".join(missing_plan_gaps)
            )
        payload = {
            "ok": False,
            "error": gap_registry_error or "gap_registry_missing_plan_required_coverage",
            "path": gap_registry_status.get("path"),
            "missing_plan_required_gates": missing_plan_gaps,
        }
        if gap_registry_status.get("detail"):
            payload["detail"] = gap_registry_status.get("detail")
        if getattr(args, "json", False):
            print(json.dumps(payload, indent=2, sort_keys=True))
        else:
            print(message, file=sys.stderr)
        raise SystemExit(2)

    runs, _ = load_all_runs(root)
    label_filter = requested_run_label(args)
    if label_filter:
        runs = [r for r in runs if run_label_for(r) == label_filter]

    # Only count over runs that have gate data
    runs_with_data = [
        r
        for r in runs
        if r.get("false_gates") is not None or r.get("null_gates") is not None
    ]
    total = len(runs_with_data)

    if total == 0:
        print("No runs with gate data found.")
        return

    all_gates = all_known_gates(runs_with_data)
    if not all_gates:
        print("No gates ever recorded as false or null.")
        return

    # For each gate: count false runs, null runs, last state
    rows = []
    for gate in sorted(all_gates):
        false_count = sum(
            1 for r in runs_with_data if gate in (r.get("false_gates") or [])
        )
        null_count = sum(
            1 for r in runs_with_data if gate in (r.get("null_gates") or [])
        )
        # Last state = state in the most recent run with data (already sorted newest first)
        last_state = gate_state(runs_with_data[0], gate)
        rows.append((gate, false_count, null_count, last_state))

    sort_key = args.sort_by
    if sort_key == "fail-count":
        rows.sort(key=lambda r: -r[1])
    elif sort_key == "null-count":
        rows.sort(key=lambda r: -r[2])
    # default "name" is already sorted

    fl = load_fl_index(root)

    print(f"Gate history across {total} run(s) with gate data.")
    print()
    headers = [
        "GATE",
        "FALSE_RUNS",
        "NULL_RUNS",
        "LAST_STATE",
        "FL",
        "HYPOTHESIS",
        "GAP",
    ]
    table_rows = []
    for g, fc, nc, ls in rows:
        e = fl.gate_latest(g)
        gap = gaps.get(g)
        if e:
            fl_str = e["fl"]
            hyp = (e.get("hypothesis") or e.get("status") or "?").split("\n")[0].strip()
            if len(hyp) > 45:
                hyp = hyp[:42] + "..."
        else:
            fl_str = "-"
            hyp = "-"
        gap_str = gap.get("id") if gap else "-"
        table_rows.append((g, fc, nc, ls, fl_str, hyp, gap_str))
    print_table(headers, table_rows)
    print(f"\n{len(table_rows)} distinct gates.")


