# FL subcommands
# ---------------------------------------------------------------------------


def _normalize_terms(raw: list) -> list:
    """Flatten each element by splitting on whitespace, stripping empty tokens.

    Single-argument terms are preserved as-is (lowercased). Multi-word
    arguments (quoted phrases) are split into individual tokens; tokens of
    length < 2 are filtered to avoid trivially broad single-char matches
    (e.g. 'yaw z snap' → ['yaw', 'snap'], not ['yaw', 'z', 'snap']).
    """
    result = []
    for t in raw:
        parts = t.split()
        if len(parts) == 1:
            result.append(t.lower())  # explicit single token — preserve as-is
        else:
            # phrase splitting: filter single-char tokens that over-match
            result.extend(tok.lower() for tok in parts if len(tok) >= 2)
    return [tok for tok in result if tok]


def _lane_audit_query_groups(raw: list[str]) -> list[list[str]]:
    groups: list[list[str]] = []
    for item in raw:
        normalized = _norm_text(str(item))
        if not normalized:
            continue
        parts = [part for part in normalized.split(" ") if part]
        if len(parts) > 1:
            groups.append([normalized, *parts])
        else:
            groups.append(parts)
    return groups


def _lane_audit_direct_match(entry: dict[str, Any], raw_terms: list[str]) -> bool:
    haystack = _norm_text(_fl_text(entry))
    line_haystacks = [_norm_text(entry.get("title") or "")]
    complaint_state = _fl_overlay_scalar(entry, "ComplaintCounterState")
    if complaint_state:
        line_haystacks.append(_norm_text(complaint_state))
    line_haystacks.extend(_norm_text(str(line)) for line in (entry.get("_lines") or []))
    groups = _lane_audit_query_groups(raw_terms)
    if not groups:
        return False
    for group in groups:
        phrase = group[0]
        if " " in phrase:
            if phrase in haystack:
                continue
            if any(all(token in line for token in group[1:]) for line in line_haystacks):
                continue
            return False
        if phrase not in haystack:
            return False
    return True


_LANE_SPENT_PATTERNS: tuple[re.Pattern[str], ...] = (
    re.compile(r"\bwhy prior attempts failed\b", re.IGNORECASE),
    re.compile(r"\balready burned\b", re.IGNORECASE),
    re.compile(r"\balready spent\b", re.IGNORECASE),
    re.compile(r"\bexhausted\b", re.IGNORECASE),
    re.compile(r"\bdo not revive\b", re.IGNORECASE),
    re.compile(r"\bnot the regression root cause\b", re.IGNORECASE),
    re.compile(r"\bcannot be the regression root cause\b", re.IGNORECASE),
    re.compile(r"\binsufficient\b", re.IGNORECASE),
)

_LANE_ACTIVE_PATTERNS: tuple[re.Pattern[str], ...] = (
    re.compile(r"\bnot exhausted yet\b", re.IGNORECASE),
    re.compile(r"\bcurrent unproven lane\b", re.IGNORECASE),
    re.compile(r"\bonly non-exhausted\b", re.IGNORECASE),
    re.compile(r"\bimmediate next step\b", re.IGNORECASE),
    re.compile(r"\bremaining lane\b", re.IGNORECASE),
    re.compile(r"\bnext real lane\b", re.IGNORECASE),
    re.compile(r"\bif .* fails,? the next\b", re.IGNORECASE),
)


def _lane_signal_rows(
    entry: dict[str, Any],
    patterns: tuple[re.Pattern[str], ...],
    *,
    max_rows: int = 4,
) -> list[str]:
    rows: list[str] = []
    complaint_state = _fl_overlay_scalar(entry, "ComplaintCounterState")
    if complaint_state:
        text = str(complaint_state).strip()
        if any(pattern.search(text) for pattern in patterns):
            rows.append(f"ComplaintCounterState: {compact_text(text, max_len=180)}")
    for line in entry.get("_lines") or []:
        text = str(line).strip()
        if not text:
            continue
        if any(pattern.search(text) for pattern in patterns):
            cleaned = re.sub(r"^[>\-\*\s]+", "", text)
            rows.append(compact_text(cleaned, max_len=180))
        if len(rows) >= max_rows:
            break
    return rows[:max_rows]


def _collect_lane_audit_report(
    entries: list[dict[str, Any]],
    entries_by_id: dict[str, dict[str, Any]],
    raw_terms: list[str],
) -> dict[str, Any]:
    terms = _normalize_terms(raw_terms)
    direct = [
        e
        for e in entries
        if _lane_audit_direct_match(e, raw_terms)
    ]
    direct_ids = {e["fl"] for e in direct}
    family_ids = _expand_cluster(direct_ids, entries_by_id, entries, terms) if direct_ids else set()
    family = sorted(
        [entries_by_id[fid] for fid in family_ids if fid in entries_by_id],
        key=lambda item: item["num"],
    )

    spent_hits = []
    active_hits = []
    for entry in family:
        spent_rows = _lane_signal_rows(entry, _LANE_SPENT_PATTERNS)
        active_rows = _lane_signal_rows(entry, _LANE_ACTIVE_PATTERNS)
        if spent_rows:
            spent_hits.append(
                {
                    "fl": entry["fl"],
                    "title": entry.get("title") or "",
                    "ledger_state": fl_ledger_state(entry),
                    "signals": spent_rows,
                }
            )
        if active_rows:
            active_hits.append(
                {
                    "fl": entry["fl"],
                    "title": entry.get("title") or "",
                    "ledger_state": fl_ledger_state(entry),
                    "signals": active_rows,
                }
            )

    if active_hits and spent_hits:
        verdict, exit_code = "MIXED", 0
    elif spent_hits:
        verdict, exit_code = "SPENT", 2
    elif active_hits:
        verdict, exit_code = "ACTIVE", 0
    elif family:
        verdict, exit_code = "NO_EXPLICIT_SIGNAL", 0
    else:
        verdict, exit_code = "NO_MATCH", 1

    return {
        "mode": "lane-audit",
        "terms": terms,
        "verdict": verdict,
        "exit_code": exit_code,
        "direct_matches": [e["fl"] for e in direct],
        "family": [e["fl"] for e in family],
        "spent_hits": spent_hits,
        "active_hits": active_hits,
    }


def cmd_fl_lane_audit(args, root: Path):
    entries = load_fl_entries(root)
    entries_by_id = {e["fl"]: e for e in entries}
    report = _collect_lane_audit_report(entries, entries_by_id, list(args.terms))

    if getattr(args, "json", False):
        print(json.dumps(report, indent=2))
        raise SystemExit(report["exit_code"])

    terms = report["terms"]
    family = report["family"]
    family_entries = [entries_by_id[fid] for fid in family if fid in entries_by_id]
    spent_hits = report["spent_hits"]
    active_hits = report["active_hits"]
    verdict = report["verdict"]
    exit_code = report["exit_code"]

    print(f"LANE AUDIT: {' '.join(repr(t) for t in terms)}")
    print(f"Direct matches: {len(report['direct_matches'])}  |  Family size: {len(family)}\n")

    if spent_hits:
        print("ALREADY BURNED / SPENT:")
        for hit in spent_hits[:8]:
            print(f"  {hit['fl']:<8}  {hit['ledger_state']:<22}  {hit['title'][:70]}")
            for signal in hit["signals"]:
                print(f"    - {signal}")
        print()

    if active_hits:
        print("NOT EXHAUSTED YET / REMAINING LANES:")
        for hit in active_hits[:8]:
            print(f"  {hit['fl']:<8}  {hit['ledger_state']:<22}  {hit['title'][:70]}")
            for signal in hit["signals"]:
                print(f"    - {signal}")
        print()

    if family_entries and not spent_hits and not active_hits:
        print("MATCHED FAMILY (no explicit spent/remaining markers detected):")
        for entry in family_entries[:8]:
            print(f"  {entry['fl']:<8}  {fl_ledger_state(entry):<22}  {(entry.get('title') or '')[:70]}")
        print()

    if family_entries:
        newest = family_entries[-1]["fl"]
        print("Next commands:")
        print(f"  python3 scripts/analyze_runs.py fl family {newest}")
        print(f"  python3 scripts/analyze_runs.py fl history-audit --fl-id {newest}")

    if verdict == "SPENT":
        print("\nVERDICT: SPENT — prior attempts/family text already marks this lane as burned or rejected.")
        raise SystemExit(exit_code)
    if verdict == "ACTIVE":
        print("\nVERDICT: ACTIVE — matching FL text still presents a remaining or immediate-next lane.")
        return
    if verdict == "MIXED":
        print("\nVERDICT: MIXED — family contains both spent-lane history and remaining-lane guidance.")
        return
    if verdict == "NO_EXPLICIT_SIGNAL":
        print("\nVERDICT: NO EXPLICIT SIGNAL — matched FL family exists, but no spent/remaining markers were found.")
        return
    print("\nVERDICT: NO MATCH — no FL family matched the proposed lane terms.")
    raise SystemExit(exit_code)


def _git_query_lines(root: Path, *args: str) -> list[str]:
    result = subprocess.run(
        ["git", *args],
        cwd=str(root),
        capture_output=True,
        text=True,
        timeout=10,
    )
    if result.returncode != 0:
        raise RuntimeError(f"git {' '.join(args)} failed: {(result.stderr or result.stdout).strip()}")
    return [line for line in result.stdout.splitlines() if line.strip()]


def cmd_fl_multiplayer_preflight(args, root: Path):
    entries = load_fl_entries(root)
    entries_by_id = {e["fl"]: e for e in entries}
    lane_report = _collect_lane_audit_report(entries, entries_by_id, list(args.terms))

    context = None
    fl_id = getattr(args, "fl_id", None)
    if fl_id:
        target_fl = fl_id.upper()
        entry = entries_by_id.get(target_fl)
        if not entry:
            if getattr(args, "json", False):
                _emit_fl_json_error(
                    command="fl multiplayer-preflight",
                    error="not_found",
                    exit_code=2,
                    fl_id=target_fl,
                )
            print(f"ERROR fl multiplayer-preflight: {target_fl} not found.", file=sys.stderr)
            raise SystemExit(2)
        family_terms = _title_expansion_terms(entry.get("title") or "")
        family_ids = _expand_cluster({target_fl}, entries_by_id, entries, family_terms)
        family = sorted(
            [entries_by_id[fid] for fid in family_ids if fid in entries_by_id],
            key=lambda item: item["num"],
        )
        context = {
            "fl_id": target_fl,
            "family_size": len(family),
            "failed": [e["fl"] for e in family if status_class(e) == "failed"],
            "resolved": [e["fl"] for e in family if status_class(e) == "resolved"],
            "open": [e["fl"] for e in family if status_class(e) == "open"],
        }

    try:
        status_lines = _git_query_lines(root, "status", "--porcelain")
        stash_lines = _git_query_lines(root, "stash", "list")
    except RuntimeError as exc:
        if getattr(args, "json", False):
            print(json.dumps({
                "mode": "multiplayer-preflight",
                "verdict": "ERROR",
                "error": str(exc),
            }, indent=2))
        else:
            print(f"MULTIPLAYER PRE-FLIGHT ERROR: {exc}")
        raise SystemExit(1)

    tracked = []
    untracked = []
    for line in status_lines:
        if line.startswith("??"):
            untracked.append(line[3:] if len(line) > 3 else line)
            continue
        tracked.append(line[3:] if len(line) > 3 else line)

    blockers: list[str] = []
    if lane_report["verdict"] == "SPENT":
        blockers.append("lane terms already map to a spent family")
    elif lane_report["verdict"] == "MIXED":
        blockers.append("lane terms still span both spent and remaining families; narrow the owner first")
    if tracked:
        blockers.append("tracked git changes present")
    if stash_lines:
        blockers.append("git stash is not empty")

    verdict = "BLOCKED" if blockers else "CLEAR"
    payload = {
        "mode": "multiplayer-preflight",
        "verdict": verdict,
        "lane_audit": lane_report,
        "context": context,
        "repo": {
            "tracked_paths": tracked,
            "untracked_paths": untracked,
            "stash_entries": stash_lines,
        },
        "blockers": blockers,
    }

    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2))
        raise SystemExit(2 if blockers else 0)

    print("MULTIPLAYER PRE-FLIGHT")
    if context:
        print(
            f"Context family: {context['fl_id']}  "
            f"(family={context['family_size']} failed={len(context['failed'])} "
            f"resolved={len(context['resolved'])} open={len(context['open'])})"
        )
    print(
        f"Lane audit: {lane_report['verdict']}  "
        f"(direct={len(lane_report['direct_matches'])} family={len(lane_report['family'])})"
    )
    print(
        f"Repo state: tracked={len(tracked)} untracked={len(untracked)} stash={len(stash_lines)}"
    )
    if blockers:
        print("\nBLOCKERS:")
        for blocker in blockers:
            print(f"  - {blocker}")
        if lane_report["spent_hits"]:
            top = lane_report["spent_hits"][0]
            print(f"  - spent evidence: {top['fl']} {top['title'][:72]}")
        if tracked:
            print(f"  - tracked sample: {tracked[0]}")
        if stash_lines:
            print(f"  - stash sample: {stash_lines[0]}")
        print("\nVERDICT: BLOCKED — do not start another multiplayer behavior patch from this state.")
        raise SystemExit(2)

    print("\nVERDICT: CLEAR — lane terms are not marked spent, and repo guardrails are clean.")


def _cmd_fl_search_legacy(args, root: Path):
    entries = load_fl_entries(root)
    terms = _normalize_terms(args.terms)

    results = []
    for e in entries:
        text = _fl_text(e).lower()
        if getattr(args, "any", False):
            if not any(t in text for t in terms):
                continue
        else:
            if not all(t in text for t in terms):
                continue
        if getattr(args, "tried", False):
            if status_class(e) != "failed":
                continue
        if getattr(args, "status", None):
            if not fl_status_matches(e, args.status):
                continue
        if getattr(args, "date_from", None):
            if (e.get("date") or "") < args.date_from:
                continue
        if getattr(args, "date_to", None):
            if (e.get("date") or "") > args.date_to:
                continue
        results.append(e)

    if getattr(args, "json", False):
        print(json.dumps([
            {"fl": e["fl"], "title": e.get("title", ""), "status": fl_status_display(e), "date": e.get("date", "")}
            for e in results
        ], indent=2))
        return

    tried_tag = " [--tried]" if getattr(args, "tried", False) else ""
    print(
        f"SEARCH: {' '.join(repr(t) for t in terms)}{tried_tag}  {len(results)} matches"
    )
    print("(direct text matches only — use 'fl history <term>' for family expansion)\n")

    for e in results:
        status_str = fl_status_display(e)[:28]
        date_str = e.get("date") or "-"
        title_str = (e.get("title") or "-")[:55]
        print(f"{e['fl']:<8}  {status_str:<28}  {date_str}  {title_str}")
        best_excerpt = None
        best_score = -1
        for line in e.get("_lines") or []:
            lc = line.lower().strip()
            if not (any(t in lc for t in terms) and len(lc) > 10):
                continue
            s = line.strip()
            if re.match(r"^-\s+\*\*[A-Za-z][^:]*:\*\*", s):
                score = 0  # metadata bullet: - **Field:**
            elif re.match(r"^-\s+\*\*[A-Za-z]", s):
                score = 1  # bold list item
            elif re.match(r"^\d+\.", s) or re.match(r"^[A-Z]", s) or s.startswith("**"):
                score = 3  # numbered list, bold header, or leading-capital prose
            else:
                score = 2
            if score > best_score:
                best_score = score
                best_excerpt = s
        if best_excerpt:
            print(f"  > {best_excerpt[:100]}")
        print()


def cmd_fl_search(args, root: Path):
    """Run the authority-ranked historical search contract.

    ``--legacy-direct`` retains the former literal ledger-only surface for
    callers that need byte-compatible JSON while they migrate. The default is
    the FL-4736 hybrid contract so ordinary agent searches cannot silently omit
    deleted owners and Git provenance.
    """
    if getattr(args, "legacy_direct", False):
        return _cmd_fl_search_legacy(args, root)

    entries = load_fl_entries(root)
    query = " ".join(str(term) for term in args.terms).strip()

    def entry_filter(entry: dict) -> bool:
        if getattr(args, "tried", False) and status_class(entry) != "failed":
            return False
        if getattr(args, "status", None) and not fl_status_matches(entry, args.status):
            return False
        entry_date = entry.get("date") or ""
        if getattr(args, "date_from", None) and entry_date < args.date_from:
            return False
        if getattr(args, "date_to", None) and entry_date > args.date_to:
            return False
        return True

    transcript_roots = [Path(value).expanduser() for value in getattr(args, "transcript_root", [])]
    index = _failure_log_snapshot(root).projection(
        "analyze_runs.HistoricalSearchIndex:" + "|".join(str(path) for path in transcript_roots),
        lambda: HistoricalSearchIndex(root, entries, transcript_roots=transcript_roots),
    )
    report = index.search(
        query,
        limit=max(1, min(int(getattr(args, "limit", 10) or 10), 50)),
        include_git=not getattr(args, "no_git", False),
        entry_filter=entry_filter,
    )
    payload = report.to_dict()
    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2))
        return

    print(f"HISTORICAL SEARCH: {query!r}")
    print(
        "expanded: "
        + ", ".join(report.expanded_terms[:24])
        + (" ..." if len(report.expanded_terms) > 24 else "")
    )
    print(
        "scope: locally reachable refs"
        + (" (shallow checkout)" if report.history_scope.get("shallow") else "")
        + ("; truncated" if report.history_scope.get("truncated") else "")
    )
    for group in HISTORICAL_GROUP_ORDER:
        rows = [result for result in report.results if result.group == group]
        if not rows:
            continue
        print(f"\n{group.replace('_', ' ').upper()} ({len(rows)})")
        for result in rows:
            identity = result.fl or (result.commit[:12] if result.commit else result.source_path)
            timestamp = result.committed_at or result.date or result.observed_at or "unknown-time"
            print(f"  {identity}  score={result.score:g}  {timestamp}")
            print(f"    {result.title}")
            print(f"    {result.excerpt[:240]}")
            print(f"    source={result.source_path}")
            if result.commit:
                print(
                    f"    commit={result.commit} role={result.provenance_role}"
                    f" authored={result.authored_at} committed={result.committed_at}"
                )
            print(f"    why={'; '.join(result.why_ranked)}")
    if not report.results:
        print("\nNo ranked results.")
    if report.history_scope.get("stop_reasons"):
        print("\nBOUNDED HISTORY WARNINGS:")
        for reason in report.history_scope["stop_reasons"]:
            print(f"  - {reason}")


def cmd_fl_recall_suite(args, root: Path):
    """Run the versioned operator-memory recall and precision acceptance gate."""
    case_path = Path(args.cases)
    if not case_path.is_absolute():
        case_path = root / case_path
    if not case_path.exists():
        print(f"error: recall case file not found: {case_path}", file=sys.stderr)
        raise SystemExit(2)
    try:
        cases = json.loads(case_path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError) as exc:
        print(f"error: invalid recall case file {case_path}: {exc}", file=sys.stderr)
        raise SystemExit(2)
    if not isinstance(cases, list):
        print("error: recall case file must contain a JSON array", file=sys.stderr)
        raise SystemExit(2)
    entries = load_fl_entries(root)
    index = _failure_log_snapshot(root).projection(
        "analyze_runs.HistoricalSearchIndex:recall-suite",
        lambda: HistoricalSearchIndex(root, entries),
    )
    reports = {
        str(case["case_id"]): index.search(
            str(case["query"]),
            limit=max(1, min(int(args.limit), 50)),
            include_git=not args.no_git,
        )
        for case in cases
    }
    metrics = evaluate_recall_cases(reports, cases, k=max(1, int(args.k)))
    metrics["schema"] = "fl.remembered_case_recall.v1"
    metrics["case_file"] = str(case_path)
    if args.json:
        print(json.dumps(metrics, indent=2))
    else:
        verdict = "PASS" if metrics["passed"] else "FAIL"
        print(f"REMEMBERED-CASE RECALL SUITE: {verdict}")
        print(f"recall@{metrics['k']}={metrics['recall_at_k']:.3f}")
        print(f"precision@{metrics['k']}={metrics['precision_at_k']:.3f}")
        for case in metrics["cases"]:
            print(
                f"  {case['case_id']}: {'PASS' if case['passed'] else 'FAIL'} "
                f"recall={case['recall_at_k']:.3f} precision={case['precision_at_k']:.3f}"
            )
            if case["missing"]:
                print(f"    missing={case['missing']}")
    if not metrics["passed"]:
        raise SystemExit(1)


def _fl_fix_attempt_count(root: Path, fl_id: str) -> int:
    raw = _fl_extract_raw(root, fl_id)
    if not raw:
        return 0
    return len(fl_fix_attempt_blocks(raw))


def cmd_fl_audit(args, root: Path):
    entries = load_fl_entries(root)
    entries_by_id = {e["fl"]: e for e in entries}
    terms = _normalize_terms(args.terms)

    # Step 1: direct matches
    direct = []
    snippet_hits = []
    for e in entries:
        text = _fl_text(e).lower()
        term_hit = bool(terms) and all(t in text for t in terms)
        s_hit = _snippet_hit(e, getattr(args, "snippet", None) or [])
        if term_hit:
            direct.append(e)
        if s_hit and e not in direct:
            snippet_hits.append(e)
    direct_ids = {e["fl"] for e in direct} | {e["fl"] for e in snippet_hits}

    # Step 2: multi-pass cluster expansion
    all_ids = _expand_cluster(direct_ids, entries_by_id, entries, terms)
    cluster = sorted(
        [entries_by_id[fid] for fid in all_ids if fid in entries_by_id],
        key=lambda x: x["num"],
    )

    # Step 3: classify — sorted lists for deterministic lineage selection
    failed = sorted(
        [e for e in cluster if status_class(e) == "failed"],
        key=lambda x: x["num"],
        reverse=True,
    )
    resolved = sorted(
        [e for e in cluster if status_class(e) == "resolved"],
        key=lambda x: x["num"],
        reverse=True,
    )
    open_e = sorted(
        [e for e in cluster if status_class(e) == "open"],
        key=lambda x: x["num"],
        reverse=True,
    )
    # Restrict canonical direction to direct-match resolved entries only —
    # expansion-pulled resolved entries (e.g. FL-020 meta-audit) appear in
    # ACCEPTED/KEEP for info but must not drive the verdict.
    direct_resolved = [e for e in resolved if e["fl"] in direct_ids]
    canonical = direct_resolved[0] if direct_resolved else None
    # Restrict top_rejected to direct-match failed entries only —
    # expansion-pulled failed entries must not drive policy/diff verdicts.
    direct_failed = [e for e in failed if e["fl"] in direct_ids]
    top_rejected = direct_failed[0] if direct_failed else None

    if getattr(args, "json", False):
        rej_refs = _extract_file_refs(direct_failed[:3])
        acc_refs = _extract_file_refs(direct_resolved[:2])
        rej_files = _diff_paths_from_refs(rej_refs)
        acc_files = _diff_paths_from_refs(acc_refs)
        rej_diff = (
            _run_git_diff(root, top_rejected["commit"], rej_files)
            if top_rejected and top_rejected.get("commit") and rej_files
            else ""
        )
        can_diff = (
            _run_git_diff(root, canonical["commit"], acc_files)
            if canonical and canonical.get("commit") and acc_files
            else ""
        )
        diff_required = bool(
            canonical
            and top_rejected
            and canonical.get("commit")
            and top_rejected.get("commit")
        )
        diff_missing = diff_required and (not rej_diff or not can_diff)
        allow_reopen = getattr(args, "allow_reopen", None)
        blocked = bool(failed and (len(failed) >= 2 or open_e))
        if diff_missing:
            verdict, exit_code = "INCOMPLETE", 3
        elif blocked and not allow_reopen:
            verdict, exit_code = "BLOCKED", 2
        elif blocked and allow_reopen:
            verdict, exit_code = "OVERRIDDEN", 0
        elif failed:
            verdict, exit_code = "CAUTION", 0
        elif canonical:
            verdict, exit_code = "CANONICAL", 0
        else:
            verdict, exit_code = "CLEAR", 0
        payload = {
            "mode": "audit",
            "terms": terms,
            "verdict": verdict,
            "exit_code": exit_code,
            "direct_matches": [e["fl"] for e in direct],
            "snippet_matches": [e["fl"] for e in snippet_hits],
            "expanded_family": [e["fl"] for e in cluster],
            "failed": [e["fl"] for e in failed],
            "resolved": [e["fl"] for e in resolved],
            "open": [e["fl"] for e in open_e],
            "implemented_unproven": [
                e["fl"] for e in cluster if fl_entry_is_implemented_unproven(e)
            ],
            "canonical": canonical["fl"] if canonical else None,
            "top_rejected": top_rejected["fl"] if top_rejected else None,
            "diff_required": diff_required,
            "diff_missing": diff_missing,
            "allow_reopen": allow_reopen,
            "next_commands": (
                [f"python3 scripts/analyze_failure_log.py family {cluster[-1]['fl']}"]
                if cluster
                else []
            ),
        }
        print(json.dumps(payload, indent=2))
        raise SystemExit(exit_code)

    print(f"AUDIT: {' '.join(repr(t) for t in terms)}")
    snippet_list = getattr(args, "snippet", None) or []
    if snippet_list:
        print(f"Snippets: {snippet_list}")
    print(
        f"Direct matches: {len(direct)}  |  Snippet matches: {len(snippet_hits)}  |  "
        f"Related expansions: {len(all_ids) - len(direct_ids)}  |  Total cluster: {len(cluster)}\n"
    )

    # ACCEPTED / KEEP
    if resolved:
        print("ACCEPTED / KEEP:")
        for e in sorted(resolved, key=lambda x: x["num"])[:3]:
            print(
                f"  {e['fl']:<8}  {(e.get('status') or ''):<20}  {e.get('date') or '-'}  {(e.get('title') or '')[:60]}"
            )
            for line in e.get("_lines") or []:
                ls = line.strip()
                if ls and len(ls) > 20 and not ls.startswith("#"):
                    print(f"  > {ls[:100]}")
                    break
        print()

    # REJECTED / DO NOT REOPEN
    if failed:
        print("REJECTED / DO NOT REOPEN:")
        for e in failed[:6]:
            print(
                f"  {e['fl']:<8}  {(e.get('status') or 'NONE'):<20}  {e.get('date') or '-'}  {(e.get('title') or '')[:60]}"
            )
        print()

    # ACTIVE REINTRODUCTION RISK
    if open_e and failed:
        print("ACTIVE REINTRODUCTION RISK:")
        ranked_open = sorted(
            open_e,
            key=lambda item: (
                0 if fl_entry_is_implemented_unproven(item) else 1,
                -int(item.get("num") or 0),
            ),
        )
        for e in ranked_open[:3]:
            print(
                f"  {e['fl']:<8}  {fl_ledger_state(e):<22}  {e.get('date') or '-'}  {(e.get('title') or '')[:55]}"
            )
        print(
            f"  -> OPEN entry in cluster with REVERTED entries — may be a reintroduction\n"
        )

    # POLICY DIFFERENCE
    if canonical and top_rejected:
        a_lines = _policy_lines(canonical, _POLICY_ACCEPT_KEYS, 2)
        r_lines = _policy_lines(top_rejected, _POLICY_REJECT_KEYS, 2)
        if a_lines or r_lines:
            print("POLICY DIFFERENCE:")
            for l in a_lines:
                print(f"  accepted: {l}")
            for l in r_lines:
                print(f"  rejected: {l}")
            print()

    # GIT DIFF EVIDENCE — file refs + commits + actual git diff
    # Use direct-match lists to avoid expansion-pulled noise in evidence.
    rej_refs = _extract_file_refs(direct_failed[:3])
    acc_refs = _extract_file_refs(direct_resolved[:2])
    rej_commits = _extract_commits(direct_failed[:3])
    acc_commits = _extract_commits(direct_resolved[:2])
    if rej_refs or acc_refs:
        print("GIT DIFF EVIDENCE:")
        if rej_refs:
            print("  rejected approach touched:")
            for ref in rej_refs[:8]:
                print(f"    {ref}")
        uniq_acc = [r for r in acc_refs if r not in set(rej_refs)][:5]
        if uniq_acc:
            print("  canonical approach touched:")
            for ref in uniq_acc:
                print(f"    {ref}")
        if rej_commits:
            print(f"  reverted commits: {' '.join(rej_commits[:4])}")
        if acc_commits:
            print(f"  canonical commits: {' '.join(acc_commits[:4])}")
        print()

    # Run real git diff (mandatory when commits available)
    rej_files = _diff_paths_from_refs(rej_refs)
    acc_files = _diff_paths_from_refs(acc_refs)
    rej_diff = can_diff = ""
    if top_rejected and top_rejected.get("commit") and rej_files:
        rej_diff = _run_git_diff(root, top_rejected["commit"], rej_files)
        if rej_diff:
            print(
                f"REJECTED LANE DIFF ({top_rejected['commit'][:8]}^..{top_rejected['commit'][:8]}):"
            )
            print(rej_diff)
            print()
    if canonical and canonical.get("commit") and acc_files:
        can_diff = _run_git_diff(root, canonical["commit"], acc_files)
        if can_diff:
            print(
                f"CANONICAL LANE DIFF ({canonical['commit'][:8]}^..{canonical['commit'][:8]}):"
            )
            print(can_diff)
            print()

    diff_required = bool(
        canonical
        and top_rejected
        and canonical.get("commit")
        and top_rejected.get("commit")
    )
    diff_missing = diff_required and (not rej_diff or not can_diff)

    # Semantic neighbors outside cluster
    outside_failed = [
        e for e in entries if status_class(e) == "failed" and e["fl"] not in all_ids
    ]
    scored = sorted(
        [
            (sum(1 for t in terms if t in _fl_text(e).lower()), e)
            for e in outside_failed
        ],
        key=lambda x: -x[0],
    )
    scored = [(s, e) for s, e in scored if s > 0]
    if scored:
        print("SIMILAR REVERTED ENTRIES (semantic neighbors — outside cluster):")
        for _, e in scored[:5]:
            print(
                f"  {e['fl']:<8}  {(e.get('status') or 'NONE'):<20}  {(e.get('title') or '')[:55]}"
            )
        print()

    # Verdict + exit code
    allow_reopen = getattr(args, "allow_reopen", None)
    if allow_reopen:
        print(f'NOTE: --allow-reopen passed: "{allow_reopen}"')

    blocked = bool(failed and (len(failed) >= 2 or open_e))

    if diff_missing:
        print(
            "VERDICT: INCOMPLETE — canonical/rejected commits exist but diff could not be produced."
        )
        print("Manual action: run git diff for both commits before proposing a fix.")
        raise SystemExit(3)
    if blocked and not allow_reopen:
        canon_ref = (
            f" Follow canonical direction {canonical['fl']}." if canonical else ""
        )
        print(f"VERDICT: BLOCKED — spent/rejected family detected.{canon_ref}")
        print('[To override: pass --allow-reopen "reason"]')
        raise SystemExit(2)
    if blocked and allow_reopen:
        print(f"VERDICT: OVERRIDDEN — {allow_reopen}")
    elif failed:
        print(f"VERDICT: CAUTION — 1 prior failed attempt. Review before proceeding.")
    elif canonical:
        print(f"VERDICT: CANONICAL DIRECTION EXISTS — follow {canonical['fl']}.")
    else:
        print(f"VERDICT: No prior attempts found in FL for these terms.")


def cmd_fl_suggest_related(args, root: Path):
    entries = load_fl_entries(root)
    entries_by_id = {e["fl"]: e for e in entries}
    terms = _normalize_terms(args.terms)

    direct = [e for e in entries if all(t in _fl_text(e).lower() for t in terms)]
    direct_ids = {e["fl"] for e in direct}
    all_ids = _expand_cluster(direct_ids, entries_by_id, entries, terms)
    cluster = sorted(
        [entries_by_id[fid] for fid in all_ids if fid in entries_by_id],
        key=lambda x: x["num"],
        reverse=True,
    )

    failed = [e for e in cluster if status_class(e) == "failed"]
    resolved = [e for e in cluster if status_class(e) == "resolved"]
    # Restrict canonical/rejected labels to direct matches only (same fix as fl audit)
    direct_resolved = [e for e in resolved if e["fl"] in direct_ids]
    direct_failed = [e for e in failed if e["fl"] in direct_ids]

    print(f"SUGGEST RELATED for: {' '.join(repr(t) for t in terms)}\n")

    if cluster:
        print("FAMILY HISTORY (paste **Related:** line into new entry):")
        for e in cluster[:8]:
            sc = status_class(e)
            display_state = fl_display_state(e)
            is_direct = e["fl"] in direct_ids
            tag = (
                "  [CANONICAL]"
                if sc == "resolved" and is_direct
                else ("  [DO NOT REOPEN]" if sc == "failed" else "")
            )
            print(
                f"  {e['fl']:<8}  {display_state:<20}  {e.get('date') or '-'}  "
                f"{(e.get('title') or '')[:45]}{tag}"
            )
        print()

    all_refs = _extract_file_refs(cluster)
    if all_refs:
        print("CODE AREAS IN THIS FAMILY (include in entry if relevant):")
        print(f"  {' '.join(all_refs[:10])}")
        print()

    commit_labels = {}
    for e in cluster:
        c = e.get("commit")
        if c:
            sc = status_class(e)
            is_direct = e["fl"] in direct_ids
            label = (
                "REVERTED"
                if sc == "failed"
                else ("canonical" if sc == "resolved" and is_direct else ("resolved" if sc == "resolved" else "open"))
            )
            commit_labels.setdefault(c, f"{label}: {(e.get('title') or '')[:55]}")
    if commit_labels:
        print("COMMIT TRAIL:")
        for c, label in list(commit_labels.items())[:6]:
            print(f"  {c}  {label}")
        print()

    # Paste-ready template
    related_ids = ", ".join(e["fl"] for e in cluster[:8])
    code_refs_str = ", ".join(f"`{r}`" for r in all_refs[:6])
    failed_note = f", 1 reverted ({direct_failed[0]['fl']}) — do not reopen" if direct_failed else ""
    resolved_note = (
        f"1 canonical ({direct_resolved[0]['fl']})"
        if direct_resolved
        else "no canonical direction yet"
    )
    print(cli_style.style("--- PASTE INTO NEW FL ENTRY ---", "subheader"))
    if related_ids:
        print(f"- **Related:** {related_ids}")
    if code_refs_str:
        print(f"- **Code areas:** {code_refs_str}")
    print(f"- **Prior attempts:** {resolved_note}{failed_note}")


def cmd_fl_history(args, root: Path):
    entries = load_fl_entries(root)
    entries_by_id = {e["fl"]: e for e in entries}
    query = args.query.lower()
    terms = _normalize_terms([args.query])
    direct = []
    for e in entries:
        text = _fl_text(e).lower()
        gate = (e.get("gate") or "").lower()
        if query == gate or (terms and all(t in text for t in terms)):
            direct.append(e)

    print(f"HISTORY: {args.query}\n")
    if not direct:
        print("  No FL entries found.")
        return

    direct_ids = {e["fl"] for e in direct}
    expanded_ids = _expand_cluster(direct_ids, entries_by_id, entries, terms)
    matching = sorted(
        [entries_by_id[fid] for fid in expanded_ids if fid in entries_by_id],
        key=lambda x: x["num"],
        reverse=True,
    )

    expansions = len(expanded_ids) - len(direct_ids)
    if expansions > 0:
        print(
            f"Direct matches: {len(direct_ids)}  |  Family expansions: {expansions}\n"
        )

    for e in matching:
        sc_label = fl_display_state(e).upper().replace("-", "/")
        match_kind = "direct" if e["fl"] in direct_ids else "family"
        attempts = _fl_fix_attempt_count(root, e["fl"])
        print(
            f"{e['fl']:<8}  {sc_label:<18}  {e.get('date') or '-'}  "
            f"{(e.get('title') or '')[:55]}  [{match_kind}, attempts={attempts}]"
        )
    counts = {"open": 0, "resolved": 0, "failed": 0, "unknown": 0}
    for e in matching:
        counts[status_class(e)] += 1
    print(
        f"\nTotals: {counts['open']} open, {counts['resolved']} resolved, "
        f"{counts['failed']} failed/reverted, {counts['unknown']} unknown"
    )


def cmd_fl_related(args, root: Path):
    entries = load_fl_entries(root)
    entries_by_id = {e["fl"]: e for e in entries}
    fl_id = args.fl_id.upper()
    if not re.match(r"^FL-\d+$", fl_id):
        sys.exit(f"error: invalid FL ID: {args.fl_id}")
    root_entry = entries_by_id.get(fl_id)
    if not root_entry:
        sys.exit(f"error: {fl_id} not found in docs/FAILURE_LOG.md")

    related_ids = set(root_entry.get("related") or []) | {fl_id}
    family = sorted(
        [entries_by_id[fid] for fid in related_ids if fid in entries_by_id],
        key=lambda x: x["num"],
    )
    print(f"RELATED FAMILY: {fl_id} (root + {len(family) - 1} related)")
    print("(follows explicit Related: links only — use 'fl family' for full cluster expansion)\n")
    for e in family:
        marker = " <- ROOT" if e["fl"] == fl_id else ""
        print(
            f"{e['fl']:<8}  {fl_status_display(e):<25}  {e.get('date') or '-'}  "
            f"{(e.get('title') or '')[:50]}{marker}"
        )


def cmd_fl_open(args, root: Path):
    entries = load_fl_entries(root)
    open_entries = [e for e in entries if status_class(e) == "open"]
    print(f"OPEN FL ENTRIES ({len(open_entries)} total)\n")
    for e in reversed(open_entries):  # newest first
        print(
            f"{e['fl']:<8}  {e.get('date') or '-'}  {(e.get('gate') or '-'):<45}  {(e.get('title') or '')[:50]}"
        )
    print(f"\n{len(open_entries)} OPEN entries.")


def _emit_fl_json_error(
    *,
    command: str,
    error: str,
    exit_code: int,
    fl_id: str | None = None,
    extra: dict[str, Any] | None = None,
) -> None:
    payload: dict[str, Any] = {
        "ok": False,
        "command": command,
        "error": error,
    }
    if fl_id:
        payload["fl_id"] = fl_id
    if extra:
        payload.update(extra)
    print(json.dumps(payload, indent=2))
    raise SystemExit(exit_code)


def _lookup_fl_entry(
    root: Path,
    fl_id: str,
    *,
    args: argparse.Namespace | None = None,
    command: str = "fl",
) -> dict:
    entries = load_fl_entries(root)
    entry = next((e for e in entries if e["fl"] == fl_id), None)
    if not entry:
        if getattr(args, "json", False):
            _emit_fl_json_error(
                command=command,
                error="not_found",
                exit_code=2,
                fl_id=fl_id,
            )
        sys.exit(f"error: {fl_id} not found in docs/FAILURE_LOG.md")
    return entry


def _lookup_fl_entries(
    root: Path,
    fl_id: str,
    *,
    args: argparse.Namespace | None = None,
    command: str = "fl",
) -> list[dict]:
    entries = [entry for entry in load_fl_entries(root) if entry["fl"] == fl_id]
    if not entries:
        if getattr(args, "json", False):
            _emit_fl_json_error(
                command=command,
                error="not_found",
                exit_code=2,
                fl_id=fl_id,
            )
        sys.exit(f"error: {fl_id} not found in docs/FAILURE_LOG.md")
    return entries


def cmd_fl_list(args, root: Path):
    entries = load_fl_entries(root)
    if getattr(args, "status", None):
        entries = [e for e in entries if fl_status_matches(e, getattr(args, "status"))]
    if getattr(args, "gate", None):
        entries = [
            e
            for e in entries
            if args.gate == e.get("gate") or args.gate in (e.get("gates") or [])
        ]
    if getattr(args, "category", None):
        entries = [
            e
            for e in entries
            if getattr(args, "category").lower() in (e.get("category") or "").lower()
        ]
    if getattr(args, "tag", None):
        wanted = normalize_fl_tag(getattr(args, "tag"))
        entries = [e for e in entries if wanted in failure_entry_tags(e)]
    if getattr(args, "implemented_unproven", False):
        entries = [e for e in entries if fl_entry_is_implemented_unproven(e)]
    if getattr(args, "date_from", None):
        entries = [e for e in entries if (e.get("date") or "") >= args.date_from]
    if getattr(args, "date_to", None):
        entries = [e for e in entries if (e.get("date") or "") <= args.date_to]
    entries = [
        e
        for e in entries
        if fl_entry_matches_overlay(
            e,
            area=getattr(args, "area", None),
            subsystem=getattr(args, "subsystem", None),
            kind=getattr(args, "kind", None),
            proof_state=getattr(args, "proof_state", None),
            epoch_status=getattr(args, "epoch_status", None),
            complaint_ref=getattr(args, "complaint_ref", None),
            complaint_counter_state=getattr(args, "complaint_counter_state", None),
            code_ref=getattr(args, "code_ref", None),
            touched_file=getattr(args, "touched_file", None),
        )
    ]
    payload_entries = []
    rows = []
    for e in reversed(entries):
        payload_entry = {
            "fl": e["fl"],
            "ledger": fl_ledger_state(e),
            "status": fl_status_display(e),
            "gate": e.get("gate") or "",
            "category": e.get("category") or "",
            "date": e.get("date") or "",
            "title": e.get("title") or "",
        }
        payload_entries.append(payload_entry)
        rows.append(
            [
                payload_entry["fl"],
                payload_entry["ledger"],
                payload_entry["status"][:20],
                payload_entry["gate"] or "-",
                payload_entry["category"] or "-",
                payload_entry["date"] or "-",
                payload_entry["title"][:45] or "-",
            ]
        )
    if getattr(args, "json", False):
        print(json.dumps({
            "ok": True,
            "command": "fl list",
            "matched_count": len(payload_entries),
            "entries": payload_entries,
        }, indent=2))
        return
    headers = ["FL-ID", "LEDGER", "STATUS", "GATE", "CATEGORY", "DATE", "TITLE"]
    print_table(headers, rows)
    print(f"\n{len(rows)} entries matched.")


def _fl_description_correction_banner(entry: dict) -> str:
    """Return the notice that an entry's authored Description was superseded.

    FL-4837: `fl show` prints the RAW markdown block, so a correction that lives
    only in the overlay would leave every reader of this command meeting the
    wrong text with nothing on it. A setter whose value no reader honors is not
    a fix, so this banner is printed ABOVE the block and the raw text is left
    untouched underneath it as the history it now is.
    """
    overlay = _fl_overlay_record(entry) if isinstance(entry, dict) else {}
    correction = str(overlay.get(FL_DESCRIPTION_CORRECTION_FIELD) or "").strip()
    if not correction:
        return ""
    reason = str(overlay.get(FL_DESCRIPTION_CORRECTION_REASON_FIELD) or "").strip()
    lines = [
        "!! DESCRIPTION SUPERSEDED — the **Description:** line below is HISTORY, not current fact.",
        f"   CURRENT: {correction}",
    ]
    if reason:
        lines.append(f"   WHY:     {reason}")
    lines.append(
        "   Full chain: python3 scripts/analyze_runs.py fl description-history "
        f"{str(entry.get('fl') or '').strip()}"
    )
    return "\n".join(lines)


def cmd_fl_description_history(args, root: Path) -> None:
    """Print every Description correction ever written for one entry, oldest first.

    The append-only overlay parts keep every superseded correction, so this is
    the command that makes the retracted claim discoverable rather than merely
    replaced.
    """
    fl_id = _fl_id_arg(args.fl_id)
    fl_path = canonical_failure_log_path(root)
    history = description_correction_history(fl_path, fl_id)
    entry = _lookup_fl_entry(root, fl_id, args=args, command="fl description-history")
    authored = str((entry or {}).get("authored_description") or "").strip()
    payload = {
        "command": "fl description-history",
        "fl": fl_id,
        "authored_description": authored,
        "corrections": history,
        "current_description": history[-1]["description"] if history else authored,
    }
    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2))
        return
    print(f"=== {fl_id} description history ===")
    print(f"[authored]  {authored}")
    for index, record in enumerate(history, start=1):
        label = "current" if index == len(history) else f"superseded #{index}"
        print(f"[{label}]  {record['description']}")
        if record["reason"]:
            print(f"            reason: {record['reason']}")
    if not history:
        print("(no correction has ever been written for this entry)")


def cmd_fl_show(args, root: Path):
    fl_id = args.fl_id.upper()
    if not re.match(r"^FL-\d+$", fl_id):
        sys.exit(f"error: invalid FL ID format: {args.fl_id!r}  (expected FL-NNN)")
    blocks = _fl_extract_raw_blocks(root, fl_id)
    if not blocks:
        if getattr(args, "json", False):
            _emit_fl_json_error(command="fl show", error="not_found", exit_code=2, fl_id=fl_id)
        sys.exit(f"error: {fl_id} not found in docs/FAILURE_LOG.md")
    if len(blocks) == 1:
        text = blocks[0]
        entry = _lookup_fl_entry(root, fl_id, args=args, command="fl show")
        fix_blocks = fl_fix_attempt_blocks(text)
        if getattr(args, "json", False):
            print(json.dumps({
                "fl": fl_id,
                "date": entry.get("date") or "",
                "status": fl_status_display(entry),
                "overlay": _fl_overlay_record(entry),
                "text": text,
                "fix_attempt_blocks": fix_blocks,
                "description_correction": _fl_overlay_record(entry).get(
                    FL_DESCRIPTION_CORRECTION_FIELD, ""
                ),
            }, indent=2))
            return
        banner = _fl_description_correction_banner(entry)
        if banner:
            print(banner)
            print()
        print(text)
        return

    occurrences = _fl_duplicate_occurrences(root, fl_id)
    if getattr(args, "json", False):
        print(json.dumps({
            "fl": fl_id,
            "duplicate_id": True,
            "matches": [
                {
                    "index": item["index"],
                    "title": item["entry"].get("title") or "",
                    "date": item["entry"].get("date") or "",
                    "status": fl_status_display(item["entry"]),
                    "overlay": _fl_overlay_record(item["entry"]),
                    "proof_state": item["proof_state"],
                    "ledger_state": item["ledger_state"],
                    "text": item["raw"],
                    "fix_attempt_blocks": item["fix_attempts"],
                }
                for item in occurrences
            ],
        }, indent=2))
        return
    print(
        f"DUPLICATE ID WARNING: {fl_id} has {len(occurrences)} entries in docs/FAILURE_LOG.md; "
        "showing all matches in file order."
    )
    print()
    for item in occurrences:
        entry = item["entry"]
        print(
            f"[{item['index']}/{len(occurrences)}] "
            f"{entry.get('date') or '-'}  {fl_status_display(entry)}  {entry.get('title') or ''}"
        )
        print(item["raw"])
        if item["index"] != len(occurrences):
            print()
            print("---")
            print()


def _fl_id_arg(value: str) -> str:
    fl_id = value.upper()
    if not fl_id.startswith("FL-") and fl_id.isdigit():
        fl_id = f"FL-{int(fl_id):03d}"
    if not re.match(r"^FL-\d+$", fl_id):
        sys.exit(f"error: invalid FL ID format: {value!r}  (expected FL-NNN)")
    return fl_id


def _fl_duplicate_occurrences(root: Path, fl_id: str) -> list[dict]:
    entries = _lookup_fl_entries(root, fl_id)
    raw_blocks = _fl_extract_raw_blocks(root, fl_id)
    occurrences: list[dict] = []
    for idx, entry in enumerate(entries):
        raw = raw_blocks[idx] if idx < len(raw_blocks) else ""
        occurrences.append(
            {
                "index": idx + 1,
                "entry": entry,
                "raw": raw,
                "proof_state": _fl_overlay_scalar(entry, "ProofState") or "OPEN",
                "ledger_state": fl_ledger_state(entry),
                "gates": fl_entry_gates(root, entry),
                "fix_attempts": fl_fix_attempt_blocks(raw),
            }
        )
    return occurrences


def _entry_family(root: Path, entry: dict, extra_terms: list[str] | None = None) -> list[dict]:
    entries = load_fl_entries(root)
    entries_by_id = {e["fl"]: e for e in entries}
    terms = _title_expansion_terms(entry.get("title") or "")
    terms.extend(_normalize_terms(extra_terms or []))
    expanded = _expand_cluster({entry["fl"]}, entries_by_id, entries, terms)
    return [entries_by_id[fid] for fid in sorted(expanded) if fid in entries_by_id]


# ---------------------------------------------------------------------------
# Human-facing ledger label (FL-4359 operator request).
#
# WHY THIS EXISTS
# ---------------
# Compact states preserve a distinction between an explicitly authored
# IMPLEMENTED proof state and an OPEN proof state. Human output must still lead
# with the canonical status so lack of closure is never hidden.
#
# WHAT THIS DOES
# --------------
# This translates the compact token into an honest human label for card output.
# The shared classifier now refuses to infer implementation from attempt text,
# so an OPEN entry with any number of historical attempts remains OPEN here and
# in every machine-readable surface.
#
# Args:
#     status : the entry's canonical Status field (e.g. "OPEN", "PARTIAL").
#     ledger : the internal ledger token from fl_ledger_state() (e.g.
#              "implemented-unproven", "raw-open-actionable").
# Returns:
#     A short human string that tells the truth: OPEN + why it is not closed.
def _human_ledger_label(status: str, ledger: str) -> str:
    status_up = (status or "").strip().upper()
    if ledger == "implemented-unproven":
        return "OPEN — UNPROVEN (implementation state recorded, no passing proof)"
    if ledger == "raw-open-actionable":
        return "OPEN — actionable"
    if ledger == "failed/rejected":
        return "OPEN — last fix REJECTED"
    if ledger == "resolved-accounted":
        return "RESOLVED"
    if ledger == "monitoring":
        return "MONITORING"
    if ledger == "missing":
        return "MISSING"
    # Anything we do not have a bespoke phrasing for: fall back to the raw token
    # but still prefix the canonical status so OPEN is never hidden.
    if status_up:
        return f"{status_up} — {ledger}"
    return ledger


def cmd_fl_card(args, root: Path):
    fl_id = _fl_id_arg(args.fl_id)
    try:
        occurrences = _fl_duplicate_occurrences(root, fl_id)
    except SystemExit:
        if getattr(args, "json", False):
            _emit_fl_json_error(command="fl card", error="not_found", exit_code=2, fl_id=fl_id)
        raise
    if len(occurrences) == 1:
        entry = occurrences[0]["entry"]
        family = _entry_family(root, entry)
        blocks = occurrences[0]["fix_attempts"]
        last_block = blocks[-1] if blocks else None
        counts = Counter(fl_ledger_state(item) for item in family)
        proof_state = occurrences[0]["proof_state"]
        gates = occurrences[0]["gates"]
        primary_ref = (_extract_file_refs([entry], limit=1) or entry.get("gates") or ["-"])[0]
        priority = _fl_overlay_scalar(entry, "Priority") or "-"

        if getattr(args, "json", False):
            # FL-4022: --raw returns the unsynthesized JSONL overlay row, so
            # callers that just wrote via 'fl add' can verify their CodeRefs /
            # ComplaintRefs round-tripped without falling back to grep.
            if getattr(args, "raw", False):
                overlay_payload = entry.get("overlay")
                if not isinstance(overlay_payload, dict):
                    overlay_payload = None
            else:
                overlay_payload = _fl_overlay_record(entry)
            print(json.dumps({
                "fl": fl_id, "status": fl_status_display(entry), "priority": priority,
                "overlay": overlay_payload,
                "overlay_source": "raw_jsonl" if getattr(args, "raw", False) else "effective",
                "proof_state": proof_state, "ledger_state": fl_ledger_state(entry),
                "gates": gates, "family_size": len(family),
                "fix_attempts": len(blocks), "fix_attempt_blocks": blocks,
                "primary_ref": primary_ref,
            }, indent=2))
            return

        print(
            f"{fl_id}  {fl_status_display(entry)}  {priority}  "
            f"{primary_ref}"
        )
        if last_block:
            suffix = f" ({last_block['suffix']})" if last_block.get("suffix") else ""
            print(f"Last fix: {last_block['date']}{suffix}")
        else:
            print("Last fix: none")
        print(f"Proof state: {proof_state}")
        print(
            "Ledger state: "
            f"{_human_ledger_label(fl_status_display(entry), fl_ledger_state(entry))}"
        )
        family_bits = ", ".join(f"{count} {state}" for state, count in sorted(counts.items()))
        print(f"Family: {len(family)} entries ({family_bits})")
        complaint_state = _fl_overlay_scalar(entry, "ComplaintCounterState")
        if complaint_state:
            print(f"Note: {compact_text(str(complaint_state), max_len=260)}")
        if gates:
            print(f"Next: proof run should observe gate(s): {', '.join(gates)}")
        else:
            print("Next: headed proof run needed — no explicit gate currently maps to this FL")
        return

    payload_matches = []
    for item in occurrences:
        entry = item["entry"]
        blocks = item["fix_attempts"]
        last_block = blocks[-1] if blocks else None
        payload_matches.append(
            {
                "index": item["index"],
                "title": entry.get("title") or "",
                "date": entry.get("date") or "",
                "status": fl_status_display(entry),
                "overlay": _fl_overlay_record(entry),
                "proof_state": item["proof_state"],
                "ledger_state": item["ledger_state"],
                "gates": item["gates"],
                "fix_attempts": len(blocks),
                "fix_attempt_blocks": blocks,
                "last_fix": {
                    "date": last_block.get("date"),
                    "suffix": last_block.get("suffix"),
                } if last_block else None,
            }
        )

    if getattr(args, "json", False):
        print(json.dumps({
            "fl": fl_id,
            "duplicate_id": True,
            "matches": payload_matches,
        }, indent=2))
        return

    print(f"{fl_id}  DUPLICATE ID WARNING  {len(occurrences)} matches")
    print("Normal lookup would be ambiguous; review each occurrence before acting.")
    for item in occurrences:
        entry = item["entry"]
        blocks = item["fix_attempts"]
        last_block = blocks[-1] if blocks else None
        print()
        print(
            f"[{item['index']}/{len(occurrences)}] {entry.get('date') or '-'}  "
            f"{fl_status_display(entry)}  {_human_ledger_label(fl_status_display(entry), item['ledger_state'])}"
        )
        print(f"Title: {entry.get('title') or ''}")
        if last_block:
            suffix = f" ({last_block['suffix']})" if last_block.get("suffix") else ""
            print(f"Last fix: {last_block['date']}{suffix}")
        else:
            print("Last fix: none")
        if item["gates"]:
            print(f"Gates: {', '.join(item['gates'][:4])}")
        else:
            print("Gates: none mapped")


def cmd_fl_prior_attempts(args, root: Path):
    args.full = True
    return cmd_fl_fix_history(args, root)


def fl_entry_gates(root: Path, entry: dict) -> list[str]:
    effective_overlay = effective_fl_overlay_record(
        entry,
        entry.get("overlay") if isinstance(entry.get("overlay"), dict) else None,
        fl_id=str(entry.get("fl") or "").strip().upper(),
    )
    overlay_gates = _normalize_overlay_list_value(
        effective_overlay.get("gates") or effective_overlay.get("GateNames") or []
    )
    gates = list(
        dict.fromkeys(
            overlay_gates
            or entry.get("gates")
            or ([entry["gate"]] if entry.get("gate") else [])
            or _extract_fl_gate_lines(entry)
        )
    )
    if gates:
        fl_id = str(entry.get("fl") or "").strip().upper()
        if fl_id == "FL-4260":
            for supplemental_gate in (
                "evidence_fl4260_termpp_light_updates_cp437_diffuse_shade",
                "evidence_fl4260_material_look_light_updates_profile_cells",
                "evidence_fl4260_material_look_target_edit_scope",
            ):
                if supplemental_gate not in gates:
                    gates.append(supplemental_gate)
        return gates
    fl_id = str(entry.get("fl") or "").strip().upper()
    if fl_id == "FL-4451":
        return [
            "evidence_fl4451_material_look_per_material_isolation",
            "evidence_fl4451_material_look_geometry_invariant",
        ]
    text = _fl_text(entry)
    known_gates = set(load_gap_registry(root))
    for gate_names in FIELD_GATE_MAP.values():
        known_gates.update(gate_names)
    found = []
    for gate in sorted(g for g in known_gates if g):
        if re.search(rf"(?<![A-Za-z0-9_]){re.escape(gate)}(?![A-Za-z0-9_])", text):
            found.append(gate)
    return found


def cmd_fl_gates(args, root: Path):
    fl_id = _fl_id_arg(args.fl_id)
    entry = _lookup_fl_entry(root, fl_id, args=args, command="fl gates")
    gates = fl_entry_gates(root, entry)
    rd = runs_dir(root)
    all_runs: list[dict[str, Any]] = []
    if rd.exists():
        all_runs, _ = load_all_runs(root)
    static_states = _fl_static_gate_states(root, fl_id)
    if getattr(args, "json", False):
        rows = []
        for gate in gates:
            run, state = _latest_gate_run(all_runs, gate)
            rows.append(
                {
                    "gate": gate,
                    "state": static_states.get(gate) or state or "open",
                    "source": "static" if gate in static_states else ("run" if state else "missing"),
                    "latest_run": _run_reference_payload(root, run),
                }
            )
        print(json.dumps({"fl": fl_id, "gates": gates, "gate_states": rows}, indent=2))
        return
    if not gates:
        print(f"No explicit gate mapping found for {fl_id}.")
        return
    gaps = load_gap_registry(root)
    print(f"Gates for {fl_id} ({len(gates)}):")
    for gate in gates:
        gap = gaps.get(gate) or {}
        wg = gap.get("id") or "-"
        run, state = _latest_gate_run(all_runs, gate)
        if gate in static_states:
            display = static_states[gate]
        elif state:
            display = state.upper()
        elif wg != "-":
            display = wg
        else:
            display = "OPEN"
        print(f"  {gate:<55}  {display}")


def _fl_static_gate_states(root: Path, fl_id: str) -> dict[str, str]:
    if fl_id == "FL-4451":
        isolation_gate = "evidence_fl4451_material_look_per_material_isolation"
        geometry_gate = "evidence_fl4451_material_look_geometry_invariant"
        summary_path = (
            root
            / "docs"
            / "research"
            / "ascii"
            / "verification"
            / "fl4260"
            / "2026-06-24-FL4451-per-material-isolation"
            / "summary.json"
        )
        geometry_path = (
            root
            / "docs"
            / "research"
            / "ascii"
            / "verification"
            / "fl4260"
            / "2026-06-24-FL4451-per-material-profile-textures"
            / "geometry_invariance_summary.json"
        )
        states: dict[str, str] = {}
        if not summary_path.exists():
            states[isolation_gate] = "OPEN"
        else:
            try:
                payload = json.loads(summary_path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                states[isolation_gate] = "ERROR"
            else:
                warm_noise = int(payload.get("warm_repeat_changed") or 0)
                unused_changed = int(payload.get("unused_changed") or 0)
                used_changed = int(payload.get("used_changed") or 0)
                used_off_material_changed = int(payload.get("used_off_material_changed") or 0)
                used_material = payload.get("used_material")
                used_hist = payload.get("used_hist") if isinstance(payload.get("used_hist"), dict) else {}
                used_target_changed = int(used_hist.get(str(used_material), used_hist.get(used_material, 0)) or 0)
                passes = (
                    payload.get("schema") == "fl4451.clean_isolation.self_contained.v2"
                    and payload.get("verdict") == "PASS"
                    and unused_changed <= max(5, warm_noise + 3)
                    and used_changed > 50
                    and used_target_changed == used_changed
                    and used_off_material_changed <= max(3, warm_noise + 3)
                )
                states[isolation_gate] = "STATIC_PASS" if passes else "STATIC_FAIL"
        if not geometry_path.exists():
            states[geometry_gate] = "OPEN"
        else:
            try:
                geometry_payload = json.loads(geometry_path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                states[geometry_gate] = "ERROR"
            else:
                pairs = geometry_payload.get("pairs") if isinstance(geometry_payload.get("pairs"), list) else []
                geometry_passes = (
                    geometry_payload.get("schema") == "fl4451.geometry_invariance.v2"
                    and geometry_payload.get("verdict") == "PASS"
                    and pairs
                    and all(
                        isinstance(pair, dict)
                        and pair.get("verdict") == "PASS"
                        and not pair.get("bridge_invariant_changed_counts")
                        and int(pair.get("off_target_visual_changed_cells") or 0) == 0
                        for pair in pairs
                    )
                )
                states[geometry_gate] = "STATIC_PASS" if geometry_passes else "STATIC_FAIL"
        return states
    if fl_id != "FL-4260":
        return {}
    def fl4260_light_cp437_state(path: Path) -> str:
        if not path.exists():
            return "OPEN"
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return "ERROR"
        diffs = payload.get("diffs") if isinstance(payload.get("diffs"), dict) else {}
        if not diffs:
            return "STATIC_FAIL"
        passes = bool(payload.get("pass"))
        for row in diffs.values():
            if not isinstance(row, dict):
                passes = False
                continue
            passes = passes and bool(row.get("pass"))
            passes = passes and int(row.get("terrain_cells") or 0) > 0
            passes = passes and int(row.get("sample_diffuses_changed") or 0) > 0
            passes = passes and int(row.get("terrain_resolve_shade_changed") or 0) > 0
            passes = passes and int(row.get("material_id_changed") or 0) == 0
            passes = passes and int(row.get("dispatch_surface_changed") or 0) == 0
            passes = passes and int(row.get("resolve_elev_changed") or 0) == 0
            visible_delta = (
                int(row.get("fg_changed") or 0)
                + int(row.get("bg_changed") or 0)
                + int(row.get("cp437_changed") or 0)
                + int(row.get("final_gid_changed") or 0)
            )
            passes = passes and visible_delta > 0
        return "STATIC_PASS" if passes else "STATIC_FAIL"

    def fl4260_light_profile_state(path: Path) -> str:
        if not path.exists():
            return "OPEN"
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return "ERROR"
        diffs = payload.get("diffs") if isinstance(payload.get("diffs"), dict) else {}
        if payload.get("mode") != "PROFILE_WITH_HARRI" or not diffs:
            return "STATIC_FAIL"
        passes = bool(payload.get("pass")) and int(payload.get("target_material") or -1) >= 0
        for row in diffs.values():
            if not isinstance(row, dict):
                passes = False
                continue
            passes = passes and bool(row.get("pass"))
            passes = passes and int(row.get("target_cells") or 0) > 0
            passes = passes and int(row.get("target_sample_diffuses_changed") or 0) > 0
            passes = passes and int(row.get("target_resolve_shade_changed") or 0) > 0
            passes = passes and int(row.get("target_final_changed") or 0) > 0
            passes = passes and int(row.get("material_id_changed") or 0) == 0
            passes = passes and int(row.get("dispatch_surface_changed") or 0) == 0
            passes = passes and int(row.get("resolve_elev_changed") or 0) == 0
            visible_color_delta = int(row.get("target_fg_changed") or 0) + int(row.get("target_bg_changed") or 0)
            passes = passes and visible_color_delta > 0
        return "STATIC_PASS" if passes else "STATIC_FAIL"

    def fl4260_target_edit_scope_state(path: Path) -> str:
        if not path.exists():
            return "OPEN"
        try:
            payload = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return "ERROR"
        acceptance = payload.get("acceptance") if isinstance(payload.get("acceptance"), dict) else {}
        pairs = payload.get("pairs") if isinstance(payload.get("pairs"), list) else []
        target_pair = None
        for pair in pairs:
            if isinstance(pair, dict) and pair.get("test") == "profile_target_edit":
                target_pair = pair
                break
        source_shot = payload.get("source_shot") if isinstance(payload.get("source_shot"), dict) else {}
        render_report = source_shot.get("render_report") if isinstance(source_shot.get("render_report"), dict) else {}
        passes = (
            payload.get("schema") == "fl4260.termpp.absolute_scope_matrix.v1"
            and payload.get("verdict") == "PASS"
            and bool(acceptance.get("cp437_repeat_stable"))
            and bool(acceptance.get("profile_initial_policy_scope"))
            and bool(acceptance.get("profile_edit_selected_material_scope"))
            and bool(acceptance.get("observe_render_euclidean"))
            and int(render_report.get("s3_active") or 0) == 0
            and isinstance(target_pair, dict)
            and int(target_pair.get("changed_total") or 0) > 0
            and int(target_pair.get("changed_non_target_material") or 0) == 0
            and int(target_pair.get("changed_non_terrain_dispatch") or 0) == 0
            and int(target_pair.get("black_regression_cells") or 0) == 0
        )
        return "STATIC_PASS" if passes else "STATIC_FAIL"

    light_cp437_gate = "evidence_fl4260_termpp_light_updates_cp437_diffuse_shade"
    light_profile_gate = "evidence_fl4260_material_look_light_updates_profile_cells"
    target_scope_gate = "evidence_fl4260_material_look_target_edit_scope"
    light_cp437_path = (
        root
        / "docs"
        / "research"
        / "ascii"
        / "verification"
        / "fl4260"
        / "2026-06-24-termpp-cp437-per-slider-light-clean-upstream-map-current-diffuse-bridge"
        / "per_slider_light_summary.json"
    )
    light_profile_path = (
        root
        / "docs"
        / "research"
        / "ascii"
        / "verification"
        / "fl4260"
        / "2026-06-24-termpp-profile-light-color-current-nonblack-bg-source-guard"
        / "profile_light_summary.json"
    )
    light_states = {
        light_cp437_gate: fl4260_light_cp437_state(light_cp437_path),
        light_profile_gate: fl4260_light_profile_state(light_profile_path),
        target_scope_gate: fl4260_target_edit_scope_state(
            root
            / "docs"
            / "research"
            / "ascii"
            / "verification"
            / "fl4260"
            / "2026-06-24-observe-render-euclidean-scope-final"
            / "absolute_scope_matrix.json"
        ),
    }
    return light_states


def _metrics_gate_state_map_for_run(run: dict) -> dict[str, str]:
    cached = run.get("_metrics_gate_state_map")
    if isinstance(cached, dict):
        return cached
    state_map: dict[str, str] = {}
    try:
        metrics, _ = _load_metrics_for_run(run)
    except SystemExit:
        state_map = {}
    except Exception:
        state_map = {}
    else:
        for key, value in (metrics.get("gates") or {}).items():
            if value is True:
                state_map[str(key)] = "true"
            elif value is False:
                state_map[str(key)] = "false"
            else:
                state_map[str(key)] = "null"
    run["_metrics_gate_state_map"] = state_map
    return state_map


def _gate_state_for_run(run: dict, gate: str) -> str | None:
    if gate in set(run.get("false_gates") or []):
        return "false"
    if gate in set(run.get("null_gates") or []):
        return "null"
    if gate in set(run.get("true_gates") or []):
        return "true"
    return _metrics_gate_state_map_for_run(run).get(gate)


def _run_reference_payload(root: Path, run: dict | None) -> dict[str, Any] | None:
    if not run:
        return None
    run_id = str(run.get("run_id") or "")
    summary_path = runs_dir(root) / run_id / "summary.json" if run_id else None
    return {
        "run_id": run_id or None,
        "date": (run.get("started_at_utc") or "")[:10] or None,
        "started_at_utc": run.get("started_at_utc"),
        "commit": (run.get("git_head") or "")[:8] or None,
        "git_head": run.get("git_head"),
        "verdict": run.get("verdict"),
        "artifact_path": run.get("artifact_path"),
        "archive_path": run.get("archive_path"),
        "summary_path": str(summary_path) if summary_path and summary_path.exists() else None,
    }


def _latest_gate_run(all_runs: list[dict], gate: str) -> tuple[dict | None, str | None]:
    for run in all_runs:
        state = _gate_state_for_run(run, gate)
        if state:
            return run, state
    return None, None


def _latest_gate_pass_fail_runs(all_runs: list[dict], gate: str) -> tuple[dict | None, dict | None]:
    last_fail: dict | None = None
    last_pass: dict | None = None
    for run in all_runs:
        state = _gate_state_for_run(run, gate)
        if state in {"false", "null"} and last_fail is None:
            last_fail = run
        elif state == "true" and last_pass is None:
            last_pass = run
        if last_fail and last_pass:
            break
    return last_fail, last_pass


def _fl_entry_run_matches(root: Path, gates: list[str], all_runs: list[dict], limit: int) -> list[dict[str, Any]]:
    matches: list[dict[str, Any]] = []
    for run in all_runs:
        gate_states = {
            gate: state
            for gate in gates
            if (state := _gate_state_for_run(run, gate))
        }
        if not gate_states:
            continue
        payload = _run_reference_payload(root, run) or {}
        payload["matching_gates"] = sorted(gate_states)
        payload["gate_states"] = gate_states
        payload["gate_fail_count"] = sum(1 for state in gate_states.values() if state == "false")
        payload["gate_null_count"] = sum(1 for state in gate_states.values() if state == "null")
        payload["gate_true_count"] = sum(1 for state in gate_states.values() if state == "true")
        matches.append(payload)
        if len(matches) >= limit:
            break
    return matches


def _fl_review_matched_runs(
    root: Path,
    gates: list[str],
    all_runs: list[dict],
    limit: int,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    matched_runs: list[dict[str, Any]] = []
    matched_payloads: list[dict[str, Any]] = []
    for run in all_runs:
        gate_states = {
            gate: state
            for gate in gates
            if (state := _gate_state_for_run(run, gate))
        }
        if not gate_states:
            continue
        payload = _run_reference_payload(root, run) or {}
        payload["matching_gates"] = sorted(gate_states)
        payload["gate_states"] = gate_states
        payload["gate_fail_count"] = sum(1 for state in gate_states.values() if state == "false")
        payload["gate_null_count"] = sum(1 for state in gate_states.values() if state == "null")
        payload["gate_true_count"] = sum(1 for state in gate_states.values() if state == "true")
        matched_runs.append(run)
        matched_payloads.append(payload)
        if len(matched_payloads) >= limit:
            break
    return matched_runs, matched_payloads


def _fl_review_changed_functions_summary(changed_functions: dict[str, Any] | None) -> str | None:
    if not isinstance(changed_functions, dict) or not changed_functions:
        return None
    rendered = []
    for path, names in changed_functions.items():
        if not isinstance(names, list) or not names:
            continue
        rendered.append(f"{path}: {', '.join(str(name) for name in names[:3])}")
    if not rendered:
        return None
    return "; ".join(rendered[:4])


def _fl_review_receipt_payload(root: Path, run: dict[str, Any] | None) -> dict[str, Any] | None:
    if not run:
        return None
    run_intent = run.get("run_intent") if isinstance(run.get("run_intent"), dict) else {}
    diff_spec = _resolve_intent_diff_spec(run)
    corpora = diff_spec.get("corpora") or []
    pathspecs = diff_spec.get("paths") or []
    snapshot = (
        _stored_receipt_diff_payload(
            run,
            requested_corpora=corpora,
            pathspecs=pathspecs,
            strategy="fl_review",
            note="latest matched run receipt snapshot",
        )
        if diff_spec.get("diff_snapshot")
        else None
    )
    aggregate = (
        _stored_receipt_aggregate_payload(
            run,
            requested_corpora=corpora,
            pathspecs=pathspecs,
        )
        if diff_spec.get("aggregate_since_previous_comparable_run")
        else None
    )
    payload: dict[str, Any] = {
        "source": "run",
        "run": _run_reference_payload(root, run),
        "intent_summary": run_intent.get("summary"),
        "introduced_by": list(run_intent.get("introduced_by") or []),
        "fix_attempts": list(run_intent.get("fix_attempts") or []),
        "baseline_runs": list(run_intent.get("baseline_runs") or []),
        "required_fields": list(run_intent.get("required_fields") or []),
        "fix_commits": list(run_intent.get("fix_commits") or []),
        "fix_commit_warnings": list(run_intent.get("fix_commit_warnings") or []),
        "diff": {
            "corpora": corpora,
            "mode": diff_spec.get("mode"),
            "paths": list(pathspecs),
            "base_commit_resolved": diff_spec.get("base_commit_resolved"),
            "head_commit_resolved": diff_spec.get("head_commit_resolved"),
            "resolved_at": diff_spec.get("resolved_at"),
            "resolution_strategy": diff_spec.get("resolution_strategy"),
            "resolution_warning": diff_spec.get("resolution_warning"),
            "resolution_error": diff_spec.get("resolution_error"),
        },
        "diff_snapshot": None,
        "aggregate_since_previous_comparable_run": None,
        "code_surface_unchanged": None,
    }
    if snapshot:
        payload["diff_snapshot"] = {
            "state": snapshot.get("state"),
            "files_changed": snapshot.get("files_changed") or [],
            "insertions": snapshot.get("insertions") or 0,
            "deletions": snapshot.get("deletions") or 0,
            "patch_sha256": snapshot.get("patch_sha256"),
            "changed_functions": snapshot.get("changed_functions") or {},
        }
    if aggregate:
        payload["aggregate_since_previous_comparable_run"] = {
            "state": aggregate.get("state"),
            "basis": aggregate.get("basis"),
            "previous_anchor": aggregate.get("previous_anchor"),
            "current_anchor": aggregate.get("current_anchor"),
            "files_changed": aggregate.get("files_changed") or [],
            "insertions": aggregate.get("insertions") or 0,
            "deletions": aggregate.get("deletions") or 0,
            "patch_sha256": aggregate.get("patch_sha256"),
            "changed_functions": aggregate.get("changed_functions") or {},
            "code_surface_unchanged": bool(aggregate.get("code_surface_unchanged")),
        }
        payload["code_surface_unchanged"] = bool(aggregate.get("code_surface_unchanged"))
    elif snapshot:
        payload["code_surface_unchanged"] = snapshot.get("state") in {
            "no_source_delta",
            "fix_commit_no_source_delta",
            "latest_relevant_fallback_no_source_delta",
        }
    return payload


def _fl_family_ledger_receipt_matches(
    root: Path,
    family: list[dict[str, Any]],
    *,
    limit: int,
) -> list[dict[str, Any]]:
    family_ids = {
        str(item.get("fl") or "").strip().upper()
        for item in family
        if str(item.get("fl") or "").strip()
    }
    for item in family:
        overlay = _fl_overlay_record(item)
        for ref in overlay.get("ComplaintRefs") or []:
            ref_norm = str(ref or "").strip().upper()
            if ref_norm.startswith("FL-"):
                family_ids.add(ref_norm)
    if not family_ids:
        return []
    try:
        payload = build_multiplayer_ledger_receipt_payload(root)
    except SystemExit:
        return []
    matches = []
    for item in payload.get("receipts") or []:
        fl_ids = {
            str(fl_id or "").strip().upper()
            for fl_id in (item.get("fl_ids") or [])
            if str(fl_id or "").strip()
        }
        if family_ids.intersection(fl_ids):
            matches.append(item)
    def _ledger_sort_key(r: dict[str, Any]) -> int:
        try:
            return int(r.get("ledger_line") or 0)
        except (ValueError, TypeError):
            return 0

    matches.sort(key=_ledger_sort_key, reverse=True)
    return matches[:max(0, limit)]


def _fl_ledger_receipt_payload(root: Path, receipt: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(receipt, dict):
        return None
    anchors = receipt.get("anchors") or {}
    runs_found = anchors.get("runs_found") or []
    primary_run = runs_found[0] if runs_found else {}
    run_ref = None
    run_id = str(primary_run.get("run_id") or "").strip()
    if run_id:
        try:
            run = load_run_by_id(root, run_id)
        except SystemExit:
            run = None
        if run:
            run_ref = _run_reference_payload(root, run)
        else:
            run_ref = {
                "run_id": run_id,
                "summary_path": primary_run.get("summary_path"),
                "commit": primary_run.get("git_head") or primary_run.get("git_head_full"),
                "verdict": primary_run.get("verdict"),
            }
    return {
        "source": _FL_LEDGER_RECEIPT_SOURCE,
        "ledger_line": receipt.get("ledger_line"),
        "header": receipt.get("header"),
        "date_context": receipt.get("date_context"),
        "title": receipt.get("title"),
        "receipt_class": receipt.get("receipt_class"),
        "basis": receipt.get("basis"),
        "fl_ids": list(receipt.get("fl_ids") or []),
        "run": run_ref,
        "run_ids": list(receipt.get("run_ids") or []),
        "commit_refs": list(receipt.get("commit_refs") or []),
        "anchors": anchors,
        "aggregate_code_surface": receipt.get("aggregate_code_surface"),
        "receipt": receipt.get("receipt") or {},
        "evidence_gap": receipt.get("evidence_gap"),
        "code_surface_unchanged": (receipt.get("aggregate_code_surface") or {}).get("code_surface_unchanged"),
    }


def _print_ledger_receipts_text(receipts: list[dict[str, Any]]) -> None:
    """Render a list of raw ledger receipt rows as human-readable text."""
    print("  Matching ledger receipts:")
    for item in receipts:
        runs = ", ".join(item.get("run_ids") or []) or "-"
        commits = ", ".join(item.get("commit_refs") or []) or "-"
        print(
            f"    L{item.get('ledger_line')}: {item.get('receipt_class')}  "
            f"runs={runs}  commits={commits}  fls={', '.join(item.get('fl_ids') or [])}"
        )


def cmd_fl_review(args, root: Path):
    fl_id = _fl_id_arg(args.fl_id)
    try:
        occurrences = _fl_duplicate_occurrences(root, fl_id)
    except SystemExit:
        if getattr(args, "json", False):
            _emit_fl_json_error(command="fl review", error="not_found", exit_code=2, fl_id=fl_id)
        raise

    if len(occurrences) != 1:
        if getattr(args, "json", False):
            print(
                json.dumps(
                    {
                        "ok": False,
                        "command": "fl review",
                        "fl_id": fl_id,
                        "error": "duplicate_id",
                        "matches": [
                            {
                                "index": item["index"],
                                "date": item["entry"].get("date") or "",
                                "status": fl_status_display(item["entry"]),
                                "title": item["entry"].get("title") or "",
                            }
                            for item in occurrences
                        ],
                    },
                    indent=2,
                )
            )
            return
        print(f"FL REVIEW: {fl_id}")
        print("  duplicate id detected; review `python3 scripts/analyze_runs.py fl show "
              f"{fl_id}` before using a merged review surface.")
        return

    entry = occurrences[0]["entry"]
    family = _entry_family(root, entry)
    family_rows = [
        {
            "fl": item["fl"],
            "date": item.get("date") or "",
            "status": fl_status_display(item),
            "proof_state": _fl_overlay_scalar(item, "ProofState") or "OPEN",
            "ledger_state": fl_ledger_state(item),
            "title": item.get("title") or "",
        }
        for item in family
    ]
    family_counts = Counter(fl_ledger_state(item) for item in family)
    gates = fl_entry_gates(root, entry)
    required_fields = fl_required_fields_advisory_for_id(root, fl_id)
    all_runs, _ = load_all_runs(root)
    limit = getattr(args, "limit", 10) or 10
    matched_runs, recent_runs = _fl_review_matched_runs(root, gates, all_runs, limit)
    latest_run = matched_runs[0] if matched_runs else None
    latest_receipt = _fl_review_receipt_payload(root, latest_run)
    ledger_receipts = _fl_family_ledger_receipt_matches(root, family, limit=limit)
    if latest_receipt is None and ledger_receipts:
        latest_receipt = _fl_ledger_receipt_payload(root, ledger_receipts[0])
    gate_rows = []
    for gate in gates:
        run, state = _latest_gate_run(all_runs, gate)
        gate_rows.append(
            {
                "gate": gate,
                "latest_state": state,
                "latest_run": _run_reference_payload(root, run),
            }
        )

    payload = {
        "ok": True,
        "command": "fl review",
        "fl": fl_id,
        "title": entry.get("title") or "",
        "date": entry.get("date") or "",
        "status": fl_status_display(entry),
        "overlay": _fl_overlay_record(entry),
        "proof_state": _fl_overlay_scalar(entry, "ProofState") or "OPEN",
        "ledger_state": fl_ledger_state(entry),
        "gates": gates,
        "required_fields": required_fields,
        "fix_attempt_blocks": occurrences[0]["fix_attempts"],
        "family": {
            "size": len(family_rows),
            "counts": dict(family_counts),
            "entries": family_rows,
        },
        "recent_runs": recent_runs,
        "gate_latest": gate_rows,
        "latest_receipt_provenance": latest_receipt,
        "ledger_receipts": ledger_receipts,
    }

    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2))
        return

    print(f"FL REVIEW: {fl_id}")
    print(f"  title:    {(entry.get('title') or '')[:120]}")
    print(f"  status:   {fl_status_display(entry)}")
    print(f"  proof:    {payload['proof_state']} / {payload['ledger_state']}")
    if gates:
        print(f"  gates:    {', '.join(gates)}")
    req_fields = required_fields.get("required_fields") or []
    req_source = required_fields.get("source") or "none"
    if req_fields:
        print(f"  required: {', '.join(req_fields)}")
        print(f"  req src:  {req_source}")
    family_bits = ", ".join(f"{count} {state}" for state, count in sorted(family_counts.items()))
    print(f"  family:   {len(family_rows)} entries ({family_bits})")
    print()

    print("--- RECENT RUNS ---")
    if not recent_runs:
        print("  no matching runs found for mapped gates")
    else:
        headers = ["RUN ID", "DATE", "COMMIT", "VERDICT", "FAIL", "NULL"]
        rows = [
            [
                item.get("run_id") or "-",
                item.get("date") or "-",
                item.get("commit") or "-",
                item.get("verdict") or "-",
                item.get("gate_fail_count") or 0,
                item.get("gate_null_count") or 0,
            ]
            for item in recent_runs
        ]
        print_table(headers, rows)
        print()

    print("--- GATE LATEST ---")
    if not gate_rows:
        print("  no explicit gate mapping found")
    else:
        headers = ["GATE", "STATE", "RUN ID", "DATE", "COMMIT"]
        rows = []
        for item in gate_rows:
            latest = item.get("latest_run") or {}
            rows.append(
                [
                    item.get("gate") or "-",
                    (item.get("latest_state") or "-").upper(),
                    latest.get("run_id") or "-",
                    latest.get("date") or "-",
                    latest.get("commit") or "-",
                ]
            )
        print_table(headers, rows)
        print()

    print("--- LATEST RECEIPT ---")
    if not latest_receipt:
        print("  no run receipt provenance found")
        return
    if latest_receipt.get("source") == "multiplayer_ledger":
        print(f"  source:    multiplayer ledger line {latest_receipt.get('ledger_line')}")
        if latest_receipt.get("receipt_class"):
            print(f"  class:     {latest_receipt.get('receipt_class')}")
        if latest_receipt.get("basis"):
            print(f"  basis:     {compact_text(str(latest_receipt.get('basis') or ''), max_len=160)}")
    latest_run_ref = latest_receipt.get("run") or {}
    print(f"  run:       {latest_run_ref.get('run_id') or '-'}")
    if latest_receipt.get("intent_summary"):
        print(f"  intent:    {compact_text(str(latest_receipt.get('intent_summary') or ''), max_len=160)}")
    if latest_receipt.get("fix_attempts"):
        print(f"  fixes:     {', '.join(str(v) for v in latest_receipt['fix_attempts'])}")
    if latest_receipt.get("fix_commits"):
        print(f"  commits:   {', '.join(str(v) for v in latest_receipt['fix_commits'])}")
    warnings = latest_receipt.get("fix_commit_warnings") or []
    if warnings:
        rendered = []
        for warning in warnings:
            if isinstance(warning, dict):
                rendered.append(f"{warning.get('input') or '?'} ({warning.get('reason') or 'unresolved'})")
            else:
                rendered.append(str(warning))
        print(f"  fix warn:  {', '.join(rendered)}")
    diff = latest_receipt.get("diff") or {}
    if diff.get("corpora") or diff.get("mode"):
        print(
            "  diff:      "
            f"{diff_corpus_label(diff.get('corpora'))} mode={diff.get('mode') or 'between_runs'}"
        )
    if diff.get("base_commit_resolved") or diff.get("head_commit_resolved"):
        print(
            "  diff revs: "
            f"{diff.get('base_commit_resolved') or '-'} -> {diff.get('head_commit_resolved') or '-'}"
        )
    if diff.get("resolution_strategy") or diff.get("resolved_at"):
        print(
            "  diff proof:"
            f" {diff.get('resolution_strategy') or '-'}"
            + (f" @ {diff.get('resolved_at')}" if diff.get("resolved_at") else "")
        )
    if diff.get("resolution_warning"):
        print(f"  diff warn: {diff.get('resolution_warning')}")
    if diff.get("resolution_error"):
        print(f"  diff error:{diff.get('resolution_error')}")
    snapshot = latest_receipt.get("diff_snapshot") or {}
    if snapshot:
        counts = (
            f"{len(snapshot.get('files_changed') or [])} files, "
            f"+{snapshot.get('insertions') or 0}/-{snapshot.get('deletions') or 0}"
        )
        print(f"  diff state:{snapshot.get('state') or '-'} ({counts})")
        if snapshot.get("patch_sha256"):
            print(f"  diff hash: {snapshot.get('patch_sha256')}")
        funcs = _fl_review_changed_functions_summary(snapshot.get("changed_functions"))
        if funcs:
            print(f"  diff funcs:{funcs}")
    aggregate = latest_receipt.get("aggregate_since_previous_comparable_run") or {}
    if aggregate:
        previous_anchor = aggregate.get("previous_anchor") if isinstance(aggregate.get("previous_anchor"), dict) else {}
        current_anchor = aggregate.get("current_anchor") if isinstance(aggregate.get("current_anchor"), dict) else {}
        previous_label = previous_anchor.get("run_id") or previous_anchor.get("head") or previous_anchor.get("commit_ref") or "-"
        current_label = current_anchor.get("run_id") or current_anchor.get("head") or latest_run_ref.get("run_id") or "-"
        print(f"  agg prev:  {previous_label} -> {current_label}")
        if aggregate.get("basis"):
            print(f"  agg basis: {aggregate.get('basis')}")
        counts = (
            f"{len(aggregate.get('files_changed') or [])} files, "
            f"+{aggregate.get('insertions') or 0}/-{aggregate.get('deletions') or 0}"
        )
        print(f"  agg state: {aggregate.get('state') or '-'} ({counts})")
        if aggregate.get("patch_sha256"):
            print(f"  agg hash:  {aggregate.get('patch_sha256')}")
        funcs = _fl_review_changed_functions_summary(aggregate.get("changed_functions"))
        if funcs:
            print(f"  agg funcs: {funcs}")
        print(
            "  surface:   "
            + ("unchanged since previous comparable run" if aggregate.get("code_surface_unchanged") else "changed since previous comparable run")
        )


def cmd_fl_entry_runs(args, root: Path):
    """Show runs that tested gates from an FL entry (fl entry-runs FL-NNN)."""
    fl_id = _fl_id_arg(args.fl_id)
    entry = _lookup_fl_entry(root, fl_id, args=args, command="fl entry-runs")
    gates = fl_entry_gates(root, entry)
    family = _entry_family(root, entry)
    _raw_limit = getattr(args, "limit", None)
    limit = 20 if _raw_limit is None else _raw_limit
    ledger_receipts = _fl_family_ledger_receipt_matches(root, family, limit=limit)
    if not gates:
        if getattr(args, "json", False):
            print(json.dumps({
                "fl": fl_id,
                "gates": [],
                "runs_scanned": 0,
                "matched_runs": 0,
                "runs": [],
                "matched_receipts": len(ledger_receipts),
                "ledger_receipts": ledger_receipts,
            }, indent=2))
            return
        print(f"ENTRY-RUNS: {fl_id}  gates=0  runs-scanned=0  matched=0  matched-receipts={len(ledger_receipts)}")
        print("  No explicit gate mapping found.\n")
        if not ledger_receipts:
            print("  No matching ledger receipts found for this FL family.")
            return
        _print_ledger_receipts_text(ledger_receipts)
        return

    all_runs, _ = load_all_runs(root)
    matched = _fl_entry_run_matches(root, gates, all_runs, limit)

    if getattr(args, "json", False):
        print(json.dumps({
            "fl": fl_id,
            "gates": gates,
            "runs_scanned": len(all_runs),
            "matched_runs": len(matched),
            "runs": matched,
            "matched_receipts": len(ledger_receipts),
            "ledger_receipts": ledger_receipts,
        }, indent=2))
        return

    print(f"ENTRY-RUNS: {fl_id}  gates={len(gates)}  runs-scanned={len(all_runs)}  matched={len(matched)}")
    print(f"  Gates: {', '.join(gates[:6])}{'...' if len(gates) > 6 else ''}\n")
    if not matched:
        print("  No runs found with these gates in false/null/true sets.")
        if ledger_receipts:
            print()
            _print_ledger_receipts_text(ledger_receipts)
        return

    headers = ["RUN ID", "DATE", "COMMIT", "VERDICT", "GATE FAILS", "GATE NULLS"]
    rows = []
    for record in matched:
        rows.append([
            record.get("run_id") or "-",
            record.get("date") or "-",
            record.get("commit") or "-",
            record.get("verdict") or "-",
            record.get("gate_fail_count") or 0,
            record.get("gate_null_count") or 0,
        ])
    print_table(headers, rows)
    print()
    for record in matched:
        gate_bits = ", ".join(
            f"{gate}={state}" for gate, state in sorted((record.get("gate_states") or {}).items())
        )
        print(f"  {record.get('run_id')}: {gate_bits}")
        if record.get("artifact_path"):
            print(f"    artifact: {record['artifact_path']}")
        if record.get("summary_path"):
            print(f"    summary:  {record['summary_path']}")


def cmd_fl_gates_with_runs(args, root: Path):
    fl_id = _fl_id_arg(args.fl_id)
    entry = _lookup_fl_entry(root, fl_id, args=args, command="fl gates-with-runs")
    gates = fl_entry_gates(root, entry)
    static_states = _fl_static_gate_states(root, fl_id)

    if not gates:
        if getattr(args, "json", False):
            print(json.dumps({"fl": fl_id, "has_gates": False, "gates": []}, indent=2))
        else:
            print(f"GATES-WITH-RUNS: {fl_id}\n  No explicit gate mapping found.")
        return

    rd = runs_dir(root)
    all_runs = []
    if rd.exists():
        all_runs, _ = load_all_runs(root)
    rows_payload = []
    for gate in gates:
        run, state = _latest_gate_run(all_runs, gate)
        rows_payload.append(
            {
                "gate": gate,
                "latest_state": static_states.get(gate) or state,
                "source": "static" if gate in static_states else ("run" if state else "missing"),
                "latest_run": _run_reference_payload(root, run),
            }
        )

    if getattr(args, "json", False):
        print(json.dumps({"fl": fl_id, "has_gates": True, "gates": rows_payload}, indent=2))
        return

    print(f"GATES-WITH-RUNS: {fl_id}\n")
    if not rows_payload:
        print("  No explicit gate mapping found.")
        return
    headers = ["GATE", "STATE", "RUN ID", "DATE", "COMMIT", "VERDICT"]
    rows = []
    for item in rows_payload:
        latest = item.get("latest_run") or {}
        rows.append([
            item.get("gate") or "-",
            (item.get("latest_state") or "-").upper(),
            latest.get("run_id") or "-",
            latest.get("date") or "-",
            latest.get("commit") or "-",
            latest.get("verdict") or "-",
        ])
    print_table(headers, rows)
    print()
    for item in rows_payload:
        latest = item.get("latest_run") or {}
        if latest.get("artifact_path"):
            print(f"  {item['gate']}: {latest['artifact_path']}")


def cmd_fl_by_gate(args, root: Path):
    """Show FL entries citing a gate and the gate's most recent run state (fl by-gate GATE)."""
    gate = args.gate_name
    entries = load_fl_entries(root)
    all_runs, _ = load_all_runs(root)
    limit = getattr(args, "limit", 20) or 20

    citing = [e for e in entries if gate in (e.get("gates") or ([e.get("gate")] if e.get("gate") else []))]
    # Fallback: text search if structured gates empty
    if not citing:
        citing = [e for e in entries if gate in _fl_text(e)]

    last_false_run, last_true_run = _latest_gate_pass_fail_runs(all_runs, gate)
    latest_run, latest_state = _latest_gate_run(all_runs, gate)
    payload_entries = []
    for entry in citing[:limit]:
        item = {
            "fl": entry.get("fl"),
            "date": entry.get("date") or "",
            "status": fl_status_display(entry),
            "proof_state": _fl_overlay_scalar(entry, "ProofState") or "OPEN",
            "ledger_state": fl_ledger_state(entry),
            "title": entry.get("title") or "",
            "gates": fl_entry_gates(root, entry),
        }
        if getattr(args, "with_runs", False):
            item["latest_run"] = _run_reference_payload(root, latest_run)
            item["latest_state"] = latest_state
        payload_entries.append(item)

    if getattr(args, "json", False):
        print(json.dumps({
            "gate": gate,
            "last_fail_run": _run_reference_payload(root, last_false_run),
            "last_pass_run": _run_reference_payload(root, last_true_run),
            "latest_run": _run_reference_payload(root, latest_run),
            "latest_state": latest_state,
            "entries": payload_entries,
        }, indent=2))
        return

    print(f"BY-GATE: {gate}")
    if last_false_run:
        run_id = last_false_run.get("run_id") or "?"
        sha = (last_false_run.get("git_head") or "?")[:8]
        date_s = (last_false_run.get("started_at_utc") or "?")[:10]
        print(f"  Last FAIL:  {run_id} @ {sha}  ({date_s})")
    else:
        print("  Last FAIL:  (none in scanned runs)")
    if last_true_run:
        run_id = last_true_run.get("run_id") or "?"
        sha = (last_true_run.get("git_head") or "?")[:8]
        date_s = (last_true_run.get("started_at_utc") or "?")[:10]
        print(f"  Last PASS:  {run_id} @ {sha}  ({date_s})")
    else:
        print("  Last PASS:  (none in scanned runs)")

    print(f"\nFL entries citing '{gate}' ({len(citing)}):")
    if not citing:
        print("  (none found)")
        return
    if getattr(args, "with_runs", False):
        headers = ["FL", "STATUS", "DATE", "LAST RUN", "STATE", "TITLE"]
        rows = []
        for item in payload_entries:
            latest = item.get("latest_run") or {}
            rows.append([
                item.get("fl") or "?",
                item.get("status") or "?",
                item.get("date") or "-",
                latest.get("run_id") or "-",
                (item.get("latest_state") or "-").upper(),
                (item.get("title") or "")[:44],
            ])
        print_table(headers, rows)
        return
    for e in citing[:limit]:
        fl_id = e.get("id") or "?"
        status = e.get("effective_status") or e.get("status") or "?"
        title = (e.get("title") or "")[:60]
        print(f"  {fl_id:<12}  {status:<10}  {title}")


def cmd_fl_summary(args, root: Path):
    from collections import Counter

    entries = load_fl_entries(root)
    total = len(entries)
    effective_counts = Counter(status_class(e) for e in entries)
    counts = Counter((e.get("status") or "NONE").strip() for e in entries)
    print(f"FL entries: {total} total\n")
    print("Effective status classes:")
    for label in ("open", "resolved", "failed", "unknown"):
        count = effective_counts.get(label, 0)
        bar = "#" * min(count, 40)
        print(f"  {label:<40} {count:4d}  {bar}")
    print("\nRaw status field values:")
    for status_str, count in sorted(counts.items(), key=lambda x: -x[1]):
        bar = "#" * min(count, 40)
        print(f"  {status_str:<40} {count:4d}  {bar}")


def _format_fl_num_range(start: int, end: int) -> str:
    if start == end:
        return f"FL-{start:03d}"
    return f"FL-{start:03d}..FL-{end:03d}"


def _git_commit_exists(root: Path, commit: str | None) -> bool:
    text = (commit or "").strip()
    if not text:
        return False
    result = run_git(["cat-file", "-e", f"{text}^{{commit}}"], root)
    return result.returncode == 0


def collect_fl_validation(root: Path, *, include_staleness: bool = False, include_coverage: bool = False) -> dict:
    entries = load_fl_entries(root)
    overlay_raw = load_fl_overlay_raw(root)
    legacy_baseline = load_fl_validation_legacy_baseline(root)
    counts = {}

    duplicate_counts = {}
    for entry in entries:
        fl_id = entry.get("fl")
        if fl_id:
            duplicate_counts[fl_id] = duplicate_counts.get(fl_id, 0) + 1
    duplicates = [
        {"fl": fl_id, "count": count}
        for fl_id, count in sorted(duplicate_counts.items())
        if count > 1
    ]
    legacy_duplicates = [
        item
        for item in duplicates
        if _fl_id_in_legacy_patterns(item.get("fl"), legacy_baseline["duplicate_ids"])
    ]
    duplicates = [
        item
        for item in duplicates
        if not _fl_id_in_legacy_patterns(item.get("fl"), legacy_baseline["duplicate_ids"])
    ]

    nums = sorted({int(e["fl"].split("-")[1]) for e in entries if re.match(r"^FL-\d+$", e.get("fl") or "")})
    gaps = []
    if nums:
        start = prev = nums[0]
        for num in nums[1:]:
            if num == prev + 1:
                prev = num
                continue
            if num > prev + 1:
                gaps.append({"start": prev + 1, "end": num - 1})
            prev = num
    legacy_gaps = [
        item
        for item in gaps
        if _fl_gap_in_legacy_patterns(item, legacy_baseline["sequence_gaps"])
    ]
    gaps = [
        item
        for item in gaps
        if not _fl_gap_in_legacy_patterns(item, legacy_baseline["sequence_gaps"])
    ]

    missing_status = [
        {
            "fl": entry.get("fl"),
            "date": entry.get("date") or "-",
            "title": entry.get("title") or "",
        }
        for entry in entries
        if not entry.get("has_status_field")
    ]
    legacy_missing_status = [
        item
        for item in missing_status
        if _fl_id_in_legacy_patterns(item.get("fl"), legacy_baseline["missing_status"])
    ]
    missing_status = [
        item
        for item in missing_status
        if not _fl_id_in_legacy_patterns(item.get("fl"), legacy_baseline["missing_status"])
    ]

    known_ids = {entry.get("fl") for entry in entries if entry.get("fl")}
    dangling_related = []
    for entry in entries:
        fl_id = entry.get("fl") or ""
        for target in entry.get("related") or []:
            if target not in known_ids:
                dangling_related.append(
                    {
                        "fl": fl_id,
                        "target": target,
                        "title": entry.get("title") or "",
                    }
                )

    missing_overlay = [
        {
            "fl": entry.get("fl"),
            "status": fl_status_display(entry),
            "date": entry.get("date") or "-",
            "category": entry.get("category") or "",
            "title": entry.get("title") or "",
        }
        for entry in fl_entries_missing_overlay(entries, overlay_raw)
    ]
    legacy_missing_overlay = [
        item
        for item in missing_overlay
        if _fl_id_in_legacy_patterns(item.get("fl"), legacy_baseline["missing_overlay"])
    ]
    missing_overlay = [
        item
        for item in missing_overlay
        if not _fl_id_in_legacy_patterns(item.get("fl"), legacy_baseline["missing_overlay"])
    ]

    status_overrides = [
        {
            "fl": entry.get("fl"),
            "from": _extract_primary_status_marker(entry.get("status")) or (entry.get("status") or ""),
            "to": entry.get("effective_status") or "",
        }
        for entry in entries
        if (entry.get("effective_status") or "")
        and (_extract_primary_status_marker(entry.get("status")) or "").upper()
        != (entry.get("effective_status") or "").upper()
    ]
    proof_state_drift = [
        {
            "fl": entry.get("fl"),
            "status": fl_status_display(entry),
            "proof_state": _fl_overlay_scalar(entry, "ProofState") or "OPEN",
            "title": entry.get("title") or "",
        }
        for entry in entries
        if fl_entry_has_fix_attempt(entry)
        and normalize_fl_tag(_fl_overlay_scalar(entry, "ProofState")) == "open"
    ]

    stale_artifacts: list[dict[str, str]] = []
    missing_commits: list[dict[str, str]] = []
    unknown_gates: list[dict[str, Any]] = []
    overlay_coverage = {
        "total_entries": len(entries),
        "overlay_rows": len(overlay_raw),
        "derived_overlay_rows": 0,
        "missing_overlay_rows": len(missing_overlay),
        "legacy_missing_overlay_rows": len(legacy_missing_overlay),
        "total_missing_overlay_rows": len(missing_overlay) + len(legacy_missing_overlay),
        "coverage_ratio": round((len(overlay_raw) / len(entries)), 4) if entries else 0.0,
    }
    if include_coverage:
        overlay_coverage["derived_overlay_rows"] = sum(
            1
            for entry in entries
            if effective_fl_overlay_record(entry, overlay_raw.get(entry.get("fl")), fl_id=entry.get("fl")).get("LastTestedRunId")
            or effective_fl_overlay_record(entry, overlay_raw.get(entry.get("fl")), fl_id=entry.get("fl")).get("LastGateResult")
            or effective_fl_overlay_record(entry, overlay_raw.get(entry.get("fl")), fl_id=entry.get("fl")).get("FixAttempts")
        )

    if include_staleness:
        try:
            runs, _ = load_all_runs(root)
        except SystemExit:
            runs = []
        known_run_ids = {run.get("run_id") for run in runs if run.get("run_id")}
        known_gates = (
            load_watchdog_gate_registry(root)
            | set(all_known_gates(runs))
            | set(PLAN_REQUIRED_APPEARANCE_GATES)
            | set(DIAGNOSTIC_ONLY_GATES)
            | set(DEPRECATED_GATES)
        )
        for entry in entries:
            fl_id = entry.get("fl")
            artifact_run_id = (entry.get("artifact_run_id") or "").strip()
            prior_pass_run_id = (entry.get("prior_pass_run_id") or "").strip()
            if artifact_run_id and artifact_run_id not in known_run_ids:
                stale_artifacts.append({"fl": fl_id, "kind": "artifact", "run_id": artifact_run_id})
            if prior_pass_run_id and prior_pass_run_id not in known_run_ids:
                stale_artifacts.append({"fl": fl_id, "kind": "prior_pass", "run_id": prior_pass_run_id})
            commit = (entry.get("commit") or "").strip()
            if commit and not _git_commit_exists(root, commit):
                missing_commits.append({"fl": fl_id, "commit": commit})
            bad_gates = sorted(
                gate for gate in fl_entry_gates(root, entry)
                if canonical_gate_name(gate) not in known_gates
            )
            if bad_gates:
                unknown_gates.append({"fl": fl_id, "gates": bad_gates, "title": entry.get("title") or ""})

    counts["duplicates"] = len(duplicates)
    counts["sequence_gaps"] = len(gaps)
    counts["missing_status"] = len(missing_status)
    counts["dangling_related"] = len(dangling_related)
    counts["missing_overlay"] = len(missing_overlay)
    counts["stale_artifacts"] = len(stale_artifacts)
    counts["missing_commits"] = len(missing_commits)
    counts["unknown_gates"] = len(unknown_gates)
    counts["missing_overlay_coverage"] = overlay_coverage["legacy_missing_overlay_rows"] if include_coverage else 0
    issue_keys = [
        "duplicates",
        "sequence_gaps",
        "missing_status",
        "dangling_related",
        "missing_overlay",
    ]
    if include_staleness:
        issue_keys.extend(("stale_artifacts", "missing_commits", "unknown_gates"))
    if include_coverage:
        issue_keys.append("missing_overlay_coverage")
    counts["issue_categories"] = sum(1 for key in issue_keys if counts[key])
    legacy_counts = {
        "duplicates": len(legacy_duplicates),
        "sequence_gaps": len(legacy_gaps),
        "missing_status": len(legacy_missing_status),
        "missing_overlay": len(legacy_missing_overlay),
    }

    return {
        "path": str(canonical_failure_log_path(root)),
        "counts": counts,
        "duplicates": duplicates,
        "sequence_gaps": gaps,
        "missing_status": missing_status,
        "dangling_related": dangling_related,
        "missing_overlay": missing_overlay,
        "legacy_baseline": {
            "counts": legacy_counts,
            "duplicates": legacy_duplicates,
            "sequence_gaps": legacy_gaps,
            "missing_status": legacy_missing_status,
            "missing_overlay": legacy_missing_overlay,
        },
        "status_overrides": status_overrides,
        "proof_state_drift": proof_state_drift,
        "stale_artifacts": stale_artifacts,
        "missing_commits": missing_commits,
        "unknown_gates": unknown_gates,
        "overlay_coverage": overlay_coverage,
    }


def _print_fl_validation_rows(title: str, rows: list[tuple], limit: int | None) -> None:
    if not rows:
        return
    print(title)
    shown = rows if limit is None else rows[:limit]
    for row in shown:
        print("  " + "  ".join(str(cell) for cell in row))
    if limit is not None and len(rows) > limit:
        print(f"  ... {len(rows) - limit} more")
    print()


def cmd_fl_validate(args, root: Path):
    report = collect_fl_validation(
        root,
        include_staleness=getattr(args, "staleness", False),
        include_coverage=getattr(args, "coverage", False),
    )
    if getattr(args, "json", False):
        print(json.dumps(report, indent=2))
        if report["counts"]["issue_categories"]:
            raise SystemExit(1)
        return

    counts = report["counts"]

    if getattr(args, "summary", False):
        # Compact one-line-per-category output; no per-row detail
        legacy = report.get("legacy_baseline", {}).get("counts", {})
        category_lines = []
        _summary_pairs = [
            ("duplicates", "duplicate IDs"),
            ("sequence_gaps", "sequence gaps"),
            ("missing_status", "missing statuses"),
            ("dangling_related", "dangling Related refs"),
            ("missing_overlay", "missing overlay rows"),
        ]
        if getattr(args, "staleness", False):
            _summary_pairs += [
                ("stale_artifacts", "stale artifact refs"),
                ("missing_commits", "missing git commits"),
                ("unknown_gates", "unknown gate refs"),
            ]
        for key, label in _summary_pairs:
            total = counts.get(key, 0)
            if total:
                category_lines.append(f"  - {label.capitalize()}: {total} (pre-existing)")
        if category_lines:
            print(f"FL VALIDATE: {len(category_lines)} issue categor{'y' if len(category_lines) == 1 else 'ies'} found.")
            for line in category_lines:
                print(line)
            print("Conclusion: no new structural issues introduced.")
            raise SystemExit(1)
        else:
            print("FL VALIDATE: clean — no issues found.")
        return

    limit = getattr(args, "limit", 20)
    print(f"FL VALIDATE: {report['path']}\n")
    print(
        "Effective-status overrides: "
        f"{len(report['status_overrides'])} entry(s) now classify by the latest append-only update.\n"
    )
    legacy_counts = report.get("legacy_baseline", {}).get("counts", {})
    legacy_total = sum(int(value or 0) for value in legacy_counts.values())
    if legacy_total:
        print(
            "Legacy baseline suppressed: "
            f"{legacy_counts.get('duplicates', 0)} duplicate IDs, "
            f"{legacy_counts.get('sequence_gaps', 0)} sequence gaps, "
            f"{legacy_counts.get('missing_status', 0)} missing statuses, "
            f"{legacy_counts.get('missing_overlay', 0)} missing overlay rows.\n"
        )

    _print_fl_validation_rows(
        f"Duplicate IDs ({counts['duplicates']}):",
        [(item["fl"], f"x{item['count']}") for item in report["duplicates"]],
        limit,
    )
    _print_fl_validation_rows(
        f"Sequence gaps ({counts['sequence_gaps']}):",
        [(_format_fl_num_range(item["start"], item["end"]),) for item in report["sequence_gaps"]],
        limit,
    )
    _print_fl_validation_rows(
        f"Missing Status field ({counts['missing_status']}):",
        [
            (item["fl"], item["date"], item["title"][:72])
            for item in report["missing_status"]
        ],
        limit,
    )
    _print_fl_validation_rows(
        f"Dangling Related refs ({counts['dangling_related']}):",
        [
            (item["fl"], "->", item["target"], item["title"][:60])
            for item in report["dangling_related"]
        ],
        limit,
    )
    _print_fl_validation_rows(
        f"Missing overlay rows ({counts['missing_overlay']}):",
        [
            (item["fl"], item["status"], item["category"][:28], item["title"][:50])
            for item in report["missing_overlay"]
        ],
        limit,
    )
    _print_fl_validation_rows(
        f"ProofState drift warnings ({len(report['proof_state_drift'])}):",
        [
            (item["fl"], item["proof_state"], item["status"], item["title"][:58])
            for item in report["proof_state_drift"]
        ],
        limit,
    )
    if getattr(args, "staleness", False):
        _print_fl_validation_rows(
            f"Stale artifact refs ({counts['stale_artifacts']}):",
            [(item["fl"], item["kind"], item["run_id"]) for item in report["stale_artifacts"]],
            limit,
        )
        _print_fl_validation_rows(
            f"Missing git commits ({counts['missing_commits']}):",
            [(item["fl"], item["commit"]) for item in report["missing_commits"]],
            limit,
        )
        _print_fl_validation_rows(
            f"Unknown gate refs ({counts['unknown_gates']}):",
            [(item["fl"], ", ".join(item["gates"][:4]), item["title"][:48]) for item in report["unknown_gates"]],
            limit,
        )
    if getattr(args, "coverage", False):
        coverage = report.get("overlay_coverage") or {}
        print("Overlay coverage:")
        print(f"  total_entries:            {coverage.get('total_entries', 0)}")
        print(f"  overlay_rows:             {coverage.get('overlay_rows', 0)}")
        print(f"  derived_overlay_rows:     {coverage.get('derived_overlay_rows', 0)}")
        print(f"  missing_overlay_rows:     {coverage.get('missing_overlay_rows', 0)}")
        print(f"  legacy_missing_overlays:  {coverage.get('legacy_missing_overlay_rows', 0)}")
        print(f"  total_missing_overlays:   {coverage.get('total_missing_overlay_rows', 0)}")
        print(f"  coverage_ratio:           {coverage.get('coverage_ratio', 0.0):.4f}")
        print()

    if counts["issue_categories"]:
        print(
            "Summary: "
            f"{counts['issue_categories']} issue categor{'y' if counts['issue_categories'] == 1 else 'ies'} found."
        )
        raise SystemExit(1)

    suffix_bits = ["duplicate IDs", "sequence gaps", "missing statuses", "dangling Related refs", "missing overlay rows"]
    if getattr(args, "staleness", False):
        suffix_bits.extend(["stale artifact refs", "missing git commits", "unknown gate refs"])
    if getattr(args, "coverage", False):
        suffix_bits.append("overlay coverage gaps")
    print(f"Summary: clean — no {', '.join(suffix_bits)}.")


def cmd_fl_dedupe(args, root: Path):
    """Duplicate-ID cleanup: inventory -> plan -> apply -> verify."""
    import shutil as _shutil

    action = getattr(args, "dedupe_action", None)
    fl_path = canonical_failure_log_path(root)

    # Match any FL header line that starts an entry.
    #
    # Historically, FAILURE_LOG headers have used multiple separators:
    # - "### FL-1234 — Title"
    # - "### FL-1234: Title"
    # - "### FL-1234 - Title"
    # - "### FL-1234 / FL-5678 — Combined header"
    #
    # The dedupe tool must treat ALL of these as entry boundaries; otherwise
    # delete spans can accidentally swallow adjacent entries (see FL-3570
    # swallowing FL-3571/FL-3572 when those used ':' headers).
    _FL_HDR = re.compile(r"^###\s+(FL-\d+)\b[^\n]*\n", re.MULTILINE)

    def _find_spans(text: str) -> list[tuple[str, int, int]]:
        """Return list of (fl_id, start_char, end_char) for every entry header in order."""
        matches = list(_FL_HDR.finditer(text))
        spans = []
        for i, m in enumerate(matches):
            end = matches[i + 1].start() if i + 1 < len(matches) else len(text)
            spans.append((m.group(1), m.start(), end))
        return spans

    def _safe_span_end(text: str, start: int, end: int) -> int:
        """Ensure a deletion span does not include multiple FL headers.

        With historical header formats, it's possible for parsing to drift and
        accidentally swallow adjacent entries. As a fail-safe, clamp end to the
        first header after start (exclusive).
        """
        matches = list(_FL_HDR.finditer(text, start, end))
        if len(matches) <= 1:
            return end
        second = matches[1].start()
        return second

    def _header_title(text: str, start: int) -> str:
        """Best-effort title extraction from the header line at start."""
        header_line = text[start : start + 240].split("\n", 1)[0].strip()
        # header_line examples:
        # - "### FL-1234 — Title"
        # - "### FL-1234: Title"
        # - "### FL-1234 - Title"
        # - "### FL-1234 / FL-5678 — Combined header"
        m = re.match(r"^###\s+FL-\d+\b(.*)$", header_line)
        if not m:
            return ""
        rest = m.group(1).strip()
        # Prefer content after a separator when present.
        sep_m = re.search(r"\s*[—:-]\s*", rest)
        if sep_m:
            return rest[sep_m.end() :].strip()
        # Otherwise return the residual (e.g. "/ FL-5678 — ...").
        return rest.strip()

    def _char_to_line(text: str, pos: int) -> int:
        return text[:pos].count("\n") + 1

    if action == "inventory":
        if not fl_path.exists():
            sys.exit("error: FAILURE_LOG.md not found")
        text = fl_path.read_text(encoding="utf-8")
        spans = _find_spans(text)
        seen: dict[str, list[tuple[int, int, str]]] = {}
        for fl_id, start, end in spans:
            title = _header_title(text, start)
            seen.setdefault(fl_id, []).append((start, end, title))
        duplicates = {k: v for k, v in seen.items() if len(v) > 1}
        if not duplicates:
            print("FL DEDUPE INVENTORY: no duplicate IDs found.")
            return
        print(f"FL DEDUPE INVENTORY: {len(duplicates)} duplicate ID(s)\n")
        for fl_id, occurrences in sorted(duplicates.items()):
            titles = [t for _, _, t in occurrences]
            kind = "exact" if len(set(titles)) == 1 else "semantic"
            print(f"  {fl_id}  x{len(occurrences)}  [{kind}]")
            for i, (start, end, title) in enumerate(occurrences):
                line = _char_to_line(text, start)
                body_size = len(text[start:end].strip())
                if i == len(occurrences) - 1:
                    marker = "(KEEPER - latest, most recent)"
                else:
                    marker = f"(RENUMBER to {fl_id}.{i+1} — {body_size} chars to merge into keeper)"
                print(f"    occurrence {i + 1}: line {line}  {marker}  {title[:60]}")
        print(f"\nRun `fl dedupe plan --write-plan FILE` to generate a reviewable renumber plan.")
        print(f"DELETION is DISABLED. Duplicate entries must be renumbered (FL-NNN.1, FL-NNN.2) or merged.")

    elif action == "plan":
        plan_file = getattr(args, "write_plan", None)
        if not plan_file:
            sys.exit("error: --write-plan FILE is required")
        if not fl_path.exists():
            sys.exit("error: FAILURE_LOG.md not found")
        text = fl_path.read_text(encoding="utf-8")
        spans = _find_spans(text)
        seen: dict[str, list[tuple[int, int, str]]] = {}
        for fl_id, start, end in spans:
            title = _header_title(text, start)
            seen.setdefault(fl_id, []).append((start, end, title))
        duplicates = {k: v for k, v in seen.items() if len(v) > 1}
        if not duplicates:
            print("FL DEDUPE PLAN: no duplicate IDs found — nothing to plan.")
            return
        # 2026-05-08: REMOVED DELETION LOGIC.
        # The apply command is now DISABLED. This plan command now generates a
        # RENUMBER proposal instead of a deletion plan.
        #
        # Strategy:
        # - The LATEST occurrence (by line number) is the keeper (most recent content).
        # - Earlier occurrences are proposed for renumbering: FL-NNN -> FL-NNN.1, FL-NNN.2, etc.
        # - Human must review, merge unique content into keeper, then renumber old entries.
        renumber_proposals = []
        for fl_id, occurrences in sorted(duplicates.items()):
            # Keep the LAST (most recent) occurrence; renumber earlier ones
            keeper_start, keeper_end, keeper_title = occurrences[-1]
            keeper_line = _char_to_line(text, keeper_start)
            suffix_counter = 1
            for start, end, title in occurrences[:-1]:
                end_safe = _safe_span_end(text, start, end)
                line_start = _char_to_line(text, start)
                line_end = _char_to_line(text, end_safe - 1)
                new_id = f"{fl_id}.{suffix_counter}"
                # Extract body content for merge review
                body = text[start:end_safe].strip()
                body_len = len(body)
                renumber_proposals.append({
                    "fl_id": fl_id,
                    "new_id": new_id,
                    "keeper_line": keeper_line,
                    "keeper_title": keeper_title[:120],
                    "renumber_line_start": line_start,
                    "renumber_line_end": line_end,
                    "renumber_title": title[:120],
                    "body_length": body_len,
                    "kind": "exact" if len({t for _, _, t in occurrences}) == 1 else "semantic",
                    "action": f"MERGE unique content from {new_id} into {fl_id} (keeper at line {keeper_line}), then change header to {new_id} with cross-reference note",
                })
                suffix_counter += 1
        plan = {
            "version": 2,  # bumped: deletion -> renumber
            "note": "DELETION DISABLED 2026-05-08. This plan proposes renumbering, not deletion.",
            "generated": __import__("datetime").datetime.now(__import__("datetime").timezone.utc).isoformat(),
            "source_path": str(fl_path),
            "duplicate_count": len(duplicates),
            "renumber_count": len(renumber_proposals),
            "target_state": {
                "duplicate_ids": 0,
                "note": "All duplicates should be renumbered (FL-NNN.1, FL-NNN.2, etc.) with content merged into latest keeper",
            },
            "renumber_proposals": renumber_proposals,
        }
        requires_approval = [d for d in renumber_proposals if d["kind"] == "semantic"]
        if requires_approval:
            plan["human_approval_required"] = True
            plan["approval_note"] = (
                f"{len(requires_approval)} semantic duplicate(s) require human review "
                "to merge unique content into the latest keeper entry before renumbering."
            )
        plan_path = Path(plan_file)
        plan_path.write_text(json.dumps(plan, indent=2), encoding="utf-8")
        print(f"FL DEDUPE PLAN (renumber, not delete): written to {plan_path}")
        print(f"  {len(duplicates)} duplicate ID(s) -> {len(renumber_proposals)} renumber proposal(s)")
        print(f"  Strategy: latest occurrence is keeper; earlier ones get renumbered (FL-NNN.1, FL-NNN.2)")
        if requires_approval:
            print(f"  {len(requires_approval)} semantic duplicate(s) require human review before merge+renumber")
        print(f"\nManual resolution steps:")
        print(f"  1. Review {plan_path}")
        print(f"  2. For each duplicate: read both entries, merge unique content into {{{{keeper}}}}")
        print(f"  3. Change old header from '### {{{{old_id}}}}' to '### {{{{new_id}}}}' with a cross-reference note")
        print(f"  4. Run `fl dedupe verify --plan-file {plan_path}` to confirm")

    elif action == "apply":
        sys.exit(
            "error: fl dedupe apply is DISABLED (2026-05-08).\n"
            "The dedupe deletion logic caused MASSIVE DATA LOSS by deleting unique content\n"
            "from duplicate FL entries (see FL-2957 May 7 proof tables, ~477 lines lost).\n"
            "The tool must be rewritten to MERGE content into the keeper entry rather than\n"
            "DELETE duplicates. Until then, use inventory + plan for review only.\n"
            "To manually resolve duplicates:\n"
            "  1. Run `fl dedupe inventory` to see duplicates\n"
            "  2. Read both entries and merge unique content into the latest entry\n"
            "  3. Replace the old entry's body with a cross-reference note\n"
            "     (e.g. 'Content merged into FL-2957 at line NNN')\n"
            "  4. Do NOT delete any FL entry body. Rename or cross-reference instead.\n"
        )

    elif action == "verify":
        plan_file = getattr(args, "plan_file", None)
        if not plan_file:
            sys.exit("error: --plan-file FILE is required")
        plan = json.loads(Path(plan_file).read_text(encoding="utf-8"))
        if not fl_path.exists():
            sys.exit("error: FAILURE_LOG.md not found")
        text = fl_path.read_text(encoding="utf-8")
        spans = _find_spans(text)
        seen: dict[str, int] = {}
        for fl_id, _, _ in spans:
            seen[fl_id] = seen.get(fl_id, 0) + 1
        # Check target IDs are no longer colliding
        # Support both old "deletions" key and new "renumber_proposals" key
        targets = plan.get("renumber_proposals") or plan.get("deletions", [])
        cleaned = []
        still_dup = []
        for d in targets:
            fl_id = d["fl_id"]
            count = seen.get(fl_id, 0)
            if count <= 1:
                cleaned.append(fl_id)
            else:
                still_dup.append((fl_id, count))
        target_dup = plan.get("target_state", {}).get("duplicate_ids", 0)
        remaining_dups = {k: v for k, v in seen.items() if v > 1}
        ok = len(still_dup) == 0 and len(remaining_dups) == target_dup
        print("FL DEDUPE VERIFY")
        print(f"  IDs now unique:     {len(set(cleaned))}")
        print(f"  Still colliding:    {len(still_dup)}")
        print(f"  Total remaining dup IDs: {len(remaining_dups)}  (target: {target_dup})")
        if still_dup:
            for fl_id, count in still_dup:
                print(f"    {fl_id} still has {count} occurrences")
        if ok:
            print("VERIFY: OK — dedupe target state achieved.")
        else:
            print("VERIFY: FAIL — target state not met; manual review required.")
            raise SystemExit(1)

    else:
        sys.exit("error: specify a dedupe action: inventory, plan, apply, verify")


_CPP_ANCHOR_EXTS = {".c", ".cc", ".cpp", ".cxx", ".h", ".hh", ".hpp", ".hxx"}


def _walk_for_enclosing_function(node, target_row: int) -> str | None:
    if node.start_point[0] > target_row or node.end_point[0] < target_row:
        return None
    for child in node.children:
        inner = _walk_for_enclosing_function(child, target_row)
        if inner is not None:
            return inner
    if node.type == "function_definition":
        return _extract_func_name_from_node(node)
    return None


def _extract_func_name_from_node(func_node) -> str | None:
    declarator = func_node.child_by_field_name("declarator")
    if declarator is None:
        return None
    return _name_from_declarator_node(declarator)


def _name_from_declarator_node(node) -> str | None:
    node_type = node.type
    if node_type == "identifier":
        return node.text.decode("utf-8", errors="replace")
    if node_type == "function_declarator":
        inner = node.child_by_field_name("declarator")
        if inner is not None:
            return _name_from_declarator_node(inner)
    if node_type == "qualified_identifier":
        name_node = node.child_by_field_name("name")
        if name_node is not None:
            return name_node.text.decode("utf-8", errors="replace").split("<")[0]
    if node_type in {"pointer_declarator", "reference_declarator"}:
        inner = node.child_by_field_name("declarator")
        if inner is not None:
            return _name_from_declarator_node(inner)
    if node_type == "destructor_name":
        return node.text.decode("utf-8", errors="replace")
    return None


def _resolve_coderef_to_function(filepath: str, lineno: int) -> str | None:
    global _TS_CPP_LANGUAGE, _TS_CPP_INIT_FAILED
    if not _TREE_SITTER_AVAILABLE or _TS_CPP_INIT_FAILED or lineno < 1:
        return None
    path = Path(filepath)
    if path.suffix.lower() not in _CPP_ANCHOR_EXTS or not path.exists():
        return None
    try:
        source = path.read_bytes()
    except OSError:
        return None
    try:
        if _TS_CPP_LANGUAGE is None:
            _TS_CPP_LANGUAGE = _ts_Language(_ts_cpp.language())  # type: ignore[call-arg]
        parser = _TSParser(_TS_CPP_LANGUAGE)  # type: ignore[call-arg]
        tree = parser.parse(source)
    except Exception:
        _TS_CPP_INIT_FAILED = True
        return None
    return _walk_for_enclosing_function(tree.root_node, lineno - 1)


def _append_fl_payload_ref(
    payload_refs: list[dict[str, Any]],
    seen_refs: set[str],
    root: Path,
    ref: str,
    *,
    source: str | None = None,
) -> None:
    if ref in seen_refs:
        return
    file_path = ref.split(":")[0]
    abs_path = _resolve_repo_ref_path(root, file_path)
    row: dict[str, Any] = {"ref": ref, "exists": abs_path is not None, "resolved_path": abs_path}
    if source:
        row["source"] = source
    payload_refs.append(row)
    seen_refs.add(ref)


def _append_anchor_name(fn_names: list[str], name: str) -> None:
    bare = name.split("::")[-1] if "::" in name else name
    if not re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*$", bare or ""):
        return
    if bare not in fn_names:
        fn_names.append(bare)


def _derive_anchor_names_from_refs(payload_refs: list[dict[str, Any]]) -> list[str]:
    names: list[str] = []
    for item in payload_refs:
        ref = str(item.get("ref") or "")
        abs_path = item.get("resolved_path")
        if not ref or not abs_path:
            continue
        parts = ref.rsplit(":", 1)
        if len(parts) != 2 or not parts[1].isdigit():
            continue
        lineno = int(parts[1])
        name = _resolve_coderef_to_function(str(abs_path), lineno)
        if name:
            _append_anchor_name(names, name)
    return names


def _collect_lineage_anchor_candidates(root: Path, target_entry: dict, entries: list[dict]) -> list[dict]:
    target_fl = str(target_entry.get("fl") or "").upper()
    candidates: list[dict] = []
    seen_ids: set[str] = set()

    def _add_candidate(entry: dict | None) -> None:
        if not entry:
            return
        fl_id = str(entry.get("fl") or "").upper()
        if not fl_id or fl_id == target_fl or fl_id in seen_ids:
            return
        seen_ids.add(fl_id)
        candidates.append(entry)

    entries_by_id = {
        str(entry.get("fl") or "").upper(): entry
        for entry in entries
        if str(entry.get("fl") or "").strip()
    }

    for ref in _fl_overlay_list(target_entry, "ComplaintRefs"):
        _add_candidate(entries_by_id.get(str(ref).upper()))

    if candidates:
        return candidates

    target_gates = set(fl_entry_gates(root=root, entry=target_entry))
    if target_gates:
        for entry in entries:
            if entry is target_entry:
                continue
            entry_gates = set(fl_entry_gates(root=root, entry=entry))
            if not (target_gates & entry_gates):
                continue
            has_overlay_anchors = bool(
                _fl_overlay_list(entry, "CodeRefs")
                or _fl_overlay_list(entry, "TouchedFiles")
                or (entry.get("overlay") or {}).get("AnchorFunctions")
            )
            has_body_anchors = bool(_extract_file_refs([entry]))
            if has_overlay_anchors or has_body_anchors:
                _add_candidate(entry)

    return candidates


def cmd_fl_code(args, root: Path) -> None:
    """Show code file/function references in FL entry body."""
    fl_id = getattr(args, "fl_id", None)
    if not fl_id:
        entries = load_fl_entries(root)
        items = [f"{e['fl']} — {e.get('title', '')[:60]}" for e in entries]
        picked = _maybe_fzf_pick(items, prompt="FL entry> ")
        if not picked:
            print("ERROR fl code: fl_id required.", file=sys.stderr)
            sys.exit(1)
        fl_id = picked.split()[0]
    fl_id = fl_id.upper()
    entries = load_fl_entries(root)
    entry = next((e for e in entries if e["fl"] == fl_id), None)
    if not entry:
        if getattr(args, "json", False):
            _emit_fl_json_error(command="fl code", error="not_found", exit_code=2, fl_id=fl_id)
        print(f"ERROR fl code: {fl_id} not found.", file=sys.stderr)
        sys.exit(1)
    # --- (1) Prose file:line refs ---
    refs = _extract_file_refs([entry])
    payload_refs: list[dict[str, Any]] = []
    seen_refs: set[str] = set()
    for ref in refs:
        _append_fl_payload_ref(payload_refs, seen_refs, root, ref)

    # --- (2) Overlay CodeRefs → payload_refs (merge, deduplicate) ---
    overlay = entry.get("overlay") or {}
    for ref in list(overlay.get("CodeRefs") or []):
        _append_fl_payload_ref(payload_refs, seen_refs, root, ref, source="overlay")

    # --- (3) Prose backtick function names (always runs, no early-exit) ---
    fn_names: list[str] = []
    for line in entry.get("_lines") or []:
        for m in re.finditer(r"`([a-zA-Z_][a-zA-Z0-9_]{3,})\(\)`", line):
            _append_anchor_name(fn_names, m.group(1))

    # --- (4) Overlay AnchorFunctions → fn_names (strip scope qualifier) ---
    for anchor in list(overlay.get("AnchorFunctions") or []):
        _append_anchor_name(fn_names, anchor)

    # --- (5) Own CodeRefs → enclosing C/C++ functions (tree-sitter when available) ---
    for name in _derive_anchor_names_from_refs(payload_refs):
        _append_anchor_name(fn_names, name)

    # --- (6) ComplaintRefs / same-gate lineage fallback for raw gate rows ---
    lineage_sources: list[str] = []
    if not fn_names:
        for candidate in _collect_lineage_anchor_candidates(root, entry, entries):
            source_fl = str(candidate.get("fl") or "").upper()
            before_count = len(fn_names)
            for ref in _extract_file_refs([candidate]):
                _append_fl_payload_ref(
                    payload_refs,
                    seen_refs,
                    root,
                    ref,
                    source=f"lineage:{source_fl}",
                )
            candidate_overlay = candidate.get("overlay") or {}
            for ref in list(candidate_overlay.get("CodeRefs") or []):
                _append_fl_payload_ref(
                    payload_refs,
                    seen_refs,
                    root,
                    ref,
                    source=f"lineage:{source_fl}",
                )
            for line in candidate.get("_lines") or []:
                for m in re.finditer(r"`([a-zA-Z_][a-zA-Z0-9_]{3,})\(\)`", line):
                    _append_anchor_name(fn_names, m.group(1))
            for anchor in list(candidate_overlay.get("AnchorFunctions") or []):
                _append_anchor_name(fn_names, anchor)
            for name in _derive_anchor_names_from_refs(payload_refs):
                _append_anchor_name(fn_names, name)
            if len(fn_names) > before_count and source_fl not in lineage_sources:
                lineage_sources.append(source_fl)

    # rg pass for all collected function names (prose + overlay).
    # fn_names is always emitted in JSON so callers get names even when rg is absent.
    functions: dict[str, list[str]] = {}
    if fn_names and _rg_available():
        cpp_root = root / "src" if (root / "src").exists() else root
        for fn in fn_names[:6]:
            hits = _rg_search(fn, cpp_root, ["--type=cpp", "-l"])
            functions[fn] = hits[:3]

    # --- Fail-closed: anchor_gap means callgraph routing is not possible ---
    # True when fn_names is empty (covers both "no anchors at all" and "CodeRefs-only").
    # CodeRefs identify code areas but are not sufficient for function-level callgraph routing;
    # AnchorFunctions are required.
    anchor_gap = not fn_names
    remediation = ""
    if anchor_gap:
        if payload_refs:
            # CodeRefs present but no AnchorFunctions — callgraph routing not possible.
            remediation = (
                f"CodeRefs found in {fl_id} but AnchorFunctions are required for "
                f"callgraph --fl routing. CodeRefs identify code areas only and are not "
                f"sufficient for function-level routing. Add AnchorFunctions to the overlay, "
                f'e.g.: {{"fl":"{fl_id}","AnchorFunctions":["FunctionName"]}}'
            )
        else:
            remediation = (
                f"No code anchors found for {fl_id}. "
                f"Add an overlay row with CodeRefs and/or AnchorFunctions, e.g.: "
                f'{{"fl":"{fl_id}","CodeRefs":["engine/game.cpp:NNNN"],'
                f'"AnchorFunctions":["FunctionName"]}}'
            )

    if getattr(args, "json", False):
        out: dict[str, Any] = {
            "fl": fl_id,
            "refs": payload_refs,
            "fn_names": fn_names,       # always present; callers use this when rg is absent
            "functions": functions,     # rg hits per name; empty dict when rg unavailable
            "anchor_gap": anchor_gap,
        }
        if lineage_sources:
            out["lineage_sources"] = lineage_sources
        if remediation:
            out["remediation"] = remediation
        print(json.dumps(out, indent=2))
        return

    if anchor_gap:
        print(f"ANCHOR GAP: {remediation}")
        return

    print(f"Code references in {fl_id}:")
    for item in payload_refs:
        mark = "✓" if item["exists"] else "?"
        source_tag = " [overlay]" if item.get("source") == "overlay" else ""
        ap = item.get("resolved_path")
        if ap and ap != item["ref"].split(":")[0]:
            print(f"  [{mark}] {item['ref']} -> {ap}{source_tag}")
        else:
            print(f"  [{mark}] {item['ref']}{source_tag}")
    if functions:
        print("\nFunction references (rg results):")
        for fn, hits in functions.items():
            for hit in hits:
                print(f"  {fn}: {hit}")
    if lineage_sources:
        print("\nDerived anchor lineage:")
        for source_fl in lineage_sources:
            print(f"  {source_fl}")


def cmd_fl_commits(args, root: Path) -> None:
    """Show commit hashes mentioned in FL entry plus git subjects naming the FL."""
    fl_id = getattr(args, "fl_id", None)
    if not fl_id:
        entries = load_fl_entries(root)
        items = [f"{e['fl']} — {e.get('title', '')[:60]}" for e in entries]
        picked = _maybe_fzf_pick(items, prompt="FL entry> ")
        if not picked:
            print("ERROR fl commits: fl_id required.", file=sys.stderr)
            sys.exit(1)
        fl_id = picked.split()[0]
    fl_id = fl_id.upper()
    entries = load_fl_entries(root)
    entry = next((e for e in entries if e["fl"] == fl_id), None)
    if not entry:
        if getattr(args, "json", False):
            _emit_fl_json_error(command="fl commits", error="not_found", exit_code=2, fl_id=fl_id)
        print(f"ERROR fl commits: {fl_id} not found.", file=sys.stderr)
        sys.exit(1)
    commit_sources: dict[str, str] = {commit: "fl_body" for commit in _extract_commits([entry])}
    try:
        subject_proc = subprocess.run(
            [
                "git",
                "log",
                "--format=%H%x09%s",
                "--extended-regexp",
                "--regexp-ignore-case",
                f"--grep={re.escape(fl_id)}",
            ],
            cwd=str(root),
            capture_output=True,
            text=True,
            timeout=10,
        )
        if subject_proc.returncode == 0:
            for line in subject_proc.stdout.splitlines():
                commit_hash, _, subject = line.partition("\t")
                if not re.search(rf"\b{re.escape(fl_id)}\b", subject, flags=re.IGNORECASE):
                    continue
                commit_hash = commit_hash.strip()
                if commit_hash:
                    commit_sources.setdefault(commit_hash, "git_subject")
    except Exception:
        pass
    commits = list(commit_sources)
    payload: list[dict[str, str]] = []
    if not commits:
        if getattr(args, "json", False):
            print(json.dumps({"fl": fl_id, "commits": []}, indent=2))
            return
        print(f"(no commit hashes found in {fl_id})")
        return
    for c in commits:
        try:
            res = subprocess.run(
                ["git", "log", "--oneline", "-1", c],
                cwd=str(root),
                capture_output=True,
                text=True,
                timeout=5,
            )
            detail = (
                res.stdout.strip() if res.returncode == 0 else "(not in local history)"
            )
        except Exception:
            detail = "(git error)"
        payload.append({"commit": c, "detail": detail, "source": commit_sources.get(c, "unknown")})
    if getattr(args, "json", False):
        print(json.dumps({"fl": fl_id, "commits": payload}, indent=2))
        return
    print(f"Commits in {fl_id}:")
    for item in payload:
        print(f"  {item['commit']}  [{item['source']}] {item['detail']}")


def _git_log_oneline(root: Path, *, since: str, until: str) -> list[tuple[str, str]]:
    """Return [(short_hash, subject)] for commits in the given time window."""
    try:
        out = subprocess.check_output(
            [
                "git",
                "log",
                f"--since={since}",
                f"--until={until}",
                "--oneline",
            ],
            cwd=str(root),
            stderr=subprocess.DEVNULL,
        ).decode("utf-8", errors="replace")
    except Exception:
        return []
    commits: list[tuple[str, str]] = []
    for line in out.splitlines():
        line = line.strip()
        if not line:
            continue
        parts = line.split(" ", 1)
        if len(parts) != 2:
            continue
        commits.append((parts[0], parts[1]))
    return commits


def _git_show_name_only(root: Path, commit: str) -> list[str]:
    try:
        out = subprocess.check_output(
            ["git", "show", "--name-only", "--pretty=format:", "-n", "1", commit],
            cwd=str(root),
            stderr=subprocess.DEVNULL,
        ).decode("utf-8", errors="replace")
    except Exception:
        return []
    paths = [line.strip() for line in out.splitlines() if line.strip()]
    return paths


def _build_commit_to_fl_index(entries: list[dict]) -> dict[str, list[dict]]:
    """Map short commit hash -> list of FL entries that mention it."""
    index: dict[str, list[dict]] = {}
    for e in entries:
        for line in e.get("_lines") or []:
            for m in _COMMIT_RE.finditer(line):
                h = m.group(1) or m.group(2)
                if not h:
                    continue
                if not any(c in "abcdef" for c in h):
                    continue
                key = h[:12]
                index.setdefault(key, []).append(e)
    return index


def cmd_fl_fix_commit_audit(args, root: Path) -> None:
    """Audit fix(<scope>) commits in a time window and show which FL entries cite them."""
    since = getattr(args, "since", None) or "1970-01-01"
    until = getattr(args, "until", None) or "2100-01-01"
    scopes_raw = getattr(args, "scopes", None) or "lag,mp-step,server,network-ingest"
    scopes = {s.strip() for s in scopes_raw.split(",") if s.strip()}
    fl_id = getattr(args, "fl_id", None)

    entries = load_fl_entries(root)
    if fl_id:
        fl_id = fl_id.upper()
        entries_by_id = {e["fl"]: e for e in entries}
        target_entry = entries_by_id.get(fl_id)
        if not target_entry:
            if getattr(args, "json", False):
                _emit_fl_json_error(
                    command="fl fix-commit-audit",
                    error="not_found",
                    exit_code=2,
                    fl_id=fl_id,
                )
            print(f"ERROR fl fix-commit-audit: {fl_id} not found.", file=sys.stderr)
            sys.exit(2)
        terms = _title_expansion_terms(target_entry.get("title") or "")
        family_ids = _expand_cluster({fl_id}, entries_by_id, entries, terms)
        family_entries = [entries_by_id[fid] for fid in family_ids if fid in entries_by_id]
        index_entries = family_entries
    else:
        index_entries = entries

    commit_to_entries = _build_commit_to_fl_index(index_entries)

    fix_re = re.compile(r"^fix\(([^)]+)\):\s*(.+)$")
    candidates = _git_log_oneline(root, since=since, until=until)
    rows: list[dict[str, Any]] = []
    for short, subj in candidates:
        m = fix_re.match(subj)
        if not m:
            continue
        scope = m.group(1).strip()
        if scope not in scopes:
            continue
        files = _git_show_name_only(root, short)
        runtime_files = [
            p for p in files
            if not p.startswith("docs/")
            and p not in {"docs/FAILURE_LOG.md"}
        ]
        cited_entries: list[dict] = []
        for key in {short[:12]}:
            cited_entries.extend(commit_to_entries.get(key, []))
        cited_unique: dict[str, dict] = {}
        for e in cited_entries:
            cited_unique[e["fl"]] = e
        cited = [
            {
                "fl": e["fl"],
                "state": fl_display_state(e),
                "status": e.get("status") or "",
                "title": e.get("title") or "",
            }
            for e in sorted(cited_unique.values(), key=lambda x: x["num"])
        ]
        rows.append(
            {
                "commit": short[:12],
                "scope": scope,
                "subject": subj,
                "runtime_files": runtime_files,
                "fl_citations": cited,
            }
        )

    payload = {
        "ok": True,
        "command": "fl fix-commit-audit",
        "since": since,
        "until": until,
        "scopes": sorted(scopes),
        "fl_id": fl_id or "",
        "matched_commits": len(rows),
        "commits": rows,
    }
    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2))
        return

    print(
        f"FIX COMMIT AUDIT: since={since} until={until} scopes={','.join(sorted(scopes))}"
        + (f" fl_id={fl_id}" if fl_id else "")
        + "\n"
    )
    for r in rows:
        print(f"- {r['commit']}  {r['subject']}")
        if r["runtime_files"]:
            print(f"  runtime_files: {', '.join(r['runtime_files'][:8])}")
        else:
            print("  runtime_files: (none or docs-only)")
        if r["fl_citations"]:
            cites = "; ".join(
                f"{c['fl']} [{c['state']}] {c['title'][:60]}"
                for c in r["fl_citations"][:6]
            )
            print(f"  FL citations: {cites}")
        else:
            print("  FL citations: (none found) — do not claim pass/fail without FL cite")
        print()


def cmd_fl_family(args, root: Path) -> None:
    """Show expanded family cluster for FL entry."""
    fl_id = getattr(args, "fl_id", None)
    if not fl_id:
        entries = load_fl_entries(root)
        items = [f"{e['fl']} — {e.get('title', '')[:60]}" for e in entries]
        picked = _maybe_fzf_pick(items, prompt="FL entry> ")
        if not picked:
            print("ERROR fl family: fl_id required.", file=sys.stderr)
            sys.exit(1)
        fl_id = picked.split()[0]
    fl_id = fl_id.upper()
    entries = load_fl_entries(root)
    entries_by_id = {e["fl"]: e for e in entries}
    if fl_id not in entries_by_id:
        if getattr(args, "json", False):
            _emit_fl_json_error(command="fl family", error="not_found", exit_code=2, fl_id=fl_id)
        print(f"ERROR fl family: {fl_id} not found.", file=sys.stderr)
        sys.exit(1)
    entry = entries_by_id[fl_id]
    terms = _title_expansion_terms(entry.get("title") or "")
    terms.extend(_normalize_terms(getattr(args, "term", None) or []))
    expanded = _expand_cluster({fl_id}, entries_by_id, entries, terms)
    print(f"Family cluster for {fl_id} ({len(expanded)} entries):")
    print(f"  Seed: {fl_id} — {entry.get('title', '')[:60]}")
    for fid in sorted(expanded - {fl_id}):
        e = entries_by_id.get(fid)
        if e:
            print(f"  {fid} [{fl_display_state(e)}] — {e.get('title', '')[:60]}")


def _fl_fix_attempt_count(root: Path, fl_id: str) -> int:
    raw = _fl_extract_raw(root, fl_id)
    if raw is None:
        raise ValueError(f"{fl_id} not found in docs/FAILURE_LOG.md")
    return len(fl_fix_attempt_blocks(raw))


def _fl4359_lane_attempt_counts(root: Path) -> dict[str, int]:
    return {fl_id: _fl_fix_attempt_count(root, fl_id) for fl_id in FL4359_LANE_DOC_IDS}


def _refresh_fl4359_lane_docs(root: Path, write: bool) -> dict[str, Any]:
    counts = _fl4359_lane_attempt_counts(root)
    return {
        "lane": FL4359_LANE_DOC_NAME,
        "write": write,
        "retired": True,
        "canonical_owner": str(FL4359_CANONICAL_OWNER),
        "fl_ids": list(FL4359_LANE_DOC_IDS),
        "attempt_counts": counts,
        "attempt_total": sum(counts.values()),
        "raw_guard_attempt_total": sum(counts.values()),
        "core_attempt_total": sum(counts[fl_id] for fl_id in FL4359_LANE_CORE_IDS),
        "commit_count": None,
        "repository_commit_count": None,
        "family_process_failure_count": None,
        "changed_paths": [],
        "doc_paths": [str(FL4359_CANONICAL_OWNER)],
    }


def cmd_fl_refresh_lane_docs(args, root: Path) -> None:
    lane = getattr(args, "lane", FL4359_LANE_DOC_NAME)
    if lane != FL4359_LANE_DOC_NAME:
        sys.exit(f"error: unsupported lane doc refresh target: {lane!r}")
    payload = _refresh_fl4359_lane_docs(root, write=bool(getattr(args, "write", False)))
    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2))
        return
    print(f"FL LANE DOC REFRESH ({payload['lane']}) [retired: canonical owner only]")
    print(f"  canonical_owner:   {payload['canonical_owner']}")
    print(f"  attempt_total:      {payload['attempt_total']}")
    print(f"  core_attempt_total: {payload['core_attempt_total']}")
    for fl_id in payload["fl_ids"]:
        print(f"  {fl_id}:             {payload['attempt_counts'][fl_id]}")
    print("  changed_paths:      none")


_FIX_ATTEMPT_SESSION_TOKEN_RE = re.compile(
    r"(?<![A-Za-z0-9_])session_id=([^\s]*)"
)
_FIX_ATTEMPT_SESSION_MARKER_RE = re.compile(r"session_id=")
_FIX_ATTEMPT_SESSION_ID_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,127}")


def _validate_fix_attempt_session_id(value: str, source: str) -> str:
    """Validate one session identity before the FL log can be mutated."""
    if not isinstance(value, str) or not value or not _FIX_ATTEMPT_SESSION_ID_RE.fullmatch(value):
        raise ValueError(
            f"invalid {source} session id; expected one non-whitespace token"
        )
    return value


def _resolve_fix_attempt_session_id(args) -> tuple[str, str]:
    """Resolve and normalize the single session identity for one FL attempt.

    Explicit CLI input has precedence, but every present source is validated
    and compared so an overridden conflicting identity cannot be hidden.
    """
    explicit = getattr(args, "session_id", None)
    description = str(getattr(args, "description", ""))
    description_matches = list(_FIX_ATTEMPT_SESSION_TOKEN_RE.finditer(description))
    if len(_FIX_ATTEMPT_SESSION_MARKER_RE.findall(description)) != len(description_matches):
        raise ValueError("invalid description session id marker")
    description_ids = [
        _validate_fix_attempt_session_id(match.group(1), "description")
        for match in description_matches
    ]
    if len(set(description_ids)) > 1:
        raise ValueError("conflicting session_id tokens in description")

    sources: list[tuple[str, str]] = []
    if explicit is not None:
        sources.append(("--session-id", _validate_fix_attempt_session_id(explicit, "--session-id")))
    if description_ids:
        sources.append(("description", description_ids[0]))
    environment = os.environ.get("CODEX_THREAD_ID")
    if environment is not None and environment != "":
        sources.append(("CODEX_THREAD_ID", _validate_fix_attempt_session_id(environment, "CODEX_THREAD_ID")))

    identities = {value for _, value in sources}
    if len(identities) > 1:
        details = ", ".join(f"{source}={value}" for source, value in sources)
        raise ValueError(f"conflicting session identities: {details}")
    if not sources:
        raise ValueError(
            "missing session identity; provide --session-id, description session_id=..., or CODEX_THREAD_ID"
        )

    # Remove caller-supplied copies before prepending the canonical token. This
    # guarantees exactly one session_id field without rewriting other prose.
    resolved = next(
        value
        for source in ("--session-id", "description", "CODEX_THREAD_ID")
        for candidate_source, value in sources
        if candidate_source == source
    )
    normalized_description = _FIX_ATTEMPT_SESSION_TOKEN_RE.sub("", description).strip()
    normalized = f"session_id={resolved}"
    if normalized_description:
        normalized = f"{normalized} {normalized_description}"
    return resolved, normalized


def cmd_fl_fix_attempt(args, root: Path):
    """Append a timestamped fix-attempt block to an FL entry in docs/FAILURE_LOG.md."""
    # FL-4855 / observer 34: all supported FL writers share the allocation
    # lock. An atomic rename alone still loses a sibling's completed append.
    with fl_write_lock(canonical_failure_log_path(root)):
        return _cmd_fl_fix_attempt_locked(args, root)


def _cmd_fl_fix_attempt_locked(args, root: Path):
    fl_path = canonical_failure_log_path(root)
    if not fl_path.exists():
        print(f"ERROR: docs/FAILURE_LOG.md not found at {fl_path}", file=sys.stderr)
        sys.exit(1)  # infrastructure missing — exit 1

    fl_id = args.fl_id.upper()
    if not re.match(r"^FL-\d+$", fl_id):
        print(
            f"ERROR: invalid FL ID format: '{args.fl_id}' (expected FL-NNN)",
            file=sys.stderr,
        )
        sys.exit(2)  # usage/caller error — exit 2

    try:
        session_id, description = _resolve_fix_attempt_session_id(args)
    except ValueError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        sys.exit(2)  # usage/caller error — refuse mutation without identity

    # Find FL entry in file
    with open(fl_path, encoding="utf-8") as f:
        lines = f.readlines()

    header_re = re.compile(r"^### (FL-\d+)\s*[—\-:]")
    duplicate_header_matches = [
        line.strip()
        for line in lines
        if (m := header_re.match(line)) and m.group(1) == fl_id
    ]
    if len(duplicate_header_matches) > 1:
        if getattr(args, "json", False):
            print(json.dumps({
                "error": "duplicate_id",
                "fl_id": fl_id,
                "session_id": session_id,
                "matches": duplicate_header_matches,
                "message": "refusing to append fix-attempt to duplicate FL id",
            }, indent=2))
        else:
            print(
                f"ERROR: duplicate FL id {fl_id}; refusing to append fix-attempt.",
                file=sys.stderr,
            )
            for match in duplicate_header_matches:
                print(f"  {match}", file=sys.stderr)
            print(
                f"Review `python3 scripts/analyze_runs.py fl show {fl_id}` and dedupe/rename before mutating.",
                file=sys.stderr,
            )
        sys.exit(2)
    found_starts: list[int] = []
    end_line = None
    for i, line in enumerate(lines):
        m = header_re.match(line)
        if m:
            found = m.group(
                1
            )  # use capture group — not re.search (avoids matching cross-refs in title)
            if found == fl_id:
                found_starts.append(i)
            elif found_starts:
                end_line = i
                break
        elif not found_starts and line.startswith("### "):
            # Combined header: ### FL-456 / FL-NNN — Title
            # Only check the identifier portion before the title separator so
            # we don't false-match cross-references in another entry's title
            # e.g. "### FL-100 — Regression from FL-457 fix" must NOT match FL-457
            sep_m = re.search(r"\s*[—:]\s*", line)
            header_part = line[: sep_m.start()] if sep_m else line
            if re.search(r"\b" + re.escape(fl_id) + r"\b", header_part):
                found_starts.append(i)

    if not found_starts:
        print(f"ERROR: {fl_id} not found in docs/FAILURE_LOG.md", file=sys.stderr)
        sys.exit(2)  # caller error (bad FL ID) — exit 2
    found_start = found_starts[0]

    # Insert point: just before end_line (or end of file if last entry)
    insert_at = end_line if end_line is not None else len(lines)
    entry_text = ''.join(lines[found_start:insert_at])
    ordinal_values = [int(value) for value in re.findall(
        r'^- \*\*Attempt sequence:\*\* (\d+)\s*$', entry_text, re.M)]
    legacy_count = len(re.findall(r'^#### Fix attempt\b', entry_text, re.M))
    attempt_sequence = max([legacy_count, *ordinal_values]) + 1

    # Keep the entry title in the result/log so callers can confirm the target.
    title_line = lines[found_start].rstrip()

    # Determine branch name
    branch = args.branch
    if not branch:
        try:
            branch = (
                subprocess.check_output(
                    ["git", "branch", "--show-current"],
                    stderr=subprocess.DEVNULL,
                    cwd=str(root),
                )
                .decode()
                .strip()
                or "unknown"
            )
        except Exception:
            branch = "unknown"

    date_str = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    json_mode = bool(getattr(args, "json", False))
    json_result: dict[str, Any] = {
        "fl_id": fl_id,
        "failure_log_path": str(fl_path),
        "branch": branch,
        "date": date_str,
        "entry_title": title_line,
        "session_id": session_id,
        "attempt_sequence": attempt_sequence,
    }
    explicit_touched_files = _dedupe_preserve_order(
        _normalize_overlay_list_value(getattr(args, "touched_file", []))
    )
    explicit_code_refs = _dedupe_preserve_order(
        _normalize_overlay_list_value(getattr(args, "code_ref", []))
    )
    try:
        _validate_fix_attempt_overlay_refs(explicit_touched_files, explicit_code_refs)
    except ValueError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        sys.exit(2)
    messages: list[str] = []
    proof_state = str(
        getattr(args, "proof_state", "") or "attempt logged; status unchanged"
    ).strip()
    if not proof_state or "\n" in proof_state or "\r" in proof_state:
        print("ERROR: --proof-state must be one non-empty line", file=sys.stderr)
        sys.exit(2)

    def emit(line: str = "") -> None:
        if json_mode:
            if line.strip():
                messages.append(line)
            return
        print(line)

    def capture_stdout(func, *func_args, **func_kwargs):
        if not json_mode:
            return func(*func_args, **func_kwargs), []
        buf = io.StringIO()
        with redirect_stdout(buf):
            result = func(*func_args, **func_kwargs)
        helper_lines = [line for line in buf.getvalue().splitlines() if line.strip()]
        return result, helper_lines

    block = (
        f"#### Fix attempt — {date_str} @ `{branch}`\n"
        f"\n"
        f"- **Approach:** {description}\n"
        f"- **Proof state:** {proof_state}.\n"
        f"- **Attempt sequence:** {attempt_sequence}\n"
    )
    emit(f"Found: {title_line}")

    # Find last non-blank line before insert_at to avoid double blank lines
    trim_at = insert_at
    while trim_at > found_start and lines[trim_at - 1].strip() == "":
        trim_at -= 1

    new_lines = lines[:trim_at] + ["\n"] + [block] + ["\n"] + lines[insert_at:]

    # Atomic write: write to temp file first, then rename to avoid truncation on crash
    tmp_fd, tmp_path = tempfile.mkstemp(
        dir=fl_path.parent,
        prefix=".FAILURE_LOG_tmp_",
        suffix=".md",
    )
    try:
        with os.fdopen(tmp_fd, "w", encoding="utf-8") as f:
            f.writelines(new_lines)
        os.replace(tmp_path, fl_path)
    except Exception:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise

    json_result["fix_attempt_block"] = block.rstrip()
    emit(f"Appended fix-attempt block to {fl_id} in docs/FAILURE_LOG.md")
    emit(block.rstrip())

    # Emit required-fields advisory so the caller (agent or human) knows what
    # instrumentation must exist before this fix attempt can be falsified.
    # Non-blocking: always printed but never causes a non-zero exit.
    advisory = fl_required_fields_advisory_for_id(root, fl_id)
    req_fields = advisory.get("required_fields") or []
    json_result["required_fields_advisory"] = req_fields
    json_result["required_fields_source"] = advisory.get("source") or "none"
    json_result["required_fields_has_gap"] = bool(advisory.get("has_gap"))
    if req_fields:
        emit()
        emit("⚠  Falsifiability gap — these fields must exist in the recorder")
        emit("   surface before this fix can be proven or falsified:")
        for f in req_fields:
            emit(f"     {f}")
        emit("   Add them to engine/game.h + web/game_web.cpp + watchdog surface")
        emit("   BEFORE implementing the fix.")

    mirror_report_path = None
    synced_spec_path = None
    actionable_curated: list[tuple[str, str, str]] = []
    if not getattr(args, "no_canon_spec_sync", False):
        mirror_report_path, helper_lines = capture_stdout(
            _append_canon_spec_fix_attempt_mirror,
            root,
            fl_id,
            description,
            branch,
            date_str,
            proof_state,
        )
        messages.extend(helper_lines)
        (curated_spec_path, curated_changes), helper_lines = capture_stdout(
            _sync_canon_spec_curated_mirrors,
            root,
            write=True,
        )
        messages.extend(helper_lines)
        actionable_curated = [
            c
            for c in curated_changes
            if c[0] not in ("missing_file", "missing_section", "missing_table")
        ]
        if actionable_curated:
            emit("Synced canon spec curated mirrors after fix-attempt:")
            for kind, section, key in actionable_curated:
                emit(f"  {kind}: {key} in {section}")
        if curated_spec_path is not None and actionable_curated:
            synced_spec_path = curated_spec_path
    json_result["mirror_report_path"] = (
        str(mirror_report_path) if mirror_report_path is not None else None
    )
    json_result["canon_spec_path"] = str(synced_spec_path) if synced_spec_path is not None else None
    json_result["curated_mirror_changes"] = [
        {"kind": kind, "section": section, "key": key}
        for kind, section, key in actionable_curated
    ]

    lane_doc_refresh: dict[str, Any] | None = None
    if fl_id in FL4359_LANE_DOC_IDS and not getattr(args, "no_lane_doc_refresh", False):
        lane_doc_refresh = _refresh_fl4359_lane_docs(root, write=True)
        changed_paths = lane_doc_refresh.get("changed_paths") or []
        emit("FL-4359 durable owner remains docs/FAILURE_LOG.md after fix-attempt:")
        emit(f"  attempts={lane_doc_refresh['attempt_total']}")
        emit("  updated parallel lane docs: none")
    json_result["lane_doc_refresh"] = lane_doc_refresh

    inline_comment_mode = "skipped"
    inline_comment_edit_count = 0
    inline_comment_paths: list[str] = []
    if getattr(args, "auto_inline_comments", False) or not getattr(args, "no_inline_comment_suggestions", False):
        # FL-2300 / FL-703: family-scope comment planning is a historical aid,
        # not a license to sweep every semantically connected later lane into
        # source edits. The planner itself narrows this to same-epoch context.
        plan = _inline_comment_plan_for_fl(
            root,
            fl_id,
            family_scope=getattr(args, "auto_inline_comments_family_scope", False),
            max_ids=getattr(args, "inline_comment_max_ids", 8),
            allow_prune=getattr(args, "allow_inline_comment_prune", False),
            drop_stale_ids=getattr(args, "drop_stale_inline_ids", False),
            annotate_accounted_ids=not getattr(args, "no_accounted_inline_annotations", False),
            fail_on_contradiction=getattr(args, "fail_on_inline_contradiction", False),
        )
        write_inline = bool(getattr(args, "auto_inline_comments", False))
        _, helper_lines = capture_stdout(_print_inline_comment_plan, plan, write=write_inline)
        messages.extend(helper_lines)
        if write_inline:
            _write_inline_comment_plan(root, plan)
            inline_comment_mode = "wrote"
            inline_comment_edit_count = len(plan["edits"])
            inline_comment_paths = _dedupe_preserve_order(
                [str(edit.get("path") or "") for edit in plan["edits"] if isinstance(edit, dict)]
            )
            emit(f"Wrote {len(plan['edits'])} inline comment edit(s).")
        else:
            inline_comment_mode = "dry_run"
            inline_comment_edit_count = len(plan["edits"])
            emit("Dry run only. Re-run with --auto-inline-comments to edit source comments.")
        emit("Safe inline maintenance: python3 scripts/analyze_runs.py fl maintain-inline-comments")
    json_result["inline_comment_mode"] = inline_comment_mode
    json_result["inline_comment_edit_count"] = inline_comment_edit_count

    generated_touched_files = [_repo_relative_str(root, fl_path)]
    if synced_spec_path is not None:
        generated_touched_files.append(_repo_relative_str(root, synced_spec_path))
    if lane_doc_refresh is not None:
        generated_touched_files.extend(str(rel) for rel in lane_doc_refresh.get("changed_paths") or [])
    generated_touched_files.extend(inline_comment_paths)

    auto_overlay_refs: dict[str, Any] = {"written": False}
    generated_overlay_refs = (
        [] if getattr(args, "no_auto_overlay_refs", False) else generated_touched_files
    )
    if explicit_touched_files or explicit_code_refs or generated_overlay_refs:
        auto_overlay_refs = _append_fl_auto_overlay_refs(
            root,
            fl_id,
            touched_files=_dedupe_preserve_order(explicit_touched_files + generated_overlay_refs),
            code_refs=explicit_code_refs,
        )
        if auto_overlay_refs.get("written"):
            emit("Synced overlay refs after fix-attempt:")
            added_touched = auto_overlay_refs.get("added_touched_files") or []
            added_code = auto_overlay_refs.get("added_code_refs") or []
            if added_touched:
                emit(f"  TouchedFiles +{len(added_touched)}")
            if added_code:
                emit(f"  CodeRefs +{len(added_code)}")
    json_result["auto_overlay_refs"] = auto_overlay_refs
    json_result["explicit_overlay_refs"] = {
        "touched_files": explicit_touched_files,
        "code_refs": explicit_code_refs,
    }

    staged_paths: list[str] = []
    if args.stage:
        stage_paths = [str(fl_path)]
        if synced_spec_path is not None:
            stage_paths.append(str(synced_spec_path))
        if lane_doc_refresh is not None:
            for rel in lane_doc_refresh.get("changed_paths") or []:
                stage_paths.append(str(root / rel))
        for rel in inline_comment_paths:
            stage_paths.append(str(root / rel))
        stage_paths = _dedupe_preserve_order(stage_paths)
        rc = subprocess.run(["git", "add", *stage_paths], cwd=str(root)).returncode
        if rc == 0:
            staged_names = ", ".join(Path(p).name for p in stage_paths)
            staged_paths = stage_paths
            emit(f"Staged: {staged_names}")
        else:
            print(
                f"ERROR: git add failed (rc={rc}) — file is written but NOT staged",
                file=sys.stderr,
            )
            sys.exit(1)
    json_result["staged_paths"] = staged_paths
    if messages:
        json_result["messages"] = messages
    if json_mode:
        print(json.dumps(json_result))


def cmd_fl_add(args, root: Path):
    """Append a new FL entry to the failure log with optional overlay row."""
    fl_path = canonical_failure_log_path(root)
    if not fl_path.parent.exists():
        fl_path.parent.mkdir(parents=True, exist_ok=True)

    # FL-4020 serialise parallel 'fl add' so id allocation and the
    # markdown+overlay write happen atomically against other processes.
    with fl_write_lock(fl_path):
        return _cmd_fl_add_locked(args, root, fl_path)


def _cmd_fl_add_locked(args, root: Path, fl_path: Path):
    if not fl_path.exists():
        existing_entries: list[FailureEntry] = []
        snapshot = FailureLogSnapshot(fl_path)
    else:
        # FL-4729: allocate from the same post-lock immutable view used to
        # parse entries, including overlay-only ids.
        snapshot = FailureLogSnapshot(fl_path)
        existing_entries = read_failure_log(fl_path, snapshot=snapshot)

    try:
        fl_id = next_failure_id(existing_entries, fl_path=fl_path, snapshot=snapshot)

        status = _normalize_status_value(getattr(args, "status", "OPEN"))
        if status and status not in VALID_STATUS:
            raise ValueError(f"Unsupported status: {status}")
        date_opened = str((getattr(args, "date_opened", "") or "").strip())
        if not date_opened:
            date_opened = datetime.now(timezone.utc).strftime("%Y-%m-%d")

        related_ids = [
            value.upper()
            for value in _split_csv_values(getattr(args, "related", None))
            if re.fullmatch(r"FL-\d+", str(value).upper())
        ]
        evidence = _split_csv_values(getattr(args, "evidence", None))
        category = str((getattr(args, "category", "") or "").strip())
        title = str((getattr(args, "title", "") or "").strip())
        # FL-4023 strip a leading 'FL-NNNN[:-—]\s*' prefix the caller may have
        # included in the title — the formatter prepends the assigned id, so
        # without this we get 'FL-NEW: FL-OLD: ...' double prefixes.
        title = re.sub(r"^\s*FL-\d+\s*[:\-—]?\s*", "", title)
        description = str((getattr(args, "description", "") or "").strip())
        root_cause = str((getattr(args, "root_cause", "") or "").strip())
        resolution = str((getattr(args, "resolution", "") or "").strip())
        date_resolved = str((getattr(args, "date_resolved", "") or "").strip())

        if not title:
            raise ValueError("missing required title")
        if not category:
            raise ValueError("missing required category")
        if not description:
            raise ValueError("missing required description")
        # FL-4023 fail fast when ACCOUNTED is requested without --resolution,
        # rather than silently writing an unresolvable entry.
        if status == "ACCOUNTED" and not resolution:
            raise ValueError(
                "ACCOUNTED status requires --resolution \"<one-line why this is accepted>\""
            )

        entry = FailureEntry(
            failure_id=fl_id,
            title=title,
            status=status,
            date_opened=date_opened,
            category=category,
            description=description,
            root_cause=root_cause,
            evidence=evidence,
            resolution=resolution,
            date_resolved=date_resolved,
            related_ids=related_ids,
        )
    except Exception as exc:
        if getattr(args, "json", False):
            _emit_fl_json_error(
                command="fl add",
                error="invalid_input",
                exit_code=1,
                extra={"message": str(exc)},
            )
        print(f"error: {exc}", file=sys.stderr)
        sys.exit(1)

    dry_run = bool(getattr(args, "dry_run", False))
    json_mode = bool(getattr(args, "json", False))
    try:
        overlay_row = _build_fl_add_overlay_row(fl_id, args)
    except ValueError as exc:
        if json_mode:
            _emit_fl_json_error(
                command="fl add",
                error="invalid_overlay_value",
                exit_code=2,
                extra={"message": str(exc)},
            )
        print(f"error: {exc}", file=sys.stderr)
        sys.exit(2)
    should_write_overlay = len(overlay_row) > 1
    staged_paths: list[str] = []

    # FL-4021 overlay completeness gate: refuse to write entries with
    # empty CodeRefs / ComplaintRefs unless the caller explicitly bypasses.
    missing_required = _fl_add_missing_required_fields(overlay_row, args)
    if missing_required:
        message = (
            "fl add refused: required overlay fields missing — "
            + ", ".join(missing_required)
            + ". Pass --overlay-code-ref <file:line> for CodeRefs, "
            + "--overlay-complaint-ref FL-NNNN for ComplaintRefs, or "
            + "--allow-empty-coderefs / --no-parent to bypass."
        )
        if json_mode:
            _emit_fl_json_error(
                command="fl add",
                error="overlay_required_fields_missing",
                exit_code=2,
                extra={"message": message, "missing": missing_required},
            )
        print(f"error: {message}", file=sys.stderr)
        sys.exit(2)

    entry_markdown = append_entry(entry, path=fl_path, dry_run=dry_run)
    if not dry_run:
        if should_write_overlay:
            if not _write_overlay_rows(root, [overlay_row]):
                if json_mode:
                    _emit_fl_json_error(
                        command="fl add",
                        error="overlay_write_failed",
                        exit_code=1,
                        fl_id=fl_id,
                    )
                print("error: overlay section missing and failed to create", file=sys.stderr)
                sys.exit(1)
        _replace_failure_log_snapshot_after_write(fl_path)
        if getattr(args, "stage", False):
            stage_proc = subprocess.run(["git", "add", str(fl_path)], cwd=str(root))
            if stage_proc.returncode != 0:
                print(
                    f"ERROR: git add failed (rc={stage_proc.returncode})",
                    file=sys.stderr,
                )
                sys.exit(1)
            staged_paths.append(str(fl_path))

    payload = {
        "command": "fl add",
        "fl_id": fl_id,
        "failure_log_path": str(fl_path),
        "status": status,
        "title": title,
        "category": category,
        "date_opened": date_opened,
        "related": related_ids,
        "dry_run": dry_run,
        "markdown": entry_markdown,
        "entry_line_count": len(entry_markdown.splitlines()),
        "overlay_row_written": bool(not dry_run and should_write_overlay),
    }
    if should_write_overlay:
        payload["overlay_row"] = overlay_row
    if staged_paths:
        payload["staged_paths"] = staged_paths

    if json_mode:
        print(json.dumps(payload))
        return

    if dry_run:
        print("DRY-RUN; not written.")
    print(f"Appended {fl_id} to docs/FAILURE_LOG.md")
    if should_write_overlay:
        print(f"Wrote overlay row for {fl_id}")
    if getattr(args, "stage", False) and not dry_run:
        print(f"Staged: {Path(fl_path).name}")


def cmd_fl_note(args, root: Path) -> None:
    """Append a dated evidence/update block to an existing FL entry and optionally write a minimal overlay row."""
    fl_id = (getattr(args, "parent", "") or "").strip().upper()
    if not re.match(r"^FL-\d+$", fl_id):
        _emit_fl_json_error(
            command="fl note",
            error="invalid_parent",
            exit_code=1,
            extra={"message": f"invalid FL ID format: {getattr(args, 'parent', '')!r}"},
        )
        return

    note_text = str((getattr(args, "note", "") or "").strip())
    if not note_text:
        _emit_fl_json_error(
            command="fl note",
            error="missing_note",
            exit_code=1,
            extra={"message": "note text is required"},
        )
        return

    severity = str((getattr(args, "severity", "") or "info")).strip().lower()
    if severity not in {"blocker", "warning", "info"}:
        severity = "info"

    dry_run = bool(getattr(args, "dry_run", False))
    json_mode = bool(getattr(args, "json", False))
    auto_stage = bool(getattr(args, "auto_stage", False))

    fl_path = canonical_failure_log_path(root)
    if not fl_path.exists():
        _emit_fl_json_error(
            command="fl note",
            error="missing_failure_log",
            exit_code=1,
            extra={"message": str(fl_path)},
        )
        return

    content = fl_path.read_text(encoding="utf-8")

    entry_header = re.compile(rf"^###\s+{re.escape(fl_id)}\s*[:\-—]", re.MULTILINE)
    match = entry_header.search(content)
    if not match:
        _emit_fl_json_error(
            command="fl note",
            error="not_found",
            exit_code=2,
            fl_id=fl_id,
        )
        return

    block_start = match.start()
    next_hdr = re.search(r"^### ", content[match.end():], re.MULTILINE)
    block_end = match.end() + next_hdr.start() if next_hdr else len(content)

    date_str = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    collapsed_note = " ".join(note_text.split())
    one_line_summary = collapsed_note[:120]

    update_lines = [
        "",
        f"#### Update — {date_str}",
        "",
        f"- **Severity:** {severity.upper()}",
        f"- **Finding:** {note_text}",
        "",
    ]
    update_text = "\n".join(update_lines)

    if not dry_run:
        new_content = (
            content[:block_end].rstrip("\n")
            + "\n"
            + update_text
            + "\n"
            + content[block_end:]
        )
        fl_path.write_text(new_content, encoding="utf-8")

    counter_state = f"{severity}:{date_str}:{one_line_summary}"
    overlay_row = {
        "fl": fl_id,
        "ComplaintCounterState": counter_state,
    }
    overlay_written = False
    if not dry_run:
        overlay_written = _write_overlay_rows(root, [overlay_row])

    staged_paths: list[str] = []
    if auto_stage and not dry_run:
        stage_proc = subprocess.run(["git", "add", str(fl_path)], cwd=str(root))
        if stage_proc.returncode == 0:
            staged_paths.append(str(fl_path))

    payload: dict[str, Any] = {
        "command": "fl note",
        "fl_id": fl_id,
        "severity": severity,
        "date": date_str,
        "note": note_text,
        "summary": one_line_summary,
        "dry_run": dry_run,
        "overlay_row": overlay_row,
        "overlay_row_written": overlay_written,
    }
    if staged_paths:
        payload["staged_paths"] = staged_paths

    if json_mode:
        print(json.dumps(payload))
        return

    if dry_run:
        print("DRY-RUN; not written.")
    print(f"Appended note to {fl_id}")
    if overlay_written:
        print(f"Wrote overlay row for {fl_id}")
    if staged_paths:
        print(f"Staged: {Path(fl_path).name}")


def cmd_fl_adhoc(args, root: Path) -> None:
    """Create an ad-hoc script file and log it as a tooling-gap FL entry in one shot."""
    description = str((getattr(args, "title", "") or "").strip())
    if not description:
        _emit_fl_json_error(
            command="fl adhoc",
            error="missing_description",
            exit_code=1,
            extra={"message": "adhoc description is required"},
        )
        return

    script_src = str((getattr(args, "script", "") or "").strip())
    use_stdin = script_src == "-"
    script_body = ""
    if use_stdin:
        script_body = sys.stdin.read()
    elif script_src:
        script_path = Path(script_src)
        if script_path.exists():
            script_body = script_path.read_text(encoding="utf-8")
        else:
            _emit_fl_json_error(
                command="fl adhoc",
                error="script_not_found",
                exit_code=1,
                extra={"message": f"script file not found: {script_src}"},
            )
            return

    dry_run = bool(getattr(args, "dry_run", False))
    json_mode = bool(getattr(args, "json", False))
    auto_stage = bool(getattr(args, "auto_stage", False))

    # Generate dated filename
    date_str = datetime.now(timezone.utc).strftime("%Y-%m-%d")
    safe_desc = re.sub(r"[^\w\s-]", "", description).strip().replace(" ", "-")[:60]
    adhoc_dir = root / "scripts" / "adhoc"
    if not dry_run:
        adhoc_dir.mkdir(parents=True, exist_ok=True)
    ext = "py" if not script_body or "#!/bin/bash" not in script_body[:200] else "sh"
    adhoc_file = adhoc_dir / f"{date_str}-{safe_desc}.{ext}"
    file_path_str = str(adhoc_file.relative_to(root))

    if not dry_run:
        header = f"# Ad hoc script: {description}\n# Created: {date_str}\n# Canonical gap: <describe what tool should own this>\n\n"
        adhoc_file.write_text(header + script_body, encoding="utf-8")

    # Now append FL entry — FL-4020 serialise id allocation + write under file lock
    fl_path = canonical_failure_log_path(root)
    with fl_write_lock(fl_path):
        return _cmd_fl_adhoc_locked(
            args,
            root,
            fl_path,
            description=description,
            script_body=script_body,
            file_path_str=file_path_str,
            date_str=date_str,
            adhoc_file=adhoc_file,
            dry_run=dry_run,
            json_mode=json_mode,
            auto_stage=auto_stage,
        )


def _cmd_fl_adhoc_locked(
    args,
    root: Path,
    fl_path: Path,
    *,
    description: str,
    script_body: str,
    file_path_str: str,
    date_str: str,
    adhoc_file: Path,
    dry_run: bool,
    json_mode: bool,
    auto_stage: bool,
) -> None:
    # FL-4729: the writer constructs its snapshot only after taking the lock.
    snapshot = FailureLogSnapshot(fl_path)
    existing_entries = (
        read_failure_log(fl_path, snapshot=snapshot) if fl_path.exists() else []
    )
    try:
        fl_id = next_failure_id(existing_entries, fl_path=fl_path, snapshot=snapshot)
        entry = FailureEntry(
            failure_id=fl_id,
            title=f"Ad hoc script: {description}",
            status="OPEN",
            date_opened=date_str,
            category="TOOLING",
            description=f"Ad hoc script created because the canonical tooling surface lacks support for: {description}. See {file_path_str}.",
            related_ids=[],
        )
    except Exception as exc:
        print(f"error: {exc}", file=sys.stderr)
        sys.exit(1)

    entry_markdown = append_entry(entry, path=fl_path, dry_run=dry_run)
    overlay_row = {
        "fl": fl_id,
        "Category": "tooling",
        "Kinds": ["process_gap"],
        "CodeRefs": [file_path_str],
        "TouchedFiles": [file_path_str],
    }
    overlay_written = False
    if not dry_run:
        overlay_written = _write_overlay_rows(root, [overlay_row])
        _replace_failure_log_snapshot_after_write(fl_path)

    staged_paths: list[str] = []
    if auto_stage and not dry_run:
        for p in (fl_path, adhoc_file):
            stage_proc = subprocess.run(["git", "add", str(p)], cwd=str(root))
            if stage_proc.returncode == 0:
                staged_paths.append(str(p.relative_to(root)))

    payload = {
        "command": "fl adhoc",
        "fl_id": fl_id,
        "title": entry.title,
        "adhoc_file": file_path_str,
        "dry_run": dry_run,
        "overlay_row_written": overlay_written,
    }
    if staged_paths:
        payload["staged_paths"] = staged_paths

    if json_mode:
        print(json.dumps(payload))
        return

    if dry_run:
        print("DRY-RUN; not written.")
    else:
        print(f"Appended {fl_id} to docs/FAILURE_LOG.md")
        print(f"Wrote {file_path_str}")
        if overlay_written:
            print(f"Wrote overlay row for {fl_id}")
        if staged_paths:
            print(f"Staged: {', '.join(staged_paths)}")


def _table_cell(text: str, limit: int = 240) -> str:
    one_line = " ".join(str(text or "").split())
    one_line = one_line.replace("|", "\\|")
    if len(one_line) > limit:
        one_line = one_line[: limit - 3].rstrip() + "..."
    return one_line or "-"


def _append_canon_spec_fix_attempt_mirror(
    root: Path,
    fl_id: str,
    description: str,
    branch: str,
    date_str: str,
    proof_state: str,
) -> Path | None:
    report_path = root / "artifacts" / "maintainer" / "watchdog_mirrors.md"
    report_path.parent.mkdir(parents=True, exist_ok=True)

    row = (
        f"| {date_str} | {fl_id} | `{_table_cell(branch, 80)}` | "
        f"{_table_cell(proof_state)} | {_table_cell(description)} |\n"
    )

    if report_path.exists():
        content = report_path.read_text(encoding="utf-8")
    else:
        content = (
            "# Watchdog Mirrors\n\n"
            "Generated watchdog run and fix-attempt summaries live here so they do not "
            "regrow inside the canon spec.\n\n"
        )
    section_header = "### Failure-Log Fix-Attempt Mirror (auto-synced)\n"
    section_intro = (
        "`analyze_runs.py fl fix-attempt` keeps compact rows here after writing "
        "`docs/FAILURE_LOG.md`. This table is a navigation mirror only; the failure log "
        "remains authoritative and closure still requires human signoff plus proof.\n"
    )
    heading_re = re.compile(
        r"^#{3,4} Failure-Log Fix-Attempt Mirror \(auto-synced\)\n",
        re.MULTILINE,
    )
    matches = list(heading_re.finditer(content))

    rows: list[str] = []
    seen_rows: set[str] = set()
    for match in matches:
        section_end = _find_next_md_header(content, match.end())
        section_text = content[match.start():section_end]
        for line in section_text.splitlines(keepends=True):
            if not line.startswith("|"):
                continue
            if line.startswith("| Date ") or line.startswith("|---"):
                continue
            if line in seen_rows:
                continue
            rows.append(line)
            seen_rows.add(line)

    if row not in seen_rows:
        rows.append(row)
        seen_rows.add(row)
    elif len(matches) == 1:
        print(f"Canon spec mirror already contained {fl_id} fix-attempt row")
        return report_path

    new_section = (
        section_header
        + "\n"
        + section_intro
        + "\n"
        + "| Date | FL | Branch | Proof state | Approach |\n"
        + "|---|---|---|---|---|\n"
        + "".join(rows)
        + "\n"
    )

    if matches:
        for match in reversed(matches[1:]):
            section_end = _find_next_md_header(content, match.end())
            content = content[:match.start()] + content[section_end:]
        first = matches[0]
        first_end = _find_next_md_header(content, first.end())
        content = content[:first.start()] + new_section + content[first_end:]
    else:
        recent_runs_header = "## Recent Watchdog Runs\n"
        section_pos = content.find(recent_runs_header)
        if section_pos != -1:
            insert_at = _find_next_md_header(content, section_pos + len(recent_runs_header))
            prefix = "" if content[:insert_at].endswith("\n\n") else "\n"
            content = content[:insert_at] + prefix + new_section + content[insert_at:]
        else:
            content = content.rstrip() + "\n\n" + new_section

    tmp_fd, tmp_path = tempfile.mkstemp(
        dir=report_path.parent,
        prefix=".WATCHDOG_MIRROR_tmp_",
        suffix=".md",
    )
    try:
        with os.fdopen(tmp_fd, "w", encoding="utf-8") as f:
            f.write(content)
        os.replace(tmp_path, report_path)
    except Exception:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise

    print(f"Updated watchdog mirror report for {fl_id}")
    return report_path


