def _classify_attempt_approach(approach: str) -> tuple[str, str]:
    """Return (class_id, keyword_matched) for a block's Approach prefix."""
    for pattern, class_id in _ATTEMPT_CLASS_RULES:
        m = re.search(pattern, approach)
        if m:
            return class_id, m.group(0)
    return "unknown", ""


def _extract_attempt_lineage_counter(raw: str) -> dict | None:
    """Extract attempt_counter from an embedded LINEAGE_JSON block, or None."""
    m = _ATTEMPT_LINEAGE_JSON_RE.search(raw)
    if not m:
        return None
    try:
        import json as _j
        return _j.loads(m.group(1))
    except Exception:
        return None


def cmd_fl_attempt_accounting(args, root: Path) -> None:
    """
    Classify fix-attempt headers for one or more FL entries.

    For each FL:
    - If the body has a LINEAGE_JSON attempt_counter, report it as authoritative
      (Tier 1).  Post-tombstone accounting headers are counted but not re-classified.
    - Otherwise, apply keyword rules to each block's Approach prefix (Tier 2).
      Results are true relative to those rules, not facts from the log headers.

    Header counts (total #### Fix attempt blocks per FL) are always reported
    and are structurally derivable without body parsing.
    """
    import json as _json

    raw_ids = getattr(args, "fl_ids", "") or ""
    fl_ids = [x.strip().upper() for x in raw_ids.split(",") if x.strip()]
    if not fl_ids:
        sys.exit("error: --fl-ids required (comma-separated, e.g. FL-2957,FL-3688)")

    since_raw = getattr(args, "since", None)
    until_raw = getattr(args, "until", None)

    results = []
    for fl_id in fl_ids:
        if not re.match(r"^FL-\d+$", fl_id):
            sys.exit(f"error: invalid FL ID format: {fl_id!r}")
        raw = _fl_extract_raw(root, fl_id)
        if raw is None:
            sys.exit(f"error: {fl_id} not found in docs/FAILURE_LOG.md")

        blocks = fl_fix_attempt_blocks(raw)

        # Apply date filter if requested
        if since_raw or until_raw:
            filtered = []
            for b in blocks:
                d = b.get("date", "")
                if since_raw and d < since_raw:
                    continue
                if until_raw and d > until_raw:
                    continue
                filtered.append(b)
            blocks = filtered

        total_headers = len(blocks)

        # Tier 1: authoritative tombstone
        counter = _extract_attempt_lineage_counter(raw)
        if counter:
            auth_total = counter.get("total", 0)
            overhead = max(0, total_headers - auth_total)
            results.append({
                "fl": fl_id,
                "total_headers": total_headers,
                "source": "lineage_json_tombstone",
                "authoritative": counter,
                "accounting_overhead_headers": overhead,
                "by_class": {},
            })
            continue

        # Tier 2: classifier
        by_class: dict[str, list[dict]] = {}
        _approach_re = re.compile(r"\*\*Approach:\*\*\s+(.+)", re.DOTALL)
        for i, block in enumerate(blocks, 1):
            am = _approach_re.search(block["body"])
            approach_raw = am.group(1).strip()[:300] if am else ""
            class_id, kw = _classify_attempt_approach(approach_raw)
            entry = {
                "number": i,
                "date": block["date"],
                "branch": block["branch"],
                "approach_snippet": approach_raw[:80],
                "class_id": class_id,
                "keyword_matched": kw,
            }
            by_class.setdefault(class_id, []).append(entry)

        results.append({
            "fl": fl_id,
            "total_headers": total_headers,
            "source": "classifier",
            "authoritative": None,
            "accounting_overhead_headers": 0,
            "by_class": by_class,
        })

    if getattr(args, "json", False):
        print(_json.dumps(results, indent=2))
        return

    summary_only = getattr(args, "summary", False)
    _print_attempt_accounting(results, summary_only=summary_only)


def _print_attempt_accounting(results: list[dict], summary_only: bool = False) -> None:
    """Print the attempt accounting report."""
    total_headers_all = sum(r["total_headers"] for r in results)
    print("=" * 78)
    print("ATTEMPT ACCOUNTING REPORT")
    print(f"Source: analyze_runs.py fl attempt-accounting")
    print(f"Total #### Fix attempt headers across listed FLs: {total_headers_all}")
    print()
    print("AUTHORITY TIERS")
    print("-" * 78)
    print("  Tier 1 (tombstone): LINEAGE_JSON attempt_counter in FL body — authoritative")
    print("  for the numbered attempt table. Post-tombstone headers counted separately.")
    print("  Tier 2 (classifier): keyword rules on Approach prefix — true relative to")
    print("  those rules, not facts derivable from log headers alone.")
    print()

    if not summary_only:
        for r in results:
            fl = r["fl"]
            total_h = r["total_headers"]
            print("=" * 78)
            if r["source"] == "lineage_json_tombstone":
                ac = r["authoritative"]
                overhead = r["accounting_overhead_headers"]
                print(f"  {fl}  —  {total_h} headers  [Tier 1: tombstone]")
                print("-" * 78)
                print(f"  Numbered attempts 1–{ac.get('total',0)} (authoritative):")
                print(f"    total={ac.get('total',0)}"
                      f"  runtime_fixes={ac.get('runtime_fixes',0)}"
                      f"  tooling_only={ac.get('tooling_only',0)}"
                      f"  observation_only={ac.get('observation_only',0)}"
                      f"  documentation_only={ac.get('documentation_only',0)}")
                if overhead:
                    print(f"  Post-tombstone accounting headers (not fix attempts): {overhead}")
            else:
                by_class = r["by_class"]
                print(f"  {fl}  —  {total_h} headers  [Tier 2: classifier]")
                print("-" * 78)
                class_display = {
                    "candidate_fix": "CANDIDATE FIX",
                    "tooling": "TOOLING/INSTRUMENTATION",
                    "observation": "OBSERVATION/RECEIPT",
                    "analysis": "ANALYSIS/DIAGNOSIS",
                    "intent": "INTENT/PLANNING",
                    "meta_analysis": "META-ANALYSIS",
                    "disqualified": "DISQUALIFIED",
                    "unknown": "UNKNOWN",
                }
                for class_id, display in class_display.items():
                    items = by_class.get(class_id, [])
                    if not items:
                        continue
                    print(f"  {display} ({len(items)})")
                    for b in items:
                        kw = f"[{b['keyword_matched']}] " if b.get("keyword_matched") else ""
                        snippet = b["approach_snippet"].replace("\n", " ")
                        print(f"    [{b['number']}] {b['date']}  {kw}{snippet}…")
            print()

    # Summary table
    print("=" * 78)
    print("SUMMARY")
    print(f"  {'FL':<12} {'HDRS':>5}  {'AUTH':>5}  {'OVHD':>5}  {'FIX':>4}  {'TOOL':>4}  {'OBS':>4}  {'ANAL':>4}  SOURCE")
    print(f"  {'-'*12} {'-'*5}  {'-'*5}  {'-'*5}  {'-'*4}  {'-'*4}  {'-'*4}  {'-'*4}  ------")
    for r in results:
        fl = r["fl"]
        h = r["total_headers"]
        if r["source"] == "lineage_json_tombstone":
            ac = r["authoritative"]
            ov = r["accounting_overhead_headers"]
            print(f"  {fl:<12} {h:>5}  {ac.get('total',0):>5}  {ov:>5}  "
                  f"{ac.get('runtime_fixes',0):>4}  {ac.get('tooling_only',0):>4}  "
                  f"{ac.get('observation_only',0):>4}  {ac.get('documentation_only',0):>4}  tombstone")
        else:
            bc = r["by_class"]
            fx = len(bc.get("candidate_fix", []))
            tl = len(bc.get("tooling", []))
            ob = len(bc.get("observation", []))
            an = len(bc.get("analysis", []))
            print(f"  {fl:<12} {h:>5}  {'—':>5}  {'—':>5}  {fx:>4}  {tl:>4}  {ob:>4}  {an:>4}  classifier")
    print()
    print("COLUMNS: HDRS=total headers | AUTH=tombstone total | OVHD=post-tombstone overhead")
    print("         FIX/TOOL/OBS/ANAL: tombstone fields or classifier classes")


def cmd_fl_fix_history(args, root: Path):
    """Show the fix-attempt timeline for a single FL entry."""
    fl_id = args.fl_id.upper()
    if not re.match(r"^FL-\d+$", fl_id):
        sys.exit(f"error: invalid FL ID format: {args.fl_id!r}  (expected FL-NNN)")

    raw = _fl_extract_raw(root, fl_id)
    if raw is None:
        sys.exit(f"error: {fl_id} not found in docs/FAILURE_LOG.md")

    blocks = fl_fix_attempt_blocks(raw)
    if getattr(args, "json", False):
        print(json.dumps({"fl": fl_id, "attempts": blocks, "count": len(blocks)}, indent=2))
        return
    if not blocks:
        print(f"FIX HISTORY: {fl_id}\n")
        print("  No fix-attempt blocks found in this entry.")
        return

    print(
        f"FIX HISTORY: {fl_id}  ({len(blocks)} attempt{'s' if len(blocks) != 1 else ''})\n"
    )
    for i, block in enumerate(blocks, 1):
        date_str = block["date"]
        branch = block["branch"]
        suffix = f" ({block['suffix']})" if block.get("suffix") else ""
        block_body = block["body"]

        print(f"[{i}] {date_str}  @  {branch}{suffix}")
        for line in block_body.splitlines():
            stripped = line.strip()
            if not stripped:
                continue
            if stripped.startswith("- **") or stripped.startswith("**"):
                label = stripped[:120] + ("…" if len(stripped) > 120 else "")
                print(f"     {label}")
            elif getattr(args, "full", False) and not stripped.startswith("#"):
                print(f"     {stripped[:120]}")
        print()


def cmd_fl_ledger_receipts(args, root: Path):
    """Backfill conservative receipt rows from the multiplayer regression ledger."""
    payload = build_multiplayer_ledger_receipt_payload(
        root,
        fl_id_filter=getattr(args, "fl_id", None),
        receipt_class_filter=getattr(args, "receipt_class", None),
    )
    out_path = str(getattr(args, "out", "") or "").strip()
    if out_path:
        dest = Path(out_path).expanduser()
        if not dest.is_absolute():
            dest = (root / dest).resolve()
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(json.dumps(payload, indent=2) + "\n", encoding="utf-8")
        payload["written_path"] = str(dest)
    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2))
        return
    counts = payload.get("receipt_counts") or {}
    print("MULTIPLAYER LEDGER RECEIPTS")
    print(f"  source:  {payload.get('source')}")
    print(f"  rows:    {payload.get('entry_count', 0)}")
    print(
        "  counts:  "
        f"runtime={counts.get('runtime_receipt', 0)}  "
        f"derived={counts.get('derived_receipt', 0)}  "
        f"insufficient={counts.get('insufficient_evidence', 0)}"
    )
    if payload.get("written_path"):
        print(f"  wrote:   {payload['written_path']}")
    print("")
    for item in payload.get("receipts") or []:
        summary = (
            f"  L{item.get('ledger_line')}: {item.get('receipt_class')}  "
            f"{item.get('header')}"
        )
        evidence_gap = item.get("evidence_gap") or {}
        reason = str(evidence_gap.get("reason") or "").strip()
        warning_tags = list(evidence_gap.get("warning_tags") or [])
        if reason:
            summary += f"  [gap={reason}]"
        if warning_tags:
            summary += f"  [warn={','.join(warning_tags)}]"
        print(summary)


_HYP_UPDATE_HDR = re.compile(
    r"^> \*\*(\[.*?\]\s*)?(?:NEW |WRONG |STALE |DISPROVEN |CONFIRMED )?[Hh]ypothesis.*?\*\*",
    re.MULTILINE,
)


def cmd_fl_hypothesis(args, root: Path):
    """Show hypothesis field and any inline updates for one FL entry, or list UNKNOWN entries."""
    entries = load_fl_entries(root)

    if getattr(args, "unknown", False):
        # List all entries where hypothesis == 'UNKNOWN'
        gate_filter = (getattr(args, "gate", None) or "").strip().lower()
        limit = getattr(args, "limit", None)
        hits = []
        for e in entries:
            hyp = (e.get("hypothesis") or "").strip()
            if hyp != "UNKNOWN":
                continue
            if gate_filter:
                gates_lower = [g.lower() for g in (e.get("gates") or [])]
                if (
                    gate_filter not in gates_lower
                    and gate_filter not in (e.get("gate") or "").lower()
                ):
                    continue
            hits.append(e)
        total = len(hits)
        if limit:
            hits = hits[:limit]
        print(
            f"UNKNOWN-HYPOTHESIS entries: {total}{f'  (showing first {limit})' if limit and limit < total else ''}\n"
        )
        for e in hits:
            gate_str = e.get("gate") or (", ".join(e.get("gates", [])) or "N/A")
            print(f"  {e['fl']:<10}  {gate_str[:55]}")
        return

    # Single-entry mode
    fl_id = args.fl_id.upper()
    if not re.match(r"^FL-\d+$", fl_id):
        sys.exit(f"error: invalid FL ID format: {args.fl_id!r}  (expected FL-NNN)")

    # Find the parsed entry for the hypothesis field value
    entry = next((e for e in entries if e["fl"] == fl_id), None)
    if entry is None:
        sys.exit(f"error: {fl_id} not found in docs/FAILURE_LOG.md")

    hyp_val = (entry.get("hypothesis") or "N/A").strip()
    print(f"HYPOTHESIS: {fl_id}\n")
    print(f"  Field value:  {hyp_val}")
    print()

    # Extract inline hypothesis update blockquotes from the raw entry text
    raw = _fl_extract_raw(root, fl_id)
    if raw is None:
        return

    updates = list(_HYP_UPDATE_HDR.finditer(raw))
    if not updates:
        print("  No inline hypothesis updates found.")
        return

    print(f"  Inline updates ({len(updates)}):\n")
    for i, m in enumerate(updates, 1):
        block_start = m.start()
        block_end = updates[i].start() if i < len(updates) else len(raw)
        # Collect the blockquote lines for this update
        block_lines = []
        for line in raw[block_start:block_end].splitlines():
            stripped = line.strip()
            if stripped.startswith(">"):
                inner = stripped.lstrip("> ").strip()
                if inner:
                    block_lines.append(inner)
            elif not stripped:
                continue
            else:
                # First non-blockquote line ends the block
                break
        header = block_lines[0] if block_lines else m.group(0).strip()
        print(f"  [{i}] {header[:110]}")
        for bl in block_lines[1:4]:
            print(f"       {bl[:110]}")
        if len(block_lines) > 4:
            print(f"       … ({len(block_lines) - 4} more lines)")
        print()


_COMMIT_BLOCK_HDR = re.compile(
    r"^(?:- )?\*\*Commits (?:between peak and this run|since last pass)[^*]*\*\*[: \t]*(.*)",
    re.IGNORECASE | re.MULTILINE,
)
_COMMIT_ITEM = re.compile(r"`([0-9a-f]{7,40})`\s+(.*)")


def cmd_fl_regression(args, root: Path):
    """Show the regression causal window for one FL entry."""
    fl_id = args.fl_id.upper()
    if not re.match(r"^FL-\d+$", fl_id):
        sys.exit(f"error: invalid FL ID format: {args.fl_id!r}  (expected FL-NNN)")

    entries = load_fl_entries(root)
    entry = next((e for e in entries if e["fl"] == fl_id), None)
    if entry is None:
        sys.exit(f"error: {fl_id} not found in docs/FAILURE_LOG.md")

    fail_commit = re.sub(r"[`\s].*", "", entry.get("commit") or "") or "N/A"
    prior_run = entry.get("prior_pass_run_id") or "N/A"

    raw = _fl_extract_raw(root, fl_id)
    if raw is None:
        sys.exit(f"error: could not extract raw text for {fl_id}")

    # Fallback: extract prior-pass from "Last `true`: peak artifact /tmp/..." style
    if prior_run == "N/A":
        alt = re.search(r"Last `true`.*?peak artifact\s+`?(/tmp/[^\s`]+)", raw)
        if alt:
            prior_run = _run_id_from_path(alt.group(1)) or alt.group(1)

    # Parse explicit commit list from body
    commit_items: list[tuple[str, str]] = []
    see_git_hash: str | None = None

    block_m = _COMMIT_BLOCK_HDR.search(raw)
    if block_m:
        inline = block_m.group(1).strip()
        # Check for "(see git log HASH)" style
        git_ref = re.search(
            r"see git log\s+`?([0-9a-f]{6,40})`?", inline, re.IGNORECASE
        )
        if git_ref:
            see_git_hash = git_ref.group(1)
        else:
            # Parse indented list items after the header; stop at next non-commit line
            block_start = block_m.end()
            seen_any = False
            for line in raw[block_start:].splitlines():
                stripped = line.strip()
                if not stripped:
                    if seen_any:
                        break  # blank line after items ends the block
                    continue  # skip leading blank lines
                cm = _COMMIT_ITEM.search(line)
                if cm and (re.match(r"^\s+- ", line) or re.match(r"^  +`", line)):
                    commit_items.append((cm.group(1), cm.group(2).strip()))
                    seen_any = True
                else:
                    if seen_any:
                        break  # first non-commit non-blank line after items ends the block

    print(f"REGRESSION CAUSAL WINDOW: {fl_id}\n")
    print(f"  Failing HEAD:       {fail_commit}")
    print(f"  Prior-pass run ID:  {prior_run}")
    print()

    if commit_items:
        print(f"  Explicit commit list ({len(commit_items)} entries):\n")
        for hash_, msg in commit_items:
            print(f"    {hash_[:9]}  {msg[:90]}")
        print()
    elif see_git_hash:
        print(f"  No explicit list — entry says: see git log {see_git_hash}")
        if getattr(args, "git", False):
            print(f"\n  git log {see_git_hash}..{fail_commit} --oneline:\n")
            result = subprocess.run(
                ["git", "log", f"{see_git_hash}..{fail_commit}", "--oneline"],
                capture_output=True,
                text=True,
                cwd=str(root),
            )
            if result.returncode == 0:
                for line in result.stdout.strip().splitlines():
                    print(f"    {line}")
            else:
                print(f"    (git log failed: {result.stderr.strip()[:200]})")
        else:
            print(
                f"  Run with --git to execute: git log {see_git_hash}..{fail_commit} --oneline"
            )
        print()
    elif block_m:
        print(f"  Commit block present but no parseable items.")
        print()
    else:
        print(f"  No commit list found in this entry.")
        print()


