def _title_tokens(title: str) -> set[str]:
    """Lowercase non-stopword tokens from a title string."""
    words = re.findall(r"[a-z0-9_]+", (title or "").lower())
    return {w for w in words if w not in _TITLE_STOPWORDS and len(w) > 2}


def _title_expansion_terms(title: str, limit: int = 5) -> list[str]:
    """Extract meaningful terms from a title for cluster expansion.

    Unlike raw .split()[:3], filters stopwords and short tokens so that
    generic titles like 'Fix the critical bug' produce ['fix', 'critical', 'bug']
    instead of ['fix', 'the', 'critical'].
    """
    seen = set()
    ordered = []
    for token in re.findall(r"[a-z0-9_]+", (title or "").lower()):
        if token in _TITLE_STOPWORDS or len(token) <= 2 or token in seen:
            continue
        seen.add(token)
        ordered.append(token)
        if len(ordered) >= limit:
            break
    return ordered


def cmd_fl_duplicate(args, root: Path):
    """Find FL entries that may be duplicates of a given entry."""
    fl_id = args.fl_id.upper()
    if not re.match(r"^FL-\d+$", fl_id):
        sys.exit(f"error: invalid FL ID format: {args.fl_id!r}  (expected FL-NNN)")

    entries = load_fl_entries(root)
    target = next((e for e in entries if e["fl"] == fl_id), None)
    if target is None:
        sys.exit(f"error: {fl_id} not found in docs/FAILURE_LOG.md")

    min_score = getattr(args, "min_score", 2)
    limit = getattr(args, "limit", 15)

    tgt_gate = (target.get("gate") or "").strip().lower()
    tgt_gates = {g.lower() for g in (target.get("gates") or []) if g}
    tgt_artifact = (target.get("artifact_run_id") or "").strip()
    tgt_commit = re.sub(r"[`\s].*", "", target.get("commit") or "")
    tgt_tokens = _title_tokens(target.get("title") or "")

    candidates: list[tuple[int, dict]] = []
    for e in entries:
        if e["fl"] == fl_id:
            continue
        score = 0

        # Gate match
        e_gate = (e.get("gate") or "").strip().lower()
        e_gates = {g.lower() for g in (e.get("gates") or []) if g}
        if tgt_gate and tgt_gate == e_gate:
            score += 3
        elif tgt_gates & e_gates:
            score += 2

        # Artifact match (same run recorded twice)
        e_artifact = (e.get("artifact_run_id") or "").strip()
        if tgt_artifact and tgt_artifact == e_artifact:
            score += 4

        # Same HEAD commit
        e_commit = re.sub(r"[`\s].*", "", e.get("commit") or "")
        if tgt_commit and tgt_commit == e_commit:
            score += 2

        # Title token overlap
        e_tokens = _title_tokens(e.get("title") or "")
        overlap = len(tgt_tokens & e_tokens)
        score += min(overlap, 3)  # cap at 3 bonus points

        if score >= min_score:
            candidates.append((score, e))

    candidates.sort(key=lambda x: (-x[0], x[1]["num"]), reverse=False)
    if limit:
        candidates = candidates[:limit]

    print(f"DUPLICATE CANDIDATES for {fl_id}  (min-score={min_score})\n")
    print(f"  Target: {fl_id}  gate={tgt_gate or 'N/A'}  commit={tgt_commit or 'N/A'}")
    print(f"  Title:  {(target.get('title') or '')[:80]}\n")

    if not candidates:
        print("  No candidates found above threshold.")
        return

    print(f"  {'FL-ID':<10}  {'Score':>5}  {'Gate':<45}  {'Status':<12}  Title")
    print(f"  {'-' * 10}  {'-' * 5}  {'-' * 45}  {'-' * 12}  {'-' * 40}")
    for score, e in candidates:
        gate_str = (e.get("gate") or "N/A")[:45]
        status_str = (e.get("status") or "N/A")[:12]
        title_str = (e.get("title") or "")[:40]
        print(
            f"  {e['fl']:<10}  {score:>5}  {gate_str:<45}  {status_str:<12}  {title_str}"
        )


_METRICS_VALUE_RE = re.compile(
    r"^\- \*\*metrics\.json value:\*\*\s*`?([^`\n]+)`?",
    re.MULTILINE | re.IGNORECASE,
)


def cmd_fl_delta(args, root: Path):
    """Show the value-change timeline for a specific gate across all FL entries."""
    gate = (args.gate or "").strip().lower()
    if not gate:
        sys.exit("error: gate name required")

    entries = load_fl_entries(root)
    gate_entries = []
    for e in entries:
        gates_lower = {g.lower() for g in (e.get("gates") or []) if g}
        primary_lower = (e.get("gate") or "").strip().lower()
        if gate == primary_lower or gate in gates_lower:
            gate_entries.append(e)

    if not gate_entries:
        sys.exit(f"error: no FL entries found for gate '{gate}'")

    # Load the full log once for bulk metric-value extraction
    fl_path = canonical_failure_log_path(root)
    full_text = fl_path.read_text(errors="replace") if fl_path.exists() else ""

    # Build per-entry metric value by scanning each entry's raw text
    _FL_HEADER_RE = re.compile(r"^### (FL-\d+) —", re.MULTILINE)
    header_positions: dict[str, int] = {}
    for m in _FL_HEADER_RE.finditer(full_text):
        header_positions[m.group(1)] = m.start()

    def _get_metric_value(fl_id: str) -> str:
        pos = header_positions.get(fl_id)
        if pos is None:
            return "N/A"
        # Find end of this entry (start of next FL header or EOF)
        next_pos = len(full_text)
        for other_id, other_pos in header_positions.items():
            if other_pos > pos:
                next_pos = min(next_pos, other_pos)
        chunk = full_text[pos:next_pos]
        m = _METRICS_VALUE_RE.search(chunk)
        return m.group(1).strip()[:60] if m else "N/A"

    # Sort by entry number (proxy for chronological order)
    gate_entries.sort(key=lambda e: e["num"])

    changes_only = getattr(args, "changes_only", False)
    print(f"DELTA TIMELINE: {gate}  ({len(gate_entries)} entries)\n")

    prev_val: str | None = None
    shown = 0
    for e in gate_entries:
        val = _get_metric_value(e["fl"])
        changed = val != prev_val
        if changes_only and not changed:
            prev_val = val
            continue
        tag = ""
        if prev_val is None:
            tag = "  FIRST"
        elif changed:
            tag = f"  → {val}"
        date_str = (e.get("date") or "?")[:10]
        run_id = (e.get("artifact_run_id") or "N/A")[:35]
        print(f"  {date_str:<12}  {e['fl']:<10}  {val:<12}  {run_id}{tag}")
        prev_val = val
        shown += 1

    if shown == 0:
        print(
            "  No entries with value changes found."
            if changes_only
            else "  No entries found."
        )


def cmd_fl_correlate(args, root: Path):
    """Correlate a run artifact with its FL entries: show false gates and matching FL records."""
    run_id = args.run_id
    run = load_run_by_id(root, run_id)

    art = _find_artifact_path(run)
    if art is None:
        sys.exit(f"error: artifact path not found for run {run_id}")

    m = _load_metrics(art)
    gates = m.get("gates") or {}
    false_gates = sorted(k for k, v in gates.items() if v is False)
    null_gates = sorted(k for k, v in gates.items() if v is None)
    if not null_gates:
        null_gates = sorted(run.get("null_gates") or [])
    run_commit = (
        run.get("git_head") or run.get("src_ref") or run.get("head_commit") or ""
    ).strip()[:8]

    entries = load_fl_entries(root)
    entries_by_gate: dict[str, list] = {}
    for e in entries:
        for g in e.get("gates") or []:
            entries_by_gate.setdefault(g.lower(), []).append(e)

    # Also index by commit
    entries_by_commit: dict[str, list] = {}
    for e in entries:
        c = re.sub(r"[`\s].*", "", e.get("commit") or "")
        if c:
            entries_by_commit.setdefault(c[:8], []).append(e)

    print(f"CORRELATE: {run_id}\n")
    print(f"  HEAD commit:  {run_commit or 'N/A'}")
    print(f"  False gates:  {len(false_gates)}")
    print(f"  Null gates:   {len(null_gates)}")
    print()

    # Show FL entries for commit
    commit_hits = entries_by_commit.get(run_commit, [])
    if commit_hits:
        print(f"  FL entries at HEAD commit {run_commit} ({len(commit_hits)}):")
        for e in commit_hits[:5]:
            status_str = (e.get("status") or "N/A")[:10]
            proof = _fl_overlay_scalar(e, "ProofState") or "OPEN"
            print(f"    {e['fl']:<10}  {status_str:<10}  {proof:<11}  {(e.get('title') or '')[:55]}")
        print()

    # Show FL entries per false/null gate
    shown_ids: set[str] = set()
    any_gate_hits = False
    for verdict_label, gate_list in (("FALSE", false_gates), ("NULL", null_gates)):
        for gate in gate_list:
            gate_entries = entries_by_gate.get(gate, [])
            if not gate_entries:
                continue
            any_gate_hits = True
            print(f"  {verdict_label} {gate}  ({len(gate_entries)} FL entries):")
            for e in sorted(gate_entries, key=lambda x: -x["num"])[:4]:
                if e["fl"] in shown_ids:
                    continue
                shown_ids.add(e["fl"])
                status_str = (e.get("status") or "N/A")[:10]
                proof = _fl_overlay_scalar(e, "ProofState") or "OPEN"
                hyp = (e.get("hypothesis") or "?")[:30]
                print(f"    {e['fl']:<10}  {status_str:<10}  {proof:<11}  {hyp}")
            print()

    if not any_gate_hits and not commit_hits:
        print("  No FL entries found for this run's false gates or commit.")


def cmd_fl_required_fields(args, root: Path):
    """Show recorder/debug fields required before an FL fix can be falsified.

    Uses the machine-readable overlay `RequiredFields` contract when present,
    with markdown parsing as a compatibility fallback. Non-blocking: exits 0
    even when fields are missing; use the output as an advisory, not a gate.

    JSON output (--json):
      {"fl_id": "FL-1458", "has_gap": true, "required_fields": ["field1", ...]}
    """
    fl_id = args.fl_id.upper()
    if not re.match(r"^FL-\d+$", fl_id):
        print(f"ERROR: invalid FL ID '{args.fl_id}' (expected FL-NNN)", file=sys.stderr)
        sys.exit(2)

    advisory = fl_required_fields_advisory_for_id(root, fl_id)
    if advisory.get("error") == "not_found":
        if getattr(args, "json", False):
            print(json.dumps({"fl_id": fl_id, "error": "not_found", "required_fields": []}))
        else:
            print(f"ERROR: {fl_id} not found in docs/FAILURE_LOG.md", file=sys.stderr)
        sys.exit(2)

    fields = advisory.get("required_fields") or []
    has_gap = bool(advisory.get("has_gap"))
    source = str(advisory.get("source") or "none")

    if getattr(args, "json", False):
        print(
            json.dumps(
                {
                    "fl_id": fl_id,
                    "has_gap": has_gap,
                    "required_fields": fields,
                    "source": source,
                }
            )
        )
        return

    if not has_gap:
        print(f"{fl_id}: no required-fields advisory found")
        return

    if not fields:
        print(f"{fl_id}: open diagnostic gap present but no required fields listed")
        return

    source_label = "overlay contract" if source == "overlay" else "markdown fallback"
    print(f"{fl_id}: {len(fields)} field(s) required before fix is falsifiable ({source_label})")
    for f in fields:
        print(f"  {f}")


def _fl_context_fail(
    args,
    error: str,
    *,
    detail: str = "",
) -> None:
    """Fail closed with a bounded error envelope."""

    if getattr(args, "json", False):
        payload: dict[str, Any] = {
            "ok": False,
            "command": "fl context",
            "error": error,
        }
        if detail:
            payload["detail"] = detail
        print(json.dumps(payload, indent=2))
        raise SystemExit(2)
    message = f"error: fl context {error}"
    if detail:
        message += f": {detail}"
    raise SystemExit(message)


def _fl_context_native_card(root: Path, fl_id: str, entry: dict, occurrence: dict) -> dict[str, Any]:
    """Build bounded card fields from native analyzer state only."""

    overlay = _fl_overlay_record(entry)
    family = _entry_family(root, entry)
    return {
        "fl": fl_id,
        "title": str(entry.get("title") or ""),
        "status": fl_status_display(entry),
        "proof_state": str(occurrence.get("proof_state") or "OPEN"),
        "priority": _fl_overlay_scalar(entry, "Priority") or "-",
        "ledger_state": fl_ledger_state(entry),
        "category": str(entry.get("category") or ""),
        "area": _fl_overlay_scalar(entry, "Area"),
        "family_size": len(family),
        "fix_attempt_count": len(occurrence.get("fix_attempts") or []),
        "primary_ref": (_extract_file_refs([entry], limit=1) or entry.get("gates") or ["-"])[0],
        "overlay": {
            "kinds": _normalize_overlay_list_value(overlay.get("Kinds") or []),
            "subsystems": _normalize_overlay_list_value(overlay.get("Subsystems") or []),
        },
    }


_FL_CONTEXT_MAX_ATTEMPTS = 5
_FL_CONTEXT_MAX_ATTEMPT_BODY_CHARS = 1200
_FL_CONTEXT_MAX_ATTEMPT_TOTAL_CHARS = 4000
_FL_CONTEXT_MAX_MATCH_METADATA = 100
_FL_CONTEXT_QUERY_STOP_WORDS = frozenset(
    {
        "about",
        "after",
        "again",
        "against",
        "also",
        "and",
        "attempt",
        "attempts",
        "before",
        "from",
        "have",
        "into",
        "that",
        "their",
        "then",
        "these",
        "this",
        "through",
        "with",
    }
)
_FL_CONTEXT_QUERY_VARIANTS: dict[str, tuple[str, ...]] = {
    "falsified": ("falsified", "falsifier", "invalidated", "rejected", "regressed", "failed", "failure"),
    "fixed": ("fixed", "verified", "restored", "repaired", "implemented", "complete", "success"),
}


def _fl_context_query_terms(task: str) -> list[str]:
    """Return stable content terms used only to retrieve native history."""

    return sorted(
        {
            token
            for token in re.findall(r"[a-z0-9][a-z0-9_-]+", task.lower())
            if len(token) >= 3
            and not token.isdigit()
            and token not in _FL_CONTEXT_QUERY_STOP_WORDS
            and not re.fullmatch(r"fl-?\d+", token)
        }
    )


def _fl_context_requested_attempt_range(task: str, _total: int) -> tuple[int, int] | None:
    match = re.search(
        r"\battempts?\s+(\d+)\s*(?:-|–|—|to)\s*(\d+)\b",
        task.lower(),
    )
    if match is None:
        return None
    start, end = int(match.group(1)), int(match.group(2))
    if start > end:
        start, end = end, start
    return start, end


def _fl_context_attempt_search_text(source: dict) -> str:
    return " ".join(
        str(source.get(key) or "")
        for key in ("date", "branch", "suffix", "body")
    ).lower()


def _fl_context_matched_query_terms(query_terms: list[str], search_text: str) -> list[str]:
    return [
        term
        for term in query_terms
        if any(
            variant in search_text
            for variant in _FL_CONTEXT_QUERY_VARIANTS.get(term, (term,))
        )
    ]


def _fl_context_is_phase_control(source: dict) -> bool:
    """Keep the active phase-start echo from displacing prior evidence."""

    body = str(source.get("body") or "").lstrip().lower()
    return "phase start" in body[:300]


def _fl_context_failure_record_priority(source: dict) -> int:
    """Prefer direct falsifier records over receipts that mention failures."""

    lead = str(source.get("body") or "").lstrip().lower()[:500]
    return int(
        any(
            marker in lead
            for marker in (
                "phase invalidated",
                "review-falsifier",
                "acceptance-falsifier",
                "process failure",
                "execution falsifier",
            )
        )
    )


def _fl_context_native_attempts(occurrence: dict, task: str = "") -> dict[str, Any]:
    """Return bounded native prior-attempt content selected for the task.

    ``occurrence['fix_attempts']`` is produced by the native Markdown parser.
    This observer does not classify an attempt or infer status/closure from
    its prose. Task terms retrieve prior records; the returned coverage and
    omission fields keep that lexical selection auditable. With no matching
    task terms, records retain the historical newest-first behavior.
    """

    source_attempts = list(occurrence.get("fix_attempts") or [])
    total_body_chars = sum(
        len(str(item.get("body") or ""))
        for item in source_attempts
        if isinstance(item, dict)
    )
    attempts: list[dict[str, Any]] = []
    returned_body_chars = 0
    truncated = total_body_chars > _FL_CONTEXT_MAX_ATTEMPT_TOTAL_CHARS
    query_terms = _fl_context_query_terms(task)
    requested_range = _fl_context_requested_attempt_range(task, len(source_attempts))
    candidates: list[dict[str, Any]] = []

    for attempt_number, source in enumerate(source_attempts, start=1):
        if not isinstance(source, dict):
            continue
        if requested_range is not None and not (
            requested_range[0] <= attempt_number <= requested_range[1]
        ):
            continue
        search_text = _fl_context_attempt_search_text(source)
        matched_terms = _fl_context_matched_query_terms(query_terms, search_text)
        if matched_terms or requested_range is not None:
            candidates.append(
                {
                    "attempt_number": attempt_number,
                    "source": source,
                    "matched_terms": matched_terms,
                    "phase_control": _fl_context_is_phase_control(source),
                    "failure_record_priority": _fl_context_failure_record_priority(source),
                }
            )

    selection_mode = (
        "task_relevance"
        if candidates or requested_range is not None
        else "newest_first"
    )
    if candidates or requested_range is not None:
        # Choose one strongest record per date before considering same-date
        # neighbors. This prevents a dense checkpoint cluster from hiding an
        # older lifecycle, refresh, Stop, or SessionStart recurrence.
        substantive_candidates = [
            candidate for candidate in candidates if not candidate["phase_control"]
        ]
        retrieval_pool = substantive_candidates or list(candidates)
        representatives_by_date: dict[str, dict[str, Any]] = {}
        for candidate in retrieval_pool:
            date = str(candidate["source"].get("date") or "")
            incumbent = representatives_by_date.get(date)
            if incumbent is None or (
                candidate["failure_record_priority"],
                len(candidate["matched_terms"]),
                candidate["attempt_number"],
            ) > (
                incumbent["failure_record_priority"],
                len(incumbent["matched_terms"]),
                incumbent["attempt_number"],
            ):
                representatives_by_date[date] = candidate
        remaining = list(representatives_by_date.values())
        uncovered_terms = set(query_terms)
        ordered_sources: list[dict[str, Any]] = []
        while remaining:
            selected = max(
                remaining,
                key=lambda item: (
                    item["failure_record_priority"],
                    len(set(item["matched_terms"]) & uncovered_terms),
                    len(item["matched_terms"]),
                    item["attempt_number"],
                ),
            )
            ordered_sources.append(selected)
            uncovered_terms.difference_update(selected["matched_terms"])
            remaining.remove(selected)
        represented_numbers = {
            candidate["attempt_number"] for candidate in ordered_sources
        }
        ordered_sources.extend(
            sorted(
                (
                    candidate
                    for candidate in retrieval_pool
                    if candidate["attempt_number"] not in represented_numbers
                ),
                key=lambda item: (
                    item["failure_record_priority"],
                    len(item["matched_terms"]),
                    item["attempt_number"],
                ),
                reverse=True,
            )
        )
    else:
        ordered_sources = [
            {
                "attempt_number": attempt_number,
                "source": source,
                "matched_terms": [],
                "phase_control": False,
                "failure_record_priority": 0,
            }
            for attempt_number, source in reversed(list(enumerate(source_attempts, start=1)))
            if isinstance(source, dict)
        ]
    selected_body_char_limit = (
        _FL_CONTEXT_MAX_ATTEMPT_TOTAL_CHARS // _FL_CONTEXT_MAX_ATTEMPTS
        if selection_mode == "task_relevance"
        else _FL_CONTEXT_MAX_ATTEMPT_BODY_CHARS
    )

    for candidate in ordered_sources:
        if len(attempts) >= _FL_CONTEXT_MAX_ATTEMPTS:
            truncated = True
            break
        source = candidate["source"]
        body = str(source.get("body") or "")
        remaining = _FL_CONTEXT_MAX_ATTEMPT_TOTAL_CHARS - returned_body_chars
        if remaining <= 0:
            truncated = True
            break
        bounded_body = body[: min(selected_body_char_limit, remaining)]
        body_truncated = len(bounded_body) < len(body)
        truncated = truncated or body_truncated
        attempt = {
            "attempt_number": candidate["attempt_number"],
            "date": str(source.get("date") or ""),
            "branch": str(source.get("branch") or ""),
            "suffix": str(source.get("suffix") or ""),
            "matched_terms": candidate["matched_terms"],
            "phase_control": candidate["phase_control"],
            "failure_record_priority": candidate["failure_record_priority"],
            "body": bounded_body,
            "body_truncated": body_truncated,
        }
        attempts.append(attempt)
        returned_body_chars += len(bounded_body)

    if len(attempts) < len(source_attempts):
        truncated = True
    candidate_metadata = [
        {
            "attempt_number": candidate["attempt_number"],
            "date": str(candidate["source"].get("date") or ""),
            "branch": str(candidate["source"].get("branch") or ""),
            "suffix": str(candidate["source"].get("suffix") or ""),
            "matched_terms": candidate["matched_terms"],
            "phase_control": candidate["phase_control"],
            "failure_record_priority": candidate["failure_record_priority"],
        }
        for candidate in candidates[:_FL_CONTEXT_MAX_MATCH_METADATA]
    ]
    lexical_matches = [candidate for candidate in candidates if candidate["matched_terms"]]
    matching_metadata = [
        metadata
        for metadata in candidate_metadata
        if metadata["matched_terms"]
    ]
    selected_numbers = [attempt["attempt_number"] for attempt in attempts]
    omitted_candidate_numbers = [
        candidate["attempt_number"]
        for candidate in candidates
        if candidate["attempt_number"] not in selected_numbers
    ]
    omitted_matching_numbers = [
        candidate["attempt_number"]
        for candidate in lexical_matches
        if candidate["attempt_number"] not in selected_numbers
    ]
    phase_control_numbers = [
        candidate["attempt_number"]
        for candidate in candidates
        if candidate["phase_control"]
    ]
    selected_term_coverage = sorted(
        {
            term
            for attempt in attempts
            for term in attempt["matched_terms"]
        }
    )
    return {
        "total": len(source_attempts),
        "returned": len(attempts),
        "total_body_chars": total_body_chars,
        "returned_body_chars": returned_body_chars,
        "truncated": truncated,
        "max_attempts": _FL_CONTEXT_MAX_ATTEMPTS,
        "max_body_chars": _FL_CONTEXT_MAX_ATTEMPT_BODY_CHARS,
        "max_total_chars": _FL_CONTEXT_MAX_ATTEMPT_TOTAL_CHARS,
        "selected_body_char_limit": selected_body_char_limit,
        "selection_mode": selection_mode,
        "query_terms": query_terms,
        "requested_attempt_range": list(requested_range) if requested_range else None,
        "candidate_total": len(candidates),
        "candidate_attempts": candidate_metadata,
        "candidate_metadata_truncated": len(candidates) > len(candidate_metadata),
        "matching_total": len(lexical_matches),
        "matching_attempts": matching_metadata,
        "matching_metadata_truncated": len(lexical_matches) > len(matching_metadata),
        "phase_control_attempt_numbers": phase_control_numbers[:_FL_CONTEXT_MAX_MATCH_METADATA],
        "phase_control_metadata_truncated": (
            len(phase_control_numbers) > _FL_CONTEXT_MAX_MATCH_METADATA
        ),
        "selected_attempt_numbers": selected_numbers,
        "selected_term_coverage": selected_term_coverage,
        "omitted_candidate_total": len(omitted_candidate_numbers),
        "omitted_candidate_attempt_numbers": omitted_candidate_numbers[:_FL_CONTEXT_MAX_MATCH_METADATA],
        "omitted_candidate_metadata_truncated": (
            len(omitted_candidate_numbers) > _FL_CONTEXT_MAX_MATCH_METADATA
        ),
        "omitted_matching_total": len(omitted_matching_numbers),
        "omitted_matching_attempt_numbers": omitted_matching_numbers[:_FL_CONTEXT_MAX_MATCH_METADATA],
        "omitted_matching_metadata_truncated": (
            len(omitted_matching_numbers) > _FL_CONTEXT_MAX_MATCH_METADATA
        ),
        "attempts": attempts,
    }


def cmd_fl_context(args, root: Path):
    """Show current native FL context.

    Native lookup, card, required fields, and prior attempts are the complete
    result.  Native FL remains the owner of status, proof, and closure.
    """

    fl_id = _fl_id_arg(args.fl_id)

    # Native authority: resolve the entry, card occurrence, and required
    # fields from the failure log.
    entry = fl_entry_by_id(root, fl_id)
    if entry is None:
        _fl_context_fail(args, "not_found", detail=f"{fl_id} is absent from docs/FAILURE_LOG.md")
    occurrences = _fl_duplicate_occurrences(root, fl_id)
    if len(occurrences) != 1:
        _fl_context_fail(
            args,
            "duplicate_id",
            detail=f"{fl_id} has {len(occurrences)} native ledger occurrences; use fl show before context lookup",
        )
    occurrence = occurrences[0]
    advisory = fl_required_fields_advisory_for_id(root, fl_id)
    native_card = _fl_context_native_card(root, fl_id, entry, occurrence)
    task = str(getattr(args, "task", "") or "").strip()
    native_attempts = _fl_context_native_attempts(occurrence, task)

    payload = {
        "ok": True,
        "command": "fl context",
        "fl": fl_id,
        "native": {
            "card": native_card,
            "required_fields": {
                "has_gap": bool(advisory.get("has_gap")),
                "fields": list(advisory.get("required_fields") or []),
                "source": str(advisory.get("source") or "none"),
            },
            "prior_attempts": native_attempts,
            "authority": "native_failure_log",
            "source": {
                "path": str(canonical_failure_log_path(root).relative_to(root)),
                "commands": [
                    f"python3 scripts/analyze_runs.py fl card {fl_id} --json",
                    f"python3 scripts/analyze_failure_log.py required-fields {fl_id} --json",
                ],
            },
        },
        "task": task,
        "authority_boundary": {
            "status_owner": "native_failure_log",
            "proof_owner": "native_failure_log",
            "closure_owner": "native_failure_log",
        },
        "recommended_next_commands": [
            f"python3 scripts/analyze_runs.py fl card {fl_id} --json",
            f"python3 scripts/analyze_failure_log.py required-fields {fl_id} --json",
            f"python3 scripts/analyze_runs.py fl family {fl_id}",
            f"python3 scripts/analyze_runs.py fl prior-attempts {fl_id} --full",
        ],
    }

    if getattr(args, "json", False):
        print(json.dumps(payload, indent=2))
        return

    print(f"{fl_id} context (native authority)")
    print(f"Title: {native_card['title']}")
    print(f"Status: {native_card['status']}  Proof: {native_card['proof_state']}  Priority: {native_card['priority']}")
    fields = payload["native"]["required_fields"]["fields"]
    print(f"Required fields: {', '.join(fields[:12]) if fields else 'none listed'}")
    attempts = payload["native"]["prior_attempts"]
    if attempts["total"]:
        suffix = " (truncated)" if attempts["truncated"] else ""
        selection_label = (
            "task-relevant"
            if attempts["selection_mode"] == "task_relevance"
            else "newest-first"
        )
        print(
            f"Prior attempts (native history; not status/closure authority): "
            f"{attempts['returned']}/{attempts['total']} {selection_label}{suffix}"
        )
        if attempts["selection_mode"] == "task_relevance":
            requested_range = attempts.get("requested_attempt_range")
            if requested_range:
                print(
                    f"Range candidates within attempts {requested_range[0]}–{requested_range[1]}: "
                    f"{attempts['candidate_total']}; lexical matches {attempts['matching_total']}; "
                    f"selected {attempts['selected_attempt_numbers']}; "
                    f"omitted {attempts['omitted_candidate_total']} candidate bodies"
                )
                omitted_numbers = attempts["omitted_candidate_attempt_numbers"]
                omitted_label = "Omitted range-candidate attempt numbers"
            else:
                print(
                    f"Matching attempts: {attempts['matching_total']}; "
                    f"selected {attempts['selected_attempt_numbers']}; "
                    f"omitted {attempts['omitted_matching_total']} matching bodies"
                )
                omitted_numbers = attempts["omitted_matching_attempt_numbers"]
                omitted_label = "Omitted matching attempt numbers"
            if omitted_numbers:
                print(f"{omitted_label}: {omitted_numbers}")
        for attempt in attempts["attempts"]:
            header = (
                f"  attempt {attempt['attempt_number']}: "
                f"{attempt['date']} @ {attempt['branch']}"
            )
            if attempt.get("suffix"):
                header += f" ({attempt['suffix']})"
            print(header)
            for line in attempt["body"].splitlines():
                print(f"    {line}")
    print("Next:")
    for command in payload["recommended_next_commands"]:
        print(f"  {command}")


