def cmd_fl_error_scan(args, root: Path):
    """Search server logs across recent runs for a pattern and map to FL entries."""
    import subprocess as _sp

    pattern = args.pattern
    runs_limit = getattr(args, "runs", 10)
    context_lines = getattr(args, "context", 2)

    all_runs, _ = load_all_runs(root)
    candidates = [r for r in all_runs if _find_artifact_path(r) is not None][
        :runs_limit
    ]

    if not candidates:
        sys.exit("error: no runs with artifacts found")

    entries = load_fl_entries(root)
    _fl_by_gate: dict[str, list] = {}
    for e in entries:
        for g in e.get("gates") or []:
            _fl_by_gate.setdefault(g.lower(), []).append(e)

    print(f"ERROR SCAN: '{pattern}'  (last {len(candidates)} runs)\n")

    total_hits = 0
    for run in candidates:
        art = _find_artifact_path(run)
        if art is None:
            continue
        sl = art / "server.log"
        if not sl.exists():
            continue
        # Use ripgrep / grep to search the log file
        result = _sp.run(
            ["grep", "-n", "-c", pattern, str(sl)],
            capture_output=True,
            text=True,
        )
        count = int(result.stdout.strip()) if result.stdout.strip().isdigit() else 0
        if count == 0:
            continue

        run_id = run.get("run_id", "?")
        commit = (run.get("git_head") or run.get("src_ref") or "?")[:8]
        verdict = (run.get("verdict") or "?")[:8]
        print(f"  {run_id}  commit={commit}  verdict={verdict}  matches={count}")

        # Show first context_lines match lines
        ctx_result = _sp.run(
            ["grep", "-n", "-m", str(context_lines + 1), pattern, str(sl)],
            capture_output=True,
            text=True,
        )
        for line in ctx_result.stdout.strip().splitlines()[:context_lines]:
            print(f"    {line[:120]}")
        related_fls: dict[str, dict] = {}
        search_text = (pattern + "\n" + ctx_result.stdout).lower()
        for gate, gate_entries in _fl_by_gate.items():
            if gate and gate in search_text:
                for entry in gate_entries:
                    related_fls[entry["fl"]] = entry
        if not related_fls:
            for entry in entries:
                if pattern.lower() in _fl_text(entry).lower():
                    related_fls[entry["fl"]] = entry
        if related_fls:
            refs = ", ".join(
                f"{fl_id}({fl_ledger_state(entry)})"
                for fl_id, entry in sorted(related_fls.items())[:6]
            )
            print(f"    FL: {refs}")
        print()
        total_hits += 1

    if total_hits == 0:
        print(
            f"  Pattern '{pattern}' not found in any of the {len(candidates)} scanned server logs."
        )
        return

    print(f"  Total runs with matches: {total_hits} / {len(candidates)}")


