def cmd_fl_epochs(args, root: Path):
    """Show epoch boundary timeline — FL entries tagged with epoch_boundary subsystem."""
    epoch_entries = _collect_epoch_entries(root)

    if getattr(args, "json", False):
        print(json.dumps({"epoch_count": len(epoch_entries), "epochs": epoch_entries}, indent=2))
        return

    if not epoch_entries:
        print("No epoch boundary entries found.")
        return

    rows = []
    for ep in epoch_entries:
        rows.append((ep["fl"], str(ep["epoch_num"]), ep["date"], ep["proof_state"], ep["epoch_label"]))

    print_table(["FL", "EPOCH", "DATE", "PROOF STATE", "LABEL"], rows)
    print(f"\n{len(epoch_entries)} epoch boundary(s).")


def cmd_fl_epoch_statuses(args, root: Path):
    """EpochStatus histogram plus the current source-backed lane inventory.

    FL-3887 epoch-lane-inventory: the histogram alone cannot identify which
    lanes are currently active, so this surface also derives lane rows from
    the canonical spec RQ table, the FL corpus (overlay RQRefs + Related
    edges), and on-disk source anchors (overlay CodeRefs).
    """
    entries = load_fl_entries(root)
    overlay = load_fl_overlay(root)

    status_counts: dict[str, int] = {}
    for entry in entries:
        fl_id = entry.get("fl") or ""
        record = effective_fl_overlay_record(entry, overlay.get(fl_id), fl_id=fl_id)
        es = (record.get("EpochStatus") or "").strip()
        if es:
            status_counts[es] = status_counts.get(es, 0) + 1

    lanes = _collect_active_lane_inventory(root, entries)

    if getattr(args, "json", False):
        print(json.dumps({
            "epoch_statuses": status_counts,
            "total_values": len(status_counts),
            "active_lanes": lanes,
            "active_lane_count": len(lanes),
        }, indent=2))
        return

    if not status_counts:
        print("No EpochStatus values found in any overlay entry.")
    else:
        rows = [(status, str(count)) for status, count in sorted(status_counts.items(), key=lambda x: -x[1])]
        print_table(["EPOCH STATUS", "COUNT"], rows)
        print(f"\n{len(status_counts)} distinct EpochStatus value(s) across {sum(status_counts.values())} entries.")

    if not lanes:
        print("\nNo active lanes derived from the canonical RQ table.")
        return

    print("\nACTIVE LANE INVENTORY (canonical RQ rows x FL corpus x source anchors)")
    lane_rows = []
    for lane in lanes:
        direct = " ".join(f"{r['fl']}({r['state']})" for r in lane["fl_refs"][:4])
        if len(lane["fl_refs"]) > 4:
            direct += f" +{len(lane['fl_refs']) - 4}"
        context = " ".join(r["fl"] for r in lane["context_refs"][:4])
        if len(lane["context_refs"]) > 4:
            context += f" +{len(lane['context_refs']) - 4}"
        lane_rows.append((
            lane["rq"],
            lane["state"],
            lane["title"][:44],
            direct or "-",
            context or "-",
            str(len(lane["source_anchors_live"])),
            str(len(lane["source_anchors_unresolved"])),
        ))
    print_table(["RQ", "STATE", "LANE", "FL REFS", "CONTEXT FL", "SRC LIVE", "UNRESOLVED"], lane_rows)
    unresolved_total = sum(len(l["source_anchors_unresolved"]) for l in lanes)
    print(
        f"\n{len(lanes)} active lane(s); anchor lists are complete in --json "
        f"({unresolved_total} unresolved historical ref(s) across all lanes)."
    )


# FL-3887: lane states copied verbatim from the canonical spec RQ table.  A
# PARKED row only re-enters the inventory while a directly linked FL is still
# effectively OPEN (e.g. RQ-172 blocks lane with FL-4361 open); DONE rows never
# re-enter.
_ACTIVE_RQ_STATES = {
    "CURRENT", "READY", "PARTIAL", "BLOCKED", "REQUIRED", "PLANNED", "IMPLEMENTED", "ALWAYS",
}

# Matches canonical spec RQ rows: | RQ-160 | CURRENT | YES | title | ...
_RQ_ROW_RE = re.compile(r"^\|\s*(RQ-\d+[a-z]?)\s*\|\s*([A-Z]+)\s*\|\s*(YES|NO)\s*\|\s*([^|]*)\|")


def _collect_active_lane_inventory(root: Path, entries: list) -> list[dict[str, Any]]:
    """Derive current lane rows: canonical RQ x FL corpus x on-disk anchors."""
    spec_path = root / "docs" / "plans" / "2026-03-22-multiplayer-canonical-spec.md"
    if not spec_path.is_file():
        return []

    rq_rows: list[dict[str, str]] = []
    for line in spec_path.read_text(encoding="utf-8", errors="replace").splitlines():
        m = _RQ_ROW_RE.match(line)
        if m:
            rq_rows.append({
                "rq": m.group(1),
                "state": m.group(2),
                "launcher_visible": m.group(3),
                "title": m.group(4).strip(),
            })

    # Index the FL corpus once: RQRefs -> direct lane membership, and Related
    # edges in both directions so historical context (e.g. FL-4598 pointing at
    # FL-4257) surfaces even when only one side authored the link.
    by_rq: dict[str, list[dict]] = {}
    by_id: dict[str, dict] = {}
    reverse_related: dict[str, list[str]] = {}
    for entry in entries:
        fl_id = entry.get("fl") or ""
        if not fl_id:
            continue
        by_id[fl_id] = entry
        for rq in _fl_overlay_list(entry, "RQRefs"):
            by_rq.setdefault(rq, []).append(entry)
        for rel in entry.get("related") or []:
            reverse_related.setdefault(rel, []).append(fl_id)

    lanes: list[dict[str, Any]] = []
    for row in rq_rows:
        direct = by_rq.get(row["rq"], [])
        any_open = any((e.get("effective_status") or e.get("status")) == "OPEN" for e in direct)
        if row["state"] not in _ACTIVE_RQ_STATES and not (row["state"] == "PARKED" and any_open):
            continue

        direct_ids = {e.get("fl") for e in direct}
        context_ids: set[str] = set()
        for e in direct:
            context_ids.update(e.get("related") or [])
            context_ids.update(reverse_related.get(e.get("fl") or "", []))
        context_ids -= direct_ids

        live: set[str] = set()
        unresolved: set[str] = set()
        for e in list(direct) + [by_id[c] for c in context_ids if c in by_id]:
            for ref in _fl_overlay_list(e, "CodeRefs"):
                # CodeRefs may carry :line or :symbol suffixes; the anchor is
                # live only when the path part exists in the current tree.
                path = ref.split(":", 1)[0].strip()
                if path and (root / path).is_file():
                    live.add(path)
                elif path:
                    unresolved.add(ref)

        lanes.append({
            "rq": row["rq"],
            "state": row["state"],
            "launcher_visible": row["launcher_visible"] == "YES",
            "title": row["title"],
            "fl_refs": [
                {"fl": e.get("fl"), "state": fl_display_state(e)}
                for e in sorted(direct, key=lambda x: x.get("fl") or "")
            ],
            "context_refs": [
                {"fl": c, "state": fl_display_state(by_id.get(c))}
                for c in sorted(context_ids)
            ],
            "source_anchors_live": sorted(live),
            "source_anchors_unresolved": sorted(unresolved),
        })
    return lanes


def _collect_epoch_entries(root: Path) -> list[dict[str, Any]]:
    entries = load_fl_entries(root)
    overlay = load_fl_overlay(root)

    epoch_entries = []
    for entry in entries:
        fl_id = entry.get("fl") or ""
        record = effective_fl_overlay_record(entry, overlay.get(fl_id), fl_id=fl_id)
        subsystems = record.get("Subsystems") or []
        if "epoch_boundary" not in subsystems:
            continue
        ccs = record.get("ComplaintCounterState") or ""
        epoch_label = ""
        epoch_num = -1
        m = re.search(r"EPOCH\s+(\d+)\s*/\s*([^(]+)", ccs)
        if m:
            epoch_num = int(m.group(1))
            epoch_label = f"EPOCH {m.group(1)} / {m.group(2).strip()}"
        else:
            m2 = re.search(r"EPOCH\s+(\d+)", ccs)
            if m2:
                epoch_num = int(m2.group(1))
                epoch_label = f"EPOCH {m2.group(1)}"
        date_match = re.search(r"\((\d{4}-\d{2}-\d{2})[^)]*\)", ccs)
        epoch_date = date_match.group(1) if date_match else (entry.get("date") or "")
        proof_state = record.get("ProofState") or ""
        summary = ccs.split(".")[0].strip() if ccs else ""
        if len(summary) > 120:
            summary = summary[:117] + "..."
        epoch_entries.append({
            "fl": fl_id,
            "epoch_num": epoch_num,
            "epoch_label": epoch_label,
            "date": epoch_date,
            "proof_state": proof_state,
            "summary": summary,
            "complaint_counter_state": ccs,
        })

    epoch_entries.sort(key=lambda x: x["epoch_num"])
    return epoch_entries


def _show_chronology_context(root: Path, run: dict[str, Any]) -> list[str]:
    started_at = run.get("started_at_utc")
    if not started_at:
        return []
    try:
        run_dt = datetime.fromisoformat(str(started_at).replace("Z", "+00:00"))
    except ValueError:
        return []

    try:
        epoch_entries = _collect_epoch_entries(root)
    except SystemExit:
        return []
    except Exception:
        return []
    if len(epoch_entries) < 3:
        return []

    timeline: list[tuple[date, dict[str, Any]]] = []
    for ep in epoch_entries:
        ep_date_raw = str(ep.get("date") or "").strip()
        if not ep_date_raw:
            continue
        try:
            timeline.append((date.fromisoformat(ep_date_raw), ep))
        except ValueError:
            continue
    if len(timeline) < 3:
        return []

    timeline.sort(key=lambda item: item[0])
    if run_dt.date() < timeline[0][0]:
        return []

    summary = " -> ".join(
        f"{ep['fl']} {ep_date.isoformat()} {ep['epoch_label']}"
        for ep_date, ep in timeline
    )
    current_date, current_epoch = timeline[0]
    for ep_date, ep in timeline:
        if ep_date <= run_dt.date():
            current_date, current_epoch = ep_date, ep
        else:
            break

    lines = [f"epochs: {summary}"]
    lines.append(f"current band: {current_epoch['fl']} ({current_date.isoformat()})")
    if current_epoch.get("fl") == "FL-1434":
        lines.append(
            "attribution: for lag/snapback work in this run window, treat the active blame lane as the post-2026-04-23 audit follow-up, not the 2026-04-20 bundle landing."
        )
        lines.append(
            "fresh-agent note: read FL-1713 and the attribution note near FL-1345 before reopening interpolation, smoothing, or mixed-ownership fixes."
        )
    return lines


def cmd_fl_history_audit(args, root: Path):
    """Detect repeat fix/revert patterns in FL family: count reversions, detect leap-to-blanket anti-patterns."""
    entries = load_fl_entries(root)
    entries_by_id = {e["fl"]: e for e in entries}
    pattern = getattr(args, "pattern", None)
    fl_id = getattr(args, "fl_id", None)
    detect_anti = getattr(args, "detect_anti_pattern", False)

    if fl_id:
        target_fl = fl_id.upper()
        target_entry = entries_by_id.get(target_fl)
        if not target_entry:
            sys.exit(f"error: {fl_id} not found in docs/FAILURE_LOG.md")

        terms = _title_expansion_terms(target_entry.get("title") or "")
        family_ids = _expand_cluster({target_fl}, entries_by_id, entries, terms)
        family = [entries_by_id[fid] for fid in family_ids if fid in entries_by_id]
    else:
        if pattern:
            terms = [t for t in re.split(r"[|\s]+", pattern.lower()) if len(t) >= 2]
            family_ids = {
                e["fl"]
                for e in entries
                if any(term in _fl_text(e).lower() for term in terms)
            }
            family_ids = _expand_cluster(family_ids, entries_by_id, entries, terms)
            family = [entries_by_id[fid] for fid in family_ids if fid in entries_by_id]
        else:
            family = entries

    if not family:
        sys.exit(
            f"error: no FL entries found"
            + (
                f" matching '{pattern}'"
                if pattern
                else f" for {fl_id}"
                if fl_id
                else ""
            )
        )

    failed = [e for e in family if status_class(e) == "failed"]
    resolved = [e for e in family if status_class(e) == "resolved"]
    open_e = [e for e in family if status_class(e) == "open"]

    print(f"HISTORY AUDIT: {len(family)} FL entries in family\n")
    print(f"  REVERTED/REJECTED: {len(failed)}")
    print(f"  RESOLVED/CANONICAL: {len(resolved)}")
    print(f"  OPEN: {len(open_e)}\n")

    print("Reverted entries (do not reopen):")
    for e in sorted(failed, key=lambda x: x["num"], reverse=True)[:8]:
        print(
            f"  {e['fl']:<8}  {e.get('status') or 'NONE':<20}  {e.get('date') or '-'}  {(e.get('title') or '')[:55]}"
        )
    print()

    print("Canonical/resolved entries:")
    for e in sorted(resolved, key=lambda x: x["num"], reverse=True)[:5]:
        print(
            f"  {e['fl']:<8}  {e.get('status') or 'NONE':<20}  {e.get('date') or '-'}  {(e.get('title') or '')[:55]}"
        )
    print()

    if detect_anti and failed and resolved:
        print("ANTI-PATTERN CHECK: 'leap from narrow case to blanket rule'")
        for fe in failed[:5]:
            fe_text = _fl_text(fe).lower()
            narrow_keywords = [
                "narrow",
                "specific",
                "edge case",
                "corner case",
                "projected",
                "wall-top",
            ]
            blanket_keywords = [
                "bypass",
                "in general",
                "always",
                "all remote",
                " blanket ",
            ]
            if any(k in fe_text for k in narrow_keywords):
                if any(k in fe_text for k in blanket_keywords):
                    print(f"  ⚠️  {fe['fl']}: NARROW CASE → BLANKET RULE detected")
                    title = fe.get("title", "")[:60]
                    print(f"      Title: {title}")

        if open_e:
            print(
                "\n⚠️  ACTIVE REINTRODUCTION RISK: OPEN entries exist alongside REVERTED entries"
            )
            for oe in open_e[:3]:
                print(f"  {oe['fl']}: {(oe.get('title') or '')[:55]}")

    default_hint = pattern or fl_id or ""
    print(f"\n[Run 'fl audit {default_hint}' before proposing any fix in this family]")


def _get_related_fl_ids(entry: dict, all_entries: list) -> set:
    """Extract Related: FL IDs from an entry."""
    related = set()
    raw = entry.get("_raw", "")
    for m in re.finditer(r"FL-(\d+)", raw):
        fl_num = int(m.group(1))
        if fl_num != entry.get("num"):
            related.add(f"FL-{fl_num}")
    return related


# ---------------------------------------------------------------------------
# Session audit (process-rule bypass detection)
# ---------------------------------------------------------------------------

_SESSION_GAMEPLAY_FILES = {
    "engine/game.cpp",
    "server/game_svr.cpp",
    "engine/physics.cpp",
    "engine/render.cpp",
    "server/server_tick.cpp",
    "web/game_web.html",
    "scripts/multiplayer_visual_watchdog.js",
}
_SESSION_GAMEPLAY_PREFIXES = ("scripts/watchdog/",)
_SESSION_GAMEPLAY_BASENAMES = {Path(path).name for path in _SESSION_GAMEPLAY_FILES}


def _session_project_key_variants(root: Path) -> set[str]:
    """Return Claude project-key variants for this checkout path.

    Claude encodes path separators as '-' and strips the dot from hidden
    components like `.worktrees`, so keep both the literal and normalized forms.
    """
    raw = str(root.resolve()).replace("/", "-").lstrip("-")
    return {
        raw,
        raw.replace("-.", "--"),
        raw.replace(".", ""),
    }


def _session_project_dir(root: Path) -> Path | None:
    claude_dir = Path.home() / ".claude" / "projects"
    if not claude_dir.exists():
        return None
    keys = _session_project_key_variants(root)
    matches = [p for p in claude_dir.iterdir() if p.is_dir() and any(key in p.name for key in keys)]
    if matches:
        return max(matches, key=lambda p: p.stat().st_mtime)
    return None


def _recent_session_jsonls(root: Path, limit: int) -> list[Path]:
    project_dir = _session_project_dir(root)
    if not project_dir:
        return []
    files = list(project_dir.glob("*.jsonl"))
    files.sort(key=lambda p: p.stat().st_mtime, reverse=True)
    return files[:limit]


def _extract_session_tool_uses(path: Path) -> list[dict]:
    records: list[dict] = []
    try:
        lines = path.read_text(encoding="utf-8", errors="replace").splitlines()
    except OSError:
        return records
    for line_num, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            continue
        if not isinstance(obj, dict):
            continue
        msg = obj.get("message")
        blocks = []
        if isinstance(msg, dict) and isinstance(msg.get("content"), list):
            blocks = msg["content"]
        elif isinstance(msg, list):
            blocks = msg
        for block in blocks:
            if not isinstance(block, dict) or block.get("type") != "tool_use":
                continue
            tool_input = block.get("input")
            records.append(
                {
                    "path": str(path),
                    "line": line_num,
                    "tool": str(block.get("name") or ""),
                    "input": tool_input if isinstance(tool_input, dict) else {},
                }
            )
    return records


def _session_tool_text(tool: str, tool_input: dict) -> str:
    if tool == "Bash":
        return str(tool_input.get("command", ""))
    if tool in {"Edit", "MultiEdit", "Write", "Read", "Grep", "Glob", "Search"}:
        values = []
        for key in ("file_path", "path", "pattern", "query", "glob", "description"):
            if key in tool_input:
                values.append(str(tool_input.get(key, "")))
        return " ".join(values)
    return json.dumps(tool_input, sort_keys=True, default=str)


def _session_is_gameplay_edit(tool: str, tool_input: dict) -> bool:
    if tool not in {"Edit", "MultiEdit", "Write"}:
        return False
    raw = str(tool_input.get("file_path") or tool_input.get("path") or "")
    if not raw:
        return False
    normalized = raw.replace(str(Path.cwd()) + "/", "")
    if normalized in _SESSION_GAMEPLAY_FILES or Path(normalized).name in _SESSION_GAMEPLAY_BASENAMES:
        return True
    return any(normalized.startswith(prefix) for prefix in _SESSION_GAMEPLAY_PREFIXES)


# FL-4691 evidence integrity: when the guard module cannot be imported this
# helper used to return [] on every record, after which the caller printed
# "No process-rule warnings found." — a clean verdict that actually meant the
# guard never ran. Record the import failure so the verdict can report absence
# instead of silence.
_SESSION_GUARD_IMPORT_ERROR: str | None = None


def _session_search_guard_findings(tool: str, tool_input: dict) -> list[str]:
    global _SESSION_GUARD_IMPORT_ERROR
    try:
        from scripts.maintainer.hooks.process_failure_pattern_guard_hook import analyze_hook_payload
    except Exception:
        try:
            from maintainer.hooks.process_failure_pattern_guard_hook import analyze_hook_payload
        except Exception as exc:
            _SESSION_GUARD_IMPORT_ERROR = f"{type(exc).__name__}: {exc}"
            return []
    findings = analyze_hook_payload({"tool_name": tool, "tool_input": tool_input})
    return [f.message for f in findings]


def cmd_session_audit(args, root: Path) -> None:
    """Audit recent agent tool use for rule 13/14 bypass patterns."""
    session_paths: list[Path] = []
    if getattr(args, "session_jsonl", None):
        session_paths = [Path(args.session_jsonl)]
    else:
        session_paths = _recent_session_jsonls(root, int(getattr(args, "sessions", 1)))

    if not session_paths:
        print("SESSION AUDIT: no Claude session JSONL files found")
        return

    tool_uses: list[dict] = []
    for path in session_paths:
        tool_uses.extend(_extract_session_tool_uses(path))

    findings: list[dict] = []
    saw_fl_audit = False
    saw_fl_family = False
    saw_fix_attempt = False
    gameplay_edits: list[dict] = []

    for rec in tool_uses:
        tool = rec["tool"]
        tool_input = rec["input"]
        text = _session_tool_text(tool, tool_input)
        if re.search(r"\b(?:analyze_runs\.py\s+fl\s+audit|scripts/fl\s+audit)\b", text):
            saw_fl_audit = True
        if re.search(r"\b(?:analyze_runs\.py\s+fl\s+family|scripts/fl\s+family)\b", text):
            saw_fl_family = True
        if re.search(r"\b(?:analyze_runs\.py\s+fl\s+fix-attempt|scripts/fl\s+fix-attempt)\b", text):
            saw_fix_attempt = True

        for message in _session_search_guard_findings(tool, tool_input):
            findings.append({
                "kind": "query-space-warning",
                "path": rec["path"],
                "line": rec["line"],
                "tool": tool,
                "message": message,
            })

        if _session_is_gameplay_edit(tool, tool_input):
            gameplay_edits.append(rec)

    if gameplay_edits:
        missing = []
        if not saw_fl_audit:
            missing.append("fl audit")
        if not saw_fl_family:
            missing.append("fl family")
        if not saw_fix_attempt:
            missing.append("fl fix-attempt")
        if missing:
            for rec in gameplay_edits[:10]:
                findings.append({
                    "kind": "missing-audit-sequence",
                    "path": rec["path"],
                    "line": rec["line"],
                    "tool": rec["tool"],
                    "message": (
                        "Gameplay/render/combat edit observed without complete audit sequence: "
                        + ", ".join(missing)
                    ),
                })

    if getattr(args, "json", False):
        print(json.dumps({
            "session_paths": [str(p) for p in session_paths],
            "tool_uses": len(tool_uses),
            "findings": findings,
            "audit_sequence": {
                "fl_audit": saw_fl_audit,
                "fl_family": saw_fl_family,
                "fl_fix_attempt": saw_fix_attempt,
            },
        }, indent=2))
        return

    print(f"SESSION AUDIT: {len(session_paths)} session file(s), {len(tool_uses)} tool use(s)")
    for path in session_paths:
        print(f"  source: {path}")
    print(
        "  audit sequence: "
        f"fl_audit={saw_fl_audit} fl_family={saw_fl_family} fl_fix_attempt={saw_fix_attempt}"
    )
    if _SESSION_GUARD_IMPORT_ERROR is not None:
        print(
            "\nPROCESS-RULE GUARD DID NOT RUN: "
            f"{_SESSION_GUARD_IMPORT_ERROR}. This is not a clean result — the "
            "query-space check was never evaluated."
        )
        return
    if not findings:
        print("\nNo process-rule warnings found.")
        return
    print(f"\nFindings ({len(findings)}):")
    for finding in findings[:50]:
        print(
            f"- {finding['kind']} {Path(finding['path']).name}:{finding['line']} "
            f"{finding['tool']}: {finding['message']}"
        )
    if len(findings) > 50:
        print(f"... {len(findings) - 50} more finding(s)")


