def cmd_commit(args, root: Path) -> None:
    """commit fls|runtime-fields|gates <hash>"""
    fl_index = load_fl_index(root)
    commit_hash = args.commit_hash.strip()
    key8 = commit_hash[:8]

    if args.commit_cmd == "fls":
        entries = fl_index.by_commit.get(key8, [])
        if not entries:
            print(f"(no FL entries found mentioning commit {key8})")
            return
        print(f"FL entries mentioning commit {key8} ({len(entries)}):")
        for e in entries:
            print(f"  {e['fl']} [{status_class(e)}] — {e.get('title', '')[:70]}")

    elif args.commit_cmd in ("runtime-fields", "gates"):
        entries = fl_index.by_commit.get(key8, [])
        if not entries:
            print(f"(no FL entries for commit {key8})")
            return
        # Collect gate names from FL entries
        all_gates: set = set()
        for e in entries:
            for g in e.get("gates") or ([e["gate"]] if e.get("gate") else []):
                all_gates.add(g)
        if args.commit_cmd == "gates":
            print(f"Gates affected by commit {key8} (via FL):")
            for g in sorted(all_gates):
                print(f"  {g}")
        else:  # runtime-fields
            fields: set = set()
            for gate in all_gates:
                for field, gates in FIELD_GATE_MAP.items():
                    if gate in gates:
                        fields.add(field)
            print(
                f"Runtime fields affected by commit {key8} (via FL + FIELD_GATE_MAP):"
            )
            if fields:
                for f in sorted(fields):
                    print(f"  {f}")
            else:
                print(
                    f"  (gates: {', '.join(sorted(all_gates)[:5])} — no FIELD_GATE_MAP entries)"
                )


def cmd_field(args, root: Path) -> None:
    """field fls|gates <field_name>"""
    field_name = args.field_name.strip()

    if args.field_cmd == "fls":
        # rg-backed search through docs/FAILURE_LOG.md
        fl_path = canonical_failure_log_path(root)
        if not fl_path.exists():
            print("ERROR field fls: docs/FAILURE_LOG.md not found.", file=sys.stderr)
            sys.exit(1)
        lines = _rg_search(re.escape(field_name), fl_path, ["-n"])
        if not lines:
            print(f"(no FL entries mentioning '{field_name}')")
            return
        # Extract FL IDs from matched lines' context
        entries = load_fl_entries(root)
        matched = [
            e
            for e in entries
            if any(field_name in line for line in (e.get("_lines") or []))
        ]
        print(f"FL entries mentioning '{field_name}' ({len(matched)}):")
        for e in matched:
            print(f"  {e['fl']} [{status_class(e)}] — {e.get('title', '')[:70]}")

    elif args.field_cmd == "gates":
        gates = FIELD_GATE_MAP.get(field_name, [])
        if not gates:
            # fuzzy: try partial match
            gates = [
                g
                for k, glist in FIELD_GATE_MAP.items()
                if field_name in k
                for g in glist
            ]
        if not gates:
            print(f"(no gate mappings for field '{field_name}' in FIELD_GATE_MAP)")
            return
        print(f"Gates related to field '{field_name}':")
        fl_index = load_fl_index(root)
        for g in sorted(set(gates)):
            fl_entries = fl_index.by_gate.get(g, [])
            ann = f"  — {len(fl_entries)} FL entries" if fl_entries else ""
            print(f"  {g}{ann}")


def cmd_gate_fls_dispatch(args, root: Path) -> None:
    """gate fls <gate_name>"""
    fl_index = load_fl_index(root)
    gate_name = args.gate_name.strip()
    entries = fl_index.by_gate.get(gate_name, [])
    if not entries:
        # Try partial match
        matches = [(g, lst) for g, lst in fl_index.by_gate.items() if gate_name in g]
        if not matches:
            print(f"(no FL entries found for gate '{gate_name}')")
            return
        for g, lst in sorted(matches):
            print(f"\nGate: {g} ({len(lst)} entries):")
            for e in lst:
                print(f"  {e['fl']} [{status_class(e)}] — {e.get('title', '')[:70]}")
        return
    print(f"FL entries for gate '{gate_name}' ({len(entries)}):")
    for e in entries:
        print(f"  {e['fl']} [{status_class(e)}] — {e.get('title', '')[:70]}")


_MSG_TOKEN_CACHE: dict = {}


def _commit_msg_tokens(commit: str, root: Path) -> set:
    key = commit[:8]
    if key not in _MSG_TOKEN_CACHE:
        try:
            res = subprocess.run(
                ["git", "log", "--oneline", "-1", key],
                cwd=str(root),
                capture_output=True,
                text=True,
                timeout=5,
            )
            _MSG_TOKEN_CACHE[key] = (
                set(res.stdout.lower().split()) if res.returncode == 0 else set()
            )
        except Exception:
            _MSG_TOKEN_CACHE[key] = set()
    return _MSG_TOKEN_CACHE[key]


def _triage_similarity(a: dict, b: dict, root: Path) -> float:
    fa = set((a.get("false_gates") or []) + (a.get("null_gates") or []))
    fb = set((b.get("false_gates") or []) + (b.get("null_gates") or []))
    union = fa | fb
    jaccard = len(fa & fb) / len(union) if union else 0.0

    def ratio(r):
        t = r.get("runtime_core_total") or 0
        return (r.get("runtime_core_passed") or 0) / t if t else 0.0

    ratio_sim = max(0.0, 1.0 - abs(ratio(a) - ratio(b)))

    ta = _commit_msg_tokens((a.get("git_head") or "")[:8], root)
    tb = _commit_msg_tokens((b.get("git_head") or "")[:8], root)
    msg_sim = len(ta & tb) / len(ta | tb) if (ta | tb) else 0.0

    return 0.60 * jaccard + 0.25 * ratio_sim + 0.15 * msg_sim


def _triage_hint(run: dict, all_runs: list, root: Path) -> str | None:
    """Return ≤3-line triage hint string, or None if no good match."""
    cur_id = run.get("run_id")
    label = run_label_for(run)
    cur_head = (run.get("git_head") or "")[:8]

    # Filter: same run label, not current run, has gate data
    past = [
        r
        for r in all_runs
        if r.get("run_id") != cur_id
        and run_label_for(r) == label
        and (r.get("false_gates") is not None or r.get("null_gates") is not None)
    ]

    if len(past) < 3:
        return None

    # Cap at 30 most recent
    candidates = past[:30]
    scored = [(c, _triage_similarity(run, c, root)) for c in candidates]
    scored.sort(key=lambda x: -x[1])
    best_run, best_score = scored[0]

    if best_score < 0.35:
        return None

    best_id = best_run.get("run_id", "?")
    best_head = (best_run.get("git_head") or "")[:8]
    commit_info = f"(same)" if cur_head == best_head else f"(→{best_head})"

    # Shared and new gates
    cur_bad = set((run.get("false_gates") or []) + (run.get("null_gates") or []))
    best_bad = set(
        (best_run.get("false_gates") or []) + (best_run.get("null_gates") or [])
    )
    shared = sorted(cur_bad & best_bad)[:3]
    new_gates = sorted(cur_bad - best_bad)[:2]

    shared_str = " ".join(shared) + (
        f" (+{len(cur_bad & best_bad) - 3} more)" if len(cur_bad & best_bad) > 3 else ""
    )
    new_str = " ".join(new_gates) if new_gates else "-"

    lines = [
        f"HINT: closest match {best_id}  sim={best_score:.2f}  commit={cur_head} {commit_info}",
        f"  shared: {shared_str}  new: {new_str}",
    ]

    if cur_head != best_head:
        msg_tokens = _commit_msg_tokens(best_head, root)
        msg = " ".join(list(msg_tokens)[:6]) if msg_tokens else "?"
        lines.append(
            f'  prev commit: "{best_head} {msg}"  '
            f"→  diff: analyze_runs.py diff {cur_id} {best_id}"
        )

    return "\n".join(lines)


def cmd_triage(args, root: Path):
    if getattr(args, "json", False):
        print(json.dumps(build_triage_payload(args, root), indent=2))
        return
    _start_card("triage", run_id=args.run_id, mode="read-only")
    run = load_run_by_id(root, args.run_id)
    if not run:
        sys.exit(f"error: run not found: {args.run_id}")
    fl = load_fl_index(root)

    verdict = run.get("verdict") or "-"
    online = "YES" if run.get("online_integrity_ok") else "NO"
    date_str = (run.get("started_at_utc") or "-")[:16].replace("T", " ")
    commit = (run.get("git_head") or "-")[:8]
    req_pass = run.get("runtime_required_passed") or 0
    req_total = run.get("runtime_required_total") or 0
    core_pass = run.get("runtime_core_passed") or 0
    core_total = run.get("runtime_core_total") or 0
    false_gates, diagnostic_false, deprecated_false = split_gate_groups(run.get("false_gates") or [])
    null_gates = run.get("null_gates") or []
    diagnostic_scope = diagnostic_scope_for_run(run)
    scope_label = diagnostic_scope_label(diagnostic_scope)
    blocker = run.get("prelaunch_blocker") or {}

    cli_style.header(f"TRIAGE: {run.get('run_id', '?')}")
    verdict_badge = cli_style.status(verdict.upper()) if verdict else '-'
    print(
        f"VERDICT: {verdict_badge}  |  ONLINE: {online}  |  DATE: {date_str}  |  COMMIT: {cli_style.style(commit, 'dim')}"
    )
    print(
        f"REQ: {cli_style.style(f'{req_pass}/{req_total}', 'count')}  CORE: {cli_style.style(f'{core_pass}/{core_total}', 'count')}  "
        f"FALSE: {cli_style.style(len(false_gates), 'count')}  NULL: {cli_style.style(len(null_gates), 'count')}"
    )
    if diagnostic_false:
        print(f"DIAGNOSTIC FALSE: {cli_style.style(len(diagnostic_false), 'count')}")
    if deprecated_false:
        print(f"DEPRECATED FALSE: {cli_style.style(len(deprecated_false), 'count')}")
    if scope_label:
        print(f"CODE SURFACE: {scope_label}")
    if isinstance(blocker, dict) and blocker:
        blocker_reason = blocker.get("reason") or blocker.get("kind") or "prelaunch_block"
        print(f"BLOCKER: {blocker_reason}")
        outside_scope = blocker.get("outside_scope_paths") or []
        if outside_scope:
            print(f"OUTSIDE SCOPE: {', '.join(str(path) for path in outside_scope[:4])}")

    if false_gates or null_gates:
        print(f"\n{cli_style.style('FAILED GATES:', 'fail')}")
        shown = 0
        for g in false_gates:
            if shown >= 10:
                print(f"  ... and {cli_style.style(len(false_gates) - shown, 'count')} more false gates")
                break
            ann = fl_gate_ann(fl, g)
            print(f"  {cli_style.fail_item(g)}{ann}")
            shown += 1
        for g in null_gates[:4]:
            print(f"  {cli_style.style('NULL', 'warn')}: {g}")
    if diagnostic_false:
        print("\nDIAGNOSTIC GATES:")
        for g in diagnostic_false[:6]:
            ann = fl_gate_ann(fl, g)
            print(f"  {g}{ann}")

    art = _find_artifact_path(run)

    gd = run.get("gate_deltas") or {}
    regs = [g for g in (gd.get("regressions_true_to_false") or []) if g not in DIAGNOSTIC_ONLY_GATES]
    diag_regs = [g for g in (gd.get("regressions_true_to_false") or []) if g in DIAGNOSTIC_ONLY_GATES]
    if regs:
        print(cli_style.style(f"\nREGRESSIONS vs prev ({len(regs)}):", "fail"))
        for g in regs[:6]:
            print(cli_style.style(f"  {g}", "fail"))
    if diag_regs:
        print(cli_style.style(f"\nDIAGNOSTIC REGRESSIONS vs prev ({len(diag_regs)}):", "warn"))
        for g in diag_regs[:6]:
            print(cli_style.style(f"  {g}", "warn"))

    # Last-passing-run: for each regression gate find the most recent prior run
    # where that gate was not false/null so the analyst knows the last good state.
    regression_gates = list(regs) + list(false_gates)
    last_pass_payload: dict[str, dict[str, str]] = {}
    if regression_gates:
        try:
            all_runs_triage, _ = load_all_runs(root)
            current_ts = run.get("started_at_utc") or ""
            prior_runs = [
                r for r in all_runs_triage
                if (r.get("started_at_utc") or "") < current_ts
            ]
            last_pass: dict[str, tuple[str, str]] = {}  # gate → (run_id, commit)
            for r in prior_runs:
                r_false = set(r.get("false_gates") or [])
                r_null = set(r.get("null_gates") or [])
                for g in regression_gates:
                    if g not in last_pass and g not in r_false and g not in r_null:
                        last_pass[g] = (
                            r.get("run_id") or "?",
                            (r.get("git_head") or "?")[:8],
                        )
                if len(last_pass) == len(regression_gates):
                    break
            if last_pass:
                last_pass_payload = {
                    gate: {"run_id": rid, "commit": sha}
                    for gate, (rid, sha) in last_pass.items()
                }
                print(f"\nLAST PASS (per regression gate):")
                for g, (rid, sha) in list(last_pass.items())[:8]:
                    print(f"  {g:<45} {rid} @ {sha}")
        except (json.JSONDecodeError, KeyError, OSError):
            pass

    cd = run.get("causal_digest") or {}
    highlights = cd.get("highlights") or []
    if highlights:
        print("\nCAUSAL DIGEST:")
        for h in highlights[:2]:
            print(f"  {str(h)[:90]}")

    post_join = derive_post_join_lag_metrics(run, root)
    tick_overrun = derive_authoritative_tick_overrun_metrics(run, root)
    if post_join:
        lines = []
        post_join_payload = {}
        for tab_name in ("tab1", "tab2"):
            pj = post_join.get(tab_name) or {}
            if not pj:
                continue
            max_ms = pj.get("post_join_lag_max_ms")
            p95_ms = pj.get("post_join_lag_p95_ms")
            samples = pj.get("post_join_lag_sample_count")
            post_join_payload[tab_name] = {
                "post_join_lag_max_ms": max_ms,
                "post_join_lag_p95_ms": p95_ms,
                "post_join_lag_sample_count": samples,
            }
            def _fmt_ms(v: object) -> str:
                return f"{v:.0f}ms" if isinstance(v, (int, float)) else "-"
            wait_samples = pj.get("post_join_lag_wait_sample_count")
            stale_samples = pj.get("post_join_lag_stale_sample_count")
            wait_age_max = pj.get("post_join_lag_wait_age_max_ms")
            rsp_age_max = pj.get("post_join_lag_response_age_max_ms")
            lines.append(
                f"{tab_name} max={_fmt_ms(max_ms)} p95={_fmt_ms(p95_ms)} "
                f"n={samples if samples is not None else '-'} "
                f"wait={wait_samples if wait_samples is not None else '-'} "
                f"stale={stale_samples if stale_samples is not None else '-'} "
                f"wait_age_max={_fmt_ms(wait_age_max)} "
                f"rsp_age_max={_fmt_ms(rsp_age_max)}"
            )
        if lines:
            print("\nPOST-JOIN LAG:")
            for line in lines:
                print(f"  {line}")

    if tick_overrun:
        max_us = tick_overrun.get("tick_max_elapsed_us")
        count = tick_overrun.get("tick_overrun_count")
        over_budget = isinstance(max_us, int) and max_us > TICK_OVERRUN_BUDGET_US
        if over_budget or (isinstance(count, int) and count > 0):
            print("\nSERVER OVERRUN:")
            print(
                f"  OVER-BUDGET tick_max_elapsed_us={max_us if max_us is not None else '-'} "
                f"tick_overrun_count={count if count is not None else '-'} "
                f"budget_us={TICK_OVERRUN_BUDGET_US}"
            )
            server_log_path = art / "server.log" if art is not None else None
            for line in _format_tick_overrun_owner(tick_overrun, server_log_path=server_log_path):
                print(line)

    # Oracle diagnosis (Unit 5b): show only when non-unclassified diagnoses are present.
    oracle_diag_block = (run.get("diagnostics") or {}).get("render_oracle_tab1") or {}
    top_diag = oracle_diag_block.get("oracle_diagnosis_top")
    if top_diag:
        diag_counts = oracle_diag_block.get("oracle_diagnosis_counts") or {}
        count = diag_counts.get(top_diag, 0)
        print(f"\nORACLE DIAGNOSIS: {top_diag} (x{count})")

    # Bootstrap diagnosis: when verdict is bootstrap_fail, read last recorder
    # samples for new packet/pending/lifecycle signals.
    if verdict in ("bootstrap_fail",):
        try:
            art_path = _find_artifact_path(run)
            rec_file = art_path / "recorder" / "recording.jsonl" if art_path else None
            if rec_file and rec_file.exists():
                _, _, t_samples = _load_recording(rec_file)
                # Find last non-null sample per tab for the key fields
                diag_fields = {
                    "server_ptr_ok": None,
                    "pending_drain_block_defer": None,
                    "pending_drain_deferred_preserved": None,
                    "pending_drain_stop_server_null": None,
                    "packet_calls": None,
                    "packet_proc_called": None,
                    "packet_deferred": None,
                    "packet_server_null": None,
                    "pending_dropped": None,
                    "pending_max_depth": None,
                    "game_loading_state": None,
                    "server_lifecycle_event": None,
                    "server_first_null_after_live_seen": None,
                    "server_first_null_after_live_stage": None,
                    "server_first_null_after_live_op": None,
                }
                for s in reversed(t_samples):
                    for fld in list(diag_fields):
                        if diag_fields[fld] is None and s.get(fld) is not None:
                            diag_fields[fld] = s[fld]
                    if all(v is not None for v in diag_fields.values()):
                        break
                # Only print if at least one field present (dirty build deployed)
                has_any = any(v is not None for v in diag_fields.values())
                if has_any:
                    drain_blk = diag_fields.get("pending_drain_block_defer")
                    deferred_preserved = diag_fields.get("pending_drain_deferred_preserved")
                    drain_stop_null = diag_fields.get("pending_drain_stop_server_null")
                    pkt_proc = diag_fields.get("packet_proc_called")
                    pkt_calls = diag_fields.get("packet_calls")
                    pkt_null = diag_fields.get("packet_server_null")
                    pkt_defer = diag_fields.get("packet_deferred")
                    svr_ok = diag_fields.get("server_ptr_ok")
                    loading = diag_fields.get("game_loading_state")
                    dropped = diag_fields.get("pending_dropped")
                    max_depth = diag_fields.get("pending_max_depth")
                    lifecycle = diag_fields.get("server_lifecycle_event")
                    first_null_seen = diag_fields.get("server_first_null_after_live_seen")
                    first_null_stage = diag_fields.get("server_first_null_after_live_stage")
                    first_null_op = diag_fields.get("server_first_null_after_live_op")
                    lines = []
                    if svr_ok is not None and not svr_ok:
                        extra = ""
                        if first_null_seen:
                            op_txt = chr(first_null_op) if isinstance(first_null_op, int) and 32 <= first_null_op <= 126 else first_null_op
                            extra = f" first_null={first_null_stage} op={op_txt}"
                        lines.append(f"  SERVER NULL (lifecycle={lifecycle}{extra})")
                    if drain_blk is not None and drain_blk > 0:
                        lines.append(f"  LEGACY HEAD-OF-LINE BLOCK: pending_drain_block_defer={drain_blk}")
                    if deferred_preserved is not None and deferred_preserved > 0:
                        lines.append(f"  DEFERRED PRESERVED: pending_drain_deferred_preserved={deferred_preserved}")
                    if drain_stop_null is not None and drain_stop_null > 0:
                        lines.append(f"  DRAIN STOPPED ON SERVER NULL: pending_drain_stop_server_null={drain_stop_null}")
                    if pkt_calls and (pkt_proc is None or pkt_proc == 0):
                        lines.append(f"  ZERO PROC: packet_calls={pkt_calls} proc={pkt_proc} null={pkt_null} defer={pkt_defer}")
                    if dropped and dropped > 0:
                        lines.append(f"  QUEUE OVERFLOW: dropped={dropped} max_depth={max_depth}")
                    if loading is not None and loading != 2:
                        lines.append(f"  LOADING STUCK: game_loading_state={loading}")
                    if lines:
                        print("\nBOOTSTRAP DIAGNOSIS:")
                        for ln in lines:
                            print(ln)
                    else:
                        print(f"\nBOOTSTRAP DIAGNOSIS: fields present but no anomaly detected (svr_ok={svr_ok} loading={loading} pkt_proc={pkt_proc})")
        except (json.JSONDecodeError, KeyError, OSError) as exc:
            print(f"warning: bootstrap diagnosis: {exc}", file=sys.stderr)

    # Triage hint (≤3 lines)
    try:
        all_runs, _ = load_all_runs(root)
        hint = _triage_hint(run, all_runs, root)
        if hint:
            print(f"\n{hint}")
    except (json.JSONDecodeError, KeyError, OSError) as exc:
        print(f"warning: triage hint: {exc}", file=sys.stderr)

    next_act = next_action_text(run)
    print(f"\n{cli_style.style('NEXT ACTION:', 'warn')}\n  {cli_style.style(next_act[:120], 'warn')}")
    obs = run.get("user_observation")
    if obs:
        print(f"\n{cli_style.style('OBSERVATION:', 'subheader')}\n  {compact_text(obs, max_len=120)}")


