# Source of truth: engine/bundle_types.h — enum ActorBundleComposeFailureStage.
_COMPOSE_FAILURE_STAGE_LABELS: dict[int, str] = {
    0: "NONE",
    1: "CACHE_FULL",
    2: "RENDER_STACK_EMPTY",
    3: "BASE_LAYER_DEF_MISSING",
    4: "BASE_LAYER_SPRITE_MISSING",
    5: "NEUTRAL_CLONE_FAILED",
    6: "OVERLAY_LAYER_DEF_MISSING",
    7: "OVERLAY_LAYER_SPRITE_MISSING",
    8: "OVERLAY_COMPOSITE_FAILED",
    9: "OFFSET_GROUP_CLONE_FAILED",
    10: "PARITY_MASK_FAILED",
}


def _compose_failure_label(stage: int | None) -> str:
    if not stage:
        return "-"
    return _COMPOSE_FAILURE_STAGE_LABELS.get(stage, f"UNKNOWN_{stage}")


# Source of truth: engine/game.cpp — enum ActorBundleMountedComposeMode.
_MOUNTED_COMPOSE_MODE_LABELS: dict[int, str] = {
    0: "NONE",
    1: "GENERIC_STACK",
    2: "EXACT_REAR_RIDER_FRONT",
}


def _mounted_compose_mode_label(mode: int | None) -> str:
    if not mode:
        return "-"
    return _MOUNTED_COMPOSE_MODE_LABELS.get(mode, f"UNKNOWN_{mode}")


_MOUNTED_PROVENANCE_HINT = (
    "manual symptom without mounted tuple in receipt = provenance mismatch, "
    "not automatic recorder-loss proof"
)


def _recording_candidate_roots(run: dict) -> list[Path]:
    roots: list[Path] = []
    primary = _find_artifact_path(run)
    if primary is not None:
        roots.append(primary)
    for key in ("archive_path", "launcher_output_dir"):
        raw = run.get(key)
        if not raw:
            continue
        candidate = Path(raw)
        if candidate.exists() and candidate not in roots:
            roots.append(candidate)
    return roots


def _recording_path_for_run(run: dict) -> tuple[Path | None, Path | None]:
    for base in _recording_candidate_roots(run):
        rec_path = base / "recorder" / "recording.jsonl"
        if rec_path.exists():
            return rec_path, base
    return None, None


def _mounted_int(sample: dict, field: str) -> int:
    value = _num(sample.get(field))
    return int(value) if value is not None else 0


def _mounted_optional_int(sample: dict, field: str) -> int | None:
    value = _num(sample.get(field))
    return int(value) if value is not None else None


def _mounted_rel_s(sample: dict) -> float | None:
    value = _num(sample.get("rel_s"))
    return float(value) if value is not None else None


def _sample_has_mounted_proof_rows(sample: dict[str, Any]) -> bool:
    if not isinstance(sample, dict):
        return False
    return isinstance(sample.get("mounted_proof_actor"), dict) or isinstance(
        sample.get("mounted_proof_remote0"), dict
    )


def _sample_has_interpolation_proof(sample: dict[str, Any]) -> bool:
    return isinstance(sample.get("interpolation_proof"), dict)


def _sample_has_item_authority_proof(sample: dict[str, Any]) -> bool:
    return isinstance(sample.get("item_authority_proof"), dict)


def _sample_has_render_visibility_proof(sample: dict[str, Any]) -> bool:
    return isinstance(sample.get("render_visibility_proof"), dict)


def _best_interpolation_observation(samples: list[dict[str, Any]]) -> dict[str, Any] | None:
    """Return the best (most informative) interpolation proof row from samples."""
    best: dict[str, Any] | None = None
    for sample in samples:
        row = sample.get("interpolation_proof") if isinstance(sample.get("interpolation_proof"), dict) else None
        if row is None:
            continue
        if not row.get("observed"):
            continue
        if best is None:
            best = row
            continue
        # Prefer tuple_present over not, then higher rank
        if bool(row.get("tuple_present")) != bool(best.get("tuple_present")):
            if row.get("tuple_present"):
                best = row
        elif bool(row.get("active")) != bool(best.get("active")):
            if row.get("active"):
                best = row
    return best


def _best_item_authority_observation(samples: list[dict[str, Any]]) -> dict[str, Any] | None:
    """Return the best item authority proof row from samples."""
    best: dict[str, Any] | None = None
    for sample in samples:
        row = sample.get("item_authority_proof") if isinstance(sample.get("item_authority_proof"), dict) else None
        if row is None:
            continue
        if not row.get("observed"):
            continue
        if best is None:
            best = row
            continue
        # Prefer tuple_present, then more world items
        if bool(row.get("tuple_present")) != bool(best.get("tuple_present")):
            if row.get("tuple_present"):
                best = row
        elif int(row.get("world_item_count") or 0) > int(best.get("world_item_count") or 0):
            best = row
    return best


def _best_render_visibility_observation(samples: list[dict[str, Any]]) -> dict[str, Any] | None:
    """Return the best render visibility proof row from samples."""
    best: dict[str, Any] | None = None
    for sample in samples:
        row = sample.get("render_visibility_proof") if isinstance(sample.get("render_visibility_proof"), dict) else None
        if row is None:
            continue
        if not row.get("observed"):
            continue
        if best is None:
            best = row
            continue
        # Prefer tuple_present, then visible, then more slots
        if bool(row.get("tuple_present")) != bool(best.get("tuple_present")):
            if row.get("tuple_present"):
                best = row
        elif bool(row.get("visible")) != bool(best.get("visible")):
            if row.get("visible"):
                best = row
        elif len(row.get("render_slot_kind_ids") or []) > len(best.get("render_slot_kind_ids") or []):
            best = row
    return best


def _empty_mounted_subject_observation(subject: str) -> dict[str, Any]:
    return {
        "subject": subject,
        "observed": False,
        "tuple_present": False,
        "authority_present": False,
        "render_tuple_present": False,
        "compose_tuple_present": False,
        "compose_failure_present": False,
        "seq": None,
        "rel_s": None,
        "tab": "-",
        "mount_state": 0,
        "snapshot_mount_state": None,
        "auth_mount_definition_id": 0,
        "compose_mode": 0,
        "compose_mode_label": "-",
        "compose_failure_stage": 0,
        "compose_failure_stage_label": "-",
        "post_interp_has_inst": None,
        "first_failing_stage": "authority",
        "score": 0,
    }


def _mounted_proof_observation_from_sample(sample: dict[str, Any], *, subject: str) -> dict[str, Any] | None:
    row_key = f"mounted_proof_{subject}"
    row = sample.get(row_key) if isinstance(sample.get(row_key), dict) else None
    if row is None:
        return None
    snapshot_mount_state = _mounted_optional_int(row, "snapshot_mount_state")
    auth_mount_definition_id = _mounted_optional_int(row, "auth_mount_definition_id") or 0
    compose_mode = _mounted_optional_int(row, "render_compose_mode") or 0
    compose_failure_stage = _mounted_optional_int(row, "render_compose_failure_stage") or 0
    post_interp_has_inst = _mounted_optional_int(row, "post_interp_has_inst")
    observed = bool(row.get("observed"))
    tuple_present = bool(row.get("tuple_present"))
    authority_present = bool(row.get("authority_present"))
    render_tuple_present = bool(row.get("render_tuple_present"))
    compose_failure_present = bool(row.get("compose_failure_present"))
    compose_tuple_present = render_tuple_present and compose_mode > 0 and not compose_failure_present
    first_failing_stage = row.get("first_failing_stage")
    score = 0
    if observed:
        score += 1
    if (snapshot_mount_state or 0) > 0:
        score += 40
    if auth_mount_definition_id > 0:
        score += 40
    if compose_mode > 0:
        score += 20
    if compose_failure_present:
        score += 12
    if tuple_present:
        score += 100
    return {
        "subject": subject,
        "observed": observed,
        "tuple_present": tuple_present,
        "authority_present": authority_present,
        "render_tuple_present": render_tuple_present,
        "compose_tuple_present": compose_tuple_present,
        "compose_failure_present": compose_failure_present,
        "seq": sample.get("seq"),
        "rel_s": _mounted_rel_s(sample),
        "tab": sample.get("tab_id") or sample.get("tab") or "-",
        "mount_state": snapshot_mount_state or 0,
        "snapshot_mount_state": snapshot_mount_state,
        "auth_mount_definition_id": auth_mount_definition_id,
        "compose_mode": compose_mode,
        "compose_mode_label": _mounted_compose_mode_label(compose_mode),
        "compose_failure_stage": compose_failure_stage,
        "compose_failure_stage_label": _compose_failure_label(compose_failure_stage),
        "post_interp_has_inst": post_interp_has_inst,
        "first_failing_stage": None if first_failing_stage in (None, "none") else first_failing_stage,
        "score": score,
    }


def _mounted_subject_observation(
    sample: dict,
    *,
    subject: str,
    mount_state_field: str,
    auth_mount_definition_field: str,
    compose_mode_field: str | None = None,
    compose_failure_field: str,
    snapshot_mount_state_field: str | None = None,
    post_interp_has_inst_field: str | None = None,
) -> dict[str, Any]:
    mount_state = _mounted_int(sample, mount_state_field)
    snapshot_mount_state = (
        _mounted_int(sample, snapshot_mount_state_field) if snapshot_mount_state_field else None
    )
    auth_mount_definition_id = _mounted_int(sample, auth_mount_definition_field)
    compose_mode = _mounted_int(sample, compose_mode_field) if compose_mode_field else 0
    compose_failure_stage = _mounted_int(sample, compose_failure_field)
    post_interp_has_inst = (
        _mounted_optional_int(sample, post_interp_has_inst_field)
        if post_interp_has_inst_field
        else None
    )
    effective_mount_state = (
        snapshot_mount_state
        if isinstance(snapshot_mount_state, int) and snapshot_mount_state > 0
        else mount_state
    )
    render_tuple_present = compose_mode > 0 or compose_failure_stage > 0
    compose_failure_present = compose_failure_stage > 0
    compose_tuple_present = render_tuple_present and compose_mode > 0 and not compose_failure_present
    authority_present = effective_mount_state > 0 and auth_mount_definition_id > 0
    observed = any(
        value > 0
        for value in (
            mount_state,
            snapshot_mount_state or 0,
            auth_mount_definition_id,
            compose_mode,
            compose_failure_stage,
        )
    )
    tuple_present = authority_present and render_tuple_present and not compose_failure_present
    if post_interp_has_inst_field:
        tuple_present = tuple_present and post_interp_has_inst == 1
    score = 0
    if observed:
        score += 1
    if effective_mount_state > 0:
        score += 40
    if auth_mount_definition_id > 0:
        score += 40
    if compose_mode > 0:
        score += 20
    if compose_failure_present:
        score += 12
    if tuple_present:
        score += 100
    return {
        "subject": subject,
        "observed": observed,
        "tuple_present": tuple_present,
        "authority_present": authority_present,
        "render_tuple_present": render_tuple_present,
        "compose_tuple_present": compose_tuple_present,
        "compose_failure_present": compose_failure_present,
        "seq": sample.get("seq"),
        "rel_s": _mounted_rel_s(sample),
        "tab": sample.get("tab_id") or sample.get("tab") or "-",
        "mount_state": mount_state,
        "snapshot_mount_state": snapshot_mount_state,
        "auth_mount_definition_id": auth_mount_definition_id,
        "compose_mode": compose_mode,
        "compose_mode_label": _mounted_compose_mode_label(compose_mode),
        "compose_failure_stage": compose_failure_stage,
        "compose_failure_stage_label": _compose_failure_label(compose_failure_stage),
        "post_interp_has_inst": post_interp_has_inst,
        "score": score,
    }


def _mounted_observation_better(candidate: dict[str, Any], current: dict[str, Any] | None) -> bool:
    if current is None:
        return True
    if int(candidate.get("score") or 0) != int(current.get("score") or 0):
        return int(candidate.get("score") or 0) > int(current.get("score") or 0)
    cand_rel = candidate.get("rel_s")
    cur_rel = current.get("rel_s")
    if isinstance(cand_rel, (int, float)) and isinstance(cur_rel, (int, float)) and cand_rel != cur_rel:
        return float(cand_rel) < float(cur_rel)
    cand_seq = candidate.get("seq")
    cur_seq = current.get("seq")
    if isinstance(cand_seq, (int, float)) and isinstance(cur_seq, (int, float)) and cand_seq != cur_seq:
        return int(cand_seq) < int(cur_seq)
    return False


def _best_mounted_subject_observation(
    samples: list[dict[str, Any]],
    *,
    subject: str,
    mount_state_field: str,
    auth_mount_definition_field: str,
    compose_mode_field: str | None = None,
    compose_failure_field: str,
    snapshot_mount_state_field: str | None = None,
    post_interp_has_inst_field: str | None = None,
) -> dict[str, Any]:
    best: dict[str, Any] | None = None
    for sample in samples:
        obs = _mounted_subject_observation(
            sample,
            subject=subject,
            mount_state_field=mount_state_field,
            auth_mount_definition_field=auth_mount_definition_field,
            compose_mode_field=compose_mode_field,
            compose_failure_field=compose_failure_field,
            snapshot_mount_state_field=snapshot_mount_state_field,
            post_interp_has_inst_field=post_interp_has_inst_field,
        )
        if not obs["observed"]:
            continue
        if _mounted_observation_better(obs, best):
            best = obs
    if best is not None:
        return best
    return _empty_mounted_subject_observation(subject)


def _best_mounted_proof_subject_observation(samples: list[dict[str, Any]], *, subject: str) -> dict[str, Any]:
    best: dict[str, Any] | None = None
    for sample in samples:
        obs = _mounted_proof_observation_from_sample(sample, subject=subject)
        if obs is None or not obs["observed"]:
            continue
        if _mounted_observation_better(obs, best):
            best = obs
    if best is not None:
        return best
    return _empty_mounted_subject_observation(subject)


def _mounted_failure_stage(observation: dict[str, Any]) -> str | None:
    if not observation.get("observed"):
        return "authority"
    if observation.get("tuple_present"):
        return None
    mount_state = int(observation.get("mount_state") or 0)
    snapshot_mount_state = int(observation.get("snapshot_mount_state") or 0)
    auth_mount_definition_id = int(observation.get("auth_mount_definition_id") or 0)
    if max(mount_state, snapshot_mount_state) <= 0 or auth_mount_definition_id <= 0:
        return "authority"
    if int(observation.get("compose_failure_stage") or 0) > 0:
        return "compose"
    if observation.get("post_interp_has_inst") == 0:
        return "remote_inst_deletion"
    return "wrapper_resolve"


def derive_mounted_witness_for_samples(samples: list[dict[str, Any]]) -> dict[str, Any]:
    if any(_sample_has_mounted_proof_rows(sample) for sample in samples):
        actor = _best_mounted_proof_subject_observation(samples, subject="actor")
        remote0 = _best_mounted_proof_subject_observation(samples, subject="remote0")
        witness_subject = None
        if remote0.get("tuple_present"):
            witness_subject = "remote0"
        elif actor.get("tuple_present"):
            witness_subject = "actor"
        primary_subject = None
        if remote0.get("observed"):
            primary_subject = "remote0"
        elif actor.get("observed"):
            primary_subject = "actor"
        failure_subject = remote0 if primary_subject == "remote0" else actor
        return {
            "available": True,
            "source": "recording_jsonl",
            "witness_found": witness_subject is not None,
            "witness_subject": witness_subject,
            "primary_subject": primary_subject,
            "first_failing_stage": None if witness_subject else failure_subject.get("first_failing_stage"),
            "provenance_mismatch": primary_subject is not None and witness_subject is None,
            "hint": _MOUNTED_PROVENANCE_HINT,
            "actor": actor,
            "remote0": remote0,
        }

    actor = _best_mounted_subject_observation(
        samples,
        subject="actor",
        mount_state_field="actor_mount_state",
        auth_mount_definition_field="auth_self_mount_definition_id",
        compose_mode_field="actor_render_compose_mode",
        compose_failure_field="actor_render_compose_failure_stage",
    )
    remote0 = _best_mounted_subject_observation(
        samples,
        subject="remote0",
        mount_state_field="remote0_mount_state",
        snapshot_mount_state_field="remote0_snapshot_mount_state",
        auth_mount_definition_field="auth_remote0_mount_definition_id",
        compose_mode_field="remote0_render_compose_mode",
        compose_failure_field="remote0_render_compose_failure_stage",
        post_interp_has_inst_field="remote0_post_interp_has_inst",
    )
    witness_subject = None
    if remote0.get("tuple_present"):
        witness_subject = "remote0"
    elif actor.get("tuple_present"):
        witness_subject = "actor"
    primary_subject = None
    if remote0.get("observed"):
        primary_subject = "remote0"
    elif actor.get("observed"):
        primary_subject = "actor"
    failure_subject = remote0 if primary_subject == "remote0" else actor
    return {
        "available": True,
        "source": "recording_jsonl",
        "witness_found": witness_subject is not None,
        "witness_subject": witness_subject,
        "primary_subject": primary_subject,
        "first_failing_stage": None if witness_subject else _mounted_failure_stage(failure_subject),
        "provenance_mismatch": primary_subject is not None and witness_subject is None,
        "hint": _MOUNTED_PROVENANCE_HINT,
        "actor": actor,
        "remote0": remote0,
    }


def derive_mounted_witness_for_artifact(artifact_path: Path) -> dict[str, Any]:
    rec_path = artifact_path / "recorder" / "recording.jsonl"
    if not rec_path.exists():
        return {
            "available": False,
            "source": "recording_jsonl",
            "reason": "recording_jsonl_missing",
            "artifact_path": str(artifact_path),
            "hint": _MOUNTED_PROVENANCE_HINT,
        }
    _meta, _events, samples = _load_recording(rec_path)
    result = derive_mounted_witness_for_samples(samples)
    result["artifact_path"] = str(artifact_path)
    return result


def derive_mounted_witness_for_run(run: dict) -> dict[str, Any]:
    rec_path, artifact_root = _recording_path_for_run(run)
    if rec_path is None or artifact_root is None:
        return {
            "available": False,
            "source": "recording_jsonl",
            "reason": "recording_jsonl_missing",
            "artifact_path": run.get("artifact_path"),
            "archive_path": run.get("archive_path"),
            "launcher_output_dir": run.get("launcher_output_dir"),
            "hint": _MOUNTED_PROVENANCE_HINT,
        }
    _meta, _events, samples = _load_recording(rec_path)
    result = derive_mounted_witness_for_samples(samples)
    result["artifact_path"] = str(artifact_root)
    return result


def _mounted_death_window_row(sample: dict[str, Any]) -> dict[str, Any] | None:
    row = sample.get("mounted_proof_remote0") if isinstance(sample.get("mounted_proof_remote0"), dict) else None
    source = row if row is not None else sample

    death_snapshot_count = _mounted_optional_int(source, "death_snapshot_count")
    if death_snapshot_count is None:
        death_snapshot_count = _mounted_optional_int(sample, "remote0_death_snapshot_count")
    first_mount_state = _mounted_optional_int(source, "first_death_snapshot_mount_state")
    if first_mount_state is None:
        first_mount_state = _mounted_optional_int(sample, "remote0_first_death_snapshot_mount_state")
    last_mount_state = _mounted_optional_int(source, "last_death_snapshot_mount_state")
    if last_mount_state is None:
        last_mount_state = _mounted_optional_int(sample, "remote0_last_death_snapshot_mount_state")
    death_tick = _mounted_optional_int(source, "death_tick")
    if death_tick is None:
        death_tick = _mounted_optional_int(sample, "remote0_death_tick")
    first_presentation_kind_id = _mounted_optional_int(source, "first_death_snapshot_presentation_kind_id")
    if first_presentation_kind_id is None:
        first_presentation_kind_id = _mounted_optional_int(sample, "remote0_first_death_snapshot_presentation_kind_id")
    last_presentation_kind_id = _mounted_optional_int(source, "last_death_snapshot_presentation_kind_id")
    if last_presentation_kind_id is None:
        last_presentation_kind_id = _mounted_optional_int(sample, "remote0_last_death_snapshot_presentation_kind_id")
    snapshot_mount_state = _mounted_optional_int(source, "snapshot_mount_state")
    if snapshot_mount_state is None:
        snapshot_mount_state = _mounted_optional_int(sample, "remote0_snapshot_mount_state")
    mount_state = _mounted_optional_int(source, "mount_state")
    if mount_state is None:
        mount_state = _mounted_optional_int(sample, "remote0_mount_state")

    observed = (
        (death_snapshot_count or 0) > 0
        and (death_tick or 0) > 0
        and max(first_mount_state or 0, last_mount_state or 0, snapshot_mount_state or 0, mount_state or 0) > 0
    )
    if not observed:
        return None

    score = 0
    score += 100 if observed else 0
    score += min(max(death_snapshot_count or 0, 0), 25)
    if (first_mount_state or 0) > 0:
        score += 20
    if (last_mount_state or 0) > 0:
        score += 20
    if (first_presentation_kind_id or 0) > 0:
        score += 10
    if (last_presentation_kind_id or 0) > 0:
        score += 10

    return {
        "observed": True,
        "seq": sample.get("seq"),
        "rel_s": _mounted_rel_s(sample),
        "tab": sample.get("tab_id") or sample.get("tab") or "-",
        "death_snapshot_count": death_snapshot_count or 0,
        "first_death_snapshot_mount_state": first_mount_state or 0,
        "last_death_snapshot_mount_state": last_mount_state or 0,
        "first_death_snapshot_presentation_kind_id": first_presentation_kind_id or 0,
        "last_death_snapshot_presentation_kind_id": last_presentation_kind_id or 0,
        "death_tick": death_tick or 0,
        "snapshot_mount_state": snapshot_mount_state,
        "mount_state": mount_state,
        "score": score,
    }


def derive_mounted_death_window_for_samples(samples: list[dict[str, Any]]) -> dict[str, Any]:
    best: dict[str, Any] | None = None
    for sample in samples:
        candidate = _mounted_death_window_row(sample)
        if candidate is None:
            continue
        if best is None:
            best = candidate
            continue
        if int(candidate.get("score") or 0) != int(best.get("score") or 0):
            if int(candidate.get("score") or 0) > int(best.get("score") or 0):
                best = candidate
            continue
        candidate_rel_s = candidate.get("rel_s")
        best_rel_s = best.get("rel_s")
        if candidate_rel_s is not None and (
            best_rel_s is None or float(candidate_rel_s) < float(best_rel_s)
        ):
            best = candidate

    if best is None:
        return {
            "available": True,
            "source": "recording_jsonl",
            "observed": False,
            "reason": "mounted_death_window_not_observed",
        }

    result = dict(best)
    result["available"] = True
    result["source"] = "recording_jsonl"
    return result


def derive_mounted_death_window_for_artifact(artifact_path: Path) -> dict[str, Any]:
    rec_path = artifact_path / "recorder" / "recording.jsonl"
    if not rec_path.exists():
        return {
            "available": False,
            "source": "recording_jsonl",
            "observed": False,
            "reason": "recording_jsonl_missing",
            "artifact_path": str(artifact_path),
        }
    _meta, _events, samples = _load_recording(rec_path)
    result = derive_mounted_death_window_for_samples(samples)
    result["artifact_path"] = str(artifact_path)
    return result


def derive_mounted_death_window_for_run(run: dict) -> dict[str, Any]:
    rec_path, artifact_root = _recording_path_for_run(run)
    if rec_path is None or artifact_root is None:
        return {
            "available": False,
            "source": "recording_jsonl",
            "observed": False,
            "reason": "recording_jsonl_missing",
            "artifact_path": run.get("artifact_path"),
            "archive_path": run.get("archive_path"),
            "launcher_output_dir": run.get("launcher_output_dir"),
        }
    _meta, _events, samples = _load_recording(rec_path)
    result = derive_mounted_death_window_for_samples(samples)
    result["artifact_path"] = str(artifact_root)
    return result


