                _val(s, "actor_render_compose_failure_overlay_layer_definition_id"),
                _val(s, "actor_render_compose_failure_overlay_slot_kind_id"),
                _mounted_compose_mode_label(_mounted_int(s, "remote0_render_compose_mode")),
                _val(s, "remote0_render_ref_alignment_observed"),
                _compose_failure_label(r0_stage) if r0_stage else "-",
                _val(s, "remote0_render_compose_failure_base_layer_definition_id"),
                _val(s, "remote0_render_compose_failure_overlay_layer_definition_id"),
                _val(s, "remote0_render_compose_failure_overlay_slot_kind_id"),
                _mounted_compose_mode_label(_mounted_int(s, "tracked_npc0_render_compose_mode")),
                _compose_failure_label(s.get("tracked_npc0_render_compose_failure_stage"))
