def _recorder_ansi_frames(art: Path, tab: str | None) -> None:
    ansi_dir = art / "ansi_frames"
    if not ansi_dir.exists():
        print("(no ansi_frames directory)")
        return

    rows = []
    for p in sorted(ansi_dir.glob("*.json")):
        stem = p.stem
        if "_" in stem:
            frame_tab, phase = stem.split("_", 1)
        else:
            frame_tab, phase = stem, "-"
        if tab and frame_tab != tab:
            continue
        width = height = captured = cell_count = "-"
        try:
            with open(p, errors="replace") as f:
                payload = json.load(f)
            width = payload.get("width", "-")
            height = payload.get("height", "-")
            captured = payload.get("captured_at_ms", "-")
            cell_count = payload.get("cell_count", "-")
        except (OSError, json.JSONDecodeError):
            pass
        rows.append(
            [
                str(p.relative_to(art)),
                frame_tab,
                phase,
                width,
                height,
                cell_count,
                captured,
            ]
        )
    _print_table(["file", "tab", "phase", "w", "h", "cells", "captured_ms"], rows)


