def _recorder_input(
    samples: list, tab: str | None, at: float | None, rng: tuple | None, stride: int
) -> None:
    cols = [
        "seq",
        "rel_s",
        "tab",
        "w",
        "a",
        "s",
        "d",
        "jump",
        "fly",
        "action",
        "key_seq",
        "last_key",
        "last_kind",
        "ws_out",
    ]
    rows = []
    event_rows = []
    seen_events = set()
    for s in _filter_samples(samples, tab, at, rng, stride):
        last_event = None
        for ev in s.get("input_event_sample") or []:
            if isinstance(ev, dict) and isinstance(ev.get("seq"), int):
                if last_event is None or ev["seq"] > last_event["seq"]:
                    last_event = ev
        rows.append(
            [
                _val(s, "seq"),
                f"{s.get('rel_s', 0):.2f}",
                s.get("tab_id") or s.get("tab") or "-",
                _val(s, "input_w_down"),
                _val(s, "input_a_down"),
                _val(s, "input_s_down"),
                _val(s, "input_d_down"),
                _val(s, "input_jump_requested"),
                _val(s, "input_fly_applied"),
                _val(s, "input_action_value"),
                last_event.get("seq") if last_event else "-",
                _input_key_label(last_event.get("key"), last_event.get("kind")) if last_event else "-",
                _input_kind_label(last_event.get("kind")) if last_event else "-",
                _val(s, "ws_out_total"),
            ]
        )
        for ev in s.get("input_event_sample") or []:
            if not isinstance(ev, dict):
                continue
            ev_seq = ev.get("seq")
            event_id = (s.get("tab_id") or s.get("tab") or "-", ev_seq)
            if ev_seq in (None, 0) or event_id in seen_events:
                continue
            seen_events.add(event_id)
            ev_kind = ev.get("kind")
            event_rows.append(
                [
                    _val(s, "seq"),
                    f"{s.get('rel_s', 0):.2f}",
                    s.get("tab_id") or s.get("tab") or "-",
                    ev_seq,
                    _input_kind_label(ev_kind),
                    _input_key_label(ev.get("key"), ev_kind),
                    ev.get("auto_repeat"),
                    ev.get("dt_ms"),
                    ev.get("main_menu_active"),
                    ev.get("show_inventory_active"),
                    ev.get("talk_box_active"),
                    ev.get("menu_depth_value"),
                ]
            )
    _print_table(cols, rows)
    if event_rows:
        print()
        _print_table(
            [
                "sample_seq",
                "rel_s",
                "tab",
                "event_seq",
                "kind",
                "key",
                "auto",
                "dt_ms",
                "menu",
                "inv",
                "talk",
                "depth",
            ],
            event_rows,
        )


def _input_kind_label(v: object) -> object:
    labels = {
        0: "down",
        1: "up",
        2: "char",
        3: "press",
    }
    return labels.get(v, v)


def _input_key_label(v: object, kind: object = None) -> object:
    if not isinstance(v, int):
        return v
    if kind == 2:
        if v in (10, 13):
            return "ENTER"
        if v == 8:
            return "BACKSPACE"
        if 32 <= v < 127:
            return repr(chr(v))
        return v
    specials = {
        1: "BACKSPACE",
        2: "TAB",
        3: "ENTER",
        5: "ESC",
        6: "SPACE",
        7: "PAGEUP",
        8: "PAGEDOWN",
        9: "END",
        10: "HOME",
        11: "LEFT",
        12: "UP",
        13: "RIGHT",
        14: "DOWN",
    }
    if v in specials:
        return specials[v]
    if 18 <= v <= 27:
        return chr(ord("0") + (v - 18))
    if 28 <= v <= 53:
        return chr(ord("A") + (v - 28))
    return v


def _recorder_item(
    samples: list, tab: str | None, at: float | None, rng: tuple | None, stride: int
) -> None:
    cols = [
        "seq",
        "rel_s",
        "tab",
        "auth_local",
        "auth_world",
        "equipped",
        "weapon_desync",
        "pickup_sent",
        "pickup_item",
        "pickup_reason",
        "auth_weapon_sync",
        "inv_open",
    ]
    rows = []
    for s, state in _iter_effective_recorder_rows(samples, tab, at, rng, stride):
        rows.append(
            [
                _val(s, "seq"),
                f"{s.get('rel_s', 0):.2f}",
                s.get("tab_id") or s.get("tab") or "-",
                _val(state, "auth_item_local"),
                _val(state, "auth_item_world"),
                _val(state, "auth_item_equipped_local"),
                _val(state, "auth_pickup_req_sent"),
                _val(state, "auth_pickup_req_last_item_id"),
                _val(state, "auth_pickup_req_last_reason"),
                _val(state, "input_show_inventory_active"),
            ]
        )
    _print_table(cols, rows)


