def cmd_phases(args, root: Path) -> None:
    run_id = getattr(args, "run_id", None)
    if not run_id:
        runs, _ = load_all_runs(root)
        picked = _maybe_fzf_pick(
            [r.get("run_id", "?") for r in runs[:50]], prompt="run> "
        )
        run_id = picked.strip() if picked else None
        if not run_id:
            print("ERROR phases: run_id required.", file=sys.stderr)
            sys.exit(1)

    run = load_run_by_id(root, run_id)
    art = _require_artifact_path(run, "phases")

    ph_path = art / "watchdog_phase_history.jsonl"
    rows = []
    if ph_path.exists():
        with open(ph_path, errors="replace") as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                try:
                    obj = json.loads(line)
                    rows.append(
                        [
                            obj.get("phase", "-"),
                            f"{obj.get('rel_s', 0):.2f}",
                            (obj.get("ts") or "")[:19],
                            obj.get("tab", "-"),
                            obj.get("operator_media_ts", obj.get("video_ts", "-")),
                        ]
                    )
                except json.JSONDecodeError:
                    pass

    if not rows:
        # fallback: scan server.log for [PHASE:*] markers
        slog = art / "server.log"
        if slog.exists():
            hits = _rg_search(r"\[PHASE:", slog)
            if hits:
                print(
                    "(phase_history.jsonl empty — found phase markers in server.log:)"
                )
                for h in hits[:30]:
                    print(f"  {h}")
                return
        print("NO PHASE DATA")
        print(f"  Suggest: analyze_runs.py artifacts {run_id} --file server.log")
        return

    _print_table(["phase", "rel_s", "ts_utc", "tab", "operator_media_ts"], rows)


