def cmd_slot(args, root: Path) -> None:
    run_id = getattr(args, "run_id", None)
    if not run_id:
        runs, _ = load_all_runs(root)
        picked = _maybe_fzf_pick(
            [r.get("run_id", "?") for r in runs[:50]], prompt="run> "
        )
        run_id = picked.strip() if picked else None
        if not run_id:
            print("ERROR slot: run_id required.", file=sys.stderr)
            sys.exit(1)

    run = load_run_by_id(root, run_id)
    art = _require_artifact_path(run, "slot")

    sm_path = art / "slot_manifest.json"
    if not sm_path.exists():
        sys.exit(f"ERROR slot: slot_manifest.json not found at {sm_path}")

    with open(sm_path) as f:
        live = json.load(f)

    expected = run.get("pre_deploy_manifest") or {}
    print("SLOT MANIFEST:")
    print(json.dumps(live, indent=2))

    if expected:
        all_keys = sorted(set(expected) | set(live))
        mismatches = [
            (k, expected.get(k, "—"), live.get(k, "—"))
            for k in all_keys
            if expected.get(k) != live.get(k)
        ]
        if mismatches:
            print(f"\nMISMATCHES vs pre_deploy_manifest ({len(mismatches)}):")
            _print_table(["key", "expected", "live"], mismatches)
        else:
            print(f"\nOK: matches pre_deploy_manifest ({len(all_keys)} keys)")


