def cmd_artifacts(args, root: Path) -> None:
    run_id = getattr(args, "run_id", None)
    if not run_id:
        runs, _ = load_all_runs(root)
        picked = _maybe_fzf_pick(
            [r.get("run_id", "?") for r in runs[:50]], prompt="run> "
        )
        run_id = picked.strip() if picked else None
        if not run_id:
            print("ERROR artifacts: run_id required.", file=sys.stderr)
            sys.exit(1)

    run = load_run_by_id(root, run_id)
    art = _require_artifact_path(run, "artifacts")

    file_arg = getattr(args, "file", None)
    if file_arg:
        target = art / file_arg
        if not target.exists():
            sys.exit(f"ERROR artifacts: file not found: {target}")
        if target.suffix == ".json":
            try:
                with open(target, errors="replace") as f:
                    print(json.dumps(json.load(f), indent=2))
            except json.JSONDecodeError as exc:
                sys.exit(f"ERROR artifacts: malformed JSON in {target.name}: {exc}")
        elif target.suffix == ".jsonl":
            with open(target, errors="replace") as f:
                for i, line in enumerate(f):
                    if i >= 50:
                        print(f"... (truncated at 50 lines)")
                        break
                    print(line, end="")
        else:
            with open(target, errors="replace") as f:
                for i, line in enumerate(f):
                    if i >= 200:
                        print(f"... (truncated at 200 lines)")
                        break
                    print(line, end="")
        return

    # List all files with sizes
    rows = []
    for p in sorted(art.rglob("*")):
        if p.is_file():
            rel = str(p.relative_to(art))
            sz = p.stat().st_size
            rows.append([rel, f"{sz:,}"])
    _print_table(["file", "size"], rows)


