def cmd_server_log(args, root: Path) -> None:
    run_id = getattr(args, "run_id", None)
    if not run_id:
        runs, _ = load_all_runs(root)
        picked = _maybe_fzf_pick(
            [r.get("run_id", "?") for r in runs[:50]], prompt="run> "
        )
        run_id = picked.strip() if picked else None
        if not run_id:
            print("ERROR server-log: run_id required.", file=sys.stderr)
            sys.exit(1)

    run = load_run_by_id(root, run_id)
    art = _require_artifact_path(run, "server-log")
    slog = art / "server.log"
    if not slog.exists():
        sys.exit(f"ERROR server-log: server.log not found at {slog}")

    fl_arg = getattr(args, "fl", None)
    filter_arg = getattr(args, "filter", None)
    error_flag = getattr(args, "error", False)
    entity_arg = getattr(args, "entity", None)
    tail_n = getattr(args, "tail", None)
    fl036_snap_count = getattr(args, "fl036_snap_count", False)

    if fl036_snap_count:
        lines = _rg_search(r"\[FL036-SNAP\]", slog, ["-a"])
        ci_counts: dict[str, int] = {}
        for line in lines:
            m = re.search(r"\bci=(\d+)", line)
            if m:
                ci = m.group(1)
                ci_counts[ci] = ci_counts.get(ci, 0) + 1
        print(f"FL036-SNAP count: {len(lines)}")
        if ci_counts:
            rows = [
                [ci, str(count)]
                for ci, count in sorted(ci_counts.items(), key=lambda x: int(x[0]))
            ]
            _print_table(["ci", "count"], rows)
        return
    if fl_arg:
        # Expand FL entry gate names into a pattern
        fl_id = fl_arg.upper()
        entries = load_fl_entries(root)
        entry = next((e for e in entries if e["fl"] == fl_id), None)
        gates = []
        if entry:
            gates = entry.get("gates") or ([entry["gate"]] if entry.get("gate") else [])
        pattern = "|".join([r"\b" + re.escape(g) + r"\b" for g in gates] + [r"\b" + re.escape(fl_id) + r"\b"])
        lines = _rg_search(pattern, slog, ["-a"])
    elif error_flag:
        lines = _rg_search(r"error|warn|critical", slog, ["-a", "-i"])
    elif entity_arg:
        lines = _rg_search(f"entity_id={entity_arg}|eid={entity_arg}", slog, ["-a"])
    elif filter_arg:
        lines = _rg_search(filter_arg, slog, ["-a", "-i"])
    else:
        with open(slog, errors="replace") as f:
            lines = [line.rstrip("\n") for line in f]

    if tail_n:
        lines = lines[-tail_n:]

    parse_mode = getattr(args, "parse", None)
    if parse_mode:
        _server_log_structured_parse(slog, parse_mode, tail_n)
        return

    for line in lines:
        print(line)
    print(f"\n({len(lines)} lines)")


def _resolve_trace_artifact(root: Path, trace_file: str | None) -> Path:
    trace_root = candidate_trace_dir(root)
    if trace_file:
        candidate = Path(trace_file)
        if candidate.exists():
            return candidate
        candidate = trace_root / trace_file
        if candidate.exists():
            return candidate
        sys.exit(f"ERROR stall-histogram: trace file not found: {trace_file}")
    files = sorted(trace_root.glob("*.txt"))
    if not files:
        sys.exit(f"ERROR stall-histogram: no trace artifacts found in {trace_root}")
    return files[-1]


def _parse_stall_histogram(path: Path) -> dict:
    text = path.read_text(encoding="utf-8", errors="replace")
    lines = text.splitlines()
    scalars: dict[str, int] = {}
    for m in re.finditer(r"^@([A-Za-z0-9_]+):\s+(\d+)\s*$", text, flags=re.MULTILINE):
        scalars[m.group(1)] = int(m.group(2))
    histogram: list[str] = []
    capture_hist = False
    for line in lines:
        if line.startswith("@write_latency_us:"):
            capture_hist = True
            continue
        if capture_hist and line.startswith("@") and not line.startswith("@write_latency_us:"):
            break
        if capture_hist:
            histogram.append(line.rstrip())
    slow_lines = [line for line in lines if line.startswith("slow_write ")]
    return {
        "path": path,
        "scalars": scalars,
        "histogram": [line for line in histogram if line.strip()],
        "slow_lines": slow_lines,
    }


def cmd_stall_histogram(args, root: Path) -> None:
    trace_root = candidate_trace_dir(root)
    if getattr(args, "list", False):
        rows = []
        for path in sorted(trace_root.glob("*.txt")):
            stat = path.stat()
            rows.append(
                [
                    path.name,
                    str(stat.st_size),
                    datetime.fromtimestamp(stat.st_mtime, tz=timezone.utc).strftime("%Y-%m-%d %H:%M"),
                ]
            )
        if not rows:
            print(f"(no trace artifacts in {trace_root})")
            return
        _print_table(["file", "size", "mtime_utc"], rows)
        return

    path = _resolve_trace_artifact(root, getattr(args, "trace_file", None))
    parsed = _parse_stall_histogram(path)
    print(f"TRACE: {path}")
    print(f"  write_count: {parsed['scalars'].get('write_count', 0)}")
    print(f"  slow_count:  {parsed['scalars'].get('slow_count', 0)}")
    if parsed["histogram"]:
        print("\nHISTOGRAM:")
        for line in parsed["histogram"]:
            print(line)
    else:
        print("\nHISTOGRAM:")
        print("  (no write_latency_us histogram in artifact)")
    show_slow = getattr(args, "show_slow", 0) or 0
    if show_slow and parsed["slow_lines"]:
        print(
            f"\nSLOW WRITES ({min(show_slow, len(parsed['slow_lines']))}/{len(parsed['slow_lines'])}):"
        )
        for line in parsed["slow_lines"][:show_slow]:
            print(f"  {line}")


# -- structured parsers for server.log tags (FL-641/642 proof instrumentation) --

_RE_FLJIT_PHYS_BASE = re.compile(
    r"\[FLJIT-PHYS\]\s+ci=(?P<ci>\d+)\s+tick=(?P<tick>\d+)"
    r"(?:\s+steps=(?P<steps>\d+))?"
    r"\s+pos=\((?P<x>[-+]?\d*\.?\d+),(?P<y>[-+]?\d*\.?\d+),(?P<z>[-+]?\d*\.?\d+)\)"
    r"\s+vel=\((?P<vx>[-+]?\d*\.?\d+),(?P<vy>[-+]?\d*\.?\d+),(?P<vz>[-+]?\d*\.?\d+)\)"
    r"\s+grounded=(?P<grounded>\d+)"
)
_RE_FLJIT_SUPPORT = re.compile(
    r"sweep=(?P<sweep>\d+)\s+swz=(?P<swz>[-+]?\d*\.?\d+)"
    r"\s+wback=(?P<wback>\d+)\s+sgate=(?P<sgate>\d+)"
    r"\s+sfound=(?P<sfound>\d+)\s+sapplied=(?P<sapplied>\d+)"
    r"\s+sh=(?P<sh>[-+]?\d*\.?\d+)\s+sdepth=(?P<sdepth>[-+]?\d*\.?\d+)"
    r"\s+rz=(?P<rz>[-+]?\d*\.?\d+)"
)

_RE_SPAWN_DECISION = re.compile(
    r"\[SPAWN-DECISION\]\s+ci=(?P<ci>\d+)\s+tick=(?P<tick>\d+)"
    r"\s+spawn_pos=\((?P<sx>[-+]?\d*\.?\d+),(?P<sy>[-+]?\d*\.?\d+),(?P<sz>[-+]?\d*\.?\d+)\)"
    r"\s+phys_pos=\((?P<px>[-+]?\d*\.?\d+),(?P<py>[-+]?\d*\.?\d+),(?P<pz>[-+]?\d*\.?\d+)\)"
    r"\s+phys_vel=\((?P<pvx>[-+]?\d*\.?\d+),(?P<pvy>[-+]?\d*\.?\d+),(?P<pvz>[-+]?\d*\.?\d+)\)"
    r"\s+terrain_z=(?P<terrain_z>[-+]?\d*\.?\d+)"
    r"\s+spawn_terrain_z=(?P<spawn_terrain_z>[-+]?\d*\.?\d+)"
    r"\s+spawn_fallback_z=(?P<spawn_fallback_z>[-+]?\d*\.?\d+)"
    r"\s+in_water=(?P<in_water>[-+]?\d*\.?\d+)"
    r"\s+has_physics=(?P<has_physics>\d+)"
)


def _server_log_structured_parse(
    slog: Path, tag: str, tail_n: int | None
) -> None:
    """Structured parse of FLJIT-PHYS or SPAWN-DECISION from server.log."""
    records: list[dict] = []
    with open(slog, errors="replace") as f:
        for line in f:
            if tag == "fljit-phys":
                m = _RE_FLJIT_PHYS_BASE.search(line)
                if m:
                    rec = m.groupdict()
                    # Second pass: extract support tuple if present
                    ms = _RE_FLJIT_SUPPORT.search(line)
                    if ms:
                        rec.update(ms.groupdict())
                    records.append(rec)
            else:
                m = _RE_SPAWN_DECISION.search(line)
                if m:
                    records.append(m.groupdict())
    if tail_n:
        records = records[-tail_n:]

    if not records:
        print(f"(0 {tag} records)")
        return

    if tag == "fljit-phys":
        cols = ["ci", "tick", "z", "grounded", "sweep", "swz", "wback",
                "sgate", "sfound", "sapplied", "sh", "sdepth", "rz"]
    else:
        cols = ["ci", "tick", "sz", "pz", "terrain_z", "spawn_terrain_z",
                "spawn_fallback_z", "in_water", "has_physics"]

    rows = []
    for rec in records:
        row = []
        for c in cols:
            v = rec.get(c)
            row.append(v if v is not None else "-")
        rows.append(row)
    _print_table(cols, rows)
    print(f"\n({len(records)} {tag} records)")


def cmd_spawn_decision(args, root: Path) -> None:
    """Dedicated query surface for [SPAWN-DECISION] records (FL-641/642)."""
    run_id = getattr(args, "run_id", None)
    if not run_id:
        runs, _ = load_all_runs(root)
        picked = _maybe_fzf_pick(
            [r.get("run_id", "?") for r in runs[:50]], prompt="run> "
        )
        run_id = picked.strip() if picked else None
        if not run_id:
            print("ERROR spawn-decision: run_id required.", file=sys.stderr)
            sys.exit(1)

    run = load_run_by_id(root, run_id)
    art = _require_artifact_path(run, "server-log")
    slog = art / "server.log"
    if not slog.exists():
        sys.exit(f"ERROR spawn-decision: server.log not found at {slog}")

    ci_filter = getattr(args, "ci", None)
    records: list[dict] = []
    with open(slog, errors="replace") as f:
        for line in f:
            m = _RE_SPAWN_DECISION.search(line)
            if m:
                rec = m.groupdict()
                if ci_filter is not None and int(rec["ci"]) != ci_filter:
                    continue
                records.append(rec)

    if not records:
        print(f"No [SPAWN-DECISION] records found in {run_id}")
        print("This means either the server binary lacks the instrumentation or no player joined.")
        return

    print(f"[SPAWN-DECISION] records from {run_id}:")
    print()
    for rec in records:
        ci = rec["ci"]
        tick = rec["tick"]
        sz = rec["sz"]
        pz = rec["pz"]
        tz = rec["terrain_z"]
        stz = rec["spawn_terrain_z"]
        sfz = rec["spawn_fallback_z"]
        iw = rec["in_water"]
        hp = rec["has_physics"]
        spawn_phys_delta = float(pz) - float(sz)
        print(f"  ci={ci}  tick={tick}")
        print(f"    spawn_pos_z = {sz}")
        print(f"    phys_pos_z  = {pz}  (delta from spawn: {spawn_phys_delta:+.3f})")
        print(f"    terrain_z   = {tz}")
        print(f"    spawn_terrain_z = {stz}")
        print(f"    spawn_fallback_z = {sfz}")
        print(f"    in_water    = {iw}")
        print(f"    has_physics = {hp}")
        if abs(spawn_phys_delta) > 10.0:
            print(f"    *** WARNING: phys_pos_z diverges from spawn_pos_z by {spawn_phys_delta:+.3f} ***")
        print()
    print(f"({len(records)} records)")


# ---------------------------------------------------------------------------
# Subcommand: server-snapshot
# ---------------------------------------------------------------------------


def cmd_server_snapshot(args, root: Path) -> None:
    run_id = getattr(args, "run_id", None)
    if not run_id:
        runs, _ = load_all_runs(root)
        picked = _maybe_fzf_pick(
            [r.get("run_id", "?") for r in runs[:50]], prompt="run> "
        )
        run_id = picked.strip() if picked else None
        if not run_id:
            print("ERROR server-snapshot: run_id required.", file=sys.stderr)
            sys.exit(1)

    run = load_run_by_id(root, run_id)
    art = _require_artifact_path(run, "server-snapshot")
    rec_path = art / "recorder" / "recording.jsonl"
    if not rec_path.exists():
        sys.exit(f"ERROR server-snapshot: recording.jsonl not found at {rec_path}")

    _, _, samples = _load_recording(rec_path)

    at_val = getattr(args, "at", None)
    tick_val = getattr(args, "tick", None)
    entity_val = getattr(args, "entity", None)

    SERVER_FIELDS = {"auth_", "server_", "npc_sample", "srv_"}

    def is_server_field(k: str) -> bool:
        return any(k.startswith(p) for p in SERVER_FIELDS)

    if at_val is not None:
        candidates = [
            s
            for s in samples
            if not (getattr(args, "tab", None) and (s.get("tab_id") or s.get("tab")) != args.tab)
        ]
        if not candidates:
            print("(no samples)")
            return
        s = min(candidates, key=lambda x: abs((x.get("rel_s") or 0) - at_val))
        srv = {k: v for k, v in s.items() if is_server_field(k) and v not in (None, 0)}
        print(
            f"Server snapshot at rel_s≈{at_val} (actual={s.get('rel_s', '?'):.2f}) "
            f"seq={s.get('seq', '?')} tab={s.get('tab', '?')}:"
        )
        print(json.dumps(srv, indent=2))
    elif tick_val is not None:
        for s in samples:
            if s.get("seq") == tick_val:
                srv = {
                    k: v
                    for k, v in s.items()
                    if is_server_field(k) and v not in (None, 0)
                }
                print(f"Server snapshot at tick {tick_val} tab={s.get('tab', '?')}:")
                print(json.dumps(srv, indent=2))
                return
        print(f"(tick {tick_val} not found in recording)")
    elif entity_val is not None:
        results = []
        for s in samples:
            srv = {
                k: v
                for k, v in s.items()
                if is_server_field(k) and str(entity_val) in str(v)
            }
            if srv:
                results.append((s.get("rel_s", 0), s.get("seq"), s.get("tab_id") or s.get("tab"), srv))
        for rel_s, seq, tab, srv in results[:20]:
            print(f"  rel_s={rel_s:.2f} seq={seq} tab={tab}:")
            for k, v in srv.items():
                print(f"    {k}: {v}")
    else:
        print(
            "ERROR server-snapshot: provide --at, --tick, or --entity", file=sys.stderr
        )
        sys.exit(1)


